from typing import Generator
def prime_generator(limit: int) -> Generator[int, None, int]:
    if limit < 2:
        return
    else:
        yield 2
    primes = [2]
    for x in range(3, limit + 1, 2):
        if any(map(lambda divisor: x % divisor == 0, primes[: int(sqrt(x))])):
            continue
        else:
            primes.append(x)
            yield x
