def readPointCloudFromPly(path):
    f = open(path, 'r')

    points = []

    headerSkipped = False
    for line in f:
        if headerSkipped:
            points.append(np.float32(np.array(line.split(' ')[0:3])))
        else:
            headerSkipped = line.find('end_header') != -1

