import warnings
from distutils.version import LooseVersion as V
def check_for_zmq(minimum_version, module='IPython.zmq'):
    try:
        import zmq
    except ImportError:
        raise ImportError("%s requires pyzmq >= %s"%(module, minimum_version))
    pyzmq_version = zmq.__version__

    if 'dev' not in pyzmq_version and V(pyzmq_version) < V(minimum_version):
        raise ImportError("%s requires pyzmq >= %s, but you have %s"%(
                        module, minimum_version, pyzmq_version))
    # fix missing DEALER/ROUTER aliases in pyzmq < 2.1.9
    if not hasattr(zmq, 'DEALER'):
        zmq.DEALER = zmq.XREQ
    if not hasattr(zmq, 'ROUTER'):
        zmq.ROUTER = zmq.XREP
    if V(zmq.zmq_version()) >= V('4.0.0'):
        warnings.warn("""libzmq 4 detected.
        It is unlikely that IPython's zmq code will work properly.
        Please install libzmq stable, which is 2.1.x or 2.2.x""",
        RuntimeWarning)
check_for_zmq('2.1.4')

from . import rest
from .common import ParseError, Docstring
_styles = {"rest": rest.parse}
def _parse_score(docstring: Docstring) -> int:
    """
    Produce a score for the parsing.
    :param Docstring docstring: parsed docstring representation
    :returns int: parse score, higher is better
    """
    score = 0
    if docstring.short_description:
        score += 1
    if docstring.long_description:
        score += docstring.long_description.count('\n')
    score += len(docstring.params)
    score += len(docstring.raises)
    if docstring.returns:
        score += 2
    return score
def parse(text: str, style: str = 'auto') -> Docstring:
    """
    Parse the docstring into its components.
    :param str text: docstring text to parse
    :param str style: docstring style, choose from: 'rest', 'auto'
    :returns Docstring: parsed docstring representation
    """
    if style == 'auto':
        rets = []
        for _parse in _styles.values():
            try:
                rets.append(_parse(text))
            except ParseError as e:
                exc = e
        if not rets:
            raise exc
        return sorted(rets, key=_parse_score, reverse=True)[0]
    else:
        return _styles[style](text)

