from odoo import models, api
class ProductTemplate(models.Model):
    _inherit = 'product.template'
    @api.multi
    def create_get_variant(self, value_ids, custom_values=None):
        """Add bill of matrials to the configured variant."""
        if custom_values is None:
            custom_values = {}
        variant = super(ProductTemplate, self).create_get_variant(
            value_ids, custom_values=custom_values
        )
        attr_products = variant.attribute_value_ids.mapped('product_id')
        line_vals = [
            (0, 0, {'product_id': product.id}) for product in attr_products
        ]
        values = {
            'product_tmpl_id': self.id,
            'product_id': variant.id,
            'bom_line_ids': line_vals
        }
        self.env['mrp.bom'].create(values)
        return variant

import re
from .common import (
    ReadCancelledError, InvalidParameterError, TypeNotFoundError,
    InvalidChecksumError
)
from .rpc_errors import (
    RPCError, InvalidDCError, BadRequestError, UnauthorizedError,
    ForbiddenError, NotFoundError, FloodError, ServerError, BadMessageError
)
from .rpc_errors_303 import *
from .rpc_errors_400 import *
from .rpc_errors_401 import *
from .rpc_errors_420 import *
def rpc_message_to_error(code, message):
    errors = {
        303: rpc_303_errors,
        400: rpc_400_errors,
        401: rpc_401_errors,
        420: rpc_420_errors
    }.get(code, None)
    if errors is not None:
        for msg, cls in errors.items():
            m = re.match(msg, message)
            if m:
                extra = int(m.group(1)) if m.groups() else None
                return cls(extra=extra)
    elif code == 403:
        return ForbiddenError(message)
    elif code == 404:
        return NotFoundError(message)
    elif code == 500:
        return ServerError(message)
    return RPCError('{} (code {})'.format(message, code))

