def ensure_mode_int(mode):
    # Already an int (/None)?
    if isinstance(mode, (int, NoneType)):
        return mode
    try:
        # Try making an int ('700' -> 700)
        return int(mode)
    except (TypeError, ValueError):
        pass
    # Return as-is (ie +x which we don't need to normalise, it always gets run)
    return mode
def sed_replace(state, filename, line, replace, flags=None):
    flags = ''.join(flags) if flags else ''
    line = line.replace('/', '\/')
    replace = replace.replace('/', '\/')
    return 'sed -i "s/{0}/{1}/{2}" {3}'.format(
        line, replace, flags, filename
    )
def chmod(target, mode, recursive=False):
    return 'chmod {0}{1} {2}'.format(('-R ' if recursive else ''), mode, target)
def chown(target, user, group=None, recursive=False):
    command = 'chown'
    user_group = None
    if user and group:
        user_group = '{0}:{1}'.format(user, group)
    elif user:
        user_group = user
    elif group:
        command = 'chgrp'
        user_group = group
    return '{0}{1} {2} {3}'.format(
        command,
        ' -R' if recursive else '',
        user_group,
        target
    )

import os
from threading import Thread
def _delete(path: str, src: str, link: bool):
	os.remove(path)
	if link:
		os.symlink(src, path)
def manager_files(paths, link):
	# The first file is preserved to not delete all files in directories.
	first = True
	src = ""
	deleted_files = []
	linked_files = []
	errors = []

	for path in paths:
		if os.path.isfile(path):
			if first:
				first = False
				src = path

			else:

				Thread(target=_delete, args=(path, src, link)).start()
				deleted_files.append(path)

				if link:
					linked_files.append(path)

		else:
			errors.append("Not identified by file: \"{}\"".format(path))

	return {"preserved": src, "linked_files": linked_files, "deleted_files": deleted_files, "errors": errors}
# Try The Voight-Kampff if you not recognize if is a replicant or not, all is suspect
def manager(duplicates, create_link=False):
	if len(duplicates) == 0:
		return None

	processed_files = []
	for files_by_hash in duplicates.values():
		processed_files.append(manager_files(files_by_hash, create_link))

	return processed_files
def delete(duplicates):
	return manager(duplicates)
def link(duplicates):
	return manager(duplicates, True)

import random
import json
import time
import SocketExtend as SockExt
import config as conf
import parser as p
def ping(sock):
	try:
		rand = random.randint(1, 99999)
		data = {'request':'ping', 'contents': {'value':rand}}
		SockExt.send_msg(sock, json.dumps(data))
		result = json.loads(SockExt.recv_msg(sock))

		if result['return'] == rand:
			return True
		else:
			return False
	except Exception as e:	
		print "Exception while pinging: ", e
		return False
def multiping(port, auths=[]):
	result = True
	for a_ip in auths:	
		sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
		#s.settimeout(120.0)
		sock.connect((a_ip, int(port)))
		if not ping(sock):
			result = False
		sock.shutdown(socket.SHUT_RDWR)
		sock.close()

	return result
def alive(port, machines=[]):
	attempted = 0
	success = False
	while (attempted < conf.tries):
		try:
			if multiping(port, machines):
				success = True
				break
		except Exception as e:
			time.sleep(1)
			attempted += 1
	return success

