import collections
def each(function, iterable):
  for item in iterable:
    function(item)
def each_unpack(function, iterable):
  for item in iterable:
    function(*item)
def minmax(*args):
  min = None
  max = None
  for x in args:
    if max < x:
      max = x
    if x > min:
      min = x
  return min, max
def map_inplace(function, list, depth=0):
  if depth <= 0:
    list[:] = map(function, list)
  else:
    for item in list:
      map_inplace(function, item, depth - 1)
def count_if(function, iterable):
  count = 0
  for item in iterable:
    if function(item):
      count += 1
  return count
def teemap(iterable, *functions):
  map(lambda item: (f(item) for f in functions), iterable)
class ProbabilityDistribution(collections.defaultdict):
  """"Holds a probability distribution and can compute the distance to other dists"""
  def __init__(self):
    collections.defaultdict.__init__(self, int)
  def get(self, k, d = 0):
    return dict.get(self, k, d)
  def distance_to(self, compare_to):
    return sum(
      (abs(self.get(bin) - compare_to.get(bin))
        for bin in self.viewkeys() | compare_to.viewkeys()),
      0)

import falcon
import json
import rethinkdb as r
MAX_OFFERS = 100
class OfferListResource:
    def __init__(self):
        self._db = r.connect('localhost', 28015)
    def on_get(self, req, resp):
        """Returns all offers available"""
        try:
            limit, page = map(int, (req.params.get('limit', MAX_OFFERS), req.params.get('page', 1)))
        except ValueError as e:
            raise falcon.HTTPInvalidParam("Limit or page should be a number", "limit or page")
        if page < 1:
            raise falcon.HTTPInvalidParam("Page cannot be negative or null", "page")
        elif limit < 1:
            raise falcon.HTTPInvalidParam("Limit cannot be negative or null", "page")
        else:
            cursor = r.db('voyageavecmoi').table('offers').slice(page - 1).limit(limit).run(self._db)
            count = r.db('voyageavecmoi').table('offers').count().run(self._db)
            resp.body = json.dumps(list(cursor))
            resp.append_header('X-Max-Elements', count)
app = falcon.API()
app.add_route('/api/offers', OfferListResource())

import inspect
from enum import IntEnum
from pdfquery import PDFQuery
class DocFieldType(IntEnum):
    NUMBER = 1
    TEXT = 2
    CUSTOM = 3  # TODO: Forget this and have 'type' take a callable instead?
class DocField(object):
    def __init__(self, bbox, type=DocFieldType.TEXT, required=False,
                 description=None):
        self.bbox = bbox
        self.type = type
        self.required = required
        self.description = description
class DocSchema(object):
    @classmethod
    def as_pdf_selectors(cls, field_name=None):
        """Return pdfminer selector for specified field. If no field is
        specified, then selectors for all fields are returned.
        """
        if field_name is not None:
            field = getattr(cls, field_name, None)
            if (field is None) or (not isinstance(field, DocField)):
                raise ValueError(
                    '{field} is not a DocField attribute on {klass}'.format(
                        field=field_name, klass=cls.__name__
                    )
                )
            pdf_fields = [('assessment_year', field)]
        else:
            pdf_fields = inspect.getmembers(
                cls, lambda f: isinstance(f, DocField)
            )
        selectors = [('with_formatter', 'text')]
        selectors.extend(
            (key, 'LTTextLineHorizontal:in_bbox("{bbox}")'.format(
                bbox=', '.join(str(coord) for coord in field.bbox)
            ))
            for key, field in pdf_fields
        )
        return selectors
class Document(object):
    variants = []
    def __init__(self, file):
        # TODO: Check for str or actual file inst?
        self._file = PDFQuery(file)
        self._data = {}
        self._check_configuration()
    @property
    def data(self):
        """Read only property that is loaded with document data once
        `extract()` is called.
        """
        return self._data
    def detect_variant(self):
        raise NotImplementedError('Subclass Document and override this method')
    def extract(self):
        self._file.load()
        variant = self.detect_variant()
        selectors = variant.as_pdf_selectors()
        extracted = self._file.extract(selectors)
        self._data = extracted
    def _check_configuration(self):
        if not self.variants:
            raise ValueError(
                "The class '{name}' hasn't been configured with any variants."
                " Set {name}.variants to a list of DocSchema types.".format(
                    name=self.__class__.__name__
                )
            )

import os
import json
import click
from cosmos import Data
def validate_filename(ctx, param, value):
    if os.path.dirname(value) and not os.path.isdir(os.path.dirname(value)):
        print('No such directory: {}'.format(value))
        ctx.exit()
    ext = os.path.splitext(value)[1]
    if ext not in ['.json', '.geojson']:
        raise click.BadParameter(
            'Only .json and .geojson filenames are accepted.')
    return value
@click.command()
@click.option('-l', '--location', type=str,
              help='input location name(city, country)', prompt=True)
@click.option('-f', '--filename', type=str, callback=validate_filename,
              help='output file name', prompt=True)
@click.option('-d', '--dtype', type=click.Choice(['roads', 'cities', 'buildings']),
              default='roads', help='data type')
@click.option('-b', '--bbox', type=(float, float, float, float),
              default=(None, None, None, None),
              help='bbox in form (west_lat, north_lon, east_lat, south_lon)')
def main(location, filename, dtype, bbox):
    data = Data(location)
    if None in bbox:
        bbox = None
    output = data.get(dtype, format='geojson', bbox=bbox)
    with open(os.path.expanduser(filename), 'w') as f:
        json.dump(output, f)

from scipy import optimize as o
import numpy as np
import clean as c
def local_minimize(func, options):
    bracket = options['bracket']
    bounds  = options['bounds']
    method  = options['method']
    tol     = options['tol']
    options = options['options']
    try:
        return o.minimize_scalar(func, bracket=bracket, bounds=bounds, method=method, tol=tol, options=options)
    except Exception as e:
        return str(e)
def global_minimize(func, options):
    guess            = options['guess']
    iterations       = options['iterations']
    temperature      = options['temperature']
    stepsize         = options['stepSize']
    include_all_mins = options['includeAllMinsFound']
    interval         = options['interval']
    res = []
    # basinhopping function accepts a callback - passes each intermediate local minima found to callback
    if (include_all_mins):
        def cb(a, b, c):
            res.append([a[0], b, c])
    else:
        cb = None
    try:
        answer = o.basinhopping(func, x0=guess, niter=iterations, stepsize=stepsize, T=temperature, callback=cb, interval=interval)
        answer['x'] = answer['x'].tolist()
        if (include_all_mins):
            answer['allMins'] = res
        return answer
    except Exception as e:
        return str(e)
def nnls(A, b):
    try:
        solution, residual = o.nnls(np.array(A), np.array(b))
        return {
            'solution': solution.tolist(),
            'residual': residual
        }
    except Exception as e:
        return str(e)

