					_tested_proxies[proxyid] = False
					return False

			except urllib.error.URLError as e:
				print("Proxy error",proxyid,e)
				_tested_proxies[proxyid] = False
				return False

		_tested_proxies[proxyid] = True
		return True	
	proxies[:] = [tup for tup in proxies if _testproxy(tup)]

	_tested_proxies = True

