import math
import re
def filter_thing_flags_read(value, table):
    """
    Filters a thing's flags value.

    Extended patches can use mnemonics for flag names, separated by plus signs.

    @raise LookupError: if the value contains an unknown mnemonic.
        """ 
    if value.isdigit() == True:
        return value

    items = re.split(r"[,+| \t\f\r]+", value)
    out = 0

    for item in items:
        item = item.strip()

        # Find the index of the flag mnemonic and convert it to a flag value.
        flag = table.flags.get(item)
        if flag is None:
            raise LookupError('Ignoring unknown thing flag {}.'.format(item))
        bit = int(math.pow(2, flag['index']))
        out += bit

    return out


def filter_thing_flags_write(value, table):
    """
    Returns a thing flags value as a string of mnemonics. 
    """

    bit = 1
    out = []

    for _ in range(0, 32):
        if (value & bit) == 0:
            bit *= 2
            continue

        for key, flag in table.flags.iteritems():
            if int(math.pow(2, flag['index'])) == bit:    
                out.append(key)
                break

        bit *= 2

    if len(out) == 0:
        return 0
    else:
        return '+'.join(out)

import collections
from data import crossword, warehouse
from puzzle.problems.crossword import _base_crossword_problem
class CrosswordProblem(_base_crossword_problem._BaseCrosswordProblem):
  @staticmethod
  def score(lines):
    return _base_crossword_problem.score(lines)
  def _solve(self):
    clue = ''.join(self.lines)
    clue_keywords = crossword.clue_keywords(clue)
    cursor = warehouse.get('/phrases/crossword/cursor')
    results = crossword.query(cursor, clue)
    if not results:
      return {}
    max_frequency = max([f for _, f, _ in results])
    ranked = []
    for (solution, frequency, keywords) in results:
      score = 0.0
      for keyword in clue_keywords:
        # Increase score by how often the keyword appeared in other clues.
        score += keywords[keyword] / frequency
      # Normalize score based on how many keywords were considered.
      score /= len(clue_keywords)
      rank = score * frequency / max_frequency
      if rank:
        ranked.append((solution, rank))
    return collections.OrderedDict(
        sorted(ranked, key=lambda x: x[1], reverse=True))

