def md_to_html(md_text):
    """Simple but solid Markdown to HTML converter using only stdlib."""
    lines = md_text.split('\n')
    html_lines = []
    in_code_block = False
    in_list = None  # 'ul' or 'ol'
    in_paragraph = False
    def close_list():
        nonlocal in_list
        if in_list:
            html_lines.append(f'</{in_list}>')
            in_list = None
    def close_para():
        nonlocal in_paragraph
        if in_paragraph:
            html_lines.append('</p>')
            in_paragraph = False
    def inline(text):
        # Images
        text = re.sub(r'!\[([^\]]*)\]\(([^)]+)\)', r'<img src="\2" alt="\1">', text)
        # Links
        text = re.sub(r'\[([^\]]+)\]\(([^)]+)\)', r'<a href="\2">\1</a>', text)
        # Bold+italic
        text = re.sub(r'\*\*\*(.+?)\*\*\*', r'<strong><em>\1</em></strong>', text)
        # Bold
        text = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', text)
        # Italic
        text = re.sub(r'\*(.+?)\*', r'<em>\1</em>', text)
        # Inline code
        text = re.sub(r'`([^`]+)`', r'<code>\1</code>', text)
        # Strikethrough
        text = re.sub(r'~~(.+?)~~', r'<del>\1</del>', text)
        return text
    for line in lines:
        # Code blocks
        if line.strip().startswith('```'):
            if in_code_block:
                html_lines.append('</code></pre>')
                in_code_block = False
            else:
                close_para()
                close_list()
                lang = line.strip()[3:].strip()
                cls = f' class="language-{html_mod.escape(lang)}"' if lang else ''
                html_lines.append(f'<pre><code{cls}>')
                in_code_block = True
            continue
        if in_code_block:
            html_lines.append(html_mod.escape(line))
            continue
        stripped = line.strip()
        # Empty line
        if not stripped:
            close_para()
            close_list()
            continue
        # Headings
        m = re.match(r'^(#{1,6})\s+(.+)$', stripped)
        if m:
            close_para()
            close_list()
            level = len(m.group(1))
            html_lines.append(f'<h{level}>{inline(m.group(2))}</h{level}>')
            continue
        # HR
        if re.match(r'^[-*_]{3,}\s*$', stripped):
            close_para()
            close_list()
            html_lines.append('<hr>')
            continue
        # Blockquote
        if stripped.startswith('>'):
            close_para()
            close_list()
            text = stripped.lstrip('>').strip()
            html_lines.append(f'<blockquote><p>{inline(text)}</p></blockquote>')
            continue
        # Unordered list
        m = re.match(r'^[-*+]\s+(.+)$', stripped)
        if m:
            close_para()
            if in_list != 'ul':
                close_list()
                html_lines.append('<ul>')
                in_list = 'ul'
            html_lines.append(f'<li>{inline(m.group(1))}</li>')
            continue
        # Ordered list
        m = re.match(r'^\d+\.\s+(.+)$', stripped)
        if m:
            close_para()
            if in_list != 'ol':
                close_list()
                html_lines.append('<ol>')
                in_list = 'ol'
            html_lines.append(f'<li>{inline(m.group(1))}</li>')
            continue
        # Paragraph
        if not in_paragraph:
            close_list()
            html_lines.append('<p>')
            in_paragraph = True
        html_lines.append(inline(stripped))
    close_para()
    close_list()
    if in_code_block:
        html_lines.append('</code></pre>')
    return '\n'.join(html_lines)
def main():
    parser = argparse.ArgumentParser(description='Convert Markdown to styled HTML')
    parser.add_argument('input', help='Input markdown file (use - for stdin)')
    parser.add_argument('-o', '--output', help='Output HTML file (default: stdout)')
    parser.add_argument('--theme', choices=['light', 'dark'], default='light')
    parser.add_argument('--title', default='Document')
    args = parser.parse_args()
    if args.input == '-':
        md_text = sys.stdin.read()
    else:
        with open(args.input, 'r') as f:
            md_text = f.read()
    css = LIGHT_CSS if args.theme == 'light' else DARK_CSS
    body = md_to_html(md_text)
    title = html_mod.escape(args.title)
    result = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>{title}</title>
<style>{css}</style>
</head>
<body>
{body}
</body>
</html>"""
    if args.output:
        with open(args.output, 'w') as f:
            f.write(result)
        print(f"Written to {args.output}", file=sys.stderr)
    else:
        print(result)
if __name__ == '__main__':
    main()

from pca9685 import PCA9685
import math
import time
class Servos:
    def __init__(self, i2c, address=0x40, freq=50, min_us=600, max_us=2400,
                 degrees=180):
        self.period = 1000000 / freq
        self.min_duty = self._us2duty(min_us)
        self.max_duty = self._us2duty(max_us)
        self.degrees = degrees
        self.freq = freq
        self.pca9685 = PCA9685(i2c, address)
        self.pca9685.freq(freq)
        self.positions = [0] * 16
    def _us2duty(self, value):
        return int(4095 * value / self.period)
    def position(self, index, degrees=None, radians=None, us=None, duty=None, push=True):
        ticks = time.ticks_us()
        if duty is not None:
            pass
        elif degrees is not None:
            span = self.max_duty - self.min_duty
            duty = self.min_duty + span * degrees / self.degrees
        elif radians is not None:
            span = self.max_duty - self.min_duty
            duty = self.min_duty + span * radians / math.radians(self.degrees)
        elif us is not None:
            duty = self._us2duty(us)
        elif duty is not None:
            pass
        else:
            return self.pca9685.duty(index)
        print('Conditional time:', time.ticks_diff(time.ticks_us(), ticks))
        #duty = min(self.max_duty, max(self.min_duty, int(duty)))
        ticks = time.ticks_us()
        self.positions[index] = duty
        print('Position time:', time.ticks_diff(time.ticks_us(), ticks))
        ticks = time.ticks_us()
        if push:
            self.pca9685.duty(index, duty)
        print('Push time:', time.ticks_diff(time.ticks_us(), ticks), 'push:', push)
    def duty(self, index, duty):
        self.positions[index] = duty
        self.pca9685.duty(index, duty)
    def release(self, index):
        self.pca9685.duty(index, 0)
    def releaseAll(self):
        for i in range(16): self.positions[i] = 0
        self.pushValues()
    def pushValues(self):
        self.pca9685.allpwm(self.positions)

