#/* Main */
def doJoysticking():
    """
    The method doJoysticking is the main function of the application.
    It parses the command line arguments, handles them, and then opens
    the main window and proceeds.
    """
    global verbosity
    # Local Variables to support parsing an Animatronics file specified
    # on the command line
    starttime = 0.0
    endtime = None
    rate = 10.0  # 10Hz
    tablefilename = None
    writetable = False
    skipbuttons = False
    outfilename = None
    animfilename = None
    # Parse arguments
    i = 1
    while i < len(sys.argv):
        if sys.argv[i] == '-' or sys.argv[i] == '-h' or sys.argv[i] == '-help':
            print_usage(sys.argv[0]);
            sys.exit(0);
        elif sys.argv[i] == '-V' or sys.argv[i] == '-version':
            exitcode = print_module_version('joysticking')
            sys.exit(exitcode)
        elif sys.argv[i] == '-v' or sys.argv[i] == '-verbose':
            verbosity = True
        elif sys.argv[i] == '-tw' or sys.argv[i] == '-tablewrite':
            i += 1
            if i < len(sys.argv):
                tablefilename = sys.argv[i]
                writetable = True
        elif sys.argv[i] == '-nb' or sys.argv[i] == '-nobuttons':
            skipbuttons = True
        elif sys.argv[i] == '-a' or sys.argv[i] == '-animfile':
            i += 1
            if i < len(sys.argv):
                animfilename = sys.argv[i]
        elif sys.argv[i] == '-o' or sys.argv[i] == '-outfile':
            i += 1
            if i < len(sys.argv):
                outfilename = sys.argv[i]
        elif sys.argv[i] == '-t' or sys.argv[i] == '-tablefile':
            i += 1
            if i < len(sys.argv):
                tablefilename = sys.argv[i]
        elif sys.argv[i] == '-s' or sys.argv[i] == '-start':
            i += 1
            if i < len(sys.argv):
                starttime = float(sys.argv[i])
        elif sys.argv[i] == '-e' or sys.argv[i] == '-end':
            i += 1
            if i < len(sys.argv):
                endtime = float(sys.argv[i])
        elif sys.argv[i] == '-r' or sys.argv[i] == '-rate':
            i += 1
            if i < len(sys.argv):
                rate = float(sys.argv[i])
        else:
            sys.stderr.write("\nWHOOPS - Unrecognized argument: %s\n" % sys.argv[i]);
            print_usage(sys.argv[0]);
            sys.exit(10);
        i += 1
    # Create the global main window
    app = QApplication(sys.argv)
    main_win = MainWindow()
    # Start with empty animation by default
    animation = Animatronics.Animatronics()
    # If an input file was specified, parse it or die trying
    if animfilename is not None:
        if os.path.isfile(animfilename):
            try:
                animation.parseXML(animfilename)
            except Exception as e:
                sys.stderr.write("\nWHOOPS - Error reading input file %s\n" % animfilename)
                sys.stderr.write("Message: %s\n" % e)
                sys.exit(11)
        else:
            sys.stderr.write("\nWHOOPS - Unable to use %s as a file\n" % animfilename)
            sys.exit(11)
    # Open the main window and process events
    main_win.setAnimatronics(animation)
    main_win.show()
    # Set the values that were input from arguments
    if rate > 20.0:
        sys.stderr.write('\nHmmm - specified record rate of %fHz may exceed polling rate of joystick.\n' % rate)
        sys.stderr.write('Polling rate utility available to check joystick rate.\n\n')
    main_win.setRate(rate)
    if starttime > 0.0:
        main_win.setStartTimeTo(starttime)
    if endtime is not None:
        main_win.setEndTimeTo(endtime)
    if tablefilename is not None:
        main_win.table.read(tablefilename)
        main_win.updateUIfromTable()
    app.exec()
if __name__ == "__main__":
    doJoysticking()

import shutil
from pathlib import Path
from unittest.mock import MagicMock
class MockLocalAGFS:
    """
    A mock implementation of AGFSClient that operates on a local directory.
    Useful for tests where running a real AGFS server is not feasible or desired.
    """
    def __init__(self, config=None, root_path=None):
        self.config = config
        self.root = Path(root_path) if root_path else Path("/tmp/viking_data")
        self.root.mkdir(parents=True, exist_ok=True)
    def _resolve(self, path):
        if str(path).startswith("viking://"):
            path = str(path).replace("viking://", "")
        if str(path).startswith("/"):
            path = str(path)[1:]
        return self.root / path
    def exists(self, path, ctx=None):
        return self._resolve(path).exists()
    def mkdir(self, path, ctx=None, parents=True, exist_ok=True):
        self._resolve(path).mkdir(parents=parents, exist_ok=exist_ok)
    def ls(self, path, ctx=None, **kwargs):
        p = self._resolve(path)
        if not p.exists():
            return []
        res = []
        for item in p.iterdir():
            res.append(
                {
                    "name": item.name,
                    "isDir": item.is_dir(),  # Note: JS style camelCase for some APIs
                    "type": "directory" if item.is_dir() else "file",
                    "size": item.stat().st_size if item.is_file() else 0,
                    "mtime": item.stat().st_mtime,
                    "uri": f"viking://{path}/{item.name}".replace("//", "/"),
                }
            )
        return res
    def writeto(self, path, content, ctx=None, **kwargs):
        p = self._resolve(path)
        p.parent.mkdir(parents=True, exist_ok=True)
        if isinstance(content, str):
            p.write_text(content, encoding="utf-8")
        else:
            p.write_bytes(content)
        return str(p)
    def write(self, path, content, ctx=None, **kwargs):
        return self.writeto(path, content, ctx, **kwargs)
    def write_file(self, path, content, ctx=None, **kwargs):
        return self.writeto(path, content, ctx, **kwargs)
    def read_file(self, path, ctx=None, **kwargs):
        p = self._resolve(path)
        if not p.exists():
            raise FileNotFoundError(path)
        return p.read_bytes()
    def read(self, path, ctx=None, **kwargs):
        return self.read_file(path, ctx, **kwargs)
    def rm(self, path, recursive=False, ctx=None):
        p = self._resolve(path)
        if p.exists():
            if p.is_dir():
                if recursive:
                    shutil.rmtree(p)
                else:
                    p.rmdir()
            else:
                p.unlink()
    def delete_temp(self, path, ctx=None):
        self.rm(path, recursive=True, ctx=ctx)
    def mv(self, src, dst, ctx=None):
        s = self._resolve(src)
        d = self._resolve(dst)
        d.parent.mkdir(parents=True, exist_ok=True)
        shutil.move(str(s), str(d))
    def stat(self, path, ctx=None):
        p = self._resolve(path)
        if not p.exists():
            raise FileNotFoundError(path)
        s = p.stat()
        return {"size": s.st_size, "mtime": s.st_mtime, "is_dir": p.is_dir()}
    def bind_request_context(self, ctx):
        return MagicMock(__enter__=lambda x: None, __exit__=lambda x, y, z: None)

