                      overrides: List[Mapping[str, Any]]):
    vllm_config = SimpleVllmConfig()
    for (subconfig_type, override) in zip(subconfig_types, overrides):
        if subconfig_type == "model":
            for key in override:
                setattr(vllm_config.model_config, key, override[key])
