def get_daily_ci_runs(token, num_runs=7):
    """Get the workflow runs of the scheduled (daily) CI.
    This only selects the runs triggered by the `schedule` event on the `main` branch.
    """
    headers = None
    if token is not None:
        headers = {"Accept": "application/vnd.github+json", "Authorization": f"Bearer {token}"}
    # The id of a workflow (not of a workflow run).
    # From a given workflow run (where we have workflow run id), we can get the workflow id by going to
    # https://api.github.com/repos/huggingface/transformers/actions/runs/{workflow_run_id}
    # and check the `workflow_id` key.
    workflow_id = "90575235"
    url = f"https://api.github.com/repos/huggingface/transformers/actions/workflows/{workflow_id}/runs"
    # On `main` branch + event being `schedule` + not returning PRs + only `num_runs` results
    url += f"?branch=main&event=schedule&exclude_pull_requests=true&per_page={num_runs}"
    result = requests.get(url, headers=headers).json()
    return result["workflow_runs"]
def get_last_daily_ci_runs(token):
    """Get the last completed workflow run id of the scheduled (daily) CI."""
    workflow_runs = get_daily_ci_runs(token)
    workflow_run_id = None
    for workflow_run in workflow_runs:
        if workflow_run["status"] == "completed":
            workflow_run_id = workflow_run["id"]
            break
    return workflow_run_id
def get_last_daily_ci_artifacts(artifact_names, output_dir, token):
    """Get the artifacts of last completed workflow run id of the scheduled (daily) CI."""
    workflow_run_id = get_last_daily_ci_runs(token)
    if workflow_run_id is not None:
        artifacts_links = get_artifacts_links(worflow_run_id=workflow_run_id, token=token)
        for artifact_name in artifact_names:
            if artifact_name in artifacts_links:
                artifact_url = artifacts_links[artifact_name]
                download_artifact(
                    artifact_name=artifact_name, artifact_url=artifact_url, output_dir=output_dir, token=token
                )
def get_last_daily_ci_reports(artifact_names, output_dir, token):
    """Get the artifacts' content of the last completed workflow run id of the scheduled (daily) CI."""
    get_last_daily_ci_artifacts(artifact_names, output_dir, token)
    results = {}
    for artifact_name in artifact_names:
        artifact_zip_path = os.path.join(output_dir, f"{artifact_name}.zip")
        if os.path.isfile(artifact_zip_path):
            results[artifact_name] = {}
            with zipfile.ZipFile(artifact_zip_path) as z:
                for filename in z.namelist():
                    if not os.path.isdir(filename):
                        # read the file
                        with z.open(filename) as f:
                            results[artifact_name][filename] = f.read().decode("UTF-8")
    return results

import os
import sys
import json
from datetime import datetime, timedelta
SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
PARENT_DIR = os.path.dirname(SCRIPT_DIR)
DATA_DIR = os.path.join(PARENT_DIR, 'data')
os.makedirs(DATA_DIR, exist_ok=True)
QUOTA_FILE = os.path.join(DATA_DIR, 'session_quota.json')
def load_quota():
    """Load quota data"""
    if os.path.exists(QUOTA_FILE):
        with open(QUOTA_FILE, 'r') as f:
            return json.load(f)
    return {
        'limits': {},  # {model: max_sessions_per_day}
        'usage': {},   # {date: {model: count}}
    }
def save_quota(quota):
    """Save quota data"""
    with open(QUOTA_FILE, 'w') as f:
        json.dump(quota, f, indent=2)
def set_limit(model, max_sessions):
    """Set session limit for a model"""
    quota = load_quota()
    quota['limits'][model] = max_sessions
    save_quota(quota)
    print(f"Set limit: {model} -> {max_sessions} sessions/day")
def record_session(model):
    """Record a session"""
    quota = load_quota()
    today = datetime.now().strftime('%Y-%m-%d')

    if today not in quota['usage']:
        quota['usage'][today] = {}

    if model not in quota['usage'][today]:
        quota['usage'][today][model] = 0

    quota['usage'][today][model] += 1
    save_quota(quota)
    print(f"Recorded session for {model}")
def check_quota(model):
    """Check if model has quota available"""
    quota = load_quota()
    today = datetime.now().strftime('%Y-%m-%d')

    limit = quota['limits'].get(model, -1)  # -1 = unlimited
    used = quota['usage'].get(today, {}).get(model, 0)

    if limit == -1:
        return {'available': True, 'limit': 'unlimited', 'used': used}

    available = limit - used
    return {
        'available': available > 0,
        'limit': limit,
        'used': used,
        'remaining': available
    }
def get_all_usage():
    """Get usage for all models today"""
    quota = load_quota()
    today = datetime.now().strftime('%Y-%m-%d')
    return quota['usage'].get(today, {})
def main():
    """CLI entry point"""
    if len(sys.argv) < 2:
        print("Usage: session_quota.py [set|record|check|usage]")
        sys.exit(1)

    command = sys.argv[1]

    if command == 'set':
        if len(sys.argv) < 4:
            print("Usage: session_quota.py set <model> <max_sessions>")
            sys.exit(1)
        set_limit(sys.argv[2], int(sys.argv[3]))
    elif command == 'record':
        if len(sys.argv) < 3:
            print("Usage: session_quota.py record <model>")
            sys.exit(1)
        record_session(sys.argv[2])
    elif command == 'check':
        if len(sys.argv) < 3:
            print("Usage: session_quota.py check <model>")
            sys.exit(1)
        print(json.dumps(check_quota(sys.argv[2]), indent=2))
    elif command == 'usage':
        print(json.dumps(get_all_usage(), indent=2))
    else:
        print(f"Unknown command: {command}")
        sys.exit(1)
if __name__ == '__main__':
    main()

from django.conf import settings
class FunctionRegistry:
    """Function registry for callback functions from NATS"""
    def __init__(self):
        self.registry = {}
    def register(self, name=None, func=None, **kwargs):
        # register(...)
        if func is not None:
            return self.register_function(func, name, **kwargs)
        # @register
        if name is not None and func is None and callable(name):
            return self.register_function(name, **kwargs)
        # @register(...)
        def dec(func):
            return self.register(name, func, **kwargs)
        return dec
    def register_function(self, func, name: str = None, **kwargs):
        namespace = kwargs.get('namespace', getattr(settings, 'NATS_NAMESPACE', 'default'))
        name = name or getattr(func, '_decorated_function', func).__name__
        js = kwargs.get('js', False)
        key = f'{namespace}.js.{name}' if js else f'{namespace}.{name}'
        if key in self.registry:
            raise ValueError(f'Duplicated NATS function key `{key}`.')
        self.registry[key] = {
            'func': func,
            'namespace': namespace,
            'name': name,
            'js': js,
        }
        return func
default_registry = FunctionRegistry()
register = default_registry.register

