            return [indent + lhs + " += " + rhs]
        if op == "Sub":
            return [indent + lhs + " -= " + rhs]
        if op == "Mult":
            return [indent + lhs + " *= " + rhs]
        if op == "Div":
            return [indent + lhs + " /= " + rhs]
        if op == "Mod":
            return [indent + lhs + " %= " + rhs]
        return [indent + lhs + " += " + rhs]
    if kind == "Swap":
        left = _target_name(stmt.get("left"))
        right = _target_name(stmt.get("right"))
        tmp = _fresh_tmp(ctx, "swap")
        return [
