            "types": dict(_type_map(ctx)),
            "return_type": ctx.get("return_type", ""),
            "continue_prefix": ctx.get("continue_prefix", ""),
            "break_label": ctx.get("break_label", ""),
            "continue_label": ctx.get("continue_label", ""),
            "yield_buffer": ctx.get("yield_buffer", ""),
