def load_dreambooth_lora(unet, vae=None, model_path=None, alpha=1.0, model_base=""):
    if model_path is None: return unet

    if model_path.endswith(".ckpt"):
        base_state_dict = torch.load(model_path)['state_dict']
    elif model_path.endswith(".safetensors"):
        state_dict = {}
        with safe_open(model_path, framework="pt", device="cpu") as f:
            for key in f.keys():
                state_dict[key] = f.get_tensor(key)

        is_lora = all("lora" in k for k in state_dict.keys())
        if not is_lora:
            base_state_dict = state_dict
        else:
            base_state_dict = {}
            with safe_open(model_base, framework="pt", device="cpu") as f:
                for key in f.keys():
                    base_state_dict[key] = f.get_tensor(key)

    converted_unet_checkpoint = convert_ldm_unet_checkpoint(base_state_dict, unet.config)
    unet_state_dict = unet.state_dict()
    for key in converted_unet_checkpoint:
        converted_unet_checkpoint[key] = alpha * converted_unet_checkpoint[key] + (1.0-alpha) * unet_state_dict[key]
    unet.load_state_dict(converted_unet_checkpoint, strict=False)
    if vae is not None:
        converted_vae_checkpoint = convert_ldm_vae_checkpoint(base_state_dict, vae.config)
        vae.load_state_dict(converted_vae_checkpoint)

    return unet, vae

import logging
import os
from collections.abc import Iterator
from pathlib import Path
logger = logging.getLogger(__name__)
IMAGE_EXTENSIONS = {".png", ".jpg", ".jpeg", ".webp", ".bmp"}
VIDEO_EXTENSIONS = {".mp4", ".avi", ".mov", ".mkv", ".webm"}
LORA_EXTENSIONS = {".safetensors"}
def iter_files(
    directory: Path,
    extensions: set[str],
    *,
    follow_symlinks: bool = True,
) -> Iterator[Path]:
    """Walk *directory* yielding files whose suffix is in *extensions*.
    Uses :func:`os.walk` with ``followlinks=follow_symlinks`` so that
    symlinked directories are traversed by default.  This is important on
    Windows where ``pathlib.rglob`` does not follow symlinks.
    Broken symlinks and inaccessible files are silently skipped.
    """
    if not directory.is_dir():
        return
    for root, _dirs, files in os.walk(directory, followlinks=follow_symlinks):
        root_path = Path(root)
        for filename in files:
            if Path(filename).suffix.lower() not in extensions:
                continue
            file_path = root_path / filename
            try:
                if file_path.is_file():
                    yield file_path
            except (OSError, PermissionError) as e:
                logger.debug(
                    "iter_files: skipping inaccessible file %s: %s", file_path, e
                )

