import json
import os
import ssl
import sys
import urllib.request
BF_API_KEY = os.environ.get('BF_API_KEY', '')
BF_BASE = 'https://bananafarmer.app/api/bot/v1'
def bf_get(endpoint, timeout=15):
    if not BF_API_KEY:
        print("ERROR: BF_API_KEY not set. Get your key at https://bananafarmer.app")
        sys.exit(1)
    url = f"{BF_BASE}/{endpoint}"
    headers = {'x-bf-bot-key': BF_API_KEY, 'User-Agent': 'BananaFarmerBot/1.0'}
    req = urllib.request.Request(url, headers=headers)
    ctx = ssl.create_default_context()
    try:
        with urllib.request.urlopen(req, timeout=timeout, context=ctx) as resp:
            body = json.loads(resp.read().decode('utf-8'))
            return body.get('data', body)
    except urllib.error.HTTPError as e:
        if e.code == 403:
            try:
                err_body = json.loads(e.read().decode('utf-8'))
                err_code = err_body.get('error', {}).get('code', '')
            except Exception:
                err_code = ''
            if err_code == 'TIER_ACCESS_DENIED':
                print(f"ERROR: This endpoint requires a higher tier. Upgrade at https://bananafarmer.app/pricing")
                print(f"  Endpoint: /{endpoint}")
                print(f"  Free tier has access to: health, discover, signals/top, requests/mine")
                return None
            print(f"ERROR: 403 Forbidden on /{endpoint}. Check your API key and User-Agent header.")
            return None
        elif e.code == 429:
            print(f"ERROR: Rate limit exceeded. Wait a moment and try again.")
            return None
        raise
def cmd_health():
    data = bf_get('health')
    if not data:
        print("Could not reach BF API")
        return
    status = data.get('marketStatus', data.get('market', {}).get('status', 'unknown'))
    freshness = data.get('dataFreshness', data.get('data', {}).get('freshness', 'unknown'))
    print(f"Market: {status}")
    print(f"Data freshness: {freshness}")
    if data.get('safetyAdvisory'):
        print(f"Advisory: {data['safetyAdvisory']}")
    print("System: OK")
def cmd_top(args):
    limit = 10
    badge = 'all'
    i = 0
    while i < len(args):
        if args[i] == '--limit' and i + 1 < len(args):
            limit = int(args[i + 1])
            i += 2
        elif args[i] == '--badge' and i + 1 < len(args):
            badge = args[i + 1]
            i += 2
        else:
            i += 1
    endpoint = f'signals/top?limit={limit}'
    if badge != 'all':
        endpoint += f'&badge={badge}'
    data = bf_get(endpoint)
    if not data:
        print("No signals available")
        return
    signals = data if isinstance(data, list) else data.get('signals', [])
    # Dedup by symbol
    seen = set()
    unique = []
    for s in signals:
        sym = s.get('symbol', '')
        if sym not in seen:
            seen.add(sym)
            unique.append(s)
    print(f"TOP {len(unique)} SIGNALS")
    print(f"{'Symbol':<8} {'Score':>5} {'Badge':<12} {'1d Change':<10} {'5d Change':<10}")
    print("-" * 52)
    for s in unique[:limit]:
        sym = s.get('symbol', '?')
        score = s.get('score', 0)
        badge_val = s.get('badge', '?')
        move = s.get('movement', {})
        c1d = move.get('priceChange1d', s.get('technicals', {}).get('change1d', ''))
        c5d = move.get('priceChange5d', s.get('technicals', {}).get('change5d', ''))
        print(f"${sym:<7} {score:>5} {badge_val:<12} {str(c1d):<10} {str(c5d):<10}")
        drivers = s.get('drivers', [])
        if drivers:
            print(f"         Drivers: {', '.join(drivers[:3])}")
def cmd_pulse():
    data = bf_get('market/pulse')
    if not data:
        print("Could not get market pulse")
        return
    print("MARKET PULSE")
    print("=" * 40)
    narrative = data.get('narrative')
    if narrative:
        if isinstance(narrative, dict):
            print(f"\n{narrative.get('summary', '')}")
        else:
            print(f"\n{narrative}")
    counts = data.get('signalCounts', data.get('counts', {}))
    if counts:
        print(f"\nSignal counts:")
        for badge, count in counts.items():
            print(f"  {badge}: {count}")
    trending = data.get('trending', [])
    if trending:
        if isinstance(trending, list):
            print(f"\nTrending: {', '.join(['$' + t.get('symbol', t) if isinstance(t, dict) else '$' + t for t in trending[:8]])}")
        elif isinstance(trending, dict):
            parts = []
            mover = trending.get('biggestMover')
            if mover and isinstance(mover, dict):
                parts.append(f"Biggest mover: ${mover.get('symbol', '?')} (+{mover.get('scoreChange', '?')})")
            sector = trending.get('hottestSector')
            if sector:
                parts.append(f"Hottest sector: {sector}")
            new_ripe_today = trending.get('newRipeToday', [])
            if new_ripe_today:
                symbols = ['$' + s for s in new_ripe_today[:5]]
                parts.append(f"New ripe: {', '.join(symbols)}")
            about = trending.get('aboutToRipe', [])
            if about:
                symbols = ['$' + s for s in about[:5]]
                parts.append(f"About to ripe: {', '.join(symbols)}")
            if parts:
                print(f"\n" + "\n".join(parts))
    new_ripe = data.get('newRipe', [])
    if new_ripe:
        print(f"\nNewly Ripe: {', '.join(['$' + s.get('symbol', s) if isinstance(s, dict) else '$' + s for s in new_ripe[:5]])}")
def main():
    if len(sys.argv) < 2:
        print("Usage: python3 bf-market.py <command> [options]")
        print()
        print("Commands:")
        print("  health              Check system and market status")
        print("  top [--limit N] [--badge ripe|ripening|all]")
        print("                      Show top momentum signals")
        print("  pulse               Market overview and trends")
        sys.exit(1)
    cmd = sys.argv[1].lower()
    if cmd == 'health':
        cmd_health()
    elif cmd == 'top':
        cmd_top(sys.argv[2:])
    elif cmd == 'pulse':
        cmd_pulse()
    else:
        print(f"Unknown command: {cmd}")
        sys.exit(1)
if __name__ == '__main__':
    main()

import logging
from flask import Blueprint, request, jsonify
from app.web import (
    require_auth,
    get_storage,
    _localize_timestamps,
)
log = logging.getLogger("docsis.web")
events_bp = Blueprint("events_bp", __name__)
@events_bp.route("/api/events", methods=["GET"])
@require_auth
def api_events_list():
    """Return list of events with optional filters."""
    _storage = get_storage()
    if not _storage:
        return jsonify({"events": [], "unacknowledged_count": 0})
    limit = request.args.get("limit", 200, type=int)
    offset = request.args.get("offset", 0, type=int)
    severity = request.args.get("severity") or None
    event_type = request.args.get("event_type") or None
    ack_param = request.args.get("acknowledged")
    acknowledged = int(ack_param) if ack_param is not None and ack_param != "" else None
    events = _storage.get_events(
        limit=limit, offset=offset, severity=severity,
        event_type=event_type, acknowledged=acknowledged,
    )
    unack = _storage.get_event_count(acknowledged=0)
    _localize_timestamps(events)
    return jsonify({"events": events, "unacknowledged_count": unack})
@events_bp.route("/api/events/count", methods=["GET"])
@require_auth
def api_events_count():
    """Return unacknowledged event count (for badge)."""
    _storage = get_storage()
    if not _storage:
        return jsonify({"count": 0})
    return jsonify({"count": _storage.get_event_count(acknowledged=0)})
@events_bp.route("/api/events/<int:event_id>/acknowledge", methods=["POST"])
@require_auth
def api_event_acknowledge(event_id):
    """Acknowledge a single event."""
    _storage = get_storage()
    if not _storage:
        return jsonify({"error": "Storage not initialized"}), 500
    if not _storage.acknowledge_event(event_id):
        return jsonify({"error": "Not found"}), 404
    return jsonify({"success": True})
@events_bp.route("/api/events/acknowledge-all", methods=["POST"])
@require_auth
def api_events_acknowledge_all():
    """Acknowledge all unacknowledged events."""
    _storage = get_storage()
    if not _storage:
        return jsonify({"error": "Storage not initialized"}), 500
    count = _storage.acknowledge_all_events()
    return jsonify({"success": True, "count": count})

import openai
import json
class FeedbackInterpreter:
    def __init__(self, api_key):
        openai.api_key = api_key
    def interpret(self, feedback_text):
        """
        Interprets natural language feedback and converts it into structured commands.
        """
        try:
            response = openai.chat.completions.create(
                model="gpt-4.1-mini",
                messages=[
                    {
                        "role": "system",
                        "content": "You are an expert in analyzing feedback for email generation. Your task is to convert natural language feedback into a structured JSON object. The user will provide feedback on an email, and you must extract the key sentiment, the specific aspect being criticized (e.g., tone, length, call-to-action), and a suggested modification. The possible values for 'aspect' are: 'tone', 'length', 'style', 'vocabulary', 'call_to_action', 'greeting', 'closing', 'clarity', 'urgency', 'personalization'. The possible values for 'sentiment' are 'positive', 'negative', 'neutral'. The 'modification' should be a concise instruction for an AI writer. If the feedback is vague, set 'modification' to 'general_improvement'."
                    },
                    {
                        "role": "user",
                        "content": f"The user's feedback is: '{feedback_text}'. Please convert this into a structured JSON object with the keys 'sentiment', 'aspect', and 'modification'."
                    }
                ],
                response_format={"type": "json_object"}
            )
            return response.choices[0].message.content
        except Exception as e:
            print(f"Error interpreting feedback: {e}")
            return json.dumps({"sentiment": "neutral", "aspect": "unknown", "modification": "general_improvement"})

import importlib.util
import json
import os
import warnings
from dataclasses import dataclass, field
import torch
from ..training_args import TrainingArguments
from ..utils import cached_property, is_sagemaker_dp_enabled, logging
logger = logging.get_logger(__name__)
# TODO: should be moved to `utils` after refactoring of SageMakerTrainer
def is_sagemaker_model_parallel_available():
    # Get the sagemaker specific mp parameters from smp_options variable.
    smp_options = os.getenv("SM_HP_MP_PARAMETERS", "{}")
    try:
        # Parse it and check the field "partitions" is included, it is required for model parallel.
        smp_options = json.loads(smp_options)
        if "partitions" not in smp_options:
            return False
    except json.JSONDecodeError:
        return False
    # Get the sagemaker specific framework parameters from mpi_options variable.
    mpi_options = os.getenv("SM_FRAMEWORK_PARAMS", "{}")
    try:
        # Parse it and check the field "sagemaker_distributed_dataparallel_enabled".
        mpi_options = json.loads(mpi_options)
        if not mpi_options.get("sagemaker_mpi_enabled", False):
            return False
    except json.JSONDecodeError:
        return False
    # Lastly, check if the `smdistributed` module is present.
    return importlib.util.find_spec("smdistributed") is not None
if is_sagemaker_model_parallel_available():
    import smdistributed.modelparallel.torch as smp
    smp.init()
@dataclass
class SageMakerTrainingArguments(TrainingArguments):
    mp_parameters: str = field(
        default="",
        metadata={"help": "Used by the SageMaker launcher to send mp-specific args. Ignored in SageMakerTrainer"},
    )
    def __post_init__(self):
        super().__post_init__()
        warnings.warn(
            "`SageMakerTrainingArguments` is deprecated and will be removed in v5 of Transformers. You can use "
            "`TrainingArguments` instead.",
            FutureWarning,
        )
    @cached_property
    def _setup_devices(self) -> "torch.device":
        logger.info("PyTorch: setting up devices")
        if torch.distributed.is_available() and torch.distributed.is_initialized() and self.local_rank == -1:
            logger.warning(
                "torch.distributed process group is initialized, but local_rank == -1. "
                "In order to use Torch DDP, launch your script with `python -m torch.distributed.launch"
            )
        if self.no_cuda:
            device = torch.device("cpu")
            self._n_gpu = 0
        elif is_sagemaker_model_parallel_available():
            local_rank = smp.local_rank()
            device = torch.device("cuda", local_rank)
            self._n_gpu = 1
        elif is_sagemaker_dp_enabled():
            import smdistributed.dataparallel.torch.torch_smddp  # noqa: F401
            torch.distributed.init_process_group(backend="smddp", timeout=self.ddp_timeout_delta)
            self.local_rank = int(os.getenv("SMDATAPARALLEL_LOCAL_RANK"))
            device = torch.device("cuda", self.local_rank)
            self._n_gpu = 1
        elif self.local_rank == -1:
            # if n_gpu is > 1 we'll use nn.DataParallel.
            # If you only want to use a specific subset of GPUs use `CUDA_VISIBLE_DEVICES=0`
            # Explicitly set CUDA to the first (index 0) CUDA device, otherwise `set_device` will
            # trigger an error that a device index is missing. Index 0 takes into account the
            # GPUs available in the environment, so `CUDA_VISIBLE_DEVICES=1,2` with `cuda:0`
            # will use the first GPU in that env, i.e. GPU#1
            device = torch.device("cuda:0" if torch.cuda.is_available() else "cpu")
            # Sometimes the line in the postinit has not been run before we end up here, so just checking we're not at
            # the default value.
            self._n_gpu = torch.cuda.device_count()
        else:
            # Here, we'll use torch.distributed.
            # Initializes the distributed backend which will take care of synchronizing nodes/GPUs
            if not torch.distributed.is_initialized():
                torch.distributed.init_process_group(backend="nccl", timeout=self.ddp_timeout_delta)
            device = torch.device("cuda", self.local_rank)
            self._n_gpu = 1
        if device.type == "cuda":
            torch.cuda.set_device(device)
        return device
    @property
    def world_size(self):
        if is_sagemaker_model_parallel_available():
            return smp.dp_size()
        return super().world_size
    @property
    def place_model_on_device(self):
        return not is_sagemaker_model_parallel_available()
    @property
    def _no_sync_in_gradient_accumulation(self):
        return False

import os
import pickle
from typing import Any, Dict
from pathlib import Path
from google_auth_oauthlib.flow import InstalledAppFlow
from googleapiclient.discovery import build
from google.auth.transport.requests import Request
from google.oauth2.credentials import Credentials

# Scopes for Gmail, Calendar, and Drive
SCOPES = [
    'https://www.googleapis.com/auth/gmail.readonly',
    'https://www.googleapis.com/auth/gmail.send',
    'https://www.googleapis.com/auth/gmail.modify',
    'https://www.googleapis.com/auth/calendar',
    'https://www.googleapis.com/auth/drive',
]

TOKEN_PATH = Path(__file__).parent / 'google_suite_tokens.json'
CREDENTIALS_PATH = Path(__file__).parent / 'google_suite_credentials.json'


def get_skill_info():
    return {
        "slug": "google-suite",
        "display_name": "Google Suite Skill",
        "tags": ["google", "gmail", "calendar", "drive", "api", "automation"],
        "description": "Unified access to Gmail, Google Calendar, and Google Drive APIs."
    }


def get_credentials() -> Credentials:
    creds = None
    if TOKEN_PATH.exists():
        creds = Credentials.from_authorized_user_file(str(TOKEN_PATH), SCOPES)
    # If there are no (valid) credentials available, let the user log in.
    if not creds or not creds.valid:
        if creds and creds.expired and creds.refresh_token:
            creds.refresh(Request())
        else:
            flow = InstalledAppFlow.from_client_config(
                {
                    "installed": {
                        "client_id": os.environ.get("GOOGLE_OAUTH_CLIENT_ID"),
                        "client_secret": os.environ.get("GOOGLE_OAUTH_CLIENT_SECRET"),
                        "redirect_uris": [os.environ.get("GOOGLE_OAUTH_REDIRECT_URI")],
                        "auth_uri": "https://accounts.google.com/o/oauth2/auth",
                        "token_uri": "https://oauth2.googleapis.com/token"
                    }
                },
                SCOPES
            )
            creds = flow.run_local_server(port=0)
        # Save the credentials for the next run
        with open(TOKEN_PATH, 'w') as token:
            token.write(creds.to_json())
    return creds


class GoogleSuiteSkill:
    def __init__(self):
        self.creds = get_credentials()

    def execute(self, params: Dict[str, Any]) -> Any:
        service = params.get("service")
        action = params.get("action")
        if service == "gmail":
            return self._handle_gmail(action, params)
        elif service == "calendar":
            return self._handle_calendar(action, params)
        elif service == "drive":
            return self._handle_drive(action, params)
        else:
            raise ValueError("Unknown service: {}".format(service))

    # Gmail operations
    def _handle_gmail(self, action, params):
        gmail = build('gmail', 'v1', credentials=self.creds)
        if action == "send":
            return self._gmail_send(gmail, params)
        elif action == "list":
            return self._gmail_list(gmail, params)
        elif action == "delete":
            return self._gmail_delete(gmail, params)
        else:
            raise ValueError(f"Unknown Gmail action: {action}")

    def _gmail_send(self, gmail, params):
        from email.mime.text import MIMEText
        import base64
        message = MIMEText(params.get("body", ""))
        message['to'] = params.get("to")
        message['subject'] = params.get("subject", "")
        raw = base64.urlsafe_b64encode(message.as_bytes()).decode()
        body = {'raw': raw}
        sent = gmail.users().messages().send(userId="me", body=body).execute()
        return {"id": sent.get("id"), "status": "sent"}

    def _gmail_list(self, gmail, params):
        query = params.get("query", "in:inbox")
        max_results = int(params.get("max_results", 10))
        results = gmail.users().messages().list(userId="me", q=query, maxResults=max_results).execute()
        messages = results.get('messages', [])
        emails = []
        for msg in messages:
            msg_detail = gmail.users().messages().get(userId="me", id=msg['id']).execute()
            snippet = msg_detail.get('snippet', '')
            emails.append({"id": msg['id'], "snippet": snippet})
        return emails

    def _gmail_delete(self, gmail, params):
        msg_id = params.get("message_id")
        if not msg_id:
            raise ValueError("message_id is required for delete action")
        gmail.users().messages().delete(userId="me", id=msg_id).execute()
        return {"id": msg_id, "status": "deleted"}

    # Calendar operations
    def _handle_calendar(self, action, params):
        calendar = build('calendar', 'v3', credentials=self.creds)
        if action == "list":
            return self._calendar_list(calendar, params)
        elif action == "create":
            return self._calendar_create(calendar, params)
        elif action == "update":
            return self._calendar_update(calendar, params)
        elif action == "delete":
            return self._calendar_delete(calendar, params)
        else:
            raise ValueError(f"Unknown Calendar action: {action}")

    def _calendar_list(self, calendar, params):
        from datetime import datetime, timedelta
        now = datetime.utcnow().isoformat() + 'Z'
        days = int(params.get("days", 7))
        end = (datetime.utcnow() + timedelta(days=days)).isoformat() + 'Z'
        events_result = calendar.events().list(
            calendarId='primary', timeMin=now, timeMax=end,
            maxResults=int(params.get("max_events", 10)), singleEvents=True,
            orderBy='startTime').execute()
        events = events_result.get('items', [])
        return [{"id": e["id"], "summary": e.get("summary"), "start": e["start"], "end": e["end"]} for e in events]

    def _calendar_create(self, calendar, params):
        event = {
            'summary': params.get('summary'),
            'start': {'dateTime': params.get('start')},
            'end': {'dateTime': params.get('end')},
        }
        created = calendar.events().insert(calendarId='primary', body=event).execute()
        return {"id": created["id"], "status": "created"}

    def _calendar_update(self, calendar, params):
        event_id = params.get('event_id')
        if not event_id:
            raise ValueError("event_id is required for update action")
        event = calendar.events().get(calendarId='primary', eventId=event_id).execute()
        if 'summary' in params:
            event['summary'] = params['summary']
        if 'start' in params:
            event['start']['dateTime'] = params['start']
        if 'end' in params:
            event['end']['dateTime'] = params['end']
        updated = calendar.events().update(calendarId='primary', eventId=event_id, body=event).execute()
        return {"id": updated["id"], "status": "updated"}

    def _calendar_delete(self, calendar, params):
        event_id = params.get('event_id')
        if not event_id:
            raise ValueError("event_id is required for delete action")
        calendar.events().delete(calendarId='primary', eventId=event_id).execute()
        return {"id": event_id, "status": "deleted"}

    # Drive operations
    def _handle_drive(self, action, params):
        drive = build('drive', 'v3', credentials=self.creds)
        if action == "list":
            return self._drive_list(drive, params)
        elif action == "upload":
            return self._drive_upload(drive, params)
        elif action == "download":
            return self._drive_download(drive, params)
        elif action == "delete":
            return self._drive_delete(drive, params)
        else:
            raise ValueError(f"Unknown Drive action: {action}")

    def _drive_list(self, drive, params):
        query = params.get("query", "")
        max_files = int(params.get("max_files", 10))
        results = drive.files().list(q=query, pageSize=max_files, fields="files(id, name)").execute()
        files = results.get('files', [])
        return [{"id": f["id"], "name": f["name"]} for f in files]

    def _drive_upload(self, drive, params):
        from googleapiclient.http import MediaFileUpload
        file_path = params.get("file_path")
        if not file_path or not os.path.exists(file_path):
            raise ValueError("file_path is required and must exist for upload action")
        file_metadata = {'name': os.path.basename(file_path)}
        media = MediaFileUpload(file_path, resumable=True)
        uploaded = drive.files().create(body=file_metadata, media_body=media, fields='id').execute()
        return {"id": uploaded["id"], "status": "uploaded"}

    def _drive_download(self, drive, params):
        file_id = params.get("file_id")
        dest_path = params.get("dest_path")
        if not file_id or not dest_path:
            raise ValueError("file_id and dest_path are required for download action")
        request = drive.files().get_media(fileId=file_id)
        with open(dest_path, 'wb') as f:
            from googleapiclient.http import MediaIoBaseDownload
            import io
            downloader = MediaIoBaseDownload(f, request)
            done = False
            while not done:
                status, done = downloader.next_chunk()
        return {"id": file_id, "status": "downloaded", "path": dest_path}

    def _drive_delete(self, drive, params):
        file_id = params.get("file_id")
        if not file_id:
            raise ValueError("file_id is required for delete action")
        drive.files().delete(fileId=file_id).execute()
        return {"id": file_id, "status": "deleted"}

