# Import necessary modules
import numpy as N
import gobject
import gtk.gdk

class DeltaDetector(object):
    def __init__(self, active=False, threshold=20.0):
        # Initialize instance variables
        self._previous_frame = None
        self._frame = None
        self.active = active
        self.threshold = threshold
        self._timed_out = False

    def send_frame(self, frame):
        # Update frames
        self._previous_frame = self._frame
        self._frame = N.array(frame, dtype=float)

        # Early exit conditions
        if self._timed_out:
            return
        if not self.active:
            return
        if self._previous_frame is None:
            return

        # Check shape compatibility
        if(self._previous_frame.shape != self._frame.shape):
            self._previous_frame = None
            return

        # Detect significant changes and beep if threshold exceeded
        if N.max(N.abs(self._frame - self._previous_frame)) > self.threshold:
            gtk.gdk.beep()

            # Prevent multiple beeps within one second
            self._timed_out = True
            gobject.timeout_add(1000, self._switch_on_timeout)

    def _switch_on_timeout(self):
        # Reset timeout flag after 1 second
        self._timed_out = False
        return False

    # Properties for active attribute
    @property
    def active(self):
        return self._active

    @active.setter
    def active(self, value):
        self._active = bool(value)

    # Properties for threshold attribute
    @property
    def threshold(self):
        return self._threshold

    @threshold.setter
    def threshold(self, value):
        self._threshold = float(value)

    # Property to compute average difference between frames
    @property
    def average(self):
        if self._frame is None or self._previous_frame is None:
            return 0.0
        return N.mean(self._frame - self._previous_frame)

