            self._resource = value
        else:
            raise ValueError("Unable to store value as requested.")

    @resource.comparator
    def resource(cls):
        return IdnaComparator(cls._resource)

# Import necessary libraries
import numpy as np

def readPointCloudFromPly(path):
    # Open the PLY file for reading
    f = open(path, 'r')

    points = []

    headerSkipped = False
    for line in f:
        if headerSkipped:
            # Parse point coordinates and convert to float32
            points.append(np.float32(np.array(line.split(' ')[0:3])))
        else:
            # Check if we've reached the end of the header
            headerSkipped = line.find('end_header') != -1

    f.close()  # Close the file
    return points


def readPointAssignementFromFiles(path):
    # Open the assignment file
    f = open(path, 'r')

    assignement = []

    for line in f:
        # Skip comment lines
        if line[0] != '#':
            # Parse assignment data and convert to int16
            assignement.append(np.int16(line.split(',')[0:2]))

    f.close()  # Close the file
    return assignement


def readPrimitiveCorrespondancesFromFiles(path, primset1, primset2):
    # Open the correspondences file
    f = open(path, 'r')

    corresp    = {}
    correspUid = {}

    for line in f:
        # Skip comment lines
        if line[0] != '#':
            # Parse the line into six integer values
            fline = np.int16(line.split(',')[0:6])

            p1 = None
            p2 = None

            # Search for matching primitives in first set
            for p in primset1:
                if p.uid == fline[0] and p.did == fline[2]:
                    p1 = p
                    break

            # Search for matching primitives in second set
            for p in primset2:
                if p.uid == fline[3] and p.did == fline[5]:
                    p2 = p
                    break

            # If both primitives found, add to correspondence maps
            if (p1 != None and p2 != None):
                corresp[p1] = p2
                correspUid[p1.uid] = p2.uid
            else: 
                print "Cannot find ",fline

    f.close()  # Close the file

    return corresp, correspUid

# Import type hints and built-in modules
import typing as tp
import builtins as py

# Import custom optional module
from .optional import Optional, optional

# Define type variables for generic dictionary
K = tp.TypeVar('K')
V = tp.TypeVar('V')


class Dictionary(tp.Generic[K, V], tp.Iterable[tp.Tuple[K, V]]):
    def __init__(self, entries: tp.Dict[K, V]) -> None:
        # Initialize internal dictionary using built-in dict constructor
        self._entries: tp.Dict[K, V] = py.dict(entries)

    def __getitem__(self, key: K) -> Optional[V]:
        # Return optional value for the given key
        return optional(self._entries.get(key))

    def __setitem__(self, key: K, value: V) -> None:
        # Set the value for the given key
        self._entries[key] = value

    @property
    def keys(self) -> tp.Iterable[K]:
        # Return iterable of keys
        return self._entries.keys()

    @property
    def values(self) -> tp.Iterable[V]:
        # Return iterable of values
        return self._entries.values()

    def for_each(self, body: tp.Callable[[K, V], None]) -> None:
        # Iterate over all entries and apply the given function
        for key, value in self._entries.items():
            body(key, value)

    @property
    def count(self) -> int:
        # Return number of entries
        return len(self._entries)

    def remove_all(self) -> None:
        # Clear all entries
        self._entries.clear()

    def __iter__(self) -> tp.Iterator[tp.Tuple[K, V]]:
        # Return iterator over key-value pairs
        return self._entries.items().__iter__()

