import random
from contextlib import contextmanager, ContextDecorator
from time import time, sleep
from locust import User, task, constant, events

# Custom context manager for manual reporting
@contextmanager
def _manual_report(name):
    # Record start time
    start_time = time()

    try:
        yield
    except Exception as e:
        # Report failure on exception
        events.request_failure.fire(
            request_type="manual",
            name=name,
            response_time=(time() - start_time) * 1000,
            response_length=0,
            exception=e,
        )
        raise
    else:
        # Report success if no exception
        events.request_success.fire(
            request_type="manual",
            name=name,
            response_time=(time() - start_time) * 1000,
            response_length=0,
        )

# Decorator function for manual reporting
def manual_report(name_or_func):
    if callable(name_or_func):
        # Used as decorator without name argument specified
        return _manual_report(name_or_func.__name__)(name_or_func)
    else:
        return _manual_report(name_or_func)

# User class definition
class MyUser(User):
    wait_time = constant(1)

    @task
    def successful_task(self):
        with manual_report("successful_task"):
            sleep(random.random())

    @task
    @manual_report
    def decorator_test(self):
        if random.random() > 0.5:
            raise Exception("decorator_task failed")
        sleep(random.random())

    @task
    def failing_task(self):
        with manual_report("failing_task"):
            sleep(random.random())
            raise Exception("Oh nooes!")

