def groupfinder(login, request):
    # Check if login contains a colon separator
    if ':' not in login:
        return None

    # Split login into namespace and localname
    namespace, localname = login.split(':', 1)

    # Handle mailto namespace
    if namespace == 'mailto':
        session = DBSession()
        model = session.query(UserMap).get(login)

        # Return None if user not found
        if model is None:
            return None

        user = model.user
        principals = ['userid:' + str(user.rid)]

        # Add lab groups
        principals.extend('lab:' + lab_uuid for lab_uuid in user.statement.object.get('lab_uuids', []))

        return principals

    # Handle remoteuser namespace
    elif namespace == 'remoteuser':
        if localname in ['TEST', 'IMPORT']:
            return ['group:admin']

