import sys, os

def getrevlimit():
    # Get maximum revision limit from environment variable
    var = 'SVNRMAX'
    if os.environ.has_key(var):
        return os.environ[var]
    return None

def writedump(url, lower, upper):
    # Process URL and open file for reading
    if url.startswith('sim://'):
        filename = url[6:]
        if filename[-1] == '/':
            filename = filename[:-1]  # Remove terminating slash
    else:
        raise ValueError('sim:// url required')

    f = open(filename, 'r')
    state = 'header'
    wroterev = False

    while(True):
        l = f.readline()
        if l == '':
            break

        # State transitions based on revision markers
        if state == 'header' and l.startswith('Revision-number: '):
            state = 'prefix'

        if state == 'prefix' and l == 'Revision-number: %s\n' % lower:
            state = 'selection'

        if not upper == 'HEAD' and state == 'selection' and l == 'Revision-number: %s\n' % upper:
            break

        # Write lines in header or selection state
        if state == 'header' or state == 'selection':
            if state == 'selection':
                wroterev = True
            sys.stdout.write(l)

    return wroterev

