def get_people_from_memberships(election_data, memberships):
    # Initialize sets for current and past candidates
    current_candidates = set()
    past_candidates = set()

    # Process each membership record
    for membership in memberships:
        # Skip if membership role doesn't match candidate role
        if not membership.get('role') == election_data['candidate_membership_role']:
            continue

        # Create person object from membership data
        person = PopItPerson.create_from_dict(membership['person_id'])

        # Check if membership covers the election date
        if membership_covers_date(
                membership,
                election_data['election_date']
        ):
            current_candidates.add(person)
        else:
            # Check other elections for past candidate determination
            for other_election, other_election_data in settings.ELECTIONS_BY_DATE:
                # Skip elections not suitable for candidate suggestions
                if not other_election_data.get('use_for_candidate_suggestions'):
                    continue

                # Check if membership covers this other election's date
                if membership_covers_date(
                        membership,
                        other_election_data['election_date'],
                ):
                    past_candidates.add(person)

    # Return both sets of candidates
    return current_candidates, past_candidates

# Import system module
import sys

class Platform(object):
    # Check if platform is Darwin (macOS)
    @staticmethod
    def is_darwin(name=None):
        name = name or sys.platform
        return 'darwin' in name

    # Check if platform is FreeBSD
    @staticmethod
    def is_freebsd(name=None):
        name = name or sys.platform
        return name.startswith("freebsd")

    # Check if platform is Linux
    @staticmethod
    def is_linux(name=None):
        name = name or sys.platform
        return 'linux' in name

    # Check if platform is BSD-like (Darwin or FreeBSD)
    @staticmethod
    def is_bsd(name=None):
        """ Return true if this is a BSD like operating system. """
        name = name or sys.platform
        return Platform.is_darwin(name) or Platform.is_freebsd(name)

    # Check if platform is Solaris
    @staticmethod
    def is_solaris(name=None):
        name = name or sys.platform
        return name == "sunos5"

    # Check if platform is Unix-like
    @staticmethod
    def is_unix(name=None):
        """ Return true if the platform is a unix, False otherwise. """
        name = name or sys.platform
        return (Platform.is_darwin()
                or Platform.is_linux()
                or Platform.is_freebsd()
        )

    # Check if platform is Windows
    @staticmethod
    def is_win32(name=None):
        name = name or sys.platform
        return name == "win32"

import discord

def user_to_bot_ratio(guild: discord.Guild):
    # Count bots and users in the guild
    bots, users = 0, 0
    for member in guild.members:
        if member.bot:
            bots += 1
        else:
            users += 1

    # Avoid division by zero
    if users == 0:
        return float('inf')

    return bots / users

async def is_blacklisted(bot, guild_id: int) -> bool:
    """ Returns a bool indicating whether a guild has been blacklisted. """
    async with bot.pgpool.acquire() as conn:
        blacklisted_record = await conn.fetchrow(
            'SELECT * FROM blacklisted_guilds WHERE guild_id = $1', 
            guild_id
        )
        return blacklisted_record is not None

async def is_bot_collection(bot, guild: discord.Guild):
    """ Returns a bool indicating whether a guild is a collection. """
    # Check if guild is blacklisted
    if await is_blacklisted(bot, guild.id):
        return True

    # Keywords in the guild name
    if any([keyword in guild.name.lower() for keyword in ('bot collection', 'bot hell')]):
        return True

    # Special guilds that shouldn't be classified as a bot collection
    if guild.id in (110373943822540800, 228317351672545290):
        return False

    # Ratio too big!
    if user_to_bot_ratio(guild) >= 8:
        return True

    return False

