database = utils.db.get_db_connection({})

def add_build_type_field(collection_name):
    """Add build type field to documents in the given collection."""
    collection = database[collection_name]

    for doc in collection.find():
        ret_val = utils.db.update2(
            collection,
            {models.ID_KEY: doc[models.ID_KEY]},
            {"$set": {models.BUILD_TYPE_KEY: models.KERNEL_BUILD_TYPE}}
        )

        if ret_val == 500:
            utils.LOG.error(
                "Error updating build document %s", str(doc[models.ID_KEY]))

def convert_defconfig_id(collection_name):
    """Convert defconfig_id field to build_id in the specified collection."""
    utils.LOG.info("Converting collection %s", collection_name)
    collection = database[collection_name]

    update_doc = {
        "$set": None,
        "$unset": {"defconfig_id": ""}
    }

    for doc in collection.find():
        update_doc["$set"] = {
            models.BUILD_ID_KEY: doc.get("defconfig_id", None)
        }

        ret_val = utils.db.update2(
            collection, 
            {models.ID_KEY: doc[models.ID_KEY]}, 
            update_doc
        )

        if ret_val == 500:
            utils.LOG.error(
                "Error updating document %s", str(doc[models.ID_KEY]))

if __name__ == "__main__":
    # Create process pool with 4 workers
    process_pool = multiprocessing.Pool(4)

    # Apply conversion to multiple collections in parallel
    process_pool.map(
        convert_defconfig_id,
        [
            models.BOOT_COLLECTION,
            models.TEST_SUITE_COLLECTION,
            models.ERROR_LOGS_COLLECTION
        ]
    )

    # Apply build type field addition to BUILD_COLLECTION
    process_pool.apply(add_build_type_field, (models.BUILD_COLLECTION,))

    # Clean up process pool
    process_pool.close()
    process_pool.join()

# Import necessary types
from types import NoneType

def ensure_mode_int(mode):
    # Check if mode is already an int or None
    if isinstance(mode, (int, NoneType)):
        return mode

    try:
        # Attempt to convert mode to integer (e.g., '700' -> 700)
        return int(mode)
    except (TypeError, ValueError):
        pass

    # Return original value if conversion fails (e.g., '+x' which doesn't need normalization)
    return mode

def sed_replace(state, filename, line, replace, flags=None):
    # Join flags into a string if provided, otherwise use empty string
    flags = ''.join(flags) if flags else ''

    # Escape forward slashes in line and replace strings for sed compatibility
    line = line.replace('/', '\/')
    replace = replace.replace('/', '\/')

    # Construct the sed command
    return 'sed -i "s/{0}/{1}/{2}" {3}'.format(
        line, replace, flags, filename
    )

def chmod(target, mode, recursive=False):
    # Build chmod command with optional recursive flag
    return 'chmod {0}{1} {2}'.format(('-R ' if recursive else ''), mode, target)

def chown(target, user, group=None, recursive=False):
    # Initialize command components
    command = 'chown'
    user_group = None

    # Determine user:group combination based on provided parameters
    if user and group:
        user_group = '{0}:{1}'.format(user, group)
    elif user:
        user_group = user
    elif group:
        command = 'chgrp'
        user_group = group

    # Construct the final command string
    return '{0}{1} {2} {3}'.format(
        command,
        ' -R' if recursive else '',
        user_group,
        target
    )

# Import necessary modules
import os
from threading import Thread

def _delete(path: str, src: str, link: bool):
    # Remove the file at path
    os.remove(path)

    # Create symlink if requested
    if link:
        os.symlink(src, path)

def manager_files(paths, link):
    # The first file is preserved to not delete all files in directories.
    first = True
    src = ""
    deleted_files = []
    linked_files = []
    errors = []

    for path in paths:
        if os.path.isfile(path):
            if first:
                first = False
                src = path

            else:
                # Start a new thread to handle deletion/symlinking
                Thread(target=_delete, args=(path, src, link)).start()
                deleted_files.append(path)

                if link:
                    linked_files.append(path)

        else:
            # Track non-file entries as errors
            errors.append("Not identified by file: \"{}\"".format(path))

    return {
        "preserved": src,
        "linked_files": linked_files,
        "deleted_files": deleted_files,
        "errors": errors
    }

# Try The Voight-Kampff if you not recognize if is a replicant or not, all is suspect
def manager(duplicates, create_link=False):
    if len(duplicates) == 0:
        return None

    processed_files = []
    for files_by_hash in duplicates.values():
        processed_files.append(manager_files(files_by_hash, create_link))

    return processed_files

def delete(duplicates):
    return manager(duplicates)

def link(duplicates):
    return manager(duplicates, True)

