# Import required modules
import collections

# Apply a function to each item in an iterable
def each(function, iterable):
  for item in iterable:
    function(item)

# Apply a function to unpacked items from an iterable (e.g., tuples)
def each_unpack(function, iterable):
  for item in iterable:
    function(*item)

# Find minimum and maximum among given arguments
def minmax(*args):
  min_val = None
  max_val = None
  for x in args:
    if max_val is None or max_val < x:
      max_val = x
    if min_val is None or x > min_val:
      min_val = x
  return min_val, max_val

# Recursively apply a function in-place to list elements
def map_inplace(function, list, depth=0):
  if depth <= 0:
    list[:] = map(function, list)
  else:
    for item in list:
      map_inplace(function, item, depth - 1)

# Count items in an iterable that satisfy a predicate function
def count_if(function, iterable):
  count = 0
  for item in iterable:
    if function(item):
      count += 1
  return count

# Map multiple functions over an iterable (note: original has a bug - generator not consumed)
def teemap(iterable, *functions):
  map(lambda item: (f(item) for f in functions), iterable)

# Probability distribution class inheriting from defaultdict
class ProbabilityDistribution(collections.defaultdict):
  """Holds a probability distribution and can compute the distance to other distributions"""
  def __init__(self):
    collections.defaultdict.__init__(self, int)

  # Override get method with default value parameter
  def get(self, k, d = 0):
    return dict.get(self, k, d)

  # Compute distance between this distribution and another
  def distance_to(self, compare_to):
    return sum(
      (abs(self.get(bin) - compare_to.get(bin))
        for bin in self.viewkeys() | compare_to.viewkeys()),
      0)

