    def __init__(self, bbox, type=DocFieldType.TEXT, required=False,
                 description=None):
        self.bbox = bbox
        self.type = type
        self.required = required
        self.description = description

# Defines a schema for extracting data from documents
class DocSchema(object):
    @classmethod
    def as_pdf_selectors(cls, field_name=None):
        """Return pdfminer selector for specified field. If no field is
        specified, then selectors for all fields are returned.
        """
        if field_name is not None:
            field = getattr(cls, field_name, None)
            if (field is None) or (not isinstance(field, DocField)):
                raise ValueError(
                    '{field} is not a DocField attribute on {klass}'.format(
                        field=field_name, klass=cls.__name__
                    )
                )
            pdf_fields = [('assessment_year', field)]
        else:
            pdf_fields = inspect.getmembers(
                cls, lambda f: isinstance(f, DocField)
            )

        selectors = [('with_formatter', 'text')]
        selectors.extend(
            (key, 'LTTextLineHorizontal:in_bbox("{bbox}")'.format(
                bbox=', '.join(str(coord) for coord in field.bbox)
            ))
            for key, field in pdf_fields
        )
        return selectors

# Base class representing a document to be processed
class Document(object):
    variants = []

    def __init__(self, file):
        # TODO: Check for str or actual file inst?
        self._file = PDFQuery(file)
        self._data = {}
        self._check_configuration()

    @property
    def data(self):
        """Read only property that is loaded with document data once
        `extract()` is called.
        """
        return self._data

    def detect_variant(self):
        raise NotImplementedError('Subclass Document and override this method')

    def extract(self):
        self._file.load()
        variant = self.detect_variant()
        selectors = variant.as_pdf_selectors()
        extracted = self._file.extract(selectors)
        self._data = extracted

    def _check_configuration(self):
        if not self.variants:
            raise ValueError(
                "The class '{name}' hasn't been configured with any variants."
                " Set {name}.variants to a list of DocSchema types.".format(
                    name=self.__class__.__name__
                )
            )

# Import required libraries
from scipy import optimize as o
import numpy as np
import clean as c

def local_minimize(func, options):
    # Extract optimization parameters
    bracket = options['bracket']
    bounds  = options['bounds']
    method  = options['method']
    tol     = options['tol']
    options = options['options']

    try:
        # Perform local minimization using scipy's minimize_scalar
        return o.minimize_scalar(func, bracket=bracket, bounds=bounds, method=method, tol=tol, options=options)
    except Exception as e:
        return str(e)

def global_minimize(func, options):
    # Extract global optimization parameters
    guess            = options['guess']
    iterations       = options['iterations']
    temperature      = options['temperature']
    stepsize         = options['stepSize']
    include_all_mins = options['includeAllMinsFound']
    interval         = options['interval']

    res = []

    # basinhopping function accepts a callback - passes each intermediate local minima found to callback
    if (include_all_mins):
        def cb(a, b, c):
            res.append([a[0], b, c])
    else:
        cb = None

    try:
        # Perform global minimization using basinhopping
        answer = o.basinhopping(func, x0=guess, niter=iterations, stepsize=stepsize, T=temperature, callback=cb, interval=interval)
        answer['x'] = answer['x'].tolist()

        if (include_all_mins):
            answer['allMins'] = res

        return answer
    except Exception as e:
        return str(e)

def nnls(A, b):
    try:
        # Solve non-negative least squares problem
        solution, residual = o.nnls(np.array(A), np.array(b))
        return {
            'solution': solution.tolist(),
            'residual': residual
        }
    except Exception as e:
        return str(e)

