# TypeScript file scanner tests for framework detection and decorated names
from skylos.visitors.languages.typescript import scan_typescript_file

def _scan(tmp_path, filename, code):
    # Write the code to a temporary file
    p = tmp_path / filename
    p.write_text(code, encoding="utf-8")

    # Scan the file and extract results
    result = scan_typescript_file(str(p))
    defs = result[0]  # definitions
    fw = result[5]    # framework_flags slot

    return defs, fw


def _decorated_names(defs, fw):
    # Extract names of definitions that are on framework-decorated lines
    return {d.name for d in defs if d.line in fw.framework_decorated_lines}


