    table = boto3.resource("dynamodb").Table(Resources.items.table_name)

    # Extract HTTP method and path parameters
    method = event["httpMethod"]
    path_params = event.get("pathParameters") or {}
    item_id = path_params.get("id")

    # Handle POST request - create new item
    if method == "POST":
        body = json.loads(event["body"])
        table.put_item(Item=body)
        return {"statusCode": 201, "body": json.dumps(body)}

    # Handle GET request - retrieve specific item by ID
    if method == "GET" and item_id:
        resp = table.get_item(Key={"pk": item_id})
        item = resp.get("Item")
        if not item:
            return {"statusCode": 404, "body": "not found"}
        return {"statusCode": 200, "body": json.dumps(item)}

    # Handle DELETE request - remove item by ID
    if method == "DELETE" and item_id:
        table.delete_item(Key={"pk": item_id})
        return {"statusCode": 200, "body": "deleted"}

    # Default response for invalid requests
    return {"statusCode": 400, "body": "bad request"}

# Import required modules
import os
import sys
import json
import requests
from datetime import datetime


class CodexAdapter:
    def __init__(self, api_key=None, api_url=None):
        # Initialize with provided or environment variables
        self.api_key = api_key or os.getenv('CODEX_API_KEY')
        self.api_url = api_url or os.getenv('CODEX_API_URL')

        # Validate required configuration
        if not self.api_key or not self.api_url:
            raise ValueError("CODEX_API_KEY and CODEX_API_URL must be set")

    def get_quota(self):
        """Query current quota usage"""
        try:
            headers = {
                'Authorization': f'Bearer {self.api_key}',
                'Content-Type': 'application/json'
            }

            response = requests.get(
                f'{self.api_url}/v1/usage',
                headers=headers,
                timeout=10
            )
            response.raise_for_status()

            data = response.json()

            return {
                'provider': 'codex',
                'status': 'ok',
                'quota': {
                    'used': data.get('used', 0),
                    'total': data.get('limit', 0),
                    'remaining': data.get('limit', 0) - data.get('used', 0),
                    'percentage': (data.get('used', 0) / data.get('limit', 1)) * 100
                },
                'timestamp': datetime.now().isoformat()
            }

        except requests.exceptions.RequestException as e:
            return {
                'provider': 'codex',
                'status': 'error',
                'error': str(e),
                'timestamp': datetime.now().isoformat()
            }

    def check_health(self):
        """Check API health status"""
        try:
            headers = {
                'Authorization': f'Bearer {self.api_key}',
                'Content-Type': 'application/json'
            }

            response = requests.get(
                f'{self.api_url}/v1/status',
                headers=headers,
                timeout=5
            )

            return response.status_code == 200

        except:
            return False


def main():
    """CLI entry point"""
    if len(sys.argv) < 2:
        print("Usage: codex.py [quota|health]")
        sys.exit(1)

    command = sys.argv[1]
    adapter = CodexAdapter()

    if command == 'quota':
        result = adapter.get_quota()
        print(json.dumps(result, indent=2))
    elif command == 'health':
        healthy = adapter.check_health()
        print(json.dumps({'healthy': healthy}))
    else:
        print(f"Unknown command: {command}")
        sys.exit(1)


if __name__ == '__main__':
    main()

