# Expert Parallel module distribution and forward replacement logic
import logging
import types
from functools import partial
from typing import Callable
import torch
from torch.distributed import DeviceMesh
from torch.distributed.tensor import Shard, DTensor, Replicate, distribute_tensor, distribute_module

from mindspeed.fsdp.distributed.expert_parallel.dispatcher import get_experts_forward_fn
from mindspeed.fsdp.distributed.expert_parallel.dispatcher_mc2 import get_experts_forward_mc2_fn
from mindspeed.fsdp.parallel_engine_config import EPPlanConfig
from mindspeed.fsdp.utils.log import print_rank
from mindspeed.fsdp.utils.str_match import module_name_match

logger = logging.getLogger(__name__)


def expert_parallelize_modules(modules: torch.nn.Module, ep_mesh: DeviceMesh, plan: EPPlanConfig):
    # Get modules to be parallelized
    ep_modules = get_ep_modules(modules, plan)

    # Get EP group info
    ep_group = ep_mesh.get_group()
    ep_rank = torch.distributed.get_rank(ep_group)
    ep_size = torch.distributed.get_world_size(ep_group)

    # Process each module
    for module in ep_modules:
        # Distribute experts across devices
        distribute_experts_module(module, ep_mesh)

        # Replace forward method with EP-aware version
        if hasattr(module, 'ep_forward') and callable(module.ep_forward):
            module.forward = partial(module.ep_forward, ep_group=ep_group)
        else:
            experts_forward_fn = get_experts_forward_fn_for_qwen(ep_group)
            module.forward = types.MethodType(experts_forward_fn, module)

    return modules


def get_ep_modules(modules: torch.nn.Module, plan: EPPlanConfig):
    ep_modules = []

    for plan_name in plan.apply_modules:
        for name, module in modules.named_modules():
            if module_name_match(plan_name, name):
                print_rank(logger.debug, f'[Expert Parallel]: Apply ep to module <{name}>')
                ep_modules.append(module)

    if len(ep_modules) == 0:
        raise RuntimeError(f'[Expert Parallel] No module named {plan} or not be ModuleList')

    return ep_modules


def prepare_distribute_input_fn(module, inputs, device_mesh):
    inputs = list(inputs)
    for idx, input_tensor in enumerate(inputs):
        if not isinstance(input_tensor, DTensor):
            input_tensor = DTensor.from_local(
                input_tensor, 
                device_mesh, 
                (Replicate(),), 
                run_check=False
            )
            inputs[idx] = input_tensor
    return *inputs,


def prepare_distribute_output_fn(module, outputs, device_mesh):
    return outputs.to_local()


def distribute_expert_weight(module_name, module, ep_mesh):
    # Distribute parameters using Shard(0)
    for name, param in module.named_parameters(recurse=False):
        dist_param = torch.nn.Parameter(distribute_tensor(param, ep_mesh, [Shard(0)]))
        module.register_parameter(name, dist_param)

    # Recursively process child modules
    for name, children_module in module.named_children():
        distribute_expert_weight(name, children_module, ep_mesh)


def distribute_experts_module(module: torch.nn.Module, ep_mesh: DeviceMesh):
    return distribute_module(
        module=module, 
        device_mesh=ep_mesh, 
        partition_fn=distribute_expert_weight,
        # input_fn=prepare_distribute_input_fn, 
        # output_fn=prepare_distribute_output_fn
    )


def get_dispatcher_fn(dispatcher, ep_group):
    forward_fn = None

    if isinstance(dispatcher, Callable):
        forward_fn = partial(dispatcher, ep_group)
    elif isinstance(dispatcher, str):
        if dispatcher == 'eager':
            forward_fn = get_experts_forward_fn(ep_group, fused=False)
        elif dispatcher == 'fused':
            forward_fn = get_experts_forward_fn(ep_group, fused=True)
        elif dispatcher == 'mc2':
            forward_fn = get_experts_forward_mc2_fn(ep_group)

    if forward_fn is None:
        raise RuntimeError(f'Unsupported dispatcher {dispatcher}.')

    return forward_fn


def get_grad_division_hook(param, ep_size):
    def hook(*unused):
        return param.grad.mul_(1 / ep_size)
    return hook


def apply_grad_division_hook(module, ep_size):
    for param in module.parameters():
        if param.requires_grad:
            param_tmp = param.expand_as(param)
            grad_acc = param_tmp.grad_fn.next_functions[0][0]
            grad_acc.register_hook(get_grad_division_hook(param, ep_size))


def get_experts_forward_fn_for_qwen(ep_group, fused=True):
    from .fused_ep import fused_ep_forward

    def experts_forward(self, hidden_states: torch.Tensor, routing_weights: torch.Tensor, router_indices: torch.Tensor):
        batch_size = hidden_states.shape[0]
        hidden_states = hidden_states.reshape(-1, self.hidden_size)

        gate_up_proj = self.gate_up_proj.to_local() if isinstance(self.gate_up_proj, DTensor) else self.gate_up_proj
        down_proj = self.down_proj.to_local() if isinstance(self.down_proj, DTensor) else self.down_proj

        hidden_states = fused_ep_forward(
            self.num_experts,
            routing_weights,
            router_indices,
            hidden_states,
            fc1_weight=gate_up_proj,
            fc2_weight=down_proj,
            ep_group=ep_group
        )

        hidden_states = hidden_states.view(batch_size, -1, self.hidden_size)
        return hidden_states

    return experts_forward

import warnings
import narwhals as nw
from narwhals.typing import Frame


class PolarsMaterializationWarning(Warning):
    pass

    @classmethod
    def warn_on_implementation_mismatch(cls, expected: nw.Implementation, actual: nw.Implementation, message: str = ""):
        if expected != actual:
            warning = f"Narwhals implementation mismatch: native is {expected}, got {actual}. This will lead to materialization into an eager Polars frame."
            if message:
                warning += f" {message}"
            warnings.warn(warning, cls, stacklevel=3)


class MetaxyColumnMissingWarning(Warning):
    pass

    @classmethod
    def warn_on_missing_column(cls, expected: str, df: Frame, message: str = ""):
        # Use collect_schema().names() to avoid PerformanceWarning on lazy frames
        columns = df.collect_schema().names()
        if expected in columns:
            return
        else:
            warning = f"Metaxy column missing: expected {expected}, got {columns}."
            if message:
                warning += f" {message}"
            warnings.warn(warning, cls, stacklevel=3)

# Rule for detecting deep nesting in functions
from __future__ import annotations
import ast
from pathlib import Path

from skylos.rules.base import SkylosRule

RULE_ID = "SKY-Q302"
_BRANCH_NODES = (ast.If, ast.For, ast.While)


def _max_depth(nodes, depth=0, is_function_body=False):
    max_depth = depth
    for node in nodes:
        # Skip function/class definitions as they start new scopes
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            continue

        # Handle branching constructs: if, for, while
        if isinstance(node, _BRANCH_NODES):
            branches = []
            if isinstance(node, ast.If):
                branches.append(node.body)
                if node.orelse:
                    branches.append(node.orelse)
            elif isinstance(node, (ast.For, ast.While)):
                branches.append(node.body)
                if node.orelse:
                    branches.append(node.orelse)

            # Recursively check each branch
            for branch in branches:
                max_depth = max(max_depth, _max_depth(branch, depth + 1))
            continue

        # Handle 'with' statements
        if isinstance(node, ast.With):
            max_depth = max(max_depth, _max_depth(node.body, depth))
            continue

        # Handle try/try* blocks
        try_types = [ast.Try]
        if hasattr(ast, "TryStar"):
            try_types.append(ast.TryStar)

        if isinstance(node, tuple(try_types)):
            # Determine increment based on context
            if is_function_body:
                increment = 0
            else:
                increment = 1

            inner_depth = depth + increment
            branches = [node.body]

            # Add handler bodies
            for handler in node.handlers:
                branches.append(handler.body)

            # Add else and final bodies if present
            if node.orelse:
                branches.append(node.orelse)
            if node.finalbody:
                branches.append(node.finalbody)

            # Recursively analyze all branches
            for branch in branches:
                max_depth = max(max_depth, _max_depth(branch, inner_depth))
            continue

    return max_depth


def _physical_length(node):
    start = getattr(node, "lineno", 0)
    end = getattr(node, "end_lineno", start)
    return max(end - start + 1, 0)


class NestingRule(SkylosRule):
    rule_id = "SKY-Q302"
    name = "Deep Nesting"

    def __init__(self, threshold=3):
        self.threshold = threshold

    def visit_node(self, node, context):
        # Only process function definitions
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            return None

        # Calculate nesting depth
        depth = _max_depth(node.body, 0, is_function_body=True)

        # Skip if within threshold
        if depth <= self.threshold:
            return None

        # Determine severity based on how much threshold is exceeded
        if depth <= self.threshold + 2:
            severity = "MEDIUM"
        elif depth <= self.threshold + 5:
            severity = "HIGH"
        else:
            severity = "CRITICAL"

        # Get physical line count of the function
        physical_len = _physical_length(node)

        # Build qualified function name
        mod = context.get("mod", "")
        func_name = f"{mod}.{node.name}" if mod else node.name

        return [
            {
                "rule_id": self.rule_id,
                "kind": "nesting",
                "severity": severity,
                "type": "function",
                "name": func_name,
                "simple_name": node.name,
                "file": context.get("filename"),
                "basename": Path(context.get("filename", "")).name,
                "line": node.lineno,
                "metric": "max_nesting",
                "value": depth,
                "threshold": self.threshold,
                "length": physical_len,
                "message": f"Nesting depth of {depth} exceeds threshold of {self.threshold}. Consider using early returns.",
            }
        ]

# Import required modules
import datetime

def period_boundaries(start_date, end_date, granularity):
    # Initialize list to store periods
    periods = []

    if granularity == "monthly":
        # Start from the first day of the month
        cur = start_date.replace(day=1)

        while cur < end_date:
            # Calculate next period boundary (first day of next month)
            next_p = (cur.replace(day=28) + datetime.timedelta(days=4)).replace(day=1)

            # Append tuple: (start_date, end_date, period_label)
            periods.append((cur, min(next_p, end_date), cur.strftime("%Y-%m")))

            # Move to next period
            cur = next_p

    else:  # yearly granularity
        # Start from January 1st of the start year
        cur = start_date.replace(month=1, day=1)

        while cur < end_date:
            # Calculate next period boundary (same date next year)
            next_p = cur.replace(year=cur.year + 1)

            # Append tuple: (start_date, end_date, year string)
            periods.append((cur, min(next_p, end_date), str(cur.year)))

            # Move to next period
            cur = next_p

    return periods


def filter_by_date(entries, start_date, end_date):
    # Filter entries based on date range
    filtered = []

    for e in entries:
        # Keep entries without a date attribute
        if not hasattr(e, "date"):
            filtered.append(e)
            continue

        # Skip entries before start_date
        if start_date and e.date < start_date:
            continue

        # Skip entries on or after end_date
        if end_date and e.date >= end_date:
            continue

        # Include entry in result
        filtered.append(e)

    return filtered


def walk_tree(real_account):
    # Build account tree node
    node = {
        "account": real_account.account,
        "balance": {},
        "children": [],
    }

    # Aggregate balances by currency
    for pos in real_account.balance:
        cur = pos.units.currency
        amt = float(pos.units.number)
        node["balance"][cur] = node["balance"].get(cur, 0) + amt

    # Process child accounts in sorted order
    for child in sorted(real_account.values(), key=lambda r: r.account):
        child_node = walk_tree(child)

        # Only include non-empty child nodes
        if child_node["children"] or child_node["balance"]:
            node["children"].append(child_node)

    return node


def extract_tree(realization, root, prefix):
    # Get account from realization or use prefix
    acc = realization.get(root, prefix)

    if acc is None:
        return {"account": prefix, "balance": {}, "children": []}

    return walk_tree(acc)


def sum_tree(realization, root, prefix):
    # Get account from realization or use prefix
    acc = realization.get(root, prefix)

    if acc is None:
        return {}

    totals = {}

    def walk(node):
        # Aggregate balances by currency
        for pos in node.balance:
            cur = pos.units.currency
            amt = float(pos.units.number)
            totals[cur] = totals.get(cur, 0) + amt

        # Recursively process children
        for child in node.values():
            walk(child)

    walk(acc)
    return totals


def convert_balance(balance, price_map, target_currency, date=None):
    """Convert a {currency: amount} dict to a single {target_currency: amount} dict."""
    from beancount.core.prices import get_price

    total = 0.0
    for cur, amt in balance.items():
        if cur == target_currency:
            total += amt
        else:
            result = get_price(price_map, (cur, target_currency), date)
            if result is None:
                raise click.UsageError(f"No price found for {cur} -> {target_currency}")
            _, price = result
            total += amt * float(price)

    return {target_currency: round(total, 2)}


def _tree_total(node):
    """Sum all balances in a tree (node + descendants)."""
    total = sum(node["balance"].values())

    for child in node["children"]:
        total += _tree_total(child)

    return total


def convert_tree(node, price_map, target_currency, date=None):
    """Recursively convert all balances in an account tree to target currency."""
    # Convert child nodes recursively
    children = [convert_tree(child, price_map, target_currency, date) for child in node["children"]]

    # Sort children by absolute total balance (descending)
    children.sort(key=lambda c: abs(_tree_total(c)), reverse=True)

    # Build converted node
    converted = {
        "account": node["account"],
        "balance": convert_balance(node["balance"], price_map, target_currency, date) if node["balance"] else {},
        "children": children,
    }

    return converted


