    """Get the artifacts' content of the last completed workflow run id of the scheduled (daily) CI."""
    get_last_daily_ci_artifacts(artifact_names, output_dir, token)
    results = {}

    for artifact_name in artifact_names:
        artifact_zip_path = os.path.join(output_dir, f"{artifact_name}.zip")

        if os.path.isfile(artifact_zip_path):
            results[artifact_name] = {}

            with zipfile.ZipFile(artifact_zip_path) as z:
                for filename in z.namelist():
                    if not os.path.isdir(filename):
                        # read the file
                        with z.open(filename) as f:
                            results[artifact_name][filename] = f.read().decode("UTF-8")

    return results

# Session quota management script
import os
import sys
import json
from datetime import datetime, timedelta

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
PARENT_DIR = os.path.dirname(SCRIPT_DIR)
DATA_DIR = os.path.join(PARENT_DIR, 'data')

# Ensure data directory exists
os.makedirs(DATA_DIR, exist_ok=True)

QUOTA_FILE = os.path.join(DATA_DIR, 'session_quota.json')


def load_quota():
    """Load quota data from JSON file"""
    if os.path.exists(QUOTA_FILE):
        with open(QUOTA_FILE, 'r') as f:
            return json.load(f)

    # Return default structure if file doesn't exist
    return {
        'limits': {},  # {model: max_sessions_per_day}
        'usage': {},   # {date: {model: count}}
    }


def save_quota(quota):
    """Save quota data to JSON file"""
    with open(QUOTA_FILE, 'w') as f:
        json.dump(quota, f, indent=2)


def set_limit(model, max_sessions):
    """Set session limit for a model"""
    quota = load_quota()
    quota['limits'][model] = max_sessions
    save_quota(quota)
    print(f"Set limit: {model} -> {max_sessions} sessions/day")


def record_session(model):
    """Record a new session for a model"""
    quota = load_quota()
    today = datetime.now().strftime('%Y-%m-%d')

    # Initialize today's usage if not present
    if today not in quota['usage']:
        quota['usage'][today] = {}

    # Initialize model usage for today if not present
    if model not in quota['usage'][today]:
        quota['usage'][today][model] = 0

    # Increment usage count
    quota['usage'][today][model] += 1
    save_quota(quota)
    print(f"Recorded session for {model}")


def check_quota(model):
    """Check if model has available quota"""
    quota = load_quota()
    today = datetime.now().strftime('%Y-%m-%d')

    # Get limit (-1 means unlimited)
    limit = quota['limits'].get(model, -1)

    # Get current usage for today
    used = quota['usage'].get(today, {}).get(model, 0)

    # Handle unlimited case
    if limit == -1:
        return {'available': True, 'limit': 'unlimited', 'used': used}

    # Calculate remaining quota
    available = limit - used
    return {
        'available': available > 0,
        'limit': limit,
        'used': used,
        'remaining': available
    }


def get_all_usage():
    """Get usage statistics for all models today"""
    quota = load_quota()
    today = datetime.now().strftime('%Y-%m-%d')
    return quota['usage'].get(today, {})


def main():
    """CLI entry point for session quota management"""
    # Check command line arguments
    if len(sys.argv) < 2:
        print("Usage: session_quota.py [set|record|check|usage]")
        sys.exit(1)

    command = sys.argv[1]

    # Handle different commands
    if command == 'set':
        if len(sys.argv) < 4:
            print("Usage: session_quota.py set <model> <max_sessions>")
            sys.exit(1)
        set_limit(sys.argv[2], int(sys.argv[3]))

    elif command == 'record':
        if len(sys.argv) < 3:
            print("Usage: session_quota.py record <model>")
            sys.exit(1)
        record_session(sys.argv[2])

    elif command == 'check':
        if len(sys.argv) < 3:
            print("Usage: session_quota.py check <model>")
            sys.exit(1)
        print(json.dumps(check_quota(sys.argv[2]), indent=2))

    elif command == 'usage':
        print(json.dumps(get_all_usage(), indent=2))

    else:
        print(f"Unknown command: {command}")
        sys.exit(1)


if __name__ == '__main__':
    main()

# Django NATS function registry module
from django.conf import settings


class FunctionRegistry:
    """Function registry for callback functions from NATS"""

    def __init__(self):
        self.registry = {}

    def register(self, name=None, func=None, **kwargs):
        # Case 1: register(func, name, ...)
        if func is not None:
            return self.register_function(func, name, **kwargs)

        # Case 2: @register (without parentheses)
        if name is not None and func is None and callable(name):
            return self.register_function(name, **kwargs)

        # Case 3: @register(...) (with parentheses)
        def dec(func):
            return self.register(name, func, **kwargs)
        return dec

    def register_function(self, func, name: str = None, **kwargs):
        # Get namespace from kwargs or settings
        namespace = kwargs.get('namespace', getattr(settings, 'NATS_NAMESPACE', 'default'))

        # Determine function name
        name = name or getattr(func, '_decorated_function', func).__name__

        # Check if JetStream mode is enabled
        js = kwargs.get('js', False)

        # Build the registry key
        key = f'{namespace}.js.{name}' if js else f'{namespace}.{name}'

        # Ensure no duplicate keys
        if key in self.registry:
            raise ValueError(f'Duplicated NATS function key `{key}`.')

        # Store function info in registry
        self.registry[key] = {
            'func': func,
            'namespace': namespace,
            'name': name,
            'js': js,
        }

        return func


# Create default registry instance and export register function
default_registry = FunctionRegistry()
register = default_registry.register

