def omg_quality(x, ys):
    total = 0

    for y in ys:
        if y > 0:
            total += y
        else:
            total -= y

    if total > 10 and x:
        for i in range(5):
            if i % 2 == 0:
                total += i
            else:
                total -= i

    try:
        while total < 100:
            if total % 3 == 0 and total % 5 == 0:
                break

            if total % 2 == 0:
                total += 7
            else:
                total += 3
    except Exception:
        total = -1

    return total

