def _scan_iteration(database):
    def verify_log(log_entry):
        modification_time, file_path, log_identifier = (
            log_entry.get('last_mtime'), 
            log_entry.get('path'), 
            log_entry.get('id'),
        )

        if modification_time is not None and modification_time >= get_file_modification_time(file_path):
            # File hasn't been modified
            return

        log_records = list(database.entries.find({'log': log_identifier}).sort('order'))
        db_contents = [record['content'] for record in log_records]

        with open(file_path, 'r') as file_handle:
            file_contents = file_handle.readlines()

        if len(file_contents) <= len(db_contents):
            # todo: special case
            return

        previous_lines = file_contents[:len(db_contents)]
        upcoming_lines = file_contents[len(db_contents):]

        if compute_md5_hash(previous_lines) != compute_md5_hash(db_contents):
            # todo: special case
            return

        final_order = log_records[len(db_contents)-1]['order']
        documents_to_insert = []
        counter = final_order + 1

        for line_content in upcoming_lines:
            documents_to_insert.append({
                'log': log_identifier,
                'content': line_content, 
                'order': counter
            })
            counter += 1

        database.entries.insert(documents_to_insert)
