class PyutrackContext(object):
    def __init__(self, conn, cfg, debug=False):
        self.connection = conn
        self.config = cfg
        self.debug = debug
        self.output_format = None

    def render(self, content, format=None):
        fmt = self.output_format or format
        is_oneline = fmt == 'oneline'
        separator = '\n' if fmt else '\n\n'
        response = ''

        if isinstance(content, str):
            response = content
        elif isinstance(content, collections.Iterable):
            response = separator.join(
                item.format(fmt, oneline=is_oneline) for item in content
            ) if len(content) > 0 else click.style(
                'No results', fg='yellow'
            )
        elif content:
            response = content.format(fmt, oneline=is_oneline)

        click.echo(response)

