    cursor = self.connection.cursor()
    try:
      cursor.execute("update " + query_text)  # Fixed SQL syntax: 'update from' -> 'update'
      cursor.close()
      self.connection.commit()
    except Exception as error:
      print(error)
      return False
    return True

  def fetch_records(self, query_text):
    cursor = self.connection.cursor()
