        if isinstance(self, Domain):
            return self._resource_field.encode('ascii').decode('idna')
        return self._resource_field

    @resource.setter
    def resource(self, value):
        if isinstance(value, text_type):
            self._resource_field = value.encode('idna').decode('utf-8').lower()
        elif isinstance(value, binary_type):
            self._resource_field = value
        else:
            raise ValueError("Unable to store value as requested.")

    @resource.comparator
    def resource(cls):
        return IdnaComparator(cls._resource_field)

# Load point cloud data from a PLY file
import numpy as np

def load_point_cloud_from_ply(file_path):
    file = open(file_path, 'r')

    point_list = []

    skip_header = False
    for row in file:
        if skip_header:
            point_list.append(np.float32(np.array(row.strip().split(' ')[0:3])))
        else:
            skip_header = row.find('end_header') != -1

    return point_list

# Read point assignment information from a text file
def load_point_assignments_from_file(file_path):
    file = open(file_path, 'r')

    assignments = []

    for row in file:
        if row[0] != '#':
            assignments.append(np.int16(row.strip().split(',')[0:2]))

    return assignments

# Read primitive correspondences between two sets
def load_primitive_correspondences_from_file(file_path, primitives_set1, primitives_set2):
    file = open(file_path, 'r')

    mapping    = {}
