                    prim1 = p
                    break

            for p in primitives_set2:
                if p.uid == values[3] and p.did == values[5]:
                    prim2 = p
                    break

            if (prim1 is not None and prim2 is not None):
                mapping[prim1] = prim2
                uid_mapping[prim1.uid] = prim2.uid
            else: 
                print "Could not locate", values

    file.close()

    return mapping, uid_mapping

# Custom dictionary implementation with optional value retrieval
import typing as t
import builtins as py
from .optional import Optional, optional

Key = t.TypeVar('Key')
Value = t.TypeVar('Value')

class Map(t.Generic[Key, Value], t.Iterable[t.Tuple[Key, Value]]):
    def __init__(self, initial_data: t.Dict[Key, Value]) -> None:
        self._data: t.Dict[Key, Value] = py.dict(initial_data)

    def __getitem__(self, key: Key) -> Optional[Value]:
        return optional(self._data.get(key))

    def __setitem__(self, key: Key, value: Value) -> None:
        self._data[key] = value

    @property
    def keys(self) -> t.Iterable[Key]:
        return self._data.keys()

    @property
    def values(self) -> t.Iterable[Value]:
        return self._data.values()

    def for_each(self, action: t.Callable[[Key, Value], None]) -> None:
        for k, v in self._data.items():
            action(k, v)

    @property
    def size(self) -> int:
        return len(self._data)

    def clear(self) -> None:
        self._data.clear()

    def __iter__(self) -> t.Iterator[t.Tuple[Key, Value]]:
        return self._data.items().__iter__()

# Retrieve metadata and schemas for available data pipelines
from typing import Iterator, Dict
from lib.constants import SRC
from lib.pipeline import DataPipeline

def list_pipeline_names() -> Iterator[str]:
    """ Generator yielding names of all accessible data pipelines """
    for directory in (SRC / "pipelines").iterdir():
        if not directory.name.startswith("_") and not directory.is_file():
            yield directory.name

def list_table_names() -> Iterator[str]:
    """ Generator yielding table names corresponding to pipelines """
    for pipeline_identifier in list_pipeline_names():
        yield pipeline_identifier.replace("_", "-")

def list_data_pipelines() -> Iterator[DataPipeline]:
    """ Generator yielding loaded DataPipeline instances """
    for pipeline_name in list_pipeline_names():
        yield DataPipeline.load(pipeline_name)

def collect_schema() -> Dict[str, type]:
    """ Aggregate schema information from all pipelines """
    combined_schema: Dict[str, type] = {}
    for pipeline_instance in list_data_pipelines():
        combined_schema.update(pipeline_instance.schema)
    return combined_schema

