# Custom manual reporting for Locust tasks
import random
from contextlib import contextmanager, ContextDecorator
from time import time, sleep
from locust import User, task, constant, events

@contextmanager
def _custom_report(task_name):
    start_timestamp = time()
    try:
        yield
    except Exception as error:
        events.request_failure.fire(
            request_type="custom",
            name=task_name,
            response_time=(time() - start_timestamp) * 1000,
            response_length=0,
            exception=error,
        )
        raise
    else:
        events.request_success.fire(
            request_type="custom",
            name=task_name,
            response_time=(time() - start_timestamp) * 1000,
            response_length=0,
        )

def custom_report(name_or_callable):
    if callable(name_or_callable):
        # used as decorator without name argument specified
        return _custom_report(name_or_callable.__name__)(name_or_callable)
    else:
        return _custom_report(name_or_callable)

class TestUser(User):
    wait_time = constant(1)

    @task
    def passed_task(self):
        with custom_report("passed_task"):
            sleep(random.random())

    @task
    @custom_report
    def decorator_scenario(self):
        if random.random() > 0.5:
            raise Exception("decorator_test failed")
        sleep(random.random())

    @task
    def error_task(self):
        with custom_report("error_task"):
            sleep(random.random())
            raise Exception("Something went wrong!")

# Context processors for Django
from django.conf import settings
from django.utils import timezone
from apps.feedback.models import FeedbackRelation

def site_settings_context(request):
    context_data = {}
    if hasattr(settings, 'GOOGLE_ANALYTICS_KEY'):
        context_data['GOOGLE_ANALYTICS_KEY'] = settings.GOOGLE_ANALYTICS_KEY
    if hasattr(settings, 'HOT_RELOAD'):
        context_data['HOT_RELOAD'] = settings.HOT_RELOAD
    return context_data

def pending_feedback_context(request):
    context_data = {}
    context_data['feedback_pending'] = []

    # Skip if user is not authenticated
    if not request.user.is_authenticated:
        return context_data

    # Get all active feedback relations
    active_feedbacks = FeedbackRelation.objects.filter(active=True)

    for feedback_item in active_feedbacks:
        # Skip if content object doesn't exist
        if feedback_item.content_object is None:
            continue

        # Check if feedback deadline has passed or event hasn't ended
        end_date = feedback_item.content_end_date()
        current_date = timezone.now().date()

        # Skip if no end date, event not over, or deadline has passed
        if not end_date or end_date.date() >= current_date or (feedback_item.deadline - current_date).days < 0:
            continue

        # Check if user hasn't answered the feedback
        not_answered = feedback_item.not_answered()
        if not_answered == False or request.user not in not_answered:
            continue

        # Add to pending feedback list
        context_data['feedback_pending'].append(feedback_item)

    return context_data

