# Check if any fresh orange becomes rotten due to adjacent rotting oranges
def checkAndRotNeighbours(row, col: int, matrix: List[List[int]]) -> bool:
    changed = False
    adjacent_cells = [[row+1, col], [row-1, col], [row, col+1], [row, col-1]]
    for position in adjacent_cells:
        r, c = position
        if r < 0 or r >= len(matrix):
            continue
        if c < 0 or c >= len(matrix[0]):
            continue
        if matrix[r][c] == 1:
            changed = True
            matrix[r][c] = 2
    return changed

