# Handle notification system with fallback support
from dbus.exceptions import DBusException

try:
    import gi
    gi.require_version('Notify', '0.7')
    from gi.repository import Notify
except (ImportError, AttributeError, ValueError):
    from scudcloud import notify2
    Notify = None

class Notifier(object):
    def __init__(self, app_name, icon):
        self.icon_path = icon
        try:
            if Notify is not None:
                Notify.init(app_name)
                self.backend = Notify
            else:
                notify2.init(app_name)
                self.backend = notify2
            self.active = True
        except DBusException:
            print("WARNING: No notification daemon found! "
                  "Notifications will be ignored.")
            self.active = False

    def notify(self, title, message, icon=None):
        if not self.active:
            return
        if icon is None:
            icon = self.icon_path
        if Notify is not None:
            notice = self.backend.Notification.new(title, message, icon)
        else:
            notice = notify2.Notification(title, message, icon)
        notice.set_hint_string('x-canonical-append', '')
        try:
            notice.show()
        except:
            pass

