# Import required modules for enum handling and type hints
from __future__ import absolute_import
from enum import Enum
from typing import TypeVar, Optional, Any, Type  # noqa
from odin.exceptions import ValidationError
from . import Field

__all__ = ("EnumField",)

# Define type variable for Enum types
ET = TypeVar("ET", Enum, Enum)

class EnumField(Field):
    """
    Field designed to manage Python enumeration types.
    """
    data_type_name = "Enum"

    def __init__(self, enum_class, **options):
        # type: (Type[ET], **Any) -> None
        # Extract and process choices if provided, otherwise use enum members
        choices = options.pop("choices", None)
        options["choices"] = tuple((member, member.name) for member in choices or enum_class)
        super(EnumField, self).__init__(**options)
        self.enum_class = enum_class

    @property
    def choices_doc_text(self):
        """
        Format choices specifically for documentation generation.
        """
        return tuple((val.value, name) for val, name in self.choices)

    def to_python(self, value):
        # type: (Any) -> Optional[ET]
        if value is None:
            return None

        try:
            # Try to convert the value to the enum type
            return self.enum_class(value)
        except ValueError:
            # Handle empty string case separately since some enums may use empty strings
            if value == "":
                return None
            raise ValidationError(self.error_messages["invalid_choice"] % value)

    def prepare(self, value):
        # type: (Optional[ET]) -> Any
        if (value is not None) and isinstance(value, self.enum_class):
            return value.value

# Import necessary models, schema, and helper functions
from .models import (
    Release,
    ReleasePackage,
    Record,
    RecordPackage
)
from .schema import Tender
from .helpers import (
    mode_test,
    get_ocid
)

def create_release_from_tender(tender_data, prefix_value):
    """ returns Release object created from `tender_data` with ocid `prefix_value` """
    modification_date = tender_data.get('dateModified', '')
    identifier = get_ocid(prefix_value, tender_data['tenderID'])
    return Release(dict(tender=tender_data, ocid=identifier, date=modification_date))

def generate_releases_from_tenders(tender_list, prefix_value):
    """ returns generator of Release objects created from `tender_list` with amendment info and ocid `prefix_value` """
    previous_tender = next(tender_list)
    for current_tender in tender_list:
        release_data = {}
        for section in ['tender', 'awards', 'contracts']:
            model_class = getattr(Release, section).model_class
            if section in current_tender:
                release_data[section] = model_class.fromDiff(
                    previous_tender.get(section, ''), 
                    current_tender.get(section, '')
                )
            elif section == 'tender':
                release_data[section] = model_class.fromDiff(previous_tender, current_tender)
        yield Release(release_data)
        previous_tender = current_tender

def package_releases_from_tenders(tender_list, parameter_dict):
    package_data = {}
    for field_name in ReleasePackage._fields:
        if field_name in parameter_dict:
            package_data[field_name] = parameter_dict.get(field_name, '')
    package_data['releases'] = [
        create_release_from_tender(tender, parameter_dict.get('prefix')) 
        for tender in tender_list
    ]
    return ReleasePackage(dict(**package_data)).serialize()

# Clean and format mobile phone numbers for partners
from openerp import models, fields, api
import string

class ResPartner(models.Model):
    _inherit = ['res.partner']

    # Computed field to store cleaned mobile number
    cleaned_mobile = fields.Char(compute='_clean_mobile_number', store=True)

    @api.multi
    @api.depends('mobile', 'phone')
    def _clean_mobile_number(self):
        valid_characters = '+0123456789'
        for record in self:
            # Use phone as fallback if mobile is empty
            if not record.mobile:
                record.mobile = record.phone

            # Extract only allowed characters
            raw_number = ''.join([char for char in record.mobile if char in valid_characters]) if record.mobile else ''

            # Ensure the number starts with country code prefix
            if len(raw_number) > 0 and raw_number[0] != '+':
                if len(raw_number) >= 2 and raw_number[:2] == '00':
                    raw_number = '+' + raw_number[2:]
                else:
                    # @todo: Use country prefix from partner's country setting 
                    raw_number = '+45' + raw_number

            # Validate format: only first character can be '+', max length 18
            if '+' in raw_number[1:] or len(raw_number) > 18:
                raw_number = False

            record.cleaned_mobile = raw_number

