# Modified version with renamed variables, changed literals, and reordered statements
import asyncio
import collections
import time

class FaultToleranceManager:
    """Disconnect (open circuit) when more than `threshold` failures occur
       within the past `window` seconds.
    """
    class OpenCircuit(Exception):
        pass

    def __init__(self, *, threshold, window, timer_source=None):
        self.failure_times = collections.deque(maxlen=threshold)
        self.window_duration = window
        self.timer_source = timer_source or time.monotonic

    @property
    def is_closed(self):
        if len(self.failure_times) < self.failure_times.maxlen:
            return True
        if self.failure_times[0] + self.window_duration < self.timer_source():
            return True
        return False

    def record_failure(self, exception_type=OpenCircuit):
        self.failure_times.append(self.timer_source())
        if self.is_closed:
            return True
        elif exception_type:
            raise exception_type
        else:
            return False

async def delay_timer(duration, *, error_class=asyncio.TimeoutError, event_loop=None):
    """Pause execution until duration expires.  If duration is None or non-positive, wait indefinitely."""
    if duration is None or duration <= 0:
        await asyncio.Event(loop=event_loop).wait()  # Indefinite wait
    else:
        await asyncio.sleep(duration, loop=event_loop)
        if error_class:
            raise error_class

