# Import the REST parser and common utilities
from . import rest
from .common import ParseError, Docstring

# Dictionary mapping style names to their parsing functions
_parsing_functions = {"rest": rest.parse}

def _evaluate_parse_quality(docstring: Docstring) -> int:
    """
    Compute a quality score for the parsed docstring.
    :param Docstring docstring: parsed docstring representation
    :returns int: parse quality score, higher indicates better parsing
    """
    quality = 0
    if docstring.short_description:
        quality += 1
    if docstring.long_description:
        quality += docstring.long_description.count('\n')
    quality += len(docstring.params)
    quality += len(docstring.raises)
    if docstring.returns:
        quality += 2
    return quality

def extract_docstring(text: str, format_style: str = 'auto') -> Docstring:
    """
    Parse the provided text into structured docstring components.
    :param str text: docstring text to analyze
    :param str format_style: parsing style, options include: 'rest', 'auto'
    :returns Docstring: structured representation of the parsed docstring
    """
    if format_style == 'auto':
        candidates = []
        last_exception = None
        for parser in _parsing_functions.values():
            try:
                candidates.append(parser(text))
            except ParseError as error:
                last_exception = error
        if not candidates:
            raise last_exception
        # Select the best candidate based on quality score
        return sorted(candidates, key=_evaluate_parse_quality, reverse=True)[0]
    else:
        return _parsing_functions[format_style](text)

# Test memory usage during LZ4 block decompression
import lz4.block
import pytest

test_inputs = [
    (b'x' * 1024 * 1024),
]

@pytest.fixture(
    params=test_inputs,
    ids=[
        'input_' + str(idx) for idx in range(len(test_inputs))
    ]
)
def sample_data(request):
    return request.param

def test_memory_consumption_during_decompression(sample_data):
    tracemalloc_module = pytest.importorskip('tracemalloc')
    tracemalloc_module.start()

    compressed_data = lz4.block.compress(sample_data)
    previous_snapshot = None

    for iteration in range(1000):
        decompressed_data = lz4.block.decompress(compressed_data)  # noqa: F841
        if iteration % 100 == 0:
            current_snapshot = tracemalloc_module.take_snapshot()
            if previous_snapshot:
                comparison_stats = current_snapshot.compare_to(previous_snapshot, 'lineno')
                assert comparison_stats[0].size_diff < (1024 * 4)
            previous_snapshot = current_snapshot

