# Script to migrate list_id field in Mendeley and Zotero node settings
import logging
import sys
from modularodm import Q
from framework.mongo import database
from framework.transactions.context import TokuTransaction
from website.app import init_app
from scripts import utils as script_utils

logger = logging.getLogger(__name__)
SOURCES = ['mendeley', 'zotero']

def update_list_id(document, source):
    try:
        database['{}nodesettings'.format(source)].find_and_modify(
            {'_id': document['_id']},
            {
                '$set': {
                    'list_id': document['{}_list_id'.format(source)]
                }
            }
        )
        database['{}nodesettings'.format(source)].find_and_modify(
            {'_id': document['_id']},
            {
                '$unset': {
                    '{}_list_id'.format(source): ''
                }
            }
        )
    except Exception:
        return False
    return True

def validate_document(doc, source):
    try:
        assert('_id' in doc)
        assert('{}_list_id'.format(source) in doc)
    except AssertionError:
        return False
    return True

def run_migration(dry_run=True):
    success_docs = {}
    failed_docs = {}
    missing_field_docs = {}

    for source in SOURCES:
        success_docs[source] = []
        failed_docs[source] = []
        missing_field_docs[source] = []

        for doc in database['{}nodesettings'.format(source)].find():
            if validate_document(doc, source):
                if update_list_id(doc, source):
                    success_docs[source].append(doc)
                else:
                    failed_docs[source].append(doc)
            else:
                missing_field_docs[source].append(doc)

    for source in SOURCES:
        if success_docs[source]:
            logger.info('Successfully migrated {0} {1} node settings documents:\n{2}'.format(
                len(success_docs[source]), source, [e['_id'] for e in success_docs[source]]
            ))
        if missing_field_docs[source]:
            logger.error('Failed to migrate {0} {1} node settings documents due to no {1}_list_id field:\n{2}'.format(
                len(missing_field_docs[source]), source, [e['_id'] for e in missing_field_docs[source]]
            ))
        if failed_docs[source]:
            logger.error('Failed to migrate {0} {1} node settings documents for unknown reason:\n{2}'.format(
                len(failed_docs[source]), source, [e['_id'] for e in failed_docs[source]]
            ))

    if dry_run:
        raise RuntimeError('Dry run, transaction rolled back.')

def execute():
    dry_run_mode = False
    if '--dry' in sys.argv:
        dry_run_mode = True

    if not dry_run_mode:
        script_utils.add_file_logger(logger, __file__)

    init_app(set_backends=True, routes=False)

    with TokuTransaction():
        run_migration(dry_run=dry_run_mode)

if __name__ == "__main__":
    execute()

