# Utility functions for handling numpy types and scaling
import math

try:
    import numpy as np
except ImportError:
    np = None

def normalize_np_value(val):
    # Check if value is NaN using math module
    if math.isnan(val):
        return None

    # Return original value if it's a basic numeric type or None
    if isinstance(val, (int, float, complex, type(None))):
        return val

    # Handle numpy-specific NaN checks if numpy is available
    if np and np.isnan(val):
        return None

    # Convert numpy integers to Python int
    if np and isinstance(val, np.integer):
        return int(val)

    # Convert numpy floats to Python float
    if np and isinstance(val, np.floating):
        return float(val)

    return val

def convert_to_array(val):
    # If already a numpy array, return as-is
    if isinstance(val, np.ndarray):
        return val

    # If scalar value, wrap in numpy array
    if np.isscalar(val):
        return np.array([val])

def compute_scale_multiplier(data_tensor):
    # Convert tensor to numpy array if needed
    processed = data_tensor.numpy() if not isinstance(data_tensor, np.ndarray) else data_tensor

    # Return scale factor based on data type
    return 1 if processed.dtype == np.uint8 else 255

# Import the exponential function from math module
from math import exp

class PositionBiasedModel(object):
    '''
    Simplified Position-biased Model:
    P(C_r=1) = P(A_r=1|E_r=1)P(E_r=1),
    where
        C_r represents click on the r-th document,
        A_r indicates attraction by the r-th document, and
        E_r denotes examination of the r-th document.
    Here, the examination probability is modeled as
    P(E_r=1) = exp(- r / tau).
    Thus, P(A_r=1|E_r=1) = P(C_r=1) / P(E_r=1).
    '''
    @classmethod
    def compute(cls, click_data, tau=12.0, limit=10):
        output = {}
        for item in click_data:
            if item.position <= limit:
                exam_prob = cls._examination_prob(item.position, tau)
                attr_prob = min([1.0, item.click_rate / exam_prob])
                output[(item.search_id, item.doc_id)] = attr_prob
        return output

    @classmethod
    def _examination_prob(cls, position, tau):
        return exp(- float(position) / tau)

import wx
## Checks whether a wx control/instance is enabled
#  
#  Helper function for compatibility across wx versions
#  \param control
#    \b \e wx.Window : The control to check
#  \param state
#    \b \e bool : Expected enabled state (default: True)
def IsControlEnabled(control, state=True):
    if wx.MAJOR_VERSION > 2:
        return control.IsThisEnabled() == state

    else:
        return control.IsEnabled() == state

## Verifies the state of multiple controls
#  
#  \return
#    \b \e bool : True if all controls match the expected enabled state
def AreControlsEnabled(control_list, expected_state=True):
    if isinstance(control_list, (tuple, list)):
        return IsControlEnabled(control_list, expected_state)

    for ctrl in control_list:
        if not IsControlEnabled(ctrl, expected_state):
            return False

    return True

