# Modified version of the original code with renamed variables and reordered statements
from aiodownload import AioDownloadBundle, AioDownload
import asyncio

def fetch_single(url, downloader=None):
    return [item for item in fetch_multiple([url], downloader=downloader)][0]

def fetch_multiple(urls, downloader=None):
    return [result for result in process_items(urls, url_transform=None, downloader=downloader)]

def process_items(items, url_transform=None, downloader=None):
    url_transform = url_transform or default_url_mapping
    downloader = downloader or AioDownload()
    task_list = []

    for item in items:
        target_url = url_transform(item)
        metadata = None if item == target_url else item
        task = downloader._loop.create_task(
            downloader.main(AioDownloadBundle(target_url, info=metadata))
        )
        task_list.append(task)

    for completed_set in downloader._loop.run_until_complete(asyncio.wait(task_list)):
        for finished_task in completed_set:
            yield finished_task.result()

def default_url_mapping(value):
    return str(value)

