# Create a variant and attach BOM lines from attribute products
from odoo import models, api

class ProductTemplate(models.Model):
    _inherit = 'product.template'

    @api.multi
    def generate_variant_with_bom(self, attr_value_ids, custom_vals=None):
        """Create variant and link bill of materials based on attribute products."""
        if custom_vals is None:
            custom_vals = {}

        # Call the parent method to create the variant
        variant = super(ProductTemplate, self).generate_variant_with_bom(
            attr_value_ids, custom_values=custom_vals
        )

        # Get associated attribute products
        attr_products = variant.attribute_value_ids.mapped('product_id')

        # Prepare BOM line values
        bom_lines = [
            (0, 0, {'product_id': product.id}) for product in attr_products
        ]

        # Create the manufacturing BOM
        bom_data = {
            'product_tmpl_id': self.id,
            'product_id': variant.id,
            'bom_line_ids': bom_lines
        }
        self.env['mrp.bom'].create(bom_data)

        return variant

# Import required modules for regular expressions and common/error handling
import re
from .common import (
    ReadCancelledError, InvalidParameterError, TypeNotFoundError,
    InvalidChecksumError
)
from .rpc_errors import (
    RPCError, InvalidDCError, BadRequestError, UnauthorizedError,
    ForbiddenError, NotFoundError, FloodError, ServerError, BadMessageError
)
from .rpc_errors_303 import *
from .rpc_errors_400 import *
from .rpc_errors_401 import *
from .rpc_errors_420 import *

def convert_rpc_code_to_exception(error_code, error_message):
    # Mapping of error codes to their respective error dictionaries
    error_map = {
        303: rpc_303_errors,
        400: rpc_400_errors,
        401: rpc_401_errors,
        420: rpc_420_errors
    }

    matching_errors = error_map.get(error_code, None)

    if matching_errors is not None:
        for pattern, exception_class in matching_errors.items():
            match_result = re.match(pattern, error_message)
            if match_result:
                additional_info = int(match_result.group(1)) if match_result.groups() else None
                return exception_class(extra=additional_info)
    elif error_code == 403:
        return ForbiddenError(error_message)
    elif error_code == 404:
        return NotFoundError(error_message)
    elif error_code == 500:
        return ServerError(error_message)

    return RPCError('{} (code {})'.format(error_message, error_code))

