# Modified version with renamed variables and adjusted logic
import sys, os

def get_max_revision():
    env_var = 'SVNRMAX'
    if env_var in os.environ:
        return os.environ[env_var]
    return None

def write_dump(url, lower_bound, upper_bound):
    if url.startswith('sim://'):
        file_path = url[6:]
        if file_path.endswith('/'):
            file_path = file_path[:-1]  # remove trailing slash
    else:
        raise ValueError('sim:// URL is required')

    with open(file_path, 'r') as f:
        current_state = 'header'
        wrote_revision = False

        while True:
            line = f.readline()
            if not line:
                break

            if current_state == 'header' and line.startswith('Revision-number: '):
                current_state = 'prefix'

            if current_state == 'prefix' and line == f'Revision-number: {lower_bound}\n':
                current_state = 'selection'

            if upper_bound != 'HEAD' and current_state == 'selection' and line == f'Revision-number: {upper_bound}\n':
                break

            if current_state in ('header', 'selection'):
                if current_state == 'selection':
                    wrote_revision = True
                sys.stdout.write(line)

    return wrote_revision

if __name__ == "__main__":
    if len(sys.argv) not in (3, 4, 5):
        print("usage: %s dump URL -rLOWER:UPPER" % sys.argv[0])
        sys.exit(1)

    if sys.argv[1] != 'dump':
        raise NotImplementedError('only "dump" is supported.')

    target_url = sys.argv[2]
    revision_range = ('0', 'HEAD')

    if len(sys.argv) == 4 and sys.argv[3].startswith('-r'):
        parts = sys.argv[3][2:].lstrip().split(':')
        revision_range = (parts[0], parts[1]) if len(parts) > 1 else (parts[0], 'HEAD')

    max_rev_limit = get_max_revision()
    if max_rev_limit is not None:
        revision_range = (revision_range[0], max_rev_limit)

    result = write_dump(target_url, revision_range[0], revision_range[1])
    exit_code = 0 if result else 1
    sys.exit(exit_code)

# Modified version of the original webhook module
import json
import httplib
import urllib

class WebhookException(Exception):
    def __init__(self, code, description):
        self.code = code
        self.description = 'Rocket.Chat server issue, status {0}: {1}'.format(code, description)
        super(WebhookException, self).__init__(self.description)

class Webhook(object):
    def __init__(self, base_url, api_token):
        # Determine protocol type
        if base_url.split('://')[0] == 'https':
            self.use_ssl = True
        else:
            self.use_ssl = False

        # Extract domain and clean up URL
        self.hostname = base_url.split('://')[-1].replace('/', '')
        self.api_key = api_token

    def send_simple(self, content):
        """Send a basic text message using a single hook."""
        self.send(ChatMessage(content))

    def send(self, msg):
        """Transmit a message to Rocket.Chat.
        msg should be a pyrocketchat.ChatMessage instance.
        For simple text-only messages, use send_simple() instead.
        Raises pyrocketchat.WebhookException on non-200 HTTP responses."""

        assert type(msg) is ChatMessage, 'Error: provided message is not a pyrocketchat.ChatMessage'

        payload_data = {}

        if msg.content:
            payload_data['text'] = msg.content

        if msg.avatar_url:
            payload_data['icon_url'] = msg.avatar_url

        if msg.embeds:
            payload_data['attachments'] = msg.embeds

        encoded_payload = 'payload=' + urllib.quote_plus(json.dumps(payload_data))
        request_headers = {'Content-Type': 'application/x-www-form-urlencoded'}

        # Establish connection based on protocol
        if self.use_ssl:
            connection = httplib.HTTPSConnection(self.hostname)
        else:
            connection = httplib.HTTPConnection(self.hostname)

        # Send POST request
        connection.request('POST', '/hooks/' + self.api_key, encoded_payload, request_headers)
        response = connection.getresponse()

        # Handle response
        if response.status != 200:
            error_response = json.loads(response.read())
            connection.close()
            raise WebhookException(response.status, error_response['message'])

        connection.close()

class ChatMessage(object):
    def __init__(self, content='', avatar_url=None):
        self.content = content
        self.avatar_url = avatar_url
        self.embeds = []

    def add_line(self, new_text):
        """Append additional text to the existing message."""
        if self.content:
            self.content = self.content + '\n' + new_text
        else:
            self.content = new_text

    def include_embed(self, **params):
        """Add an embed/attachment to the message.
        Supported parameters (as per Rocket.Chat v0.17):
            * title
            * title_link
            * text
            * image_url
            * color
        Multiple embeds can be added to one message."""
        self.embeds.append(params)

# Decorator to convert async handler return values into JSON responses
from functools import partial, wraps
from inspect import iscoroutine
from aiohttp.web import (
    json_response, HTTPError,
    HTTPSuccessful, HTTPRedirection
)

def async_json_response(orig_func=None, *, response_code=200, mime_type='application/json', **decorator_kwargs):
    """Convert dictionary output from an HTTP handler into a JSON response.
    Designed for use with aiohttp request handlers.
    """
    if orig_func is None:
        return partial(async_json_response, response_code=200, mime_type='application/json', **decorator_kwargs)

    @wraps(orig_func)
    async def decorated_handler(*handler_args, **handler_kwargs):
        try:
            result_dict = orig_func(*handler_args, **handler_kwargs)
            if iscoroutine(result_dict):
                result_dict = await result_dict
        except (HTTPSuccessful, HTTPRedirection):
            raise
        except HTTPError as http_err:
            if http_err.empty_body:
                raise
            response_code_val = http_err.status_code,
            result_dict = {
                'error': http_err.body,
            }
        try:
            response_code_val = result_dict['status']
        except KeyError:
            result_dict['status'] = response_code
        return json_response(
            result_dict,
            status=response_code_val,
            content_type=mime_type,
            **decorator_kwargs
        )
    return decorated_handler

# Remove XML elements based on XPath expressions
import glob
import os
import lxml.etree as ET
from xml.sax.saxutils import escape
from cumulusci.core.tasks import BaseTask

class RemoveElementsXPath(BaseTask):
    task_options = {
        'items': {
            'description': 'A list of dictionaries containing file_pattern and xpath_query keys. The file_pattern key is a file path that supports wildcards and xpath_query is the xpath for the elements to remove. Multiple dictionaries can be passed in the list to run multiple removal operations in the same task. Metadata elements in the xpath need to be prefixed with ns:, for example: ./ns:Layout/ns:relatedLists',
            'required': True,
        },
        'working_dir': {
            'description': 'Change the current working directory before processing files',
        }
    }

    def _run_task(self):
        original_dir = os.getcwd()
        target_dir = self.options.get('working_dir')
        if target_dir:
            self.logger.info('Switching to directory {}'.format(target_dir))
            os.chdir(target_dir)

        for item in self.options['items']:
            self._handle_item(item)

        if target_dir:
            os.chdir(original_dir)

    def _handle_item(self, item):
        self.logger.info(
            'Removing elements matching {xpath_query} from {file_pattern}'.format(
                **item
            )
        )
        for filepath in glob.glob(item['file_pattern']):
            with open(filepath, 'r') as file_obj:
                original_content = file_obj.read()

            root = ET.parse(filepath)
            xpath_expr = item['xpath_query'].replace('ns:', '{http://soap.sforce.com/2006/04/metadata}')
            matched_elements = root.findall(xpath_expr)

            for elem in matched_elements:
                if elem.getparent() is not None:
                    elem.getparent().remove(elem)

            updated_xml = '{}\n{}\n'.format(
                '<?xml version="1.0" encoding="UTF-8"?>',
                ET.tostring(root, encoding='unicode'),
            )

            if original_content.strip() != updated_xml.strip():
                self.logger.info('Updated {}'.format(filepath))
                with open(filepath, 'w') as out_file:
                    out_file.write(updated_xml)

# Redirect utilities and candidate processing functions
from django.core.urlresolvers import reverse
from django.conf import settings
from django.http import HttpResponseRedirect
from slugify import slugify
from ..election_specific import AREA_POST_DATA
from ..models import (
    PopItPerson, membership_covers_date
)

def redirect_to_constituency(election_id, constituency_data):
    """Generate a redirect response to a constituency page"""
    simplified_label = AREA_POST_DATA.shorten_post_label(
        election_id, constituency_data['label']
    )
    return HttpResponseRedirect(
        reverse(
            'constituency',
            kwargs={
                'election': election_id,
                'post_id': constituency_data['id'],
                'ignored_slug': slugify(simplified_label),
            }
        )
    )

def extract_candidates_from_memberships(election_info, membership_list):
    """Separate current and past candidates from membership data"""
    present_candidates = set()
    previous_candidates = set()

    for membership in membership_list:
        # Skip memberships that don't match the candidate role
        if membership.get('role') != election_info['candidate_membership_role']:
            continue

        person = PopItPerson.create_from_dict(membership['person_id'])

        # Check if membership covers the election date
        if membership_covers_date(
                membership,
                election_info['election_date']
        ):
            present_candidates.add(person)
        else:
            # Look for other elections where this membership might apply
            for other_election, other_election_info in settings.ELECTIONS_BY_DATE:
                if not other_election_info.get('use_for_candidate_suggestions'):
                    continue

                if membership_covers_date(
                        membership,
                        other_election_info['election_date'],
                ):
                    previous_candidates.add(person)

    return present_candidates, previous_candidates

# Check operating system platform types
import sys

class OSChecker(object):
    @staticmethod
    def is_macos(name=None):
        name = name or sys.platform
        return 'darwin' in name

    @staticmethod
    def is_freebsd_system(name=None):
        name = name or sys.platform
        return name.startswith("freebsd")

    @staticmethod
    def is_linux_system(name=None):
        name = name or sys.platform
        return 'linux' in name

    @staticmethod
    def is_bsd_variant(name=None):
        """ Determine if the system is a BSD-like OS. """
        name = name or sys.platform
        return OSChecker.is_macos(name) or OSChecker.is_freebsd_system(name)

    @staticmethod
    def is_solaris_system(name=None):
        name = name or sys.platform
        return name == "sunos5"

    @staticmethod
    def is_unix_system(name=None):
        """ Return True if the platform is Unix-based, False otherwise. """
        name = name or sys.platform
        return (OSChecker.is_macos()
                or OSChecker.is_linux_system()
                or OSChecker.is_freebsd_system()
        )

    @staticmethod
    def is_windows(name=None):
        name = name or sys.platform
        return name == "win32"

