import discord

def member_classification(guild: discord.Guild):
    bot_count, human_count = 0, 0
    for member in guild.members:
        if member.bot:
            bot_count += 1
        else:
            human_count += 1
    return bot_count / human_count if human_count > 0 else float('inf')

async def is_guild_blacklisted(bot, guild_id: int) -> bool:
    """ Returns a bool indicating whether a guild has been blacklisted. """
    async with bot.pgpool.acquire() as conn:
        blacklist_entry = await conn.fetchrow('SELECT * FROM blacklisted_guilds WHERE guild_id = $1', guild_id)
        return blacklist_entry is not None

async def is_bot_hub(bot, guild: discord.Guild):
    """ Returns a bool indicating whether a guild is a bot collection/hub. """
    # Check if guild is blacklisted
    if await is_guild_blacklisted(bot, guild.id):
        return True

    # Keywords in the guild name suggesting bot activity
    suspicious_terms = ('bot farm', 'bot server', 'bot paradise')
    if any(term in guild.name.lower() for term in suspicious_terms):
        return True

    # Known non-bot-hub guilds (exceptions)
    safe_guild_ids = {110373943822540800, 228317351672545290}
    if guild.id in safe_guild_ids:
        return False

    # High bot-to-user ratio indicates bot hub
    if member_classification(guild) >= 8:
        return True

    return False

