from dateutil.relativedelta import relativedelta
from django.apps import apps
from django.utils import timezone

class UserDeletionManagerMixin:
    def users_to_notify(self):
        """Identifies users who have been inactive beyond the notification threshold and haven't been notified yet."""
        user_deletion_config = apps.get_app_config('user_deletion')
        cutoff_date = timezone.now() - relativedelta(
            months=user_deletion_config.MONTH_NOTIFICATION,
        )
        return self.filter(last_login__lte=cutoff_date, notified=False)

    def users_to_delete(self):
        """Identifies users who have been inactive beyond the deletion threshold and were previously notified."""
        user_deletion_config = apps.get_app_config('user_deletion')
        cutoff_date = timezone.now() - relativedelta(
            months=user_deletion_config.MONTH_DELETION,
        )
        return self.filter(last_login__lte=cutoff_date, notified=True)

import _pybinding
from scipy.sparse import csr_matrix as _sparse_csr
from .system import System as _SystemClass
from .hamiltonian import Hamiltonian as _HamiltonianClass
from .solver.solver_ex import SolverEx as _SolverClass

class CustomModel(_pybinding.Model):
    def __init__(self, *args):
        super().__init__()
        self.append(*args)

    def append(self, *args):
        for item in args:
            if item is None:
                continue
            if isinstance(item, (tuple, list)):
                self.append(*item)
            else:
                super().add(item)

    def compute(self, output):
        self._execute(output)
        return output

    @property
    def system(self) -> _SystemClass:
        sys = super().system
        sys.__class__ = _SystemClass
        sys.geometry = self.shape
        sys.lattice_structure = self.lattice
        return sys

    @property
    def _hamiltonian_matrix(self) -> _HamiltonianClass:
        ham = super().hamiltonian
        ham.__class__ = _HamiltonianClass
        return ham

    @property
    def hamiltonian(self) -> _sparse_csr:
        ham = super().hamiltonian
        ham.__class__ = _HamiltonianClass
        return ham.matrix.to_scipy_csr()

    @property
    def solver_instance(self) -> _SolverClass:
        sol = super().solver
        sol.__class__ = _SolverClass
        sol.system = self.system
        return sol

# Function to take beer from the fridge
def retrieve_beer(storage, quantity=1):
    if "beer" not in storage:
        raise Exception("No beer available:(")
    if quantity > storage["beer"]:
        raise Exception("Insufficient beer:(")
    storage["beer"] -= quantity

