def check_ping(sock):
    try:
        # Generate a random number for ping verification
        rand_val = random.randint(1, 99999)
        payload = {'request': 'ping', 'contents': {'value': rand_val}}
        SockExt.send_msg(sock, json.dumps(payload))
        response = json.loads(SockExt.recv_msg(sock))

        # Verify the response matches the sent value
        if response['return'] == rand_val:
            return True
        else:
            return False
    except Exception as error:
        print "Error during ping operation:", error
        return False

def multi_check_ping(port, hosts=[]):
    overall_result = True
    for host_ip in hosts:
        connection = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        # connection.settimeout(120.0)
        connection.connect((host_ip, int(port)))
        if not check_ping(connection):
            overall_result = False
        connection.shutdown(socket.SHUT_RDWR)
        connection.close()

    return overall_result

def is_alive(port, servers=[]):
    tries_count = 0
    status = False
    while (tries_count < conf.tries):
        try:
            if utilities.multi_check_ping(port, servers):
                status = True
                break
        except Exception as err:
            tries_count += 1
    return status

# Progress indicator for file transfers or operations
from datetime import datetime, timedelta
import sys

class FileProgress(object):
    def __init__(self, target_file, display_format):
        self.target_file = target_file
        self.display_format = display_format
        self.current_count = 0
        self.total_count = 0
        self.start_time = datetime.now()
        self.last_update_time = self.start_time

    def __call__(self, current, total):
        self.current_count = current
        self.total_count = total
        is_complete = current == total

        if datetime.now() - self.last_update_time > timedelta(seconds=0.5) or is_complete:
            formatted_output = self.display_format.format(
                filename=self.target_file,
                percentage=self.calculate_percentage(),
                rate=self.calculate_throughput()
            )
            sys.stdout.write('\r' + formatted_output)
            if is_complete:
                sys.stdout.write('\n')
            sys.stdout.flush()
            self.last_update_time = datetime.now()

    def calculate_percentage(self):
        return self.current_count / float(self.total_count)

    def calculate_throughput(self):
        elapsed_time = datetime.now() - self.start_time
        if not elapsed_time.seconds:
            return 0
        return self.current_count * 8 / float(elapsed_time.seconds) / 1000 / 1000

