# Apply a function to key-value pairs in a dictionary
def transform_kv(func, mapping):
    return dict(func(key, value) for key, value in mapping.iteritems())

# Map a function over the keys of a dictionary
def apply_to_keys(func, mapping):
    return transform_kv(lambda key, value: (func(key), value), mapping)

# Map a function over the values of a dictionary
def apply_to_values(func, mapping):
    return transform_kv(lambda key, value: (key, func(value)), mapping)

# Select key-value pairs based on a predicate function
def filter_by_key_value(pred, mapping):
    return { key: value for key, value in mapping.iteritems() if pred(key, value) }

# Extract schema information from a value
def get_schema(val):
    if not callable(val):
        val = lambda: val
    return util.fninfo(val)

# Compute dependencies from a graph structure
def compute_dependencies(graph):
    dependencies = {}
    for node, info in graph.iteritems():
        for dependency in info["required"]:
            dependencies.setdefault(node, set()).add(dependency)
    return dependencies

# Perform topological sort on dependencies
def topo_sort(dependencies):
    if not dependencies:
        return []

    # Find nodes with no incoming edges (sources)
    sources = list(set(dependencies) - set(chain(*dependencies.values())))

    if not sources:
        raise ValueError("Graph cycle detected!")

    # Recursively process remaining nodes
    remaining_deps = filter_by_key_value(lambda node, _: node not in sources, dependencies)
    return sources + topo_sort(remaining_deps)

# Compile a graph or callable into a structured format
def compile_graph(graph):
    if callable(graph):
        return graph
    else:
        # Process recursively
        processed = apply_to_values(compile_graph, graph)
        schematized = apply_to_values(get_schema, processed)

        # Compute dependencies and topological order
        deps = compute_dependencies(schematized)
        reverse_topo = topo_sort(deps)[::-1]

        return {
            "schema": schematized,
            "node_order": reverse_topo,
            "edges": deps,
        }

