def transfer_gender_to_identity(model, gender_options):
    ThroughModel = model.gender_identity.through
    for choice_code, identity_name in gender_mapping.items():
        selected_choice = gender_options[identity_name]
        profiles = model.objects.filter(gender=choice_code)

        # Create through model instances only if not already associated
        records = [
            ThroughModel(**{
                f"{model.__name__.lower()}": profile,
                "genderchoices": selected_choice
            })
            for profile in profiles 
            if not profile.gender_identity.filter(pk=selected_choice.pk).exists()
        ]
        ThroughModel.objects.bulk_create(records, ignore_conflicts=True)

