# Calculate the longest chain of words where each word is formed by removing one letter from the next
def maxWordChain(wordList):
    if not wordList:
        return 0

    # Dictionary mapping word length to set of words with that length
    lengthMap = {}
    lengths = []

    # Build the dictionary where key is word length and value is dict of words
    for word in wordList:
        length = len(word)
        if length in lengthMap:
            lengthMap[length][word] = 1
        else:
            lengthMap[length] = {word: 1}
            lengths.append(length)

    # Sort the lengths in ascending order
    lengths.sort()

    maxSize = 1
    # Process each length starting from the second smallest
    for i in range(1, len(lengths)):
        currentLength = lengths[i]
        # Check if there's a previous length (currentLength - 1)
        if currentLength - 1 in lengthMap:
            currentGroup = lengthMap[currentLength]
            for word in currentGroup:
                # Try removing each character to form a potential predecessor
                for pos in range(len(word)):
                    predecessor = word[:pos] + word[pos + 1:]
                    if predecessor in lengthMap[currentLength - 1]:
                        # Update chain size if longer chain found
                        tempSize = lengthMap[currentLength - 1][predecessor] + 1
                        if tempSize > lengthMap[currentLength][word]:
                            lengthMap[currentLength][word] = tempSize
                            if tempSize > maxSize:
                                maxSize = tempSize

    return maxSize

