@register.filter
def weekly_commit_counts(package):
    now = datetime.now()
    week_data = []
    commit_dates = Commit.objects.filter(package=package).values_list('commit_date', flat=True)

    for week_index in range(52):
        week_count = len([
            date for date in commit_dates 
            if date < now and date > (now - timedelta(days=7))
        ])
        week_data.append(week_count)
        now -= timedelta(days=7)

    week_data.reverse()
    week_data = map(str, week_data)
    return ','.join(week_data)

