@atomic
def migrate_shop_themes(*args):
    # Process theme settings that are not associated with any shop
    for theme_cfg in ThemeSettings.objects.filter(shop__isnull=True):
        for (pos, shop) in enumerate(Shop.objects.all()):
            # Skip if this shop already has a theme setting with the same identifier
            if ThemeSettings.objects.filter(shop=shop, theme_identifier=theme_cfg.theme_identifier).exists():
                continue
            # For subsequent shops, create copies by resetting primary key
            if pos > 0:
                theme_cfg.pk = None
            theme_cfg.shop = shop
            theme_cfg.save()

    # Process saved view configurations that are not associated with any shop
    for saved_view in SavedViewConfig.objects.filter(shop__isnull=True):
        for (pos, shop) in enumerate(Shop.objects.all()):
            # Skip if this shop already has a saved view config with the same identifier
            if SavedViewConfig.objects.filter(shop=shop, theme_identifier=saved_view.theme_identifier).exists():
                continue
            # For subsequent shops, create copies by resetting primary key
            if pos > 0:
                saved_view.pk = None
            saved_view.shop = shop
            saved_view.save()

