# Constant time - O(1)
def constant(x):
    value = x * x
    return value

##############################
# Logarithmic time - O(log(n))
##############################
def logarithmic(x):
    count = 0
    while x > 1:
        x = x // 2
        count += 1
    return count

###################
# Linear Time - O(n)
###################
def linear(size, arr):
    for index in range(size):
        if arr[index] == 0:
            return 0
    return 1

#########################
# Quadratic time - O(n^2)
#########################
def quadratic(size):
    counter = 0
    for i in range(size):
        for j in range(1, size):
            counter += 1
    return counter

# Generate formatted usage text for a command
from bot.action.util.textformat import FormattedText, FormattedTextFactory

class CommandHelpMessage:
    @classmethod
    def produce_formatted_help(cls, cmd_name, parameters=None, help_text=""):
        # Start with the "Usage" header in bold
        content = FormattedTextFactory.get_new_markdown().bold("Usage").newline()

        # Handle different argument types
        if isinstance(parameters, list):
            content.concat(
                FormattedTextFactory.get_new_markdown().newline().join(
                    (cls.__build_command_with_params(cmd_name, param) for param in parameters)
                )
            )
        else:
            content.concat(cls.__build_command_with_params(cmd_name, parameters))

        # Append description if provided
        if help_text:
            if not isinstance(help_text, FormattedText):
                help_text = FormattedTextFactory.get_new_markdown().raw(help_text)
            content.newline().newline().concat(help_text)

        return content

    @classmethod
    def produce_help_message(cls, cmd_name, parameters=None, help_text=""):
        return cls.produce_formatted_help(cmd_name, parameters, help_text).build_message()

    @staticmethod
    def __build_command_with_params(command, params):
        result = command
        if params:
            result += " " + params
        return FormattedTextFactory.get_new_markdown().code_inline(result)

