from types import NoneType

def normalize_mode(mode_value):
    # Check if it's already an int or None
    if isinstance(mode_value, (int, NoneType)):
        return mode_value
    try:
        # Attempt conversion to integer (e.g., '755' -> 755)
        converted = int(mode_value)
        return converted
    except (TypeError, ValueError):
        pass
    # Return original value unchanged (e.g., +x which doesn't require normalization)
    return mode_value

def perform_sed_edit(current_state, file_path, search_pattern, replacement_text, options=None):
    options = ''.join(options) if options else ''
    search_pattern = search_pattern.replace('/', '\\/')
    replacement_text = replacement_text.replace('/', '\\/')
    return 'sed -i "s/{0}/{1}/{2}" {3}'.format(
