    )

def change_ownership(path, owner_name, group_name=None, apply_recursively=False):
    base_command = 'chown'
    user_group_spec = None

    if owner_name and group_name:
        user_group_spec = '{0}:{1}'.format(owner_name, group_name)
    elif owner_name:
        user_group_spec = owner_name
    elif group_name:
        base_command = 'chgrp'
        user_group_spec = group_name

    return '{0}{1} {2} {3}'.format(
        base_command,
        ' -R' if apply_recursively else '',
        user_group_spec,
        path
    )

