import os
from threading import Thread

def _remove_and_link(target: str, source: str, should_link: bool):
    os.remove(target)
    if should_link:
        os.symlink(source, target)

def manage_files(file_list, create_symlink=False):
    # Keep the first file to avoid removing everything in directories
    keep_first = True
    reference = ""
    removed_items = []
    symlinked_items = []
    failure_messages = []

    for filepath in file_list:
        if os.path.isfile(filepath):
            if keep_first:
                keep_first = False
                reference = filepath

            else:
                Thread(target=_remove_and_link, args=(filepath, reference, create_symlink)).start()
                removed_items.append(filepath)

                if create_symlink:
                    symlinked_items.append(filepath)

        else:
            failure_messages.append("Not recognized as a file: \"{}\"".format(filepath))

    return {"kept": reference, "symlinked_files": symlinked_items, "removed_files": removed_items, "failures": failure_messages}

# Enhanced duplicate manager - handles groups of duplicate files
def manage_duplicates(dup_groups, make_link=False):
    if len(dup_groups) == 0:
        return None

    results = []
    for group in dup_groups.values():
        results.append(manage_files(group, make_link))

    return results

def remove_duplicates(dup_groups):
    return manage_duplicates(dup_groups)

def symlink_duplicates(dup_groups):
    return manage_duplicates(dup_groups, True)

# Check server availability using ping requests
import random
import json
import time
import SocketExtend as SockExt
import config as conf
import parser as p

def check_ping(sock):
    try:
        # Generate a random number for verification
        rand_val = random.randint(1, 99999)
        payload = {'request': 'ping', 'contents': {'value': rand_val}}
        SockExt.send_msg(sock, json.dumps(payload))
        response = json.loads(SockExt.recv_msg(sock))

        # Verify the response matches the sent value
        if response['return'] == rand_val:
            return True
        else:
            return False
    except Exception as error:
        print "Error during ping operation:", error
        return False

def multi_check(port, servers=[]):
    overall_result = True
    for server_ip in servers:
        connection = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        # connection.settimeout(120.0)
        connection.connect((server_ip, int(port)))

        if not check_ping(connection):
            overall_result = False

        connection.shutdown(socket.SHUT_RDWR)
        connection.close()

    return overall_result

def is_server_available(port, hosts=[]):
    tries_count = 0
    status = False

    while tries_count < conf.tries:
        try:
            if multi_check(port, hosts):
                status = True
                break
        except Exception as err:
            time.sleep(1)
            tries_count += 1

    return status

