    def _perform_action(self):
        opponents = self.difficulty_level.get_entities_not_in_faction(self.entity.faction)
        if len(opponents) > 0:
            # Find nearest opponent
            ranges = {self.entity.distance_from(o): o for o in opponents}
            min_range = min(ranges)
            nearest_opponent = ranges[min_range]

            # Check inventory for applicable items
            if self.entity.inventory is not None:
                applicable = self.entity.inventory.get_applicable_items()
                ranged_items = [item for item in applicable if item.item.can_use_item(self.entity, nearest_opponent, self.difficulty_level)]
            else:
                ranged_items = []

            # Attack if close enough
            if min_range <= 1.5:
                self.entity.combatant.attack(nearest_opponent)

            # Use ranged item if available
            if len(ranged_items) > 0:
                ranged_items[0].item.use_item(self.entity, nearest_opponent, self.difficulty_level)
            else:
                self.entity.move_to(nearest_opponent.x_pos, nearest_opponent.y_pos, self.difficulty_level)

# Import necessary modules for Redis and web handling
import json
import aioredis
from kyokai import Request
from kyokai.context import HTTPRequestContext

async def cached_execution(ctx: HTTPRequestContext, handler_func, *params, ttl=300):
    """
    Execute a coroutine with caching support.
    Saves the outcome in Redis using a generated key.
    """
    assert isinstance(ctx.redis, aioredis.Redis)
    # Generate cache key from function name and parameters
    cache_key = handler_func.__name__ + repr(params)

    # Try retrieving from cache
    cached_value = await ctx.redis.get(cache_key)
    if cached_value:
        return cached_value.decode()

    # If not cached, execute the function
    output = await handler_func(ctx, *params)

    # Store the result in Redis with expiration time
    await ctx.redis.set(cache_key, output, expire=ttl)
    return output

def to_json_response(handler_func):
    """
    Wrap a handler to automatically convert its output to JSON format.
    """
    async def wrapper(ctx: HTTPRequestContext):
        raw_result = await handler_func(ctx)
        assert isinstance(ctx.request, Request)

        if isinstance(raw_result, tuple):
            # Merge request metadata into response data
            response_data = {
                "_request": {
                    "route": ctx.request.path,
                    "api_ver": 1
                },
                **raw_result[0]
            }

            # Handle different tuple lengths
            if len(raw_result) == 1:
                return json.dumps(response_data), 200, {"Content-Type": "application/json"}
            elif len(raw_result) == 2:
                return json.dumps(response_data), raw_result[1], {"Content-Type": "application/json"}
            else:
                # Merge additional headers if provided
                extra_headers = {**{"Content-Type": "application/json"}, **raw_result[2]}
                return json.dumps(response_data), raw_result[1], extra_headers
        else:
            # Single return value case - wrap in dict with metadata
            final_data = {
                "_request": {
                    "route": ctx.request.path,
                    "api_ver": 1
                },
                **raw_result
            }
            return json.dumps(final_data), 200, {"Content-Type": "application/json"}

    return wrapper

