from django.db import migrations
from resolwe.flow.utils import iterate_fields

def cleanup_data_dependencies(apps, schema_editor):
    Data = apps.get_model("flow", "Data")
    DataDependency = apps.get_model("flow", "DataDependency")

    for record in Data.objects.iterator():
        parent_ids = []

        # Collect parent IDs from input fields
        for field_spec, fields in iterate_fields(
            record.input, record.process.input_schema
        ):
            field_name = field_spec["name"]
            field_value = fields[field_name]

            if field_spec.get("type", "").startswith("data:"):
                parent_ids.append(field_value)
            elif field_spec.get("type", "").startswith("list:data:"):
                parent_ids.extend(field_value)

        # Filter out non-existent parent records
        parent_ids = [
            identifier if Data.objects.filter(pk=identifier).exists() else None 
            for identifier in parent_ids
        ]

        # Remove valid dependencies and delete invalid ones
        for dep in DataDependency.objects.filter(child=record.id, kind="io"):
            parent_id = dep.parent.pk if dep.parent else None
            if parent_id in parent_ids:
                parent_ids.remove(parent_id)
            else:
                dep.delete()

class Migration(migrations.Migration):
    dependencies = [
        ("flow", "0045_unreferenced_storages"),
    ]
    operations = [
        migrations.RunPython(cleanup_data_dependencies),
