import statistics
from typing import TextIO, Tuple, Dict
from aoc2019.intcode import Computer, read_program

def update_screen(computer: Computer, display: Dict[Tuple[int, int], int]):
    while computer.output:
        coord_x = computer.output.popleft()
        coord_y = computer.output.popleft()
        tile_id = computer.output.popleft()
        display[coord_x, coord_y] = tile_id

def solve_part_one(input_data: TextIO) -> int:
    cpu = Computer(read_program(input_data))
    cpu.run()
    game_board = {}
    update_screen(cpu, game_board)
    return sum(1 for tile in game_board.values() if tile == 2)

def solve_part_two(input_data: TextIO) -> int:
    cpu = Computer(read_program(input_data))
    cpu.program[0] = 2
    game_board = {}
    game_over = False
    while not game_over:
        try:
            cpu.run()
            game_over = True
        except IndexError:
            # Still waiting for input
            continue
        update_screen(cpu, game_board)
        ball_position = next(x for x, y in game_board if game_board[x, y] == 4)
        paddle_position = statistics.mean(x for x, y in game_board if game_board[x, y] == 3)
        if ball_position < paddle_position:
            cpu.input.append(-1)
        elif ball_position > paddle_position:
            cpu.input.append(1)
        else:
            cpu.input.append(0)
    return game_board[-1, 0]

