            directory_list.append(full_path)
    return directory_list

def run_program():
    arguments = argv
    processed_items = []

    # Strip the script name from arguments
    del arguments[0]

    if len(arguments) == 0 or "help" in arguments:
        commands.help()
        exit(0)

    elif "detect" in arguments:
        processed_items = commands.detect(collect_paths(arguments))

    elif "delete" in arguments:
        processed_items = commands.delete(commands.detect(collect_paths(arguments)))

    elif "link" in arguments:
        processed_items = commands.link(commands.detect(collect_paths(arguments)))

    else:
        commands.help()
        exit(0)

    if len(processed_items) > 0:
        pprint(processed_items)
    else:
        print("No duplicates found")
        print("All clear! Goodbye!")

    exit(0)

