import sklearn.model_selection  # Updated import path for newer sklearn versions

class DataHandler(object):
    def __init__(self):
        self.dataset_counter = 0
        self.random_seed = 0
        self.data_source = None
        self.trained_model = None

    def load_data(self, input_dataset):
        self.trained_model = None
        self.dataset_counter += 1
        self.data_source = input_dataset
        self._features = input_dataset['data']
        self._labels = input_dataset['target']
        return True

    def has_data(self):
        return (self.data_source is not None)

    def train_model(self):
        if not self.has_data():
            return False
        classifier = self.get_classifier()
        classifier.fit(self._features, self._labels)
        self.trained_model = classifier
        return True

    def is_trained(self):
        return (self.trained_model is not None)

    def evaluate(self, validation_split=0.3):
        if not self.has_data():
            return []
        self.random_seed += 1
        classifier = self.get_classifier()
        X_train, X_val, y_train, y_val = sklearn.model_selection.train_test_split(
            self._features, self._labels, test_size=validation_split, random_state=self.random_seed
        )
        classifier.fit(X_train, y_train)
        return [classifier.score(X_val, y_val)]

    def inference(self, input_data):
        return self.trained_model.predict(input_data)

