import collections

def apply_func(func, sequence):
  for element in sequence:
    func(element)

def apply_func_unpacked(func, sequence):
  for element in sequence:
    func(*element)

def find_min_max(*values):
  minimum = None
  maximum = None
  for val in values:
    if maximum is None or val > maximum:
      maximum = val
    if minimum is None or val < minimum:
      minimum = val
  return minimum, maximum

def transform_inplace(func, data_list, level=0):
  if level <= 0:
    data_list[:] = list(map(func, data_list))
  else:
    for sub_item in data_list:
      transform_inplace(func, sub_item, level - 1)

def filter_count(func, items):
  counter = 0
  for item in items:
    if func(item):
      counter += 1
  return counter

def multi_map(sequence, *funcs):
  list(map(lambda item: [f(item) for f in funcs], sequence))

class Distribution(collections.defaultdict):
  """Represents a probability distribution and supports distance calculations"""
  def __init__(self):
    collections.defaultdict.__init__(self, int)

  def fetch(self, key, default=0):
    return dict.get(self, key, default)

  def divergence_from(self, other_dist):
    return sum(
      abs(self.fetch(bin_key) - other_dist.fetch(bin_key))
      for bin_key in set(self.keys()) | set(other_dist.keys())
    )

# Module for document field and schema handling with PDF extraction support
import inspect
from enum import IntEnum
from pdfquery import PDFQuery

class FieldType(IntEnum):
    INTEGER = 1
    STRING = 2
    FUNCTIONAL = 3  # TODO: Remove this and allow 'field_type' to accept a callable?

class Field(object):
    def __init__(self, bounding_box, field_type=FieldType.STRING, mandatory=False,
                 label=None):
        self.bounding_box = bounding_box
        self.field_type = field_type
        self.mandatory = mandatory
        self.label = label

class Schema(object):
    @classmethod
    def to_pdf_selectors(cls, field_name=None):
        """Generate pdfminer selector for given field. If no field is provided,
        selectors for all fields are returned.
        """
        if field_name is not None:
            field = getattr(cls, field_name, None)
            if (field is None) or (not isinstance(field, Field)):
                raise ValueError(
                    '{field} is not a Field attribute on {klass}'.format(
                        field=field_name, klass=cls.__name__
                    )
                )
            pdf_fields = [('report_year', field)]
        else:
            pdf_fields = inspect.getmembers(
                cls, lambda f: isinstance(f, Field)
            )
        selectors = [('convert_text', 'text')]
        selectors.extend(
            (key, 'LTTextLineHorizontal:in_bbox("{bbox}")'.format(
                bbox=', '.join(str(coord) for coord in field.bounding_box)
            ))
            for key, field in pdf_fields
        )
        return selectors

class Document(object):
    models = []
    def __init__(self, source_file):
        # TODO: Validate input is string or file-like object?
        self._source = PDFQuery(source_file)
        self._records = {}
        self._validate_setup()

    @property
    def records(self):
        """Read-only property populated after calling `process()`."""
        return self._records

    def identify_model(self):
        raise NotImplementedError('Subclass Document and override this method')

    def process(self):
        self._source.load()
        model = self.identify_model()
        selectors = model.to_pdf_selectors()
        results = self._source.extract(selectors)
        self._records = results

    def _validate_setup(self):
        if not self.models:
            raise ValueError(
                "The class '{name}' hasn't been configured with any models."
                " Set {name}.models to a list of Schema types.".format(
                    name=self.__class__.__name__
                )
            )

# Import required libraries
from scipy import optimize as opt
import numpy as np
import clean as cln

def local_minimize(function, params):
    bracket_val = params['bracket']
    bounds_val  = params['bounds']
    method_val  = params['method']
    tol_val     = params['tol']
    opts        = params['options']
    try:
        return opt.minimize_scalar(function, bracket=bracket_val, bounds=bounds_val, method=method_val, tol=tol_val, options=opts)
    except Exception as err:
        return str(err)

def global_minimize(function, params):
    initial_guess    = params['guess']
    num_iterations   = params['iterations']
    temp             = params['temperature']
    step_size        = params['stepSize']
    collect_all_mins = params['includeAllMinsFound']
    interval_val     = params['interval']
    minima_list = []

    # basinhopping function accepts a callback - passes each intermediate local minima found to callback
    if (collect_all_mins):
        def callback_func(xk, fval, accepted):
            minima_list.append([xk[0], fval, accepted])
    else:
        callback_func = None

    try:
        result = opt.basinhopping(function, x0=initial_guess, niter=num_iterations, stepsize=step_size, T=temp, callback=callback_func, interval=interval_val)
        result['x'] = result['x'].tolist()
        if (collect_all_mins):
            result['allMins'] = minima_list
        return result
    except Exception as err:
        return str(err)

def nnls(matrix_A, vector_b):
    try:
        sol, res = opt.nnls(np.array(matrix_A), np.array(vector_b))
        return {
            'solution': sol.tolist(),
            'residual': res
        }
    except Exception as err:
        return str(err)

