_proxies_tested_flag = False

def validate_proxies():
    global _proxies_tested_flag

    if _proxies_tested_flag:
        return

    _proxies_tested_flag = {}

    def _check_proxy(proxy_addr):
        if proxy_addr == '':
            return True

        if _proxies_tested_flag.get(proxy_addr) is not None:
            return _proxies_tested_flag.get(proxy_addr)

        print("Checking proxy", proxy_addr)
        proxy_handler = urllib.request.ProxyHandler({'http': proxy_addr, 'https': proxy_addr})
        url_opener = urllib.request.build_opener(proxy_handler)

        try:
            response = url_opener.open('http://example.com')
            if not response:
                _proxies_tested_flag[proxy_addr] = False
                return False
            content = response.read()
            assert(content.find(b"Example Domain") > -1)

        except urllib.error.URLError as err:
            try:
                response = url_opener.open('http://google.com')
                if not response:
                    _proxies_tested_flag[proxy_addr] = False
                    return False

            except urllib.error.URLError as err:
                print("Proxy issue", proxy_addr, err)
                _proxies_tested_flag[proxy_addr] = False
                return False

        _proxies_tested_flag[proxy_addr] = True
        return True

