# Convert RGBA float values (0-1) to a 32-bit integer color
def rgba_to_int(r, g, b, a=1.0):
    if any(map(lambda val: val < 0 or val > 1, (r, g, b, a))):
        raise ValueError("Values must be in the range 0..1 (inclusive)")
    r, g, b, a = map(lambda component: int(0xFF * component), (r, g, b, a))
    return (a << 24) | (r << 16) | (g << 8) | b

# Migration script to sanitize stream names and user display names
from django.db import models, migrations
from django.db.backends.postgresql_psycopg2.schema import DatabaseSchemaEditor
from django.db.migrations.state import StateApps
from typing import Text

def clean_stream_names(apps, schema_editor):
    # type: (StateApps, DatabaseSchemaEditor) -> None
    StreamModel = apps.get_model('zerver', 'Stream')
    PROHIBITED_CHARS = ['*', '@', '`', '#']

    for stream_obj in StreamModel.objects.all():
        if set(stream_obj.name).intersection(PROHIBITED_CHARS):
            for symbol in PROHIBITED_CHARS:
                stream_obj.name = stream_obj.name.replace(symbol, ' ').strip()

            while StreamModel.objects.filter(name__iexact=stream_obj.name, realm=stream_obj.realm).exists():
                stream_obj.name = stream_obj.name + '^'
                if len(stream_obj.name) > 60:
                    # Handle edge case where name exceeds max length
                    stream_obj.name = stream_obj.name[-60:]

            stream_obj.save(update_fields=['name'])

def clean_user_display_names(apps, schema_editor):
    # type: (StateApps, DatabaseSchemaEditor) -> None
    UserProfileModel = apps.get_model('zerver', 'UserProfile')
    FORBIDDEN_CHARS = ['*', '`', '>', '"', '@', '#']

    for user_obj in UserProfileModel.objects.all():
        # Clean full_name field
        if set(user_obj.full_name).intersection(FORBIDDEN_CHARS):
            for char in FORBIDDEN_CHARS:
                user_obj.full_name = user_obj.full_name.replace(char, ' ').strip()
            user_obj.save(update_fields=['full_name'])

        # Clean short_name field
        if set(user_obj.short_name).intersection(FORBIDDEN_CHARS):
            for char in FORBIDDEN_CHARS:
                user_obj.short_name = user_obj.short_name.replace(char, ' ').strip()
            user_obj.save(update_fields=['short_name'])

class Migration(migrations.Migration):
    dependencies = [
        ('zerver', '0125_realm_max_invites'),
    ]
    operations = [
        migrations.RunPython(clean_stream_names),
        migrations.RunPython(clean_user_display_names),
    ]

import math
import re

def process_thing_flags_read(flag_value, flag_table):
    """
    Processes a thing's flags value.

    Extended patches can use mnemonics for flag names, separated by plus signs.

    @raise LookupError: if the value contains an unknown mnemonic.
        """ 
    if flag_value.isdigit() == True:
        return flag_value

    parts = re.split(r"[,+| \t\f\r]+", flag_value)
    result = 0

    for part in parts:
        part = part.strip()

        # Locate the index of the flag mnemonic and convert it to a flag value.
        flag_entry = flag_table.flags.get(part)
        if flag_entry is None:
            raise LookupError('Ignoring unknown thing flag {}.'.format(part))
        mask = int(math.pow(2, flag_entry['index']))
        result += mask

    return result


def process_thing_flags_write(flag_value, flag_table):
    """
    Converts a thing flags value into a string of mnemonics. 
    """

    bit_position = 1
    output_list = []

    for _ in range(0, 32):
        if (flag_value & bit_position) == 0:
            bit_position *= 2
            continue

        for key_name, flag_data in flag_table.flags.iteritems():
            if int(math.pow(2, flag_data['index'])) == bit_position:    
                output_list.append(key_name)
                break

        bit_position *= 2

    if len(output_list) == 0:
        return 0
    else:
        return '+'.join(output_list)

