import random
from dataclasses import dataclass
from typing import List
from training.dataset.vos_segment_loader import LazySegments

MAX_ATTEMPTS = 1000

@dataclass
class FrameObjectSample:
    selected_frames: List[int]
    selected_objects: List[int]

class VideoSampler:
    def __init__(self, order_frames=True):
        # Frames are sorted by frame index when order_frames is True
        self.order_frames = order_frames

    def sample(self, video):
        raise NotImplementedError()

class UniformRandomSampler(VideoSampler):
    def __init__(
        self,
        frame_count,
        max_obj_count,
        time_reverse_chance=0.0,
    ):
        self.frame_count = frame_count
        self.max_obj_count = max_obj_count
        self.time_reverse_chance = time_reverse_chance

    def sample(self, video, segment_provider, current_epoch=None):
        for attempt in range(MAX_ATTEMPTS):
            if len(video.frames) < self.frame_count:
                raise Exception(
                    f"Cannot extract {self.frame_count} frames from video {video.video_name} since it contains only {len(video.frames)} annotated frames."
                )

            start_idx = random.randrange(0, len(video.frames) - self.frame_count + 1)
            sampled_frames = [video.frames[start_idx + offset] for offset in range(self.frame_count)]

            if random.uniform(0, 1) < self.time_reverse_chance:
                # Reverse temporal order
                sampled_frames = sampled_frames[::-1]

            # Retrieve object IDs from the first frame
            candidate_objects = []
            first_frame_segments = segment_provider.load(sampled_frames[0].frame_idx)

            if isinstance(first_frame_segments, LazySegments):
                # LazySegments used for SA1BRawDataset
                candidate_objects = list(first_frame_segments.keys())
            else:
                for obj_id, mask in segment_provider.load(sampled_frames[0].frame_idx).items():
                    if mask.sum() > 0:
                        candidate_objects.append(obj_id)

            # Ensure at least one object is visible in the first frame
            if len(candidate_objects) > 0:
                break

            if attempt >= MAX_ATTEMPTS - 1:
                raise Exception("No visible objects found")

        # Select a subset of objects up to max_obj_count
        final_objects = random.sample(
            candidate_objects,
            min(len(candidate_objects), self.max_obj_count),
        )
        return FrameObjectSample(selected_frames=sampled_frames, selected_objects=final_objects)

class EvaluationSampler(VideoSampler):
    """
    VOS Sampler for evaluation: selects all frames and all objects in a video
    """
    def __init__(self):
        super().__init__()

    def sample(self, video, segment_provider, current_epoch=None):
        """
        Sampling all frames and all objects present in the video
        """
        if self.order_frames:
            # Sort frames by frame index
            frames = sorted(video.frames, key=lambda x: x.frame_idx)
        else:
            # Preserve original frame order
            frames = video.frames

        # Get object IDs from the first frame
        object_ids = list(segment_provider.load(frames[0].frame_idx).keys())

        if len(object_ids) == 0:
            raise Exception("First frame of the video contains no objects")

        return FrameObjectSample(selected_frames=frames, selected_objects=object_ids)

