from uuid import UUID
from celery import chain
from common.dependencies import get_file_repository, get_file_scheduling_service
from common.file.file_repository import Tag
from common.services.query_builder import QueryParameters
from worker.index_file.add_tags_to_file_task import FileNotFoundException, app, logger
from worker.index_file.infra.file_indexing_task import FileIndexingTask
from worker.index_file.tasks import persist_processing_done
from worker.index_file.tasks.persist_tags import persist_remove_tag

@app.task()
def execute_tag_removal(
    tag: Tag,
):
    logger.info("initiating tag removal process for: '%s' ", tag)
    repo = get_file_repository()
    search_params = QueryParameters(
        query_id=repo.open_point_in_time(), search_string=f'tags: "{tag}"'
    )
    for file_record in repo.get_generator_by_query(query=search_params):
        initiate_single_file_removal.s(file_id=file_record.id_, tag=tag).delay().forget()

@app.task()
def initiate_single_file_removal(
    file_id: UUID,
    tag: Tag,
):
    logger.info("removing tag '%s' from file identified by id '%s'", tag, file_id)
    get_file_scheduling_service().remove_tag(file_id, tag)

@app.task(base=FileIndexingTask)
def process_tag_removal(file_id: UUID, tag: Tag):
    logger.info("processing tag '%s' removal for file with id '%s'", tag, file_id)
    target_file = get_file_repository().get_by_id(file_id)
    if target_file is None:
        raise FileNotFoundException("no matching file found")
    chain(
        persist_remove_tag.s(tag, target_file), persist_processing_done.signature(target_file)
    ).delay().forget()

