import fnmatch
import logging
import os
import re
import sys
from . import DistlibException
from .compat import fsdecode
from .util import convert_path

__all__ = ['Manifest']
logger = logging.getLogger(__name__)

# Pattern to match backslash followed by spaces and newline
_COLLAPSE_PATTERN = re.compile('\\\\s*\n', re.M)
# Pattern to match commented lines or end-of-line
_COMMENTED_LINE = re.compile('#.*?(?=\n)|\n(?=$)', re.M | re.S)

# Version check for Python-specific behavior
_PYTHON_VERSION = sys.version_info[:2]

class Manifest(object):
    """
    A list of files constructed by traversing the filesystem and filtered using various
    patterns applied to discovered items.
    """
    def __init__(self, root=None):
        """
        Initialize a manifest instance.
        :param root: The root directory to scan.
        """
        self.root = os.path.abspath(os.path.normpath(root or os.getcwd()))
        self.prefix = self.root + os.sep
        self.allfiles = None
        self.items = set()

    #
    # Public API
    #
    def discover(self):
        """Scan recursively under root and populate ``allfiles`` with absolute paths."""
        from stat import S_ISREG, S_ISDIR, S_ISLNK
        self.allfiles = all_files = []
        current_root = self.root
        stack = [current_root]
        pop = stack.pop
        push = stack.append

        while stack:
            current_root = pop()
            try:
                names = os.listdir(current_root)
            except OSError:
                continue

            for name in names:
                full_path = os.path.join(current_root, name)
                try:
                    stat_info = os.stat(full_path)
                    mode = stat_info.st_mode
                    if S_ISREG(mode):
                        all_files.append(fsdecode(full_path))
                    elif S_ISDIR(mode) and not S_ISLNK(mode):
                        push(full_path)
                except OSError:
                    continue

    def add_item(self, path):
        """
        Add a file to the manifest.
        :param path: Path to add (can be relative to root).
        """
        if not path.startswith(self.prefix):
            path = os.path.join(self.root, path)
        self.items.add(os.path.normpath(path))

    def add_multiple(self, paths):
        """
        Add multiple files to the manifest.
        :param paths: List of paths to add (each can be relative to root).
        """
        for path in paths:
            self.add_item(path)

    def get_sorted(self, include_dirs=False):
        """
        Return sorted list of files in directory order.
        """
        def include_parent_directory(directories, directory):
            directories.add(directory)
            logger.debug('Added directory %s', directory)
            if directory != self.root:
                parent_dir, _ = os.path.split(directory)
                assert parent_dir not in ('', '/')
                include_parent_directory(directories, parent_dir)

        result = set(self.items)  # copy
        if include_dirs:
            directories = set()
            for item in result:
                include_parent_directory(directories, os.path.dirname(item))
            result |= directories

        return [os.path.join(*path_parts) for path_parts in
                sorted(os.path.split(p) for p in result)]

    def reset(self):
        """Clear all collected files."""
        self.items = set()
        self.allfiles = []

    def apply_directive(self, directive):
        """
        Apply a directive to include/exclude files based on patterns.
        :param directive: Directive string in MANIFEST.in format.
        """
        action, patterns, directory, dir_pattern = self._parse_manifest_directive(directive)

        if action == 'append':
            for pattern in patterns:
                if not self._apply_include(pattern, anchor=True):
                    logger.warning('No files matched pattern %r', pattern)
        elif action == 'remove':
            for pattern in patterns:
                self._apply_exclude(pattern, anchor=True)
        elif action == 'global-append':
            for pattern in patterns:
                if not self._apply_include(pattern, anchor=False):
                    logger.warning('No files found matching %r '
                                   'anywhere in distribution', pattern)
        elif action == 'global-remove':
            for pattern in patterns:
                self._apply_exclude(pattern, anchor=False)
        elif action == 'recursive-append':
            for pattern in patterns:
                if not self._apply_include(pattern, prefix=directory):
                    logger.warning('No files found matching %r '
                                   'under directory %r', pattern, directory)
        elif action == 'recursive-remove':
            for pattern in patterns:
                self._apply_exclude(pattern, prefix=directory)
        elif action == 'add-tree':
            if not self._apply_include(None, prefix=dir_pattern):
                logger.warning('No directories found matching %r',
                               dir_pattern)
        elif action == 'remove-tree':
            if not self._apply_exclude(None, prefix=dir_pattern):
                logger.warning('No previously-included directories found '
                               'matching %r', dir_pattern)
        else:
            raise DistlibException(
                'Invalid directive action %r' % action)

    #
    # Private API
    #
    def _parse_manifest_directive(self, directive):
        """
        Validate and parse a manifest directive.
        :param directive: Directive string to parse.
        :return: Tuple (action, patterns, directory, dir_pattern)
        """
        tokens = directive.split()
        if len(tokens) == 1 and tokens[0] not in ('append', 'remove',
                                                  'global-append',
                                                  'global-remove',
                                                  'recursive-append',
                                                  'recursive-remove',
                                                  'add-tree', 'remove-tree'):
            tokens.insert(0, 'append')

        action = tokens[0]
        patterns = directory = dir_pattern = None

        if action in ('append', 'remove', 'global-append', 'global-remove'):
            if len(tokens) < 2:
                raise DistlibException(
                    '%r requires at least one pattern' % action)
            patterns = [convert_path(token) for token in tokens[1:]]
        elif action in ('recursive-append', 'recursive-remove'):
            if len(tokens) < 3:
                raise DistlibException(
                    '%r requires <dir> <pattern1> <pattern2> ...' % action)
            directory = convert_path(tokens[1])
            patterns = [convert_path(token) for token in tokens[2:]]
        elif action in ('add-tree', 'remove-tree'):
            if len(tokens) != 2:
                raise DistlibException(
                    '%r requires exactly one directory pattern' % action)
            dir_pattern = convert_path(tokens[1])
        else:
            raise DistlibException('Unknown action %r' % action)

        return action, patterns, directory, dir_pattern

    def _apply_include(self, pattern, anchor=True, prefix=None,
                       use_regex=False):
        """Select files from allfiles that match the given pattern and add them to items.
        Return True if any files matched.
        """
        found = False
        regex = self._convert_to_regex(pattern, anchor, prefix, use_regex)

        if self.allfiles is None:
            self.discover()

        for filename in self.allfiles:
            if regex.search(filename):
                self.items.add(filename)
                found = True

        return found

    def _apply_exclude(self, pattern, anchor=True, prefix=None,
                       use_regex=False):
        """Remove files matching pattern from items.
        Return True if any files were removed.
        """
        found = False
        regex = self._convert_to_regex(pattern, anchor, prefix, use_regex)

        for f in list(self.items):
            if regex.search(f):
                self.items.remove(f)
                found = True

        return found

    def _convert_to_regex(self, pattern, anchor=True, prefix=None,
                          use_regex=False):
        """Convert shell-like glob pattern to compiled regular expression."""
        if use_regex:
            if isinstance(pattern, str):
                return re.compile(pattern)
            else:
                return pattern

        if _PYTHON_VERSION > (3, 2):
            start_marker, _, end_marker = self._glob_to_regex('_').partition('_')

        if pattern:
            pattern_re = self._glob_to_regex(pattern)
            if _PYTHON_VERSION > (3, 2):
                assert pattern_re.startswith(start_marker) and pattern_re.endswith(end_marker)
        else:
            pattern_re = ''

        base = re.escape(os.path.join(self.root, ''))

        if prefix is not None:
            if _PYTHON_VERSION <= (3, 2):
                empty_glob = self._glob_to_regex('')
                prefix_re = self._glob_to_regex(prefix)[:-len(empty_glob)]
            else:
                prefix_re = self._glob_to_regex(prefix)
                assert prefix_re.startswith(start_marker) and prefix_re.endswith(end_marker)
                prefix_re = prefix_re[len(start_marker): len(prefix_re) - len(end_marker)]

            sep = os.sep
            if os.sep == '\\':
                sep = r'\\'

            if _PYTHON_VERSION <= (3, 2):
                pattern_re = '^' + base + sep.join((prefix_re, '.*' + pattern_re))
            else:
                pattern_re = pattern_re[len(start_marker): len(pattern_re) - len(end_marker)]
                pattern_re = r'%s%s%s%s.*%s%s' % (start_marker, base, prefix_re, sep,
                                                  pattern_re, end_marker)
        else:
            if anchor:
                if _PYTHON_VERSION <= (3, 2):
                    pattern_re = '^' + base + pattern_re
                else:
                    pattern_re = r'%s%s%s' % (start_marker, base, pattern_re[len(start_marker):])

        return re.compile(pattern_re)

    def _glob_to_regex(self, pattern):
        """Translate a glob pattern to a regular expression string."""
        regex = fnmatch.translate(pattern)

        # Replace unescaped dots to avoid matching path separators
        sep = os.sep
        if os.sep == '\\':
            sep = r'\\\\'

        replacement = r'\1[^%s]' % sep
        regex = re.sub(r'((?<!\\)(\\\\)*)\.', replacement, regex)
        return regex

# Custom logging setup for whimbox application
from loguru import logger
import types
import os, sys
import time
from whimbox.common.path_lib import *
from whimbox.common.cvars import DEBUG_MODE
import datetime

log_prefix = 'whimbox-'

def get_timestamp():
    return time.strftime('%Y-%m-%d %H:%M:%S', time.localtime())

def get_datestamp():
    return time.strftime('%Y-%m-%d', time.localtime())

logged_once = {}

def warn_once(self, msg):
    already_warned = logged_once.setdefault(msg, False)
    if not already_warned:
        self.warning(msg)
        logged_once[msg] = True

def demo_log(self, msg):
    self.info(f"DEMO: {msg}")

def cleanup_old_logs(directory, max_age_days):
    current_time = datetime.datetime.now()
    for dirpath, _, filenames in os.walk(directory):
        for filename in filenames:
            if filename.startswith(log_prefix):
                full_path = os.path.join(dirpath, filename)
                file_mtime = datetime.datetime.fromtimestamp(os.path.getmtime(full_path))
                age_in_days = (current_time - file_mtime).days
                if age_in_days > max_age_days:
                    if DEBUG_MODE:
                        print(f"Log Cleanup: Removing {full_path} (Last modified: {file_mtime}, Days since modification: {age_in_days}, Threshold: {max_age_days})")
                    os.remove(full_path)

cleanup_old_logs(LOG_PATH, 7)

# Configure loguru handlers and extensions
