logger.warn_once = types.MethodType(warn_once, logger)
logger.demo_log = types.MethodType(demo_log, logger)
logger.add(os.path.join(LOG_PATH, log_prefix + "{time:YYYY-MM-DD}.log"), level="TRACE", backtrace=True)

if DEBUG_MODE:
    logger.add(sys.stdout, level="TRACE", backtrace=True)
else:
    logger.add(sys.stdout, level="INFO", backtrace=True)

def hr_section(title, level=3):
    title_str = str(title).upper()
    if level == 1:
        logger.info('=' * 20 + ' ' + title_str + ' ' + '=' * 20)
    elif level == 2:
        logger.info('-' * 20 + ' ' + title_str + ' ' + '-' * 20)
    elif level == 3:
        logger.info('<' * 3 + ' ' + title_str + ' ' + '>' * 3)
    elif level == 0:
        content_line = '|' + ' ' * 20 + title_str + ' ' * 20 + '|'
        border_line = '+' + '-' * (len(content_line) - 2) + '+'
        logger.info(border_line)
        logger.info(content_line)
        logger.info(border_line)

def log_attribute(name, value):
    logger.info('[%s] %s' % (str(name), str(value)))

def log_aligned(name, value, prefix='', width=22):
    name_str = str(name).rjust(width)
    if prefix:
        name_str = prefix + name_str[len(prefix):]
    logger.info('%s: %s' % (name_str, str(value)))

logger.hr = types.MethodType(hr_section, logger)
logger.attr = types.MethodType(log_attribute, logger)
logger.attr_align = types.MethodType(log_aligned, logger)

