# Process LLM output to preserve only the largest code section for a given language
from .get_comment import get_comment
from .comment_line import comment_line
from .find_section import find_section

def postprocess_0(llm_output: str, language: str) -> str:
    # Step 1: Retrieve the comment character corresponding to the language
    comment_char = get_comment(language)

    # Step 2: Split the LLM output into lines and identify code sections
    lines = llm_output.splitlines()
    sections = find_section(lines)

    # Step 3: Locate the largest code section matching the specified language
    best_section = None
    max_length = 0
    for lang_tag, start_idx, end_idx in sections:
        if lang_tag.lower() == language.lower():
            section_length = end_idx - start_idx
            if section_length > max_length:
                max_length = section_length
                best_section = (start_idx, end_idx)

    # Step 4 & 5: Comment out lines outside the selected code section
    updated_lines = []
    inside_code_block = False
    for idx, current_line in enumerate(lines):
        if best_section and idx == best_section[0] + 1:
            inside_code_block = True
        elif best_section and idx == best_section[1]:
            inside_code_block = False

        if not inside_code_block:
            updated_lines.append(comment_line(current_line, comment_char))
        else:
            updated_lines.append(current_line)

    # Return the final processed string
    return '\n'.join(updated_lines)

import string
import pandas as pd
from mindspeed_mm.tasks.evaluation.eval_datasets.datasets_base import BaseEvalDataset
from mindspeed_mm.tasks.evaluation.utils.string_utils import string_to_list, is_expected_type

class MMMUEvalDataset(BaseEvalDataset):
    def __init__(self, dataset_path, dataset_name):
        super().__init__(dataset_path, dataset_name)

    @staticmethod
    def split_MMMU(messages):
        text_content, image_list = None, []
        for item in messages:
            if item['type'] == 'image':
                image_list.append(item['value'])
            elif item['type'] == 'text':
                if text_content is not None:
                    raise ValueError("Multiple text messages found")
                text_content = item['value']

        text_parts = text_content.split('<image ')
        if len(text_parts) == 1:
            return messages

        segments = [dict(type='text', value=text_parts[0])]
        for idx, part in enumerate(text_parts):
            if idx == 0:
                continue
            if not (is_expected_type(part[0], int) and part[1] == '>'):
                raise ValueError("Invalid image tag format")
            img_index = int(part[0]) - 1
            segments.append(dict(type='image', value=image_list[img_index]))
            segments.append(dict(type='text', value=part[2:]))
        return segments

    def _construct_prompt(self, row):
        if isinstance(row, int):
            row = self.data.iloc[row]

        if self.meta_only:
            target_paths = string_to_list(row['image_path'])
        else:
            target_paths = self.dump_image(row)

        question_text = row['question']
        choices = {
            letter: row[letter]
            for letter in string.ascii_uppercase
            if letter in row and not pd.isna(row[letter])
        }

        options_text = 'Options:\n'
        for label, content in choices.items():
            options_text += f'{label}. {content}\n'

        hint_text = row['hint'] if ('hint' in row and not pd.isna(row['hint'])) else None

        final_prompt = ''
        if hint_text is not None:
            final_prompt += f'Hint: {hint_text}\n'
        final_prompt += f'Question: {question_text}\n'

        if len(choices):
            final_prompt += options_text
            final_prompt += 'Please select the correct answer from the options above. \n'

        prompt_messages = []
        if isinstance(target_paths, list):
            prompt_messages.extend([dict(type='image', value=path) for path in target_paths])
        else:
            prompt_messages = [dict(type='image', value=target_paths)]

        prompt_messages.append(dict(type='text', value=final_prompt))
        return prompt_messages

    def build_prompt(self, sample):
        initial_msgs = self._construct_prompt(sample)
        processed_msgs = self.split_MMMU(initial_msgs)
        return processed_msgs

# Modified version with Type I clone transformations (variable renaming, literal changes, statement reordering)
import os
import string
import torch
import torch.distributed as dist
import pandas as pd
from tqdm import tqdm
from megatron.core import mpu
from mindspeed_mm.utils.security_utils.input_filter import sanitize_dataframe
from mindspeed_mm.utils.security_utils.validate_path import normalize_path
from mindspeed_mm.tasks.evaluation.utils.analysis_utils import mmmu_open_question_preprocess, report_acc, eval_vanilla, \
    track_progress_rich
from mindspeed_mm.tasks.evaluation.utils.string_utils import logger_rank_0
from mindspeed_mm.tasks.evaluation.utils.file_utils import load_json, save_json
from mindspeed_mm.tasks.evaluation.eval_prompt.build_prompt_base import BasePromptTemplate
from mindspeed_mm.tasks.evaluation.eval_datasets.datasets_base import BaseEvalDataset

class BaseEvalImpl:
    def __init__(self, dataset_obj: BaseEvalDataset, infer_pipeline, config_args, prompt_template=None, remove_tail=False):
        self.local_rank = mpu.get_data_parallel_group().rank()
        self.world_proc_num = mpu.get_data_parallel_world_size()
        self.save_dir = normalize_path(config_args.result_output_path)[0]
        os.makedirs(self.save_dir, exist_ok=True)
        model_id = config_args.evaluation_model
        self.dataset_obj = dataset_obj
        self.infer_pipeline = infer_pipeline
        self.prompt_template = prompt_template
        self.dataset_id = config_args.evaluation_dataset
        self.allowed_types = ['text', 'image', 'video']
        self.xlsx_file = os.path.join(self.save_dir, model_id + "_" + self.dataset_id + ".xlsx")
        self.prev_result = os.path.join(self.save_dir, model_id + "_" + self.dataset_id + "_PREV.json")
        # Store per-rank output files
        self.rank_out_file = self._get_rank_file(self.local_rank)
        self.acc_report = self.xlsx_file.replace('.xlsx', '_acc.xlsx')

        is_even_split = len(dataset_obj) % self.world_proc_num == 0
        remainder_items = len(dataset_obj) % self.world_proc_num

        if is_even_split:
            total_samples = len(dataset_obj)
        elif remove_tail and not is_even_split:
            raise ValueError("remove_tail must be false in current implementation")
        elif not remove_tail and not is_even_split:
            print(f"dataset length: {len(dataset_obj)}, world size: {self.world_proc_num}, remainder: {remainder_items}")
            raise ValueError(f'Total samples ({len(dataset_obj)}) must be divisible by world size ({self.world_proc_num}).')

        assigned_indices = list(range(self.local_rank, total_samples, self.world_proc_num))
        print(f"Rank {self.local_rank} handles {len(assigned_indices)} samples for evaluation")

        self.data_subset = dataset_obj.data.iloc[assigned_indices]
        self.sample_ids = [idx for idx in self.data_subset['index']]
        self.partial_results = load_json(self.prev_result) if os.path.exists(self.prev_result) else {}

    def __call__(self):
        """
        Execute evaluation pipeline and store results to disk
        """
        filtered_data = self.data_subset[~self.data_subset['index'].isin(self.partial_results)]
        num_samples = len(filtered_data)

        for idx in tqdm(range(num_samples)):
            sample_index = filtered_data.iloc[idx]['index']

            if sample_index in self.partial_results:
                continue

            if self.prompt_template and self.prompt_template.is_custom_prompt_required(self.dataset_id):
                prompt_content = self.prompt_template.construct_prompt(filtered_data.iloc[idx], 
                                                                       self.dataset_obj.dump_image,
                                                                       self.dataset_id)
            else:
                prompt_content = self.dataset_obj.create_prompt(filtered_data.iloc[idx])

            BasePromptTemplate.validate_content_type(prompt_content)
            instruction = BasePromptTemplate.apply_preprocessing(prompt_content)

            if instruction is None or BasePromptTemplate.validate_content_type(instruction) != 'ListOfDict':
                raise ValueError(f'Invalid instruction format: {instruction}. Only ListOfDict allowed.')

            for segment in instruction:
                if segment['modality'] not in self.allowed_types:
                    raise ValueError(
                        f'Modality "{segment["modality"]}" unsupported. Allowed: {", ".join(self.allowed_types)}')

            # Synchronize all processes before inference
            dist.barrier()

            if hasattr(self.infer_pipeline, "run_evaluation"):
                model_response = self.infer_pipeline.run_evaluation(instruction)
            else:
                text_segments, image_list = '', []
                for segment in instruction:
                    if segment['modality'] == 'text':
                        text_segments += segment['value']
                    elif segment['modality'] == 'image':
                        image_list.append(segment['value'])
                    else:
                        raise Exception("Unsupported modality type")
                model_response = self.infer_pipeline(prompt=text_segments, images=image_list, return_ids=True)

            torch.cuda.empty_cache()

            if model_response is not None:
                print(model_response, flush=True)
                self.partial_results[sample_index] = model_response

            # Save intermediate results every 20 iterations
            if (
                ((idx + 1) % 20 == 0)
                and mpu.is_pipeline_last_stage()
                and (mpu.get_tensor_model_parallel_rank() == 0)
            ):
                save_json(self.partial_results, self.rank_out_file)

        # Final save on last rank
        if mpu.is_pipeline_last_stage() and mpu.get_tensor_model_parallel_rank() == 0:
            final_results = {k: self.partial_results[k] for k in self.sample_ids}
            save_json(final_results, self.rank_out_file)

    def gather_result(self):
        """
        Aggregate evaluation outputs from all ranks
        """
        if self.world_proc_num > 0:
            print("rank:", self.local_rank, " completed evaluation")
            dist.barrier()

        if torch.distributed.get_rank() == 0:
            aggregated_data = {}
            for r in range(self.world_proc_num):
                aggregated_data.update(load_json(self._get_rank_file(r)))

            full_dataset = self.dataset_obj.data
            for item_id in full_dataset['index']:
                if item_id not in aggregated_data:
                    raise ValueError(f"{item_id} missing in aggregated results")

            full_dataset['prediction'] = [str(aggregated_data.get(idx, None)) for idx in full_dataset['index']]

            if 'image' in full_dataset.columns:
                full_dataset.drop(columns=['image'], inplace=True)

            full_dataset.to_excel(self.xlsx_file, index=False, engine='xlsxwriter')

            for r in range(self.world_proc_num):
                os.remove(self._get_rank_file(r))

        if self.world_proc_num > 0:
            dist.barrier()

    def analyse_result(self):
        if self.world_proc_num > 0:
            dist.barrier()

        if torch.distributed.get_rank() == 0:
            result_df = pd.read_excel(self.xlsx_file)
            result_df.sort_values(by='index', inplace=True)
            result_df['prediction'] = result_df['prediction'].astype(str)

            # Rename columns to lowercase where appropriate
            for col in result_df.columns:
                new_col = col.lower() if col not in list(string.ascii_uppercase) else col
                if new_col != col:
                    result_df.rename(columns={col: new_col}, inplace=True)

            meta_info = self.dataset_obj.data
            question_map = {row['index']: row['question'] for _, row in meta_info.iterrows()}
            result_question_map = {row['index']: row['question'] for _, row in result_df.iterrows()}

            for qid in result_question_map:
                if qid not in question_map:
                    raise ValueError(
                        f'Result file should match or be subset of dataset {self.dataset_id}'
                    )

            evaluation_results = {}
            answer_key = {row['index']: row['answer'] for _, row in meta_info.iterrows()}

            if 'MMMU' in self.dataset_id:
                result_df = mmmu_open_question_preprocess(result_df)
                answer_key = {k: ('A' if v not in list(string.ascii_uppercase) else v) 
                             for k, v in answer_key.items()}

            filtered_result = result_df[result_df['index'].isin(answer_key)]
            filtered_result['GT'] = [answer_key[idx] for idx in filtered_result['index']]

            processed_items = []
            for i in range(len(filtered_result)):
                item = filtered_result.iloc[i]
                if item['index'] not in evaluation_results:
                    processed_items.append(item)

            task_configs = [dict(item=x, dataset_name=self.dataset_id) for x in processed_items]
            item_keys = [x['index'] for x in processed_items]

            if task_configs:
                eval_outputs = track_progress_rich(eval_vanilla, task_configs, nproc=1, chunksize=1, 
                                                  save=self.prev_result, keys=item_keys)
                temp_results = load_json(self.prev_result)
                for key, value in zip(item_keys, eval_outputs):
                    temp_results[key] = value

            filtered_result['hit'] = [temp_results.get(i, {}).get('hit', None) for i in filtered_result['index']]
            filtered_result['log'] = [temp_results.get(i, {}).get('log', None) for i in filtered_result['index']]

            if 'GT' in filtered_result.columns:
                filtered_result.drop(columns=['GT'], inplace=True)

            cleaned_df = sanitize_dataframe(filtered_result)
            cleaned_df.to_excel(self.xlsx_file, index=False, engine='xlsxwriter')

            accuracy_summary = report_acc(filtered_result)
            cleaned_acc = sanitize_dataframe(accuracy_summary)
            cleaned_acc.to_excel(self.acc_report, index=False, engine='xlsxwriter')
            logger_rank_0(f"Accuracy report saved to {self.acc_report}")

        if self.world_proc_num > 0:
            dist.barrier()

    def _get_rank_file(self, rank_id):
        return os.path.join(self.save_dir,
                           str(rank_id) + "_" + f'{self.world_proc_num}_{self.dataset_id}.json')

# Check if the market is open for forex trading
import datetime

def fetch_trading_symbol(exchange_name: str):
    if exchange_name == 'binance':
        return 'BTC-USDT'
    elif exchange_name == 'okx':
        return 'ADA-USDT'
    elif exchange_name == 'coinbase_pro':
        return 'BTC-USD'
    elif exchange_name == 'alpaca':
        return 'AAPL'
    elif exchange_name == 'oanda':
        return 'EUR-USD'
    elif exchange_name == 'ftx':
        return 'BTC-USD'
    elif exchange_name == 'kucoin':
        return 'ETH-USDT'
    else:
        raise LookupError("Specified exchange not found.")

def is_forex_market_active():
    current_time = datetime.datetime.now()
    # Friday is represented as 4, Saturday as 5
    # Note: Market technically reopens at 5pm Sunday, but this case isn't handled here
    if current_time.weekday() >= 5:
        return False
    elif current_time.weekday() >= 4 and current_time.hour >= 17:
        return False
    else:
        return True

# Modified version of AbstractModel with renamed variables and reordered logic
import json
import sys

class BaseModel(object):
    """Base class for all data models."""

    def _convert_to_dict(self, skip_none=True):
        """Convert object to dictionary representation, optionally excluding None values."""
        def traverse(item):
            if isinstance(item, BaseModel):
                attributes = vars(item)
                result = {}
                for field_name in attributes:
                    processed_value = traverse(attributes[field_name])
                    if skip_none and processed_value is None:
                        continue
                    # Capitalize first letter of field name
                    key_name = field_name[0].upper() + field_name[1:]
                    result[key_name] = processed_value
                return result
            elif isinstance(item, list):
                return [traverse(element) for element in item 
                       if not skip_none or traverse(element) is not None]
            else:
                # Handle string encoding for Python 2 compatibility
                if isinstance(item, type(u"")) and sys.version_info[0] == 2:
                    return item.encode("UTF-8")
                return item

        return traverse(self)

    def _parse_from_dict(self, data):
        """Initialize object from dictionary data."""
        return None

    def export_json(self, *args, **options):
        """Serialize the object to a JSON string, preserving Unicode characters."""
        if "ensure_ascii" not in options:
            options["ensure_ascii"] = False
        return json.dumps(self._convert_to_dict(skip_none=True), *args, **options)

    def load_from_json(self, json_data):
        """Reconstruct object from JSON string."""
        parsed_params = json.loads(json_data)
        self._parse_from_dict(parsed_params)

    def __str__(self):
        return "%s" % self.export_json()

