import functools
import os
import sys
import os.path
from io import StringIO
from pip._vendor.pygments.formatter import Formatter
from pip._vendor.pygments.token import Token, Text, STANDARD_TYPES
from pip._vendor.pygments.util import get_bool_opt, get_int_opt, get_list_opt

try:
    import ctags
except ImportError:
    ctags = None

__all__ = ['HtmlFormatter']

# HTML escaping table for special characters
_html_escape_map = {
    ord('&'): '&amp;',
    ord('<'): '&lt;',
    ord('>'): '&gt;',
    ord('"'): '&quot;',
    ord("'"): '&#39;',
}

def html_escape(text, mapping=_html_escape_map):
    """Escape &, <, > as well as single and double quotes for HTML."""
    return text.translate(mapping)

def format_color(color):
    if color.startswith('calc') or color.startswith('var'):
        return color
    else:
        return '#' + color

def get_css_type_name(token_type):
    base_name = STANDARD_TYPES.get(token_type)
    if base_name:
        return base_name
    suffix = ''
    while base_name is None:
        suffix = '-' + token_type[-1] + suffix
        token_type = token_type.parent
        base_name = STANDARD_TYPES.get(token_type)
    return base_name + suffix

CSS_FILE_STYLESHEET = '''\
/*
generated by Pygments <https://pygments.org/>
Copyright 2006-2023 [redacted]
Licensed under the BSD license, see LICENSE for details.
*/
%(style_definitions)s
'''

DOCUMENT_HEADER_MAIN = '''\
<!DOCTYPE html PUBLIC "-//W3C//DTD HTML 4.01//EN"
   "http://www.w3.org/TR/html4/strict.dtd">
<!--
generated by Pygments <https://pygments.org/>
Copyright 2006-2023 [redacted]
Licensed under the BSD license, see LICENSE for details.
-->
<html>
<head>
  <title>%(page_title)s</title>
  <meta http-equiv="content-type" content="text/html; charset=%(charset)s">
  <style type="text/css">
''' + CSS_FILE_STYLESHEET + '''
  </style>
</head>
<body>
<h2>%(page_title)s</h2>
'''

DOCUMENT_HEADER_EXTERNAL_STYLESHEET = '''\
<!DOCTYPE html PUBLIC "-//W3C//DTD HTML 4.01//EN"
   "http://www.w3.org/TR/html4/strict.dtd">
<html>
<head>
  <title>%(page_title)s</title>
  <meta http-equiv="content-type" content="text/html; charset=%(charset)s">
  <link rel="stylesheet" href="%(stylesheet_file)s" type="text/css">
</head>
<body>
<h2>%(page_title)s</h2>
'''

DOCUMENT_FOOTER = '''\
</body>
</html>
'''

class HtmlFormatter(Formatter):
    r"""
    Format tokens as HTML 4 ``<span>`` tags. By default, the content is enclosed
    in a ``<pre>`` tag, itself wrapped in a ``<div>`` tag (but see the `nowrap` option).
    The ``<div>``'s CSS class can be set by the `cssclass` option.
    Example usage and options are documented in the original docstring.
    """
    name = 'HTML'
    aliases = ['html']
    filenames = ['*.html', '*.htm']

    def __init__(self, **kwargs):
        Formatter.__init__(self, **kwargs)
        self.page_title = self._decode_if_needed(self.title)
        self.disable_wrapping = get_bool_opt(kwargs, 'nowrap', False)
        self.use_inline_styles = get_bool_opt(kwargs, 'noclasses', False)
        self.css_prefix = kwargs.get('classprefix', '')
        self.wrapper_class = self._decode_if_needed(kwargs.get('cssclass', 'highlight'))
        self.wrapper_styles = self._decode_if_needed(kwargs.get('cssstyles', ''))
        self.pre_tag_styles = self._decode_if_needed(kwargs.get('prestyles', ''))
        self.external_css_file = self._decode_if_needed(kwargs.get('cssfile', ''))
        self.dont_overwrite_css = get_bool_opt(kwargs, 'noclobber_cssfile', False)
        self.ctags_file = self._decode_if_needed(kwargs.get('tagsfile', ''))
        self.tag_url_format = self._decode_if_needed(kwargs.get('tagurlformat', ''))
        self.source_filename = self._decode_if_needed(kwargs.get('filename', ''))
        self.use_code_tag = get_bool_opt(kwargs, 'wrapcode', False)
        self.span_openers = {}
        self.show_token_info = get_bool_opt(kwargs, 'debug_token_types', False)

        if self.ctags_file:
            if not ctags:
                raise RuntimeError('The "ctags" package must to be installed '
                                   'to be able to use the "tagsfile" feature.')
            self._ctags_index = ctags.CTags(self.ctags_file)

        line_numbers_mode = kwargs.get('linenos', False)
        if line_numbers_mode == 'inline':
            self.line_number_mode = 2
        elif line_numbers_mode:
            self.line_number_mode = 1
        else:
            self.line_number_mode = 0

        self.start_line_number = abs(get_int_opt(kwargs, 'linenostart', 1))
        self.line_number_step = abs(get_int_opt(kwargs, 'linenostep', 1))
        self.special_line_number_style = abs(get_int_opt(kwargs, 'linenospecial', 0))
        self.no_background = get_bool_opt(kwargs, 'nobackground', False)
        self.line_break = kwargs.get('lineseparator', '\n')
        self.line_anchor_prefix = kwargs.get('lineanchors', '')
        self.line_span_prefix = kwargs.get('linespans', '')
        self.anchor_line_numbers = get_bool_opt(kwargs, 'anchorlinenos', False)

        self.highlighted_lines = set()
        for line_num in get_list_opt(kwargs, 'hl_lines', []):
            try:
                self.highlighted_lines.add(int(line_num))
            except ValueError:
                pass

        self._generate_css_rules()

    def _get_css_identifier(self, token_type):
        css_class = get_css_type_name(token_type)
        if css_class:
            return self.css_prefix + css_class
        return ''

    def _get_all_css_classes(self, token_type):
        classes = self._get_css_identifier(token_type)
        while token_type not in STANDARD_TYPES:
            token_type = token_type.parent
            classes = self._get_css_identifier(token_type) + ' ' + classes
        return classes or ''

    def _get_inline_styles(self, token_type):
        style_key = self.ttype_to_class.get(token_type)
        while style_key is None:
            token_type = token_type.parent
            style_key = self.ttype_to_class.get(token_type)
        return style_key or ''

    def _generate_css_rules(self):
        ttype_to_class = self.ttype_to_class = {Token: ''}
        class_to_style = self.class_to_style = {}

        for token_type, definition in self.style:
            css_name = self._get_css_identifier(token_type)
            style_str = ''

            if definition['color']:
                style_str += 'color: %s; ' % format_color(definition['color'])
            if definition['bold']:
                style_str += 'font-weight: bold; '
            if definition['italic']:
                style_str += 'font-style: italic; '
            if definition['underline']:
                style_str += 'text-decoration: underline; '
            if definition['bgcolor']:
                style_str += 'background-color: %s; ' % format_color(definition['bgcolor'])
            if definition['border']:
                style_str += 'border: 1px solid %s; ' % format_color(definition['border'])

            if style_str:
                ttype_to_class[token_type] = css_name
                class_to_style[css_name] = (style_str[:-2], token_type, len(token_type))

    def get_style_definitions(self, selector=None):
        output_lines = []
        output_lines.extend(self.get_line_number_style_defs())
        output_lines.extend(self.get_background_style_defs(selector))
        output_lines.extend(self.get_token_style_defs(selector))
        return '\n'.join(output_lines)

    def get_token_style_defs(self, selector=None):
        prefix_func = self.get_css_selector_prefix(selector)
        styles_list = [
            (level, token_type, css_class, style_text)
            for css_class, (style_text, token_type, level) in self.class_to_style.items()
            if css_class and style_text
        ]
        styles_list.sort()
        result_lines = [
            '%s { %s } /* %s */' % (prefix_func(css_class), style_text, repr(token_type)[6:])
            for (level, token_type, css_class, style_text) in styles_list
        ]
        return result_lines

    def get_background_style_defs(self, selector=None):
        prefix_func = self.get_css_selector_prefix(selector)
        bg_color = self.style.background_color
        highlight_color = self.style.highlight_color
        lines = []

        if selector and not self.no_background and bg_color is not None:
            text_style = ''
            if Text in self.ttype_to_class:
                text_style = ' ' + self.class_to_style[self.ttype_to_class[Text]][0]
            lines.insert(
                0, '%s{ background: %s;%s }' % (
                    prefix_func(''), bg_color, text_style
                )
            )

        if highlight_color is not None:
            lines.insert(
                0, '%s { background-color: %s }' % (prefix_func('hll'), highlight_color)
            )
        return lines

    def get_line_number_style_defs(self):
        lines = [
            'pre { %s }' % self._preformatted_style,
            'td.linenos .normal { %s }' % self._line_numbers_style,
            'span.linenos { %s }' % self._line_numbers_style,
            'td.linenos .special { %s }' % self._special_line_number_style,
            'span.linenos.special { %s }' % self._special_line_number_style,
        ]
        return lines

    def get_css_selector_prefix(self, selector_arg):
        if selector_arg is None:
            selector_arg = ('cssclass' in self.options and '.'+self.wrapper_class or '')
        if isinstance(selector_arg, str):
            selectors = [selector_arg]
        else:
            selectors = list(selector_arg)

        def apply_prefix(cls_name):
            if cls_name:
                cls_name = '.' + cls_name
            temp = []
            for sel in selectors:
                temp.append((sel and sel + ' ' or '') + cls_name)
            return ', '.join(temp)
        return apply_prefix

    @property
    def _preformatted_style(self):
        return 'line-height: 125%;'

    @property
    def _line_numbers_style(self):
        return 'color: %s; background-color: %s; padding-left: 5px; padding-right: 5px;' % (
            self.style.line_number_color,
            self.style.line_number_background_color
        )

    @property
    def _special_line_number_style(self):
        return 'color: %s; background-color: %s; padding-left: 5px; padding-right: 5px;' % (
            self.style.line_number_special_color,
            self.style.line_number_special_background_color
        )

    def _decode_if_needed(self, value):
        if isinstance(value, bytes):
            if self.encoding:
                return value.decode(self.encoding)
            return value.decode()
        return value

    def _wrap_full_document(self, inner_content, output_stream):
        if self.external_css_file:
            if os.path.isabs(self.external_css_file):
                css_path = self.external_css_file
            else:
                try:
                    filename = output_stream.name
                    if not filename or filename[0] == '<':
                        raise AttributeError
                    css_path = os.path.join(os.path.dirname(filename),
                                           self.external_css_file)
                except AttributeError:
                    print('Note: Cannot determine output file name, '
                          'using current directory as base for the CSS file name',
                          file=sys.stderr)
                    css_path = self.external_css_file

            try:
                if not os.path.exists(css_path) or not self.dont_overwrite_css:
                    with open(css_path, "w", encoding="utf-8") as css_file:
                        css_file.write(CSS_FILE_STYLESHEET %
                                 {'style_definitions': self.get_style_defs('body')})
            except OSError as err:
                err.strerror = 'Error writing CSS file: ' + err.strerror
                raise

            yield 0, (DOCUMENT_HEADER_EXTERNAL_STYLESHEET %
                      dict(page_title=self.page_title,
                           stylesheet_file=self.external_css_file,
                           charset=self.encoding))
        else:
            yield 0, (DOCUMENT_HEADER_MAIN %
                      dict(page_title=self.page_title,
                           style_definitions=self.get_style_defs('body'),
                           charset=self.encoding))
        yield from inner_content
        yield 0, DOCUMENT_FOOTER

    def _wrap_with_line_numbers_table(self, inner_generator):
        buffer_stream = StringIO()
        line_count = 0
        for flag, content in inner_generator:
            if flag:
                line_count += 1
            buffer_stream.write(content)

        start_num = self.start_line_number
        width = len(str(line_count + start_num - 1))
        special_mod = self.special_line_number_style
        step_mod = self.line_number_step
        anchor_base = self.line_anchor_prefix or self.line_span_prefix
        use_anchors = self.anchor_line_numbers
        inline_styles = self.use_inline_styles

        number_rows = []
        for i in range(start_num, start_num + line_count):
            show_number = i % step_mod == 0
            is_special = special_mod and i % special_mod == 0

            if show_number:
                num_str = '%*d' % (width, i)
                if use_anchors:
                    num_str = '<a href="#%s-%d">%s</a>' % (anchor_base, i, num_str)
            else:
                num_str = ' ' * width

            if inline_styles:
                if is_special:
                    style_attr = ' style="%s"' % self._special_line_number_style
                else:
                    style_attr = ' style="%s"' % self._line_numbers_style
            else:
                if is_special:
                    style_attr = ' class="special"'
                else:
                    style_attr = ' class="normal"'

            if style_attr:
                num_str = '<span%s>%s</span>' % (style_attr, num_str)
            number_rows.append(num_str)

        numbers_block = '\n'.join(number_rows)

        # Handle filename row if specified
        filename_row = ""
        if self.source_filename:
            filename_row = (
                '<tr><th colspan="2" class="filename">'
                '<span class="filename">' + self.source_filename + '</span>'
                '</th></tr>')

        yield 0, (f'<table class="{self.wrapper_class}table">' + filename_row +
            '<tr><td class="linenos"><div class="linenodiv"><pre>' +
            numbers_block + '</pre></div></td><td class="code">')
        yield 0, '<div>'
        yield 0, buffer_stream.getvalue()
        yield 0, '</div>'
        yield 0, '</td></tr></table>'

    def _wrap_with_inline_line_numbers(self, inner_generator):
        inner_items = list(inner_generator)
        special_mod = self.special_line_number_style
        step_mod = self.line_number_step
        current_line = self.start_line_number
        width = len(str(len(inner_items) + current_line - 1))
        anchor_base = self.line_anchor_prefix or self.line_span_prefix
        use_anchors = self.anchor_line_numbers
        inline_styles = self.use_inline_styles

        for _, content in inner_items:
            show_number = current_line % step_mod == 0
            is_special = special_mod and current_line % special_mod == 0

            if show_number:
                num_str = '%*d' % (width, current_line)
            else:
                num_str = ' ' * width

            if inline_styles:
                if is_special:
                    style_attr = ' style="%s"' % self._special_line_number_style
                else:
                    style_attr = ' style="%s"' % self._line_numbers_style
            else:
                if is_special:
                    style_attr = ' class="linenos special"'
                else:
                    style_attr = ' class="linenos"'

            if style_attr:
                line_numbers = '<span%s>%s</span>' % (style_attr, num_str)
            else:
                line_numbers = num_str

            if use_anchors:
                yield 1, ('<a href="#%s-%d">%s</a>' % (anchor_base, current_line, line_numbers) +
                          content)
            else:
                yield 1, line_numbers + content
            current_line += 1

    def _wrap_with_line_anchors(self, inner_generator):
        prefix = self.line_anchor_prefix
        counter = self.start_line_number - 1
        for flag, content in inner_generator:
            if flag:
                counter += 1
                href = "" if self.line_number_mode == 0 else ' href="#%s-%d"' % (prefix, counter)
                yield 1, '<a id="%s-%d" name="%s-%d"%s></a>' % (prefix, counter, prefix, counter, href) + content
            else:
                yield 0, content

    def _wrap_with_line_spans(self, inner_generator):
        prefix = self.line_span_prefix
        counter = self.start_line_number - 1
        for flag, content in inner_generator:
            if flag:
                counter += 1
                yield 1, '<span id="%s-%d">%s</span>' % (prefix, counter, content)
            else:
                yield 0, content

    def _wrap_with_div_container(self, inner_generator):
        style_parts = []
        if (self.use_inline_styles and not self.no_background and
                self.style.background_color is not None):
            style_parts.append('background: %s' % (self.style.background_color,))
        if self.wrapper_styles:
            style_parts.append(self.wrapper_styles)
        style_string = '; '.join(style_parts)

        yield 0, ('<div' + (self.wrapper_class and ' class="%s"' % self.wrapper_class) +
                  (style_string and (' style="%s"' % style_string)) + '>')
        yield from inner_generator
        yield 0, '</div>\n'

    def _wrap_with_pre_tag(self, inner_generator):
        style_parts = []
        if self.pre_tag_styles:
            style_parts.append(self.pre_tag_styles)
        if self.use_inline_styles:
            style_parts.append(self._preformatted_style)
        style_string = '; '.join(style_parts)

        if self.source_filename and self.line_number_mode != 1:
            yield 0, ('<span class="filename">' + self.source_filename + '</span>')

        yield 0, ('<pre' + (style_string and ' style="%s"' % style_string) + '><span></span>')
        yield from inner_generator
        yield 0, '</pre>'

    def _wrap_with_code_tag(self, inner_generator):
        yield 0, '<code>'
        yield from inner_generator
        yield 0, '</code>'

    @functools.lru_cache(maxsize=100)
    def _split_value_by_lines(self, value):
        """HTML-escape a value and split it by newlines."""
        return value.translate(_html_escape_map).split('\n')

    def _format_tokens_as_lines(self, token_source):
        nocls = self.use_inline_styles
        line_sep = self.line_break
        tagsfile = self.ctags_file
        last_span = ''
        current_line = []

        for token_type, value in token_source:
            try:
                current_span = self.span_openers[token_type]
            except KeyError:
                title_attr = ' title="%s"' % '.'.join(token_type) if self.show_token_info else ''
                if nocls:
                    css_style = self._get_inline_styles(token_type)
                    if css_style:
                        css_style = self.class_to_style[css_style][0]
                        current_span = '<span style="%s"%s>' % (css_style, title_attr)
                    else:
                        current_span = ''
                else:
                    css_class = self._get_all_css_classes(token_type)
                    if css_class:
                        current_span = '<span class="%s"%s>' % (css_class, title_attr)
                    else:
                        current_span = ''
                self.span_openers[token_type] = current_span

            parts = self._split_value_by_lines(value)

            if tagsfile and token_type in Token.Name:
                filename, line_num = self._lookup_ctag_entry(value)
                if line_num:
                    base_dir, fname = os.path.split(filename)
                    if base_dir:
                        base_dir += '/'
                    name_part, ext_part = os.path.splitext(fname)
                    url = self.tag_url_format % {'path': base_dir, 'fname': name_part,
                                               'fext': ext_part}
                    parts[0] = "<a href=\"%s#%s-%d\">%s" % \
                        (url, self.line_anchor_prefix, line_num, parts[0])
                    parts[-1] = parts[-1] + "</a>"

            for part in parts[:-1]:
                if current_line:
                    if last_span != current_span and part:
                        current_line.extend(((last_span and '</span>'), current_span, part,
                                     (current_span and '</span>'), line_sep))
                    else:
                        current_line.extend((part, (last_span and '</span>'), line_sep))
                    yield 1, ''.join(current_line)
                    current_line = []
                elif part:
                    yield 1, ''.join((current_span, part, (current_span and '</span>'), line_sep))
                else:
                    yield 1, line_sep

            if current_line and parts[-1]:
                if last_span != current_span:
                    current_line.extend(((last_span and '</span>'), current_span, parts[-1]))
                    last_span = current_span
                else:
                    current_line.append(parts[-1])
            elif parts[-1]:
                current_line = [current_span, parts[-1]]
                last_span = current_span

        if current_line:
            current_line.extend(((last_span and '</span>'), line_sep))
            yield 1, ''.join(current_line)

    def _lookup_ctag_entry(self, token):
        entry = ctags.TagEntry()
        if self._ctags_index.find(entry, token.encode(), 0):
            return entry['file'], entry['lineNumber']
        else:
            return None, None

    def _highlight_specified_lines(self, token_source):
        highlighted_set = self.highlighted_lines
        for idx, (flag, content) in enumerate(token_source):
            if flag != 1:
                yield flag, content
            if idx + 1 in highlighted_set:
                if self.use_inline_styles:
                    style = ''
                    if self.style.highlight_color is not None:
                        style = (' style="background-color: %s"' %
                                 (self.style.highlight_color,))
                    yield 1, '<span%s>%s</span>' % (style, content)
                else:
                    yield 1, '<span class="hll">%s</span>' % content
            else:
                yield 1, content

    def wrap(self, source_generator):
        output = source_generator
        if self.use_code_tag:
            output = self._wrap_with_code_tag(output)
        output = self._wrap_with_pre_tag(output)
        return output

    def format_unencoded(self, token_source, output_stream):
        source = self._format_tokens_as_lines(token_source)

        if not self.disable_wrapping and self.line_number_mode == 2:
            source = self._wrap_with_inline_line_numbers(source)

        if self.highlighted_lines:
            source = self._highlight_specified_lines(source)

        if not self.disable_wrapping:
            if self.line_anchor_prefix:
                source = self._wrap_with_line_anchors(source)
            if self.line_span_prefix:
                source = self._wrap_with_line_spans(source)
            source = self.wrap(source)
            if self.line_number_mode == 1:
                source = self._wrap_with_line_numbers_table(source)
            source = self._wrap_with_div_container(source)
            if self.full:
                source = self._wrap_full_document(source, output_stream)

        for flag, content in source:
            output_stream.write(content)

# Test GeLU activation implementation
import pytest
import torch
import tilegym
from ... import common

class Test_GeLU(common.PyTestCase):
    @staticmethod
    def reference_func(input_tensor, mode):
        return torch.nn.functional.gelu(input_tensor, approximate=mode)

    _supported_backends = ["cutile"]

    @pytest.mark.parametrize(
        "rows, cols, approx_mode, data_type",
        [
            (256, 2048, "none", torch.float32),
            (256, 2048, "tanh", torch.float32),
            (256, 2048, "none", torch.float16),
            (256, 2048, "tanh", torch.float16),
        ],
    )
    @pytest.mark.parametrize("backend_name", _supported_backends)
    def test_activation(self, rows, cols, approx_mode, data_type, backend_name):
        if tilegym.is_backend_available(backend_name):
            tilegym.set_backend(backend_name)
        else:
            pytest.skip(f"Backend {backend_name} is not available")

        device = torch.device("cuda")
        input_shape = (rows, cols)
        input_tensor = torch.rand(input_shape, dtype=data_type, device=device, requires_grad=False).mul_(0.5).add_(-2.3)

        self.assertCorrectness(
            tilegym.ops.activation.gelu,
            self.reference_func,
            {"input": input_tensor, "approximate": approx_mode},
            rtol=0.0,
            atol=1e-2,
        )

import sys
import json
from pathlib import Path

# Define the path to the floor status configuration file
FLOOR_CONFIG_PATH = Path('C:/path/to/user/arifOS/metadata/floor_status.json')

def retrieve_floor_status():
    # If the status file doesn't exist, default all floors to operational (value 1)
    if not FLOOR_CONFIG_PATH.is_file():
        return {f'F{i}': 1 for i in range(1, 14)}
    return json.loads(FLOOR_CONFIG_PATH.read_text())

def execute_check():
    floor_data = retrieve_floor_status()
    problematic_floors = [floor for floor, status in floor_data.items() if status != 1]

    if problematic_floors:
        sys.stderr.write(f"[constitution_lint] Floor issues found: {', '.join(problematic_floors)}\n")
        sys.exit(1)

    # No issues detected
    sys.stdout.write('[constitution_lint] All floors are compliant.\n')
    sys.exit(0)

