# Function to generate list of prime numbers less than given value
def generate_primes_below(limit):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    generate_primes_below(5) => [2,3]
    generate_primes_below(11) => [2,3,5,7]
    generate_primes_below(0) => []
    generate_primes_below(20) => [2,3,5,7,11,13,17,19]
    generate_primes_below(1) => []
    generate_primes_below(18) => [2,3,5,7,11,13,17]
    """
    if limit <= 2:
        return []

    def check_prime(value):
        if value < 2:
            return False
        if value == 2:
            return True
        if value % 2 == 0:
            return False
        divisor = 3
        while divisor * divisor <= value:
            if value % divisor == 0:
                return False
            divisor += 2
        return True

    prime_list = []
    for number in range(2, limit):
        if check_prime(number):
            prime_list.append(number)
    return prime_list

