import sys

sensor_list = list()
Sensor_Template = {}
Verbose = False

def log_message(fmt, *args):
    if Verbose:
        print >>sys.stderr, "DEBUG: " + fmt % args

def get_metric_value(name):
    log_message("%s", name)
    try:
        category, sensor_id = name.split("usbrh_")[1].split("_")
        file_path = "/proc/usbrh/%(sensor_id)s/%(category)s" % locals()
        f = open(file_path, 'r')
    except IOError:
        return 0

    for line in f:
        cleaned_line = line.rstrip()
        if category == "temperature":
            cleaned_line = float(cleaned_line)
    return cleaned_line

def initialize_module(params):
    global sensor_list, Sensor_Template, Verbose
    print '[usbrh] initialize'
    print params

    # Initialize template for sensor descriptors
    Sensor_Template = {
        'name'        : 'usbrh',
        'callback'    : get_metric_value,
        'max_time'    : 60,
        'data_type'   : 'float',
