        'tags'        : 'usbrh',
        }

    if "debug" in params:
        Verbose = params["debug"]
    log_message("%s", "Verbose mode on")

    # Spoof host configuration
    if "spoof_host" in params:
        Sensor_Template["spoof_host"] = params["spoof_host"]

    sensor_list.append(build_descriptor(Sensor_Template, {
                "name"       : "usbrh_temperature_0",
