# Ensure image dimensions are divisible by specified factors
from typing import Union
import torch
from PIL import Image
from torchvision.transforms import functional as TVF

class DivisibleCrop:
    def __init__(self, divisor):
        if not isinstance(divisor, tuple):
            divisor = (divisor, divisor)
        self.height_divisor, self.width_divisor = divisor[0], divisor[1]

    def __call__(self, img: Union[torch.Tensor, Image.Image]):
        if isinstance(img, torch.Tensor):
            img_height, img_width = img.shape[-2:]
        elif isinstance(img, Image.Image):
            img_width, img_height = img.size
        else:
            raise NotImplementedError

        new_height = img_height - (img_height % self.height_divisor)
        new_width = img_width - (img_width % self.width_divisor)

        cropped_img = TVF.center_crop(img=img, output_size=(new_height, new_width))
        return cropped_img

# PDF utility script for extracting text, markdown, tables, images, and metadata
import sys
import json

def get_text_content(file_path, page_numbers=None):
    import pymupdf
    document = pymupdf.open(file_path)
    pages_to_process = range(len(document)) if page_numbers is None else page_numbers
    for idx in pages_to_process:
        if idx < len(document):
            print(f"\n--- Page {idx+1}/{len(document)} ---\n")
            print(document[idx].get_text())

def convert_to_markdown(file_path, page_numbers=None):
    import pymupdf4llm
    md_content = pymupdf4llm.to_markdown(file_path, pages=page_numbers)
    print(md_content)

def retrieve_tables(file_path):
    import pymupdf
    document = pymupdf.open(file_path)
    for page_idx, page in enumerate(document):
        table_finder = page.find_tables()
        for table_idx, table_obj in enumerate(table_finder.tables):
            print(f"\n--- Page {page_idx+1}, Table {table_idx+1} ---\n")
            dataframe = table_obj.to_pandas()
            print(dataframe.to_markdown(index=False))

def save_images(file_path, destination_folder):
    import pymupdf
    from pathlib import Path
    Path(destination_folder).mkdir(parents=True, exist_ok=True)
    document = pymupdf.open(file_path)
    image_counter = 0
    for page_num, page in enumerate(document):
        for img_pos, image_info in enumerate(page.get_images(full=True)):
            xref_id = image_info[0]
            pixmap = pymupdf.Pixmap(document, xref_id)
            if pixmap.n >= 5:
                pixmap = pymupdf.Pixmap(pymupdf.csRGB, pixmap)
            output_file = f"{destination_folder}/page{page_num+1}_img{img_pos+1}.png"
            pixmap.save(output_file)
            image_counter += 1
    print(f"Extracted {image_counter} images to {destination_folder}/")

def display_document_info(file_path):
    import pymupdf
    document = pymupdf.open(file_path)
    print(json.dumps({
        "total_pages": len(document),
        "document_title": document.metadata.get("title", ""),
        "author_name": document.metadata.get("author", ""),
        "topic": document.metadata.get("subject", ""),
        "created_by": document.metadata.get("creator", ""),
        "software_version": document.metadata.get("producer", ""),
        "file_type": document.metadata.get("format", ""),
    }, indent=2))

if __name__ == "__main__":
    arguments = sys.argv[1:]
    if not arguments or arguments[0] in ("-h", "--help"):
        print(__doc__)
        sys.exit(0)

    pdf_file = arguments[0]
    selected_pages = None

    if "--pages" in arguments:
        position = arguments.index("--pages")
        page_arg = arguments[position + 1]
        if "-" in page_arg:
            begin, finish = page_arg.split("-")
            selected_pages = list(range(int(begin), int(finish) + 1))
        else:
            selected_pages = [int(page_arg)]

    if "--metadata" in arguments:
        display_document_info(pdf_file)
    elif "--tables" in arguments:
        retrieve_tables(pdf_file)
    elif "--images" in arguments:
        pos = arguments.index("--images")
        folder = arguments[pos + 1] if pos + 1 < len(arguments) else "./images"
        save_images(pdf_file, folder)
    elif "--markdown" in arguments:
        convert_to_markdown(pdf_file, page_numbers=selected_pages)
    else:
        get_text_content(pdf_file, page_numbers=selected_pages)

# Custom YAML serialization utilities for safe representation of Python objects
import enum
import functools
import inspect
from contextlib import contextmanager
from typing import Any, Generator, Optional
import yaml

@contextmanager
def secure_yaml_dumpers() -> Generator[None, None, None]:
    """
    Context manager for securely registering and unregistering custom YAML representers.
    Temporarily registers specialized representers for functions, enums, and other objects
    with the YAML SafeDumper, then restores the initial state upon exiting.
    Example:
        with secure_yaml_dumpers():
            yaml_output = yaml.safe_dump(complicated_object)
    """
    # Preserve existing representers
    saved_representers = yaml.SafeDumper.yaml_representers.copy()
    saved_multi_representers = yaml.SafeDumper.yaml_multi_representers.copy()
    try:
        # Install custom representers
        yaml.SafeDumper.add_representer(functools.partial, _partial_dumper)
        yaml.SafeDumper.add_multi_representer(enum.Enum, _enum_dumper)
        yaml.SafeDumper.add_representer(type(lambda: ...), _function_dumper)
        yaml.SafeDumper.add_representer(type(object), _function_dumper)

        # Attempt to register PyTorch dtype handler if torch is available
        try:
            import torch
            yaml.SafeDumper.add_representer(torch.dtype, _torch_dtype_dumper)
        except ModuleNotFoundError:
            pass

        # Attempt to register GenerationConfig handler if transformers is available
        try:
            from transformers import GenerationConfig
            yaml.SafeDumper.add_representer(GenerationConfig, _generation_config_dumper)
        except ModuleNotFoundError:
            pass

        # Attempt to register PretrainedConfig handler generically
        try:
            from transformers import PretrainedConfig
            yaml.SafeDumper.add_multi_representer(PretrainedConfig, _pretrained_config_dumper)
        except ModuleNotFoundError:
            pass

        # Default object handler
        yaml.SafeDumper.add_multi_representer(object, _default_object_dumper)
        yield
    finally:
        # Restore original representers
        yaml.SafeDumper.yaml_representers = saved_representers
        yaml.SafeDumper.yaml_multi_representers = saved_multi_representers

def export_to_yaml(data: Any, filepath: Optional[str] = None) -> Optional[str]:
    """Serialize a dataclass or arbitrary Python object into YAML format.
    Leverages secure representers to handle various built-in and third-party types.

    Args:
        data: The object to be serialized.
        filepath: If specified, writes YAML to this file path; otherwise returns string.

    Returns:
        YAML string if filepath is None; None otherwise.
    """
    with secure_yaml_dumpers():
        if filepath is not None:
            with open(filepath, "w+") as output_file:
                yaml.safe_dump(data, output_file)
        else:
            return yaml.safe_dump(data)

def _function_dumper(dumper, item):
    """Convert function objects into YAML-safe dictionary format."""
    info = {
        "_target_": f"{inspect.getmodule(item).__name__}.{item.__qualname__}",  # type: ignore
        "_call_": False,
    }
    return dumper.represent_data(info)

def _torch_dtype_dumper(dumper, item):
    """Convert torch.dtype instances into YAML-safe dictionary format."""
    info = {
        "_target_": str(item),
        "_call_": False,
    }
    return dumper.represent_data(info)

def _default_object_dumper(dumper, item):
    """
    Generic fallback representer for unknown objects.
    Attempts to extract module and qualified name; if unavailable, uses class info.
    Determines whether the target should be instantiated (_call_ flag).
    """
    try:
        obj = item
        location = f"{inspect.getmodule(obj).__name__}.{obj.__qualname__}"
        instantiate = False
    except AttributeError:
        obj = item.__class__
        location = f"{inspect.getmodule(obj).__name__}.{obj.__qualname__}"
        instantiate = True
    result = {
        "_target_": location,  # type: ignore
        "_call_": instantiate,
    }
    return dumper.represent_data(result)

def _partial_dumper(dumper, item):
    """Convert functools.partial objects into YAML-safe dictionary format."""
    base_func = item.func
    info = {
        "_target_": f"{inspect.getmodule(base_func).__name__}.{base_func.__qualname__}",
        "_partial_": True,
        "_args_": list(item.args) if item.args else [],
    }
    if item.keywords:
        for key, val in item.keywords.items():
            info[key] = val
    return dumper.represent_data(info)

def _enum_dumper(dumper, item):
    """Convert enum members into YAML-safe dictionary format."""
    enum_type = item.__class__
    info = {
        "_target_": f"{inspect.getmodule(enum_type).__name__}.{enum_type.__qualname__}",
        "_call_": True,
        "_args_": [item.value],
        "_name_": item.name,
    }
    return dumper.represent_data(info)

def _generation_config_dumper(dumper, item):
    """Convert transformers GenerationConfig objects into YAML-safe dictionary format."""
    cls = item.__class__
    info = {
        "_target_": f"{inspect.getmodule(cls).__name__}.{cls.__qualname__}.from_dict",
        "_call_": True,
        "config_dict": item.to_dict(),
    }
    return dumper.represent_data(info)

def _pretrained_config_dumper(dumper, item):
    """Convert transformers PretrainedConfig objects generically using from_dict/to_dict methods."""
    cls = item.__class__
    info = {
        "_target_": f"{inspect.getmodule(cls).__name__}.{cls.__qualname__}.from_dict",
        "_call_": True,
        "config_dict": item.to_dict(),
    }
    return dumper.represent_data(info)

