from pca9685 import PCA9685
import math
import time

class ServoController:
    def __init__(self, i2c_bus, addr=0x40, hz=50, min_pulse=600, max_pulse=2400,
                 angle_range=180):
        self.pulse_period = 1000000 / hz
        self.min_duty_cycle = self._micros_to_duty(min_pulse)
        self.max_duty_cycle = self._micros_to_duty(max_pulse)
        self.angle_limit = angle_range
        self.frequency = hz
        self.controller = PCA9685(i2c_bus, addr)
        self.controller.freq(hz)
        self.servo_positions = [0] * 16

    def _micros_to_duty(self, micros_value):
        return int(4095 * micros_value / self.pulse_period)

    def set_position(self, channel, angle=None, rad=None, pulse_us=None, duty_val=None, update=True):
        start_time = time.ticks_us()

        if duty_val is not None:
            final_duty = duty_val
        elif angle is not None:
            duty_span = self.max_duty_cycle - self.min_duty_cycle
            final_duty = self.min_duty_cycle + duty_span * angle / self.angle_limit
        elif rad is not None:
            duty_span = self.max_duty_cycle - self.min_duty_cycle
            final_duty = self.min_duty_cycle + duty_span * rad / math.radians(self.angle_limit)
        elif pulse_us is not None:
            final_duty = self._micros_to_duty(pulse_us)
        else:
            return self.controller.duty(channel)

        print('Calculation duration:', time.ticks_diff(time.ticks_us(), start_time))

        # Clamp duty cycle to valid range (commented out in original)
        # final_duty = min(self.max_duty_cycle, max(self.min_duty_cycle, int(final_duty)))

        timing_check = time.ticks_us()
        self.servo_positions[channel] = final_duty
        print('Storage duration:', time.ticks_diff(time.ticks_us(), timing_check))

        timing_push = time.ticks_us()
        if update:
            self.controller.duty(channel, final_duty)
        print('Update duration:', time.ticks_diff(time.ticks_us(), timing_push), 'update:', update)

    def set_duty(self, channel, duty_value):
        self.servo_positions[channel] = duty_value
        self.controller.duty(channel, duty_value)

    def disable_servo(self, channel):
        self.controller.duty(channel, 0)

    def disable_all(self):
        for idx in range(16): 
            self.servo_positions[idx] = 0
        self.apply_all_values()

    def apply_all_values(self):
        self.controller.allpwm(self.servo_positions)

