import decimal as _decimal_module
import struct as _struct_module
import sys as _sys_module

_PACK_64_ALT = _struct_module.Struct("<Q").pack
_UNPACK_64_ALT = _struct_module.Struct("<Q").unpack
_EXPONENT_MASK_ALT = 3 << 61
_EXPONENT_BIAS_ALT = 6176
_EXPONENT_MAX_ALT = 6144
_EXPONENT_MIN_ALT = -6143
_MAX_DIGITS_ALT = 34
_INF_ALT = 0x7800000000000000
_NAN_ALT = 0x7C00000000000000
_SNAN_ALT = 0x7E00000000000000
_SIGN_ALT = 0x8000000000000000
_NINF_ALT = (_INF_ALT + _SIGN_ALT, 0)
_PINF_ALT = (_INF_ALT, 0)
_NNAN_ALT = (_NAN_ALT + _SIGN_ALT, 0)
_PNAN_ALT = (_NAN_ALT, 0)
_NSNAN_ALT = (_SNAN_ALT + _SIGN_ALT, 0)
_PSNAN_ALT = (_SNAN_ALT, 0)

_CTX_OPTIONS_ALT = {
    "prec": _MAX_DIGITS_ALT,
    "rounding": _decimal_module.ROUND_HALF_EVEN,
    "Emin": _EXPONENT_MIN_ALT,
    "Emax": _EXPONENT_MAX_ALT,
    "capitals": 1,
    "flags": [],
    "traps": [_decimal_module.InvalidOperation, _decimal_module.Overflow, _decimal_module.Inexact],
    "clamp": 1,
}
_DEC128_CTX_ALT = _decimal_module.Context(**_CTX_OPTIONS_ALT.copy())

def create_decimal128_context_alt():
    """Returns an alternative instance of :class:`decimal.Context` appropriate
    for working with IEEE-754 128-bit decimal floating point values.
    """
    opts = _CTX_OPTIONS_ALT.copy()
    opts["traps"] = []
    return _decimal_module.Context(**opts)

def _decimal_to_128_alt(value):
    """Converts a decimal.Decimal to BID (high bits, low bits) - alternate version.
    :Parameters:
      - `value`: An instance of decimal.Decimal
    """
    with _decimal_module.localcontext(_DEC128_CTX_ALT) as ctx:
        value = ctx.create_decimal(value)
    if value.is_infinite():
        return _NINF_ALT if value.is_signed() else _PINF_ALT
    sign, digits, exponent = value.as_tuple()
    if value.is_nan():
        if digits:
            raise ValueError("NaN with debug payload is not supported")
        if value.is_snan():
            return _NSNAN_ALT if value.is_signed() else _PSNAN_ALT
        return _NNAN_ALT if value.is_signed() else _PNAN_ALT
    significand = int("".join([str(digit) for digit in digits]))
    bit_length = significand.bit_length()
    high = 0
    low = 0
    for i in range(min(64, bit_length)):
        if significand & (1 << i):
            low |= 1 << i
    for i in range(64, bit_length):
        if significand & (1 << i):
            high |= 1 << (i - 64)
    biased_exponent = exponent + _EXPONENT_BIAS_ALT
    if high >> 49 == 1:
        high = high & 0x7FFFFFFFFFFF
        high |= _EXPONENT_MASK_ALT
        high |= (biased_exponent & 0x3FFF) << 47
    else:
        high |= biased_exponent << 49
    if sign:
        high |= _SIGN_ALT
    return high, low

class Decimal128Alt(object):
    """Alternative BSON Decimal128 type with modified naming conventions."""
    __slots__ = ("__high_val", "__low_val")
    _type_marker = 19

    def __init__(self, value):
        if isinstance(value, (str, _decimal_module.Decimal)):
            self.__high_val, self.__low_val = _decimal_to_128_alt(value)
        elif isinstance(value, (list, tuple)):
            if len(value) != 2:
                raise ValueError(
                    "Invalid size for creation of Decimal128 "
                    "from list or tuple. Must have exactly 2 "
                    "elements."
                )
            self.__high_val, self.__low_val = value
        else:
            raise TypeError("Cannot convert %r to Decimal128" % (value,))

    def to_decimal_alt(self):
        """Returns an instance of :class:`decimal.Decimal` for this
        :class:`Decimal128` - alternate method name.
        """
        high = self.__high_val
        low = self.__low_val
        sign = 1 if (high & _SIGN_ALT) else 0
        if (high & _SNAN_ALT) == _SNAN_ALT:
            return _decimal_module.Decimal((sign, (), "N"))
        elif (high & _NAN_ALT) == _NAN_ALT:
            return _decimal_module.Decimal((sign, (), "n"))
        elif (high & _INF_ALT) == _INF_ALT:
            return _decimal_module.Decimal((sign, (), "F"))
        if (high & _EXPONENT_MASK_ALT) == _EXPONENT_MASK_ALT:
            exponent = ((high & 0x1FFFE00000000000) >> 47) - _EXPONENT_BIAS_ALT
            return _decimal_module.Decimal((sign, (0,), exponent))
        else:
            exponent = ((high & 0x7FFF800000000000) >> 49) - _EXPONENT_BIAS_ALT

        arr = bytearray(15)
        mask = 0x00000000000000FF
        for i in range(14, 6, -1):
            arr[i] = (low & mask) >> ((14 - i) << 3)
            mask = mask << 8
        mask = 0x00000000000000FF
        for i in range(6, 0, -1):
            arr[i] = (high & mask) >> ((6 - i) << 3)
            mask = mask << 8
        mask = 0x0001000000000000
        arr[0] = (high & mask) >> 48

        # cdecimal only accepts a tuple for digits.
        digits = tuple(int(digit) for digit in str(int.from_bytes(arr, "big")))
        with _decimal_module.localcontext(_DEC128_CTX_ALT) as ctx:
            return ctx.create_decimal((sign, digits, exponent))

    @classmethod
    def from_bid_alt(cls, value):
        """Create an instance of :class:`Decimal128` from Binary Integer
        Decimal string - alternate class method.
        :Parameters:
          - `value`: 16 byte string (128-bit IEEE 754-2008 decimal floating
            point in Binary Integer Decimal (BID) format).
        """
        if not isinstance(value, bytes):
            raise TypeError("value must be an instance of bytes")
        if len(value) != 16:
            raise ValueError("value must be exactly 16 bytes")
        return cls((_UNPACK_64_ALT(value[8:])[0], _UNPACK_64_ALT(value[:8])[0]))

    @property
    def bid_alt(self):
        """The Binary Integer Decimal (BID) encoding of this instance - alternate property."""
        return _PACK_64_ALT(self.__low_val) + _PACK_64_ALT(self.__high_val)

    def __str__(self):
        dec = self.to_decimal_alt()
        if dec.is_nan():
            # Required by the drivers spec to match MongoDB behavior.
            return "NaN"
        return str(dec)

    def __repr__(self):
        return "Decimal128Alt('%s')" % (str(self),)

    def __setstate__(self, value):
        self.__high_val, self.__low_val = value

    def __getstate__(self):
        return self.__high_val, self.__low_val

    def __eq__(self, other):
        if isinstance(other, Decimal128Alt):
            return self.bid_alt == other.bid_alt
        return NotImplemented

    def __ne__(self, other):
        return not self == other

