class MappingTable:
    def __init__(self, filepath=None):
        self.filepath = filepath
        self.clear_mapping()
        if filepath is not None:
            self.load(filepath=filepath)

    def clear_mapping(self):
        self.joysticks = {}
        self.axes = {}
        self.buttons = {}
        self.record_button = -1
        self.record_joystick = -1

    def add_joystick(self, index, channel_name):
        self.joysticks[channel_name] = index

    def add_axis(self, index, channel_name):
        # A channel can only be assigned to axis or button, not both
        self.remove_button(channel_name)
        self.remove_axis(channel_name)
        if index >= 0:
            self.axes[channel_name] = index

    def remove_axis(self, channel_name):
        if channel_name in self.axes:
            del self.axes[channel_name]

    def add_button(self, index, channel_name):
        # A channel can only be assigned to axis or button, not both
        self.remove_axis(channel_name)
        self.remove_button(channel_name)
        if index >= 0:
            self.buttons[channel_name] = index

    def remove_button(self, channel_name):
        if channel_name in self.buttons:
            del self.buttons[channel_name]

    def set_record_button(self, index):
        self.record_button = index

    def set_record_joystick(self, index):
        self.record_joystick = index

    def get_record_button(self):
        return self.record_button

    def get_record_joystick(self):
        return self.record_joystick

    def get_axis_for_channel(self, channel_name):
        if channel_name in self.axes and channel_name in self.joysticks:
            return (self.joysticks[channel_name], self.axes[channel_name])
        else:
            return None

    def get_axis_indices(self):
        return self.axes.keys()

    def get_button_for_channel(self, channel_name):
        if channel_name in self.buttons and channel_name in self.joysticks:
            return (self.joysticks[channel_name], self.buttons[channel_name])
        else:
            return None

    def get_button_indices(self):
        return self.buttons.keys()

    def get_channel_for_axis(self, joystick_id, axis_id):
        for channel_name in self.joysticks:
            js_id = self.joysticks[channel_name]
            if js_id == joystick_id:
                if channel_name in self.axes and self.axes[channel_name] == axis_id:
                    return channel_name
        return None

    def get_channel_for_button(self, joystick_id, button_id):
        for channel_name in self.joysticks:
            js_id = self.joysticks[channel_name]
            if js_id == joystick_id:
                if channel_name in self.buttons and self.buttons[channel_name] == button_id:
                    return channel_name
        return None

    def load(self, filepath=None):
        '''
        Reads a mapping file with format:
        Type,ChannelName,JoystickID,AxisorButtonID
        where ChannelName can be Record for the record button
        '''
        try:
            if filepath is not None:
                data_file = open(filepath, 'r')
            elif self.filepath is not None:
                data_file = open(self.filepath, 'r')
            else:
                system.stderr.write("ERROR - No table file specified!\n")
                return

            # Clear existing mapping
            self.clear_mapping()

            # Skip header line
            header_line = data_file.readline()
            if header_line != 'Type,ChannelName,Joystick,ID\n':
                system.stderr.write("ERROR - Invalid table file format!\n")
                raise Exception('Invalid table file format!')

            for line in data_file:
                parts = line.strip().split(',')
                if len(parts) == 4:
                    if parts[1] == 'Record':
                        self.record_joystick = int(parts[2])
                        self.record_button = int(parts[3])
                    elif parts[0] == 'Button':
                        self.add_joystick(int(parts[2]), parts[1])
                        self.add_button(int(parts[3]), parts[1])
                    elif parts[0] == 'Axis':
                        self.add_joystick(int(parts[2]), parts[1])
                        self.add_axis(int(parts[3]), parts[1])

            data_file.close()
            self.filepath = filepath
        except:
            system.stderr.write("ERROR - Failed to read table file!\n")

    def save(self, filepath=None):
        '''
        Writes a mapping file with format:
        Type,ChannelName,JoystickID,AxisorButtonID
        where ChannelName can be Record for the record button
        '''
        try:
            if filepath is not None:
                output_file = open(filepath, 'w')
            elif self.filepath is not None:
                output_file = open(self.filepath, 'w')
            else:
                system.stderr.write("ERROR - No table file specified!\n")
                return

            output_file.write('Type,ChannelName,Joystick,ID\n')
            if self.record_joystick >= 0 and self.record_button >= 0:
                output_file.write('Button,Record,%d,%d\n' % (self.record_joystick, self.record_button))

            for channel_name in self.axes:
                if channel_name in self.joysticks:
                    output_file.write('Axis,%s,%d,%d\n' % (channel_name, self.joysticks[channel_name], self.axes[channel_name]))

            for channel_name in self.buttons:
                if channel_name in self.joysticks:
                    output_file.write('Button,%s,%d,%d\n' % (channel_name, self.joysticks[channel_name], self.buttons[channel_name]))

            output_file.close()
        except:
            system.stderr.write("ERROR - Failed to write table file!\n")

class SoundPlayer:
    def __init__(self, audio_file=None):
        game.mixer.init()
        game.mixer.music.set_volume(0.5)
        self.duration = 0.0
        if audio_file is not None:
            self.load(audio_file)

    def load(self, wavefile):
        sound = game.mixer.Sound(wavefile)
        self.duration = sound.get_length()
        game.mixer.music.load(wavefile)
        game.mixer.music.play()
        game.mixer.music.pause()

    def play(self, start_time=None):
        if self.duration <= 0.0: return   # Verify sound file loaded
        # Validate start time
        if start_time is not None and (start_time < 0.0 or start_time > self.duration): return

        # If player idle, rewind first
        if not game.mixer.music.get_busy():
            self.rewind()

        # Set optional start position
        if start_time is not None:
            game.mixer.music.set_pos(start_time)

        # Resume playback
        game.mixer.music.unpause()

    def stop(self):
        if self.duration <= 0.0: return   # Verify sound file loaded
        game.mixer.music.pause()

    def rewind(self):
        if self.duration <= 0.0: return   # Verify sound file loaded
        game.mixer.music.rewind()
        game.mixer.music.play()
        game.mixer.music.pause()

    def get_position(self):
        if self.duration <= 0.0: return 0.0  # Verify sound file loaded
        return game.mixer.music.get_pos()/1000.0

    def is_playing(self):
        if self.duration <= 0.0: return False   # Verify sound file loaded
        return game.mixer.music.get_busy()

