                system.stderr.write("until issue is resolved.\n\n")

                while len(pressed_buttons) > 0:
                    system.stderr.write("Current pressed buttons:")
                    for btn_idx in pressed_buttons:
                        system.stderr.write(" %d" % btn_idx)
                    system.stderr.write("                                    \r")
                    pressed_buttons = self.get_pressed_buttons()

                system.stderr.write("All clear -- proceeding.                                                    \n\n")

    def process_events(self):
        for event in game.event.get():
            if debug_mode: print('Received event:', event)
            pass

    def get_pressed_buttons(self):
        self.process_events()
        pressed = []
        for idx in range(self.button_count):
            if self.js.get_button(idx):
                pressed.append(idx)
        return pressed

    def is_button_pressed(self, index):
        if index >= 0 and index < self.button_count:
            return self.js.get_button(index)
        else:
            return None

    def get_max_axis(self):
        self.process_events()
        max_axis_idx = -1
        max_axis_value = 0.0

        for idx in range(self.axis_count):
            if abs(self.js.get_axis(idx)) > max_axis_value:
                max_axis_value = abs(self.js.get_axis(idx))
                max_axis_idx = idx

        return max_axis_idx, max_axis_value

    def get_axis_value(self, index):
        if index >= 0 and index < self.axis_count:
            raw_value = self.js.get_axis(index)
            if raw_value > self.deadzone:
                value = (raw_value - self.deadzone) / (1.0 - self.deadzone)
            elif raw_value < -self.deadzone:
                value = (raw_value + self.deadzone) / (1.0 - self.deadzone)
            else:
                value = 0.0
            return value
        else:
            return None

    def get_all_axis_values(self):
        self.process_events()
        values = []
        for idx in range(self.axis_count):
            values.append(self.get_axis_value(idx))
        return values

