def format_time(seconds):
    negative = seconds < 0
    if negative:
        seconds = -seconds
    time_str = ''
    hours = int(seconds/3600.0)
    if hours > 0:
        time_str += '%02d:' % hours
    seconds -= hours*3600
    minutes = int(seconds/60.0)
    seconds -= minutes*60
    time_str += '%02d:%05.2f' % (minutes, seconds)
    if negative: time_str = '-' + time_str
    return time_str

def parse_time(time_string):
    total_seconds = 0.0
    time_string = time_string.strip()
    negative = time_string[0] == '-'
    parts = time_string.split(':')
    for part in parts:
        total_seconds = total_seconds * 60.0 + abs(float(part))
    if negative: total_seconds = -total_seconds
    return total_seconds

