        self.recording_enabled = True
        self.playback_enabled = False
        self.rewind()

        self.mode_label.setText('Recording Enabled')
        palette = self.mode_label.palette()
        palette.setColor(self.mode_label.backgroundRole(), QColor('red'))
        palette.setColor(self.mode_label.foregroundRole(), QColor('white'))
        self.mode_label.setAutoFillBackground(True)
        self.mode_label.setPalette(palette)

        # Clear channels to be recorded
        for channel_name in self.animatronics.channels:
            if channel_name in self.mapping_table.buttons or channel_name in self.mapping_table.axes:
                self.animatronics.channels[channel_name].delete_knot_range(self.start_time, self.end_time)

    def enable_playback(self):
        if not self.on_recording_tab: return

        self.recording_enabled = False
        self.playback_enabled = True
        self.rewind()

        self.mode_label.setText('Playback Enabled')
        palette = self.mode_label.palette()
        palette.setColor(self.mode_label.backgroundRole(), Qt.yellow)
        palette.setColor(self.mode_label.foregroundRole(), Qt.black)
        self.mode_label.setAutoFillBackground(True)
        self.mode_label.setPalette(palette)

    def set_sample_rate(self, rate):
        self.sample_rate = rate

    def set_start_time_value(self, time_value):
        self.start_time = time_value
        formatted = format_time(time_value)
        self.start_time_display.setDigitCount(len(formatted))
        self.start_time_display.display(formatted)
        self.time_display.setDigitCount(max(self.start_time_display.digitCount(), self.end_time_display.digitCount()))

    def set_start_time(self, event):
        text, ok = self.get_time_input('Set Start Time', format_time(self.current_time))
        if ok:
            self.set_start_time_value(parse_time(text))

    def set_end_time_value(self, time_value):
        self.end_time = time_value
        formatted = format_time(time_value)
        self.end_time_display.setDigitCount(len(formatted))
        self.end_time_display.display(formatted)
        self.time_display.setDigitCount(max(self.start_time_display.digitCount(), self.end_time_display.digitCount()))

    def set_end_time(self, event):
        text, ok = self.get_time_input('Set End Time', format_time(self.current_time))
        if ok:
            self.set_end_time_value(parse_time(text))

    def get_time_input(self, title, default_value):
        text, ok = QInputDialog().getText(self, title, title, QLineEdit.EchoMode.Normal, default_value)
        try:
            text = format_time(parse_time(text))
        except:
            ok = False
        return text, ok

    def rewind(self):
        self.current_time = self.start_time
        self.set_start_time_value(self.start_time)
        self.time_display.display(format_time(self.current_time))

    def reset_to_audio(self):
        self.set_start_time_value(0.0)
        self.set_end_time_value(self.sound_player.duration)
        self.current_time = 0.0
        self.time_display.display(format_time(self.current_time))

    def create_menus(self):
