    def is_recording(self):
        js_index = self.mapping_table.get_record_joystick()
        if js_index >= 0 and self.recording_enabled:
            buttons = self.joystick_handlers[js_index].get_pressed_buttons()
            return self.mapping_table.get_record_button() in buttons
        else:
            return False

    def is_playing_back(self):
        js_index = self.mapping_table.get_record_joystick()
        if js_index >= 0 and self.playback_enabled:
            buttons = self.joystick_handlers[js_index].get_pressed_buttons()
            return self.mapping_table.get_record_button() in buttons
        else:
            return False

    def handle_events(self):
        # Process events for all joysticks
        for i in range(self.joystick_count):
            self.joystick_handlers[i].process_events()

        # Enable controls based on mapping availability
        self.enable_button.setEnabled(self.mapping_table is not None and self.mapping_table.get_record_button() >= 0)
        self.review_button.setEnabled(self.mapping_table is not None and self.mapping_table.get_record_button() >= 0 and COMMUNICATION_ENABLED)

        # Handle recording time control
        if self.is_recording() and not self.recording_active:
            self.recording_active = True
            self.monotonic_start = timer.monotonic()
            self.current_time = self.start_time
            self.next_record_time = self.start_time
            if self.sound_player is not None: 
                self.sound_player.play(startTime=self.start_time)

        elif self.is_playing_back() and not self.recording_active:
            self.recording_active = True
            self.monotonic_start = timer.monotonic()
            self.current_time = self.start_time
            if self.sound_player is not None: 
                self.sound_player.play(startTime=self.start_time)

        elif (not (self.is_recording() or self.is_playing_back()) or self.current_time >= self.end_time) and self.recording_active:
            if self.sound_player is not None: 
                self.sound_player.stop()
            if not self.is_recording(): 
                self.recording_active = False
            self.disable_all_controls()

        if self.sound_player.is_playing() or self.recording_active:
            self.current_time = timer.monotonic() - self.monotonic_start + self.start_time
            self.time_display.display(format_time(self.current_time))

            # Perform recording or playback
            if self.is_playing_back():
                self.playback()
            elif self.is_recording():
                if self.current_time >= self.next_record_time:
                    self.next_record_time += 1.0/self.sample_rate
                    self.record(True)
                else:
                    self.record()
        elif self.recording_enabled:
            self.record()

        # Update selectors from joystick actions
        if self.active_joystick_selector is not None:
            for js_idx in self.joystick_handlers:
                buttons = self.joystick_handlers[js_idx].get_pressed_buttons()
                if len(buttons) > 0:
                    self.active_joystick_selector.setCurrentIndex(js_idx)
                    channel_name = self.active_joystick_selector.property('ChannelName')
                    if isinstance(channel_name, str):
                        self.mapping_table.add_joystick(js_idx, channel_name)
                    else:
                        self.mapping_table.set_record_joystick(js_idx)
                    break

        if self.active_button_selector is not None:
            for js_idx in self.joystick_handlers:
                buttons = self.joystick_handlers[js_idx].get_pressed_buttons()
                if len(buttons) > 0:
                    self.active_button_selector.setCurrentIndex(buttons[0]+1)
                    channel_name = self.active_button_selector.property('ChannelName')
                    if isinstance(channel_name, str):
                        self.mapping_table.addButton(buttons[0], channel_name)
                    else:
                        self.mapping_table.set_record_button(buttons[0])
                    break

        if self.active_axis_selector is not None:
            for js_idx in self.joystick_handlers:
                axis_idx, axis_value = self.joystick_handlers[js_idx].get_max_axis()
                if axis_value > 0.75:
                    self.active_axis_selector.setCurrentIndex(axis_idx+1)
                    channel_name = self.active_axis_selector.property('ChannelName')
                    if isinstance(channel_name, str):
                        self.mapping_table.add_axis(axis_idx, channel_name)
                    break

    def playback(self):
        # Play back every channel that has values
        for channel_name in self.animatronics.channels:
            channel = self.animatronics.channels[channel_name]
            if channel.num_knots() > 0:
                value = channel.getValueAtTime(self.current_time)
                if value is not None:
                    self.set_channel(channel_name, value)

    def set_channel(self, channel_name, value):
        if channel_name in self.animatronics.channels and COMMUNICATION_ENABLED:
            channel = self.animatronics.channels[channel_name]
            port = channel.port
            if port >= 0:
                if channel.type == channel.DIGITAL:
                    commlib.setDigitalChannel(port, value)
                else:
                    commlib.setServo(port, value)

    def record(self, flag=False):
        # Check every channel for mapping
        for channel_name in self.animatronics.channels:
            # Handle button
            butt_val = self.mapping_table.get_button_for_channel(channel_name)
            if butt_val is not None:
                state = self.joystick_handlers[butt_val[0]].is_button_pressed(butt_val[1])
                if state is not None:
                    channel = self.animatronics.channels[channel_name]
                    if flag: 
                        channel.add_knot(self.current_time, state)
                    self.set_channel(channel_name, state)

            # Handle axis
            axis_val = self.mapping_table.get_axis_for_channel(channel_name)
            if axis_val is not None:
                value = self.joystick_handlers[axis_val[0]].get_axis_value(axis_val[1])
                if value is not None:
                    channel = self.animatronics.channels[channel_name]
                    # Scale axis value to valid range
                    value = (value + 1.0) / 2.0 * (channel.maxLimit - channel.minLimit) + channel.minLimit
                    if flag: 
                        channel.add_knot(self.current_time, value)
                    self.set_channel(channel_name, value)

    def update_window_title(self, filename):
        if filename is not None:
            self.setWindowTitle("Joy - " + filename)
        else:
            self.setWindowTitle("Joy")

    def set_animatronics(self, anim_data):
        self.animatronics = anim_data
        self.update_window_title(self.animatronics.filename)
        self.update_xml_display()

        # Setup UI based on animation
        self.enable_button.setEnabled(False)
        self.mapping_table = MappingTable()

        if anim_data.newAudio is not None:
            self.sound_player.load(anim_data.newAudio.audiofile)
            self.reset_to_audio()

        # Reset selector dictionaries
        self.all_button_selectors = {}
        self.all_axis_selectors = {}
        self.all_joystick_selectors = {}

        # Setup channel mapping tabs
        # Record button mapping
        record_layout = self.record_button_mapping_widget.layout()
        if record_layout is not None:
            clear_layout(record_layout)
        else:
            record_layout = QHBoxLayout()
            self.record_button_mapping_widget.setLayout(record_layout)

        self.record_button_js_selector = QComboBox()
        self.record_button_js_selector.setToolTip('Press any button on desired joystick')
        self.record_button_js_selector.enterEvent = self.enter_joystick_combo
        self.record_button_js_selector.leaveEvent = self.leave_combo

        for i in range(self.joystick_count):
            self.joystick_handlers[i] = JoystickHandler(i)
            self.record_button_js_selector.addItem('%d - %s' % (i, self.joystick_handlers[i].js.get_name()))

        record_layout.addWidget(self.record_button_js_selector)
        self.record_button_js_selector.activated.connect(self.record_button_js_selected)
        self.record_button_js_selector.setCurrentIndex(0)

        self.record_button_selector = QComboBox()
        self.record_button_selector.setToolTip('Press any joystick button here')
        self.record_button_selector.enter

# Mock AGFS client for testing without a real server
import shutil
from pathlib import Path
from unittest.mock import MagicMock

class LocalAGFSMock:
    """
    A mock implementation of AGFSClient that operates on a local directory.
    Useful for tests where running a real AGFS server is not feasible or desired.
    """
    def __init__(self, settings=None, base_dir=None):
        self.settings = settings
        self.base = Path(base_dir) if base_dir else Path("/tmp/test_data")
        self.base.mkdir(parents=True, exist_ok=True)

    def _normalize_path(self, path):
        if str(path).startswith("viking://"):
            path = str(path).replace("viking://", "")
        if str(path).startswith("/"):
            path = str(path)[1:]
        return self.base / path

    def file_exists(self, path, context=None):
        return self._normalize_path(path).exists()

    def create_dir(self, path, context=None, parents=True, allow_exist=True):
        self._normalize_path(path).mkdir(parents=parents, exist_ok=allow_exist)

    def list_dir(self, path, context=None, **options):
        p = self._normalize_path(path)
        if not p.exists():
            return []
        result = []
        for entry in p.iterdir():
            result.append(
                {
                    "name": entry.name,
                    "isDir": entry.is_dir(),
                    "type": "directory" if entry.is_dir() else "file",
                    "size": entry.stat().st_size if entry.is_file() else 0,
                    "mtime": entry.stat().st_mtime,
                    "uri": f"viking://{path}/{entry.name}".replace("//", "/"),
                }
            )
        return result

    def save_to(self, path, data, context=None, **options):
        p = self._normalize_path(path)
        p.parent.mkdir(parents=True, exist_ok=True)
        if isinstance(data, str):
            p.write_text(data, encoding="utf-8")
        else:
            p.write_bytes(data)
        return str(p)

    def put(self, path, data, context=None, **options):
        return self.save_to(path, data, context, **options)

    def store_file(self, path, data, context=None, **options):
        return self.save_to(path, data, context, **options)

    def load_file(self, path, context=None, **options):
        p = self._normalize_path(path)
        if not p.exists():
            raise FileNotFoundError(path)
        return p.read_bytes()

    def get(self, path, context=None, **options):
        return self.load_file(path, context, **options)

    def remove(self, path, follow_links=False, context=None):
        p = self._normalize_path(path)
        if p.exists():
            if p.is_dir():
                if follow_links:
                    shutil.rmtree(p)
                else:
                    p.rmdir()
            else:
                p.unlink()

    def clear_temp(self, path, context=None):
        self.remove(path, follow_links=True, context=context)

    def move(self, source, destination, context=None):
        src = self._normalize_path(source)
        dst = self._normalize_path(destination)
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.move(str(src), str(dst))

    def info(self, path, context=None):
        p = self._normalize_path(path)
        if not p.exists():
            raise FileNotFoundError(path)
        s = p.stat()
        return {"size": s.st_size, "mtime": s.st_mtime, "is_dir": p.is_dir()}

    def attach_context(self, context):
        return MagicMock(__enter__=lambda x: None, __exit__=lambda x, y, z: None)

