# Load relationship and weight data from JSON files
import json
from pathlib import Path

def fetch_relationships(file_relations: Path, file_weights: Path):
    relationships = {"subsidiaries": {}, "parents": {}, "suppliers": {}, "customers": {}}
    weights = {"subsidiary_to_parent": 1.0, "parent_to_subsidiary": 0.8, "customer_to_supplier": 0.5, "supplier_to_customer": 0.3}

    try:
        relationships.update(json.loads(file_relations.read_text(encoding="utf-8")))
    except Exception:
        pass

    try:
        weights.update(json.loads(file_weights.read_text(encoding="utf-8")))
    except Exception:
        pass

    # Automatically infer inverse relationships when missing
    if not relationships.get("parents") and relationships.get("subsidiaries"):
        parents_map = {}
        for parent, children in relationships["subsidiaries"].items():
            for child in children:
                parents_map.setdefault(child, []).append(parent)
        relationships["parents"] = parents_map

    if not relationships.get("customers") and relationships.get("suppliers"):
        customers_map = {}
        for customer, vendors in relationships["suppliers"].items():
            for vendor in vendors:
                customers_map.setdefault(vendor, []).append(customer)
        relationships["customers"] = customers_map

    return relationships, weights

import subprocess
from subprocess import Popen
from threading import Event, Thread

def terminate_threads(thread_list: list[Thread]):
    """Gracefully terminate a collection of threads"""
    for t in thread_list:
        t.join(timeout=5)

def terminate_subprocesses(proc_list: list[Popen]):
    """Gracefully terminate a collection of subprocesses"""
    for proc in proc_list:
        if proc.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=60)
            except subprocess.TimeoutExpired:
                proc.kill()

def watch_process(proc: Popen, stop_flag: Event, error_buffer: list, name: str):
    """Observe a subprocess and report failures through a shared buffer."""
    proc.wait()
    if proc.returncode != 0:
        err_msg = f"{name.capitalize()} failed with exit code {proc.returncode}"
        if proc.stderr:
            err_msg += f"\n{proc.stderr.read().decode('utf-8')}"
        error_buffer.append(RuntimeError(err_msg))
    stop_flag.set()

