import base64
import json
import os
from cosmos_rl.utils.logging import logger
from cosmos_rl.utils.wfm.validator import JsonDict, Validator

"""
Base class for parsing environment variables using validators.
Class will iterate through its list of validators and retrieve values from corresponding environment variables.
Validators provide:
- default value
- typed parsing
- enforcement of mandatory values
Additionally, environment variables can be passed as a single base64-encoded string.
Since we cannot prevent components from directly accessing environment variables,
parameter evaluation should raise errors to ensure the actual env var is correct.
"""
class EnvParser:
    def __init__(self, encoded_str=None):
        if encoded_str:
            logger.critical(f"encoded_str received: {encoded_str}")
            self.decode_from_b64(encoded_str)
        else:
            self.load_from_env()

    def load_from_env(self):
        validators = self.get_validator_dict()
        for param_name in validators.keys():
            env_val = os.getenv(param_name.upper())
            logger.debug(f"fetching env var {param_name.upper()}: {env_val}")
            if env_val:
                setattr(self, param_name, env_val)
        self.validate_required_fields()

    def load_from_json_file(self, file_path):
        with open(file_path, "r") as f:
            logger.info(f"Reading env params from {file_path}")
            data = json.load(f)
            for key, val in data.items():
                setattr(self, key, val)
            self.validate_required_fields()

    def encode_to_b64(self):
        json_data = self.serialize_to_json()
        # convert to bytes for base64 encoding
        json_bytes = json_data.encode('utf-8')
        encoded = base64.b64encode(json_bytes).decode('utf-8')
        print(encoded)
        return encoded

    def decode_from_b64(self, b64_input):
        decoded_json = base64.b64decode(b64_input).decode('utf-8')
        data = json.loads(decoded_json)
        for key, val in data.items():
            setattr(self, key, val)
        self.validate_required_fields()

    def validate_required_fields(self):
        for param_name, validator in self.get_validator_dict().items():
            current_val = getattr(self, param_name)
            if current_val is None and validator.default is None:
                raise ValueError(f"Missing required env var: {param_name}")

    @classmethod
    def get_validator_dict(cls):
        logger.debug(f"retrieving validator dict for {cls.__name__}")
        validators = {}
        validators.update(
            {
                attr_name: attr_value
                for attr_name, attr_value in cls.__dict__.items()
                if isinstance(attr_value, Validator)
            }
        )
        return validators

    def log_validators(self):
        validators = self.get_validator_dict()
        for name, validator in validators.items():
            logger.debug(f"{name}: {validator.__get__(self)}")

    def serialize_to_json(self, output_file=None):
        data = {
            key.upper(): value.__get__(self)
            for key, value in EnvParser.__dict__.items()
            if isinstance(value, Validator)
        }
        json_output = json.dumps(data, indent=4)
        print(json_output)
        if output_file:
            with open(output_file, "w") as f:
                logger.info(f"Writing env params to {output_file}")
                f.write(json_output)
        return json_output

    def to_string_dict(self):
        result = {}
        for key, validator in self.get_validator_dict().items():
            value = getattr(self, key)
            if value is None:
                value = validator.default
            if isinstance(validator, JsonDict):
                value = json.dumps(value)
            else:
                value = str(value)
            result[key] = value
        return result

    def __str__(self):
        return ", ".join(f"{key}={value}" for key, value in self.__dict__.items())

# Convert DeepSeek V3 model weights to HuggingFace format
import re
import torch

def transform_deepseekv3_to_hf(config, param_name, weight):
    # Handle embedding and output layers
    if param_name == "module.module.embedding.word_embeddings.weight":
        return [("model.embed_tokens.weight", weight)]
    if param_name == "module.module.output_layer.weight":
        return [("lm_head.weight", weight)]
    if param_name == "module.module.decoder.final_layernorm.weight":
        return [("model.norm.weight", weight)]

    try:
        # Compute head dimension from config
        dim_per_head = config.kv_channels if config.kv_channels is not None else config.hidden_size // config.num_attention_heads
    except AttributeError:
        dim_per_head = config.hidden_size // config.num_attention_heads

    num_values_per_group = config.num_attention_heads // config.num_query_groups
    decoder_layers_regex = r"module\.module\.decoder\.layers\.(\d+)\.(.+)"
    layer_match = re.match(decoder_layers_regex, param_name)

    if layer_match:
        layer_id, rest_param = layer_match.groups()

        # Experts handling
        expert_regex = r"mlp.experts\.(.+)\.weight(\d+)"
        expert_match = re.match(expert_regex, rest_param)
        if expert_match:
            rest_part, expert_id = expert_match.groups()
            if rest_part == "linear_fc1":
                gate_weight, up_weight = weight.chunk(2, dim=0)
                result = [
                    (f"model.layers.{layer_id}.mlp.experts.{expert_id}.gate_proj.weight", gate_weight),
                    (f"model.layers.{layer_id}.mlp.experts.{expert_id}.up_proj.weight", up_weight),
                ]
                return result
            elif rest_part == "linear_fc2":
                result = [
                    (f"model.layers.{layer_id}.mlp.experts.{expert_id}.down_proj.weight", weight),
                ]
                return result
            else:
                raise ValueError(f"Unknown expert parameter name: {param_name}")

        # Shared experts handling
        shared_expert_regex = r"mlp.shared_experts\.(.+)"
        shared_match = re.match(shared_expert_regex, rest_param)
        if shared_match:
            rest_part = shared_match.groups()[0]
            if rest_part == "linear_fc1.weight":
                gate_weight, up_weight = weight.chunk(2, dim=0)
                return [
                    (f"model.layers.{layer_id}.mlp.shared_experts.gate_proj.weight", gate_weight),
                    (f"model.layers.{layer_id}.mlp.shared_experts.up_proj.weight", up_weight),
                ]
            elif rest_part == "linear_fc2.weight":
                return [(f"model.layers.{layer_id}.mlp.shared_experts.down_proj.weight", weight)]
            else:
                raise ValueError(f"Unknown shared expert parameter name: {param_name}")

        # Standard attention and MLP layers
        if rest_param == "self_attention.linear_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.o_proj.weight", weight)]
        elif rest_param == "self_attention.linear_q_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.q_proj.weight", weight)]
        elif rest_param == "self_attention.linear_q_down_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.q_a_proj.weight", weight)]
        elif rest_param == "self_attention.linear_q_up_proj.layer_norm_weight":
            return [(f"model.layers.{layer_id}.self_attn.q_a_layernorm.weight", weight)]

        # Indexer components
        elif rest_param == "self_attention.wq_b.weight":
            wq_b = weight
            wq_b = wq_b.view(-1, 128, wq_b.shape[-1])  # fixed size 128
            wq_b = torch.cat([wq_b[:, 64:], wq_b[:, :64]], dim=1).view(-1, wq_b.shape[-1])
            return [(f"model.layers.{layer_id}.self_attn.indexer.wq_b.weight", wq_b)]
        elif rest_param == "self_attention.wk.weight":
            wk = weight
            wk = torch.cat([wk[64:], wk[:64]], dim=0).view(-1, wk.shape[-1])
            return [(f"model.layers.{layer_id}.self_attn.indexer.wk.weight", wk)]
        elif rest_param == "self_attention.weights_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.indexer.weights_proj.weight", weight)]
        elif rest_param == "self_attention.k_norm.weight":
            knorm_w = weight
            knorm_w = torch.cat([knorm_w[64:], knorm_w[:64]], dim=0)
            return [(f"model.layers.{layer_id}.self_attn.indexer.k_norm.weight", knorm_w)]
        elif rest_param == "self_attention.k_norm.bias":
            knorm_b = weight
            knorm_b = torch.cat([knorm_b[64:], knorm_b[:64]], dim=0)
            return [(f"model.layers.{layer_id}.self_attn.indexer.k_norm.bias", knorm_b)]
        elif rest_param == "self_attention.linear_q_up_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.q_b_proj.weight", weight)]
        elif rest_param == "self_attention.linear_qkv.bias":
            weight = weight.view(config.num_query_groups, -1)
            q_bias, k_bias, v_bias = torch.split(
                weight,
                split_size_or_sections=[num_values_per_group * dim_per_head, dim_per_head, dim_per_head],
                dim=1,
            )
            q_bias = q_bias.contiguous().flatten()
            k_bias = k_bias.contiguous().flatten()
            v_bias = v_bias.contiguous().flatten()
            return [
                (f"model.layers.{layer_id}.self_attn.q_proj.bias", q_bias),
                (f"model.layers.{layer_id}.self_attn.k_proj.bias", k_bias),
                (f"model.layers.{layer_id}.self_attn.v_proj.bias", v_bias),
            ]
        elif rest_param == "mlp.linear_fc1.weight":
            gate_weight, up_weight = weight.chunk(2, dim=0)
            return [
                (f"model.layers.{layer_id}.mlp.gate_proj.weight", gate_weight),
                (f"model.layers.{layer_id}.mlp.up_proj.weight", up_weight),
            ]
        elif rest_param == "mlp.linear_fc2.weight":
            return [(f"model.layers.{layer_id}.mlp.down_proj.weight", weight)]
        elif rest_param == "self_attention.linear_qkv.layer_norm_weight" or rest_param == "input_layernorm.weight":
            return [(f"model.layers.{layer_id}.input_layernorm.weight", weight)]
        elif rest_param == "mlp.linear_fc1.layer_norm_weight":
            return [(f"model.layers.{layer_id}.post_attention_layernorm.weight", weight)]
        elif rest_param == "self_attention.linear_kv_down_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.kv_a_proj_with_mqa.weight", weight)]
        elif rest_param == "self_attention.linear_kv_up_proj.layer_norm_weight":
            return [(f"model.layers.{layer_id}.self_attn.kv_a_layernorm.weight", weight)]
        elif rest_param == "self_attention.linear_kv_up_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.kv_b_proj.weight", weight)]
        elif rest_param == "pre_mlp_layernorm.weight":
            return [(f"model.layers.{layer_id}.post_attention_layernorm.weight", weight)]
        elif rest_param == "mlp.router.weight":
            return [(f"model.layers.{layer_id}.mlp.gate.weight", weight)]
        elif rest_param == "mlp.router.expert_bias":
            return [(f"model.layers.{layer_id}.mlp.gate.e_score_correction_bias", weight)]

    # MTP layers handling
    mtp_layer_regex = r"module\.module\.mtp\.layers\.(\d+)\.(.+)"
    mtp_match = re.match(mtp_layer_regex, param_name)
    if mtp_match:
        layer_id, rest_param = mtp_match.groups()
        layer_id = int(layer_id) + config.num_layers
        if rest_param == "eh_proj.weight":
            return [(f"model.layers.{layer_id}.eh_proj.weight", weight)]
        elif rest_param == "enorm.weight":
            return [(f"model.layers.{layer_id}.enorm.weight", weight)]
        elif rest_param == "hnorm.weight":
            return [(f"model.layers.{layer_id}.hnorm.weight", weight)]
        elif rest_param == "final_layernorm.weight":
            return [(f"model.layers.{layer_id}.shared_head.norm.weight", weight)]
        else:
            new_name = f"module.module.decoder.layers.{layer_id}.{rest_param}"
            new_name = new_name.replace("transformer_layer.", "")
            return transform_deepseekv3_to_hf(config, new_name, weight)

    raise ValueError(f"Unknown parameter name: {param_name}")

# Dynamically import modules and plugins for model/data registration
import importlib
import pkgutil
from mindspeed.fsdp.utils.log import print_rank

def load_module(module_path, show_log=True):
    if "/" in module_path:
        module_path = module_path.replace("/", ".")
    module_path = module_path.strip(".")
    try:
        module = importlib.import_module(module_path)
        if show_log:
            print_rank(print, f"Successfully loaded: {module_path}")
        return module, module_path
    except ModuleNotFoundError as err:
        if show_log:
            print_rank(print, f"Loading failed: {module_path}. Error: {err}")
        else:
            raise err
    return None, None

def load_plugins(plugin_paths=None):
    if not plugin_paths:
        return
    for plugin_path in plugin_paths:
        module, module_name = load_module(plugin_path, show_log=True)
        if not hasattr(module, "__path__"):
            continue
        for _, sub_module_name, is_package in pkgutil.walk_packages(module.__path__, prefix=f"{module_name}."):
            if not is_package:
                _ = load_module(sub_module_name, show_log=False)

class RegistryManager:
    def __init__(self):
        self._registry = {}

    def register(self, identifier):
        def decorator(item):
            nonlocal identifier
            if identifier in self._registry:
                existing = self._registry[identifier]
                raise KeyError(f"Identifier '{identifier}' is already registered to {existing.__name__}.")
            self._registry[identifier] = item
        return decorator

    def fetch(self, identifier):
        if identifier not in self._registry:
            raise KeyError(f"Identifier '{identifier}' is not registered.")
        return self._registry[identifier]

model_registry = RegistryManager()
data_registry = RegistryManager()

