import skylos.rules.danger.danger_web.xss_flow as xss

def _locate_violation(violations, code):
    for v in violations:
        if v.get("rule_id") == code:
            return True
    return False

def test_qualified_name_from_call_simple_variant():
    expr_node = ast.parse("bar(42)").body[0].value
    assert isinstance(expr_node, ast.Call)
