# Handle DynamoDB operations for items management 
import json
import boto3
from stlv_resources import Resources

def handler(event, context):
    dynamodb_table = boto3.resource("dynamodb").Table(Resources.items.table_name)
    request_method = event.get("httpMethod")
    path_params = event.get("pathParameters") or {}
    item_key = path_params.get("id")

    if request_method == "POST":
        payload = json.loads(event["body"])
        dynamodb_table.put_item(Item=payload)
        return {"statusCode": 201, "body": json.dumps(payload)}

    if request_method == "GET" and item_key:
        response = dynamodb_table.get_item(Key={"pk": item_key})
        record = response.get("Item")
        if not record:
            return {"statusCode": 404, "body": "not found"}
        return {"statusCode": 200, "body": json.dumps(record)}

    if request_method == "DELETE" and item_key:
        dynamodb_table.delete_item(Key={"pk": item_key})
        return {"statusCode": 200, "body": "deleted"}

    return {"statusCode": 400, "body": "bad request"}

