# Modified version of CodexAdapter with renamed variables and reordered logic
import os
import sys
import json
import requests
from datetime import datetime

class APIManager:
    def __init__(self, key=None, endpoint=None):
        self.api_key = key or os.getenv('CODEX_API_KEY')
        self.api_url = endpoint or os.getenv('CODEX_API_URL')

        if not self.api_key or not self.api_url:
            raise ValueError("Environment variables CODEX_API_KEY and CODEX_API_URL must be configured")

    def fetch_quota_info(self):
        """Retrieve current usage statistics"""
        try:
            auth_headers = {
                'Authorization': f'Bearer {self.api_key}',
                'Accept': 'application/json'
            }

            api_response = requests.get(
                f'{self.api_url}/v1/usage',
                headers=auth_headers,
                timeout=10
            )
            api_response.raise_for_status()

            response_data = api_response.json()

            total_limit = response_data.get('limit', 0)
            used_amount = response_data.get('used', 0)

            return {
                'service': 'codex',
                'status': 'success',
                'quota_details': {
                    'consumed': used_amount,
                    'maximum': total_limit,
                    'available': total_limit - used_amount,
                    'utilization_percent': (used_amount / max(total_limit, 1)) * 100
                },
                'recorded_at': datetime.now().isoformat()
            }

        except requests.exceptions.RequestException as error:
            return {
                'service': 'codex',
                'status': 'failed',
                'message': str(error),
                'recorded_at': datetime.now().isoformat()
            }

    def verify_service_availability(self):
        """Test if the API service is reachable"""
        try:
            auth_headers = {
                'Authorization': f'Bearer {self.api_key}',
                'Content-Type': 'application/json'
            }

            status_response = requests.get(
                f'{self.api_url}/v1/status',
                headers=auth_headers,
                timeout=5
            )

            return status_response.status_code == 200

        except Exception:
            return False

def run_cli():
    """Main entry point for command-line interface"""
    if len(sys.argv) < 2:
        print("Usage: codex.py [quota|health]")
        sys.exit(1)

    selected_command = sys.argv[1]
    manager = APIManager()

    if selected_command == 'quota':
        output = manager.fetch_quota_info()
        print(json.dumps(output, indent=2))
    elif selected_command == 'health':
        is_healthy = manager.verify_service_availability()
        print(json.dumps({'healthy': is_healthy}))
    else:
        print(f"Unknown command: {selected_command}")
        sys.exit(1)

if __name__ == '__main__':
    run_cli()

