# Expert parallelization module for distributed training
import logging
import types
from functools import partial
from typing import Callable
import torch
from torch.distributed import DeviceMesh
from torch.distributed.tensor import Shard, DTensor, Replicate, distribute_tensor, distribute_module
from mindspeed.fsdp.distributed.expert_parallel.dispatcher import get_experts_forward_fn
from mindspeed.fsdp.distributed.expert_parallel.dispatcher_mc2 import get_experts_forward_mc2_fn
from mindspeed.fsdp.parallel_engine_config import EPPlanConfig
from mindspeed.fsdp.utils.log import print_rank
from mindspeed.fsdp.utils.str_match import module_name_match

logger = logging.getLogger(__name__)

def expert_parallelize_modules(model: torch.nn.Module, ep_mesh: DeviceMesh, config: EPPlanConfig):
    target_modules = get_target_modules(model, config)
    ep_group = ep_mesh.get_group()
    ep_rank = torch.distributed.get_rank(ep_group)
    ep_world_size = torch.distributed.get_world_size(ep_group)

    for layer in target_modules:
        distribute_experts_layer(layer, ep_mesh)

        # Replace forward method with expert-parallel version
        if hasattr(layer, 'ep_forward') and callable(layer.ep_forward):
            layer.forward = partial(layer.ep_forward, ep_group=ep_group)
        else:
            experts_forward_impl = get_experts_forward_qwen_style(ep_group)
            layer.forward = types.MethodType(experts_forward_impl, layer)

    return model

def get_target_modules(model: torch.nn.Module, config: EPPlanConfig):
    selected_layers = []
    for pattern in config.apply_modules:
        for layer_path, layer in model.named_modules():
            if module_name_match(pattern, layer_path):
                print_rank(logger.debug, f'[Expert Parallel]: Applying ep to layer <{layer_path}>')
                selected_layers.append(layer)

    if len(selected_layers) == 0:
        raise RuntimeError(f'[Expert Parallel] No layers matched patterns {config} or not ModuleList')

    return selected_layers

def prepare_input_distribution(layer, inputs, device_mesh):
    inputs_list = list(inputs)
    for i, input_tensor in enumerate(inputs_list):
        if not isinstance(input_tensor, DTensor):
            input_tensor = DTensor.from_local(input_tensor, device_mesh, (Replicate(),), run_check=False)
            inputs_list[i] = input_tensor
    return tuple(inputs_list)

def prepare_output_distribution(layer, outputs, device_mesh):
    return outputs.to_local()

def distribute_expert_parameters(layer_name, layer, ep_mesh):
    for param_name, param in layer.named_parameters(recurse=False):
        dist_param = torch.nn.Parameter(distribute_tensor(param, ep_mesh, [Shard(0)]))
        layer.register_parameter(param_name, dist_param)

    for child_name, child_module in layer.named_children():
        distribute_expert_parameters(child_name, child_module, ep_mesh)

def distribute_experts_layer(layer: torch.nn.Module, ep_mesh: DeviceMesh):
    return distribute_module(module=layer, device_mesh=ep_mesh, partition_fn=distribute_expert_parameters,)
                             # input_fn=prepare_input_distribution, output_fn=prepare_output_distribution)

def get_dispatcher_function(dispatcher, ep_group):
    forward_impl = None
    if isinstance(dispatcher, Callable):
        forward_impl = partial(dispatcher, ep_group)
    elif isinstance(dispatcher, str):
        if dispatcher == 'eager':
            forward_impl = get_experts_forward_fn(ep_group, fused=False)
        elif dispatcher == 'fused':
            forward_impl = get_experts_forward_fn(ep_group, fused=True)
        elif dispatcher == 'mc2':
            forward_impl = get_experts_forward_mc2_fn(ep_group)

    if forward_impl is None:
        raise RuntimeError(f'Unsupported dispatcher mode: {dispatcher}.')

    return forward_impl

def get_gradient_reduction_hook(param, ep_world_size):
    def hook(*unused):
        return param.grad.mul_(1.0 / ep_world_size)
    return hook

def apply_gradient_reduction_hooks(layer, ep_world_size):
    for param in layer.parameters():
        if param.requires_grad:
            param_view = param.expand_as(param)
            grad_acc_node = param_view.grad_fn.next_functions[0][0]
            grad_acc_node.register_hook(get_gradient_reduction_hook(param, ep_world_size))

def get_experts_forward_qwen_style(ep_group, fused=True):
    from .fused_ep import fused_ep_forward

    def experts_forward(self, hidden_states: torch.Tensor, routing_weights: torch.Tensor, router_indices: torch.Tensor):
        batch_size = hidden_states.shape[0]
        hidden_states = hidden_states.reshape(-1, self.hidden_dim)

        gate_up_proj = self.gate_up_proj.to_local() if isinstance(self.gate_up_proj, DTensor) else self.gate_up_proj
        down_proj = self.down_proj.to_local() if isinstance(self.down_proj, DTensor) else self.down_proj

        hidden_states = fused_ep_forward(
            self.num_experts,
            routing_weights,
            router_indices,
            hidden_states,
            fc1_weight=gate_up_proj,
            fc2_weight=down_proj,
            ep_group=ep_group
        )

        hidden_states = hidden_states.view(batch_size, -1, self.hidden_dim)
        return hidden_states

    return experts_forward

