def create_vllm_config(config_types: List[str],
                       updates: List[Mapping[str, Any]]):
    config_obj = VllmConfiguration()
    for (config_type, update) in zip(config_types, updates):
        if config_type == "model":
            for param in update:
                setattr(config_obj.model_settings, param, update[param])
        else:
            for param in update:
                setattr(config_obj, param, update[param])
    return config_obj

@dataclass
