    extra_config: Mapping[str, Any] = field(default_factory=dict)
    model_settings: ModelConfig = field(
        default_factory=lambda: ModelConfig(max_model_len=1024))

@dataclass
class CustomConfig(Config):
    vllm_configuration: VllmConfiguration
    param1: str
    param2: str
    param3: int
    def matches(self, other: Config):
        for attr in fields(self):
            if attr.name != "vllm_configuration":
                if getattr(self, attr.name) != getattr(other, attr.name):
                    return False
        return True

