# Custom warning classes for Metaxy and Polars materialization issues
import warnings
import narwhals as nw
from narwhals.typing import Frame

class PolarsMaterializationWarning(Warning):
    pass

    @classmethod
    def warn_on_implementation_mismatch(cls, expected_impl: nw.Implementation, actual_impl: nw.Implementation, extra_msg: str = ""):
        if expected_impl != actual_impl:
            warning_msg = f"Narwhals implementation mismatch: native is {expected_impl}, got {actual_impl}. This will lead to materialization into an eager Polars frame."
            if extra_msg:
                warning_msg += f" {extra_msg}"
            warnings.warn(warning_msg, cls, stacklevel=3)

class MetaxyColumnMissingWarning(Warning):
    pass

    @classmethod
    def warn_on_missing_column(cls, required_col: str, data_frame: Frame, additional_info: str = ""):
        # Use collect_schema().names() to avoid PerformanceWarning on lazy frames
        available_columns = data_frame.collect_schema().names()
        if required_col in available_columns:
            return
        else:
            warning_text = f"Metaxy column missing: expected {required_col}, got {available_columns}."
            if additional_info:
                warning_text += f" {additional_info}"
            warnings.warn(warning_text, cls, stacklevel=3)

