    max_depth_found = current_depth
    for item in nodes:
        if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            continue
        if isinstance(item, _BRANCH_NODES):
            sub_branches = []
            if isinstance(item, ast.If):
                sub_branches.append(item.body)
                if item.orelse:
                    sub_branches.append(item.orelse)
            elif isinstance(item, (ast.For, ast.While)):
                sub_branches.append(item.body)
                if item.orelse:
                    sub_branches.append(item.orelse)
            for branch in sub_branches:
                max_depth_found = max(max_depth_found, _calculate_max_depth(branch, current_depth + 1))
            continue
        if isinstance(item, ast.With):
            max_depth_found = max(max_depth_found, _calculate_max_depth(item.body, current_depth))
            continue
        try_types = [ast.Try]
        if hasattr(ast, "TryStar"):
            try_types.append(ast.TryStar)
        if isinstance(item, tuple(try_types)):
            if is_in_function:
                depth_increment = 0
            else:
                depth_increment = 1
            local_depth = current_depth + depth_increment
            all_branches = [item.body]
            for handler in item.handlers:
                all_branches.append(handler.body)
            if item.orelse:
                all_branches.append(item.orelse)
            if item.finalbody:
                all_branches.append(item.finalbody)
            for branch in all_branches:
                max_depth_found = max(max_depth_found, _calculate_max_depth(branch, local_depth))
            continue
    return max_depth_found

def _count_lines(node):
    start_line = getattr(node, "lineno", 0)
    end_line = getattr(node, "end_lineno", start_line)
    return max(end_line - start_line + 1, 0)

class NestingAnalysis(SkylosRule):
    rule_id = "SKY-Q302"
    name = "Excessive Nesting Detection"
    def __init__(self, limit=3):
        self.limit = limit

    def check_node(self, node, context):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            return None
        computed_depth = _calculate_max_depth(node.body, 0, is_in_function=True)
        if computed_depth <= self.limit:
            return None
        if computed_depth <= self.limit + 2:
            level = "MEDIUM"
        elif computed_depth <= self.limit + 5:
            level = "HIGH"
        else:
            level = "CRITICAL"
        line_count = _count_lines(node)
        module_name = context.get("mod", "")
        if module_name:
            full_name = f"{module_name}.{node.name}"
        else:
            full_name = node.name
        return [
            {
                "rule_id": self.rule_id,
                "kind": "nesting",
                "severity": level,
                "type": "function",
                "name": full_name,
                "simple_name": node.name,
                "file": context.get("filename"),
                "basename": Path(context.get("filename", "")).name,
                "line": node.lineno,
                "metric": "max_nesting",
                "value": computed_depth,
                "threshold": self.limit,
                "length": line_count,
                "message": f"Nesting depth of {computed_depth} exceeds threshold of {self.limit}. Consider using early returns.",
            }
        ]

# Calculate period boundaries based on start, end dates and granularity (monthly/yearly)
import datetime

def get_period_ranges(start_date, end_date, interval_type):
    intervals = []
    if interval_type == "monthly":
        current = start_date.replace(day=1)
        while current < end_date:
            next_interval = (current.replace(day=28) + datetime.timedelta(days=4)).replace(day=1)
            intervals.append((current, min(next_interval, end_date), current.strftime("%Y-%m")))
            current = next_interval
    else:  # yearly
        current = start_date.replace(month=1, day=1)
        while current < end_date:
            next_interval = current.replace(year=current.year + 1)
            intervals.append((current, min(next_interval, end_date), str(current.year)))
            current = next_interval
    return intervals

def filter_entries_by_time_range(entries, from_date, to_date):
    result = []
    for item in entries:
        if not hasattr(item, "date"):
            result.append(item)
            continue
        if from_date and item.date < from_date:
            continue
        if to_date and item.date >= to_date:
            continue
        result.append(item)
    return result

def build_account_tree(account_node):
    tree_node = {
        "name": account_node.account,
        "totals": {},
        "subnodes": [],
    }
    for holding in account_node.balance:
        currency = holding.units.currency
        value = float(holding.units.number)
        tree_node["totals"][currency] = tree_node["totals"].get(currency, 0) + value
    for child in sorted(account_node.values(), key=lambda r: r.account):
        subtree = build_account_tree(child)
        if subtree["subnodes"] or subtree["totals"]:
            tree_node["subnodes"].append(subtree)
    return tree_node

def extract_subtree(realization_map, account_path, default_name):
    acc = realization_map.get(account_path, default_name)
    if acc is None:
        return {"name": default_name, "totals": {}, "subnodes": []}
    return build_account_tree(acc)

def aggregate_balances(realization_map, account_path, default_name):
    acc = realization_map.get(account_path, default_name)
    if acc is None:
        return {}
    summary = {}
    def traverse(node):
        for holding in node.balance:
            currency = holding.units.currency
            amount = float(holding.units.number)
            summary[currency] = summary.get(currency, 0) + amount
        for child in node.values():
            traverse(child)
    traverse(acc)
    return summary

def normalize_currency_totals(totals_dict, price_data, target_currency, reference_date=None):
    """Convert a {currency: amount} dictionary into a single {target_currency: amount} dictionary."""
    from beancount.core.prices import get_price
    final_amount = 0.0
    for currency, amount in totals_dict.items():
        if currency == target_currency:
            final_amount += amount
        else:
            conversion_result = get_price(price_data, (currency, target_currency), reference_date)
            if conversion_result is None:
                raise click.UsageError(f"No price available for {currency} -> {target_currency}")
            _, exchange_rate = conversion_result
            final_amount += amount * float(exchange_rate)
    return {target_currency: round(final_amount, 2)}

def _sum_tree_values(tree_node):
    """Aggregate all balances in a tree structure (node + its descendants)."""
    subtotal = sum(tree_node["totals"].values())
    for child in tree_node["subnodes"]:
        subtotal += _sum_tree_values(child)
    return subtotal

def convert_tree_to_target_currency(tree_node, price_data, target_currency, reference_date=None):
    """Recursively transform all balances in an account tree to the specified target currency."""
    converted_children = [convert_tree_to_target_currency(child, price_data, target_currency, reference_date) for child in tree_node["subnodes"]]
    converted_children.sort(key=lambda c: abs(_sum_tree_values(c)), reverse=True)
    converted_node = {
        "name": tree_node["name"],
        "totals": normalize_currency_totals(tree_node["totals"], price_data, target_currency, reference_date) if tree_node["totals"] else {},
        "subnodes": converted_children,
    }
    return converted_node

