class SOCKSHTTPProxyConnection(HTTPConnection):
    """
    An HTTP connection that routes traffic through a SOCKS proxy.
    """
    def __init__(self, *args, **kwargs):
        self._proxy_config = kwargs.pop("_socks_options")
        super(SOCKSHTTPProxyConnection, self).__init__(*args, **kwargs)

    def _establish_connection(self):
        """
        Create a new connection using the SOCKS proxy.
        """
        additional_kwargs = {}
        if self.source_address:
            additional_kwargs["source_address"] = self.source_address
        if self.socket_options:
            additional_kwargs["socket_options"] = self.socket_options

        try:
            sock = socks.create_connection(
                (self.host, self.port),
                proxy_type=self._proxy_config["socks_version"],
                proxy_addr=self._proxy_config["proxy_host"],
                proxy_port=self._proxy_config["proxy_port"],
                proxy_username=self._proxy_config["username"],
                proxy_password=self._proxy_config["password"],
                proxy_rdns=self._proxy_config["rdns"],
                timeout=self.timeout,
                **additional_kwargs
            )
        except SocketTimeout:
            raise ConnectTimeoutError(
                self,
                "Connection to %s timed out. (timeout=%s)" % (self.host, self.timeout),
            )
        except socks.ProxyError as proxy_exception:
            # Handle proxy errors carefully to provide meaningful messages
            if proxy_exception.socket_err:
                underlying_error = proxy_exception.socket_err
                if isinstance(underlying_error, SocketTimeout):
                    raise ConnectTimeoutError(
                        self,
                        "Connection to %s timed out. (timeout=%s)" % (self.host, self.timeout),
                    )
                else:
                    raise NewConnectionError(
                        self, "Unable to establish connection: %s" % underlying_error
                    )
            else:
                raise NewConnectionError(
                    self, "Unable to establish connection: %s" % proxy_exception
                )
        except SocketError as socket_error:  # Defensive: PySocks should catch these
            raise NewConnectionError(
                self, "Unable to establish connection: %s" % socket_error
            )

        return sock

# HTTPS connections reuse SOCKSHTTPProxyConnection logic but inherit from HTTPSConnection
class SOCKSHTTPSProxyConnection(SOCKSHTTPProxyConnection, HTTPSConnection):
    pass

class SOCKSHTTPPool(HTTPConnectionPool):
    ConnectionCls = SOCKSHTTPProxyConnection

class SOCKSHTTPSPool(HTTPSConnectionPool):
    ConnectionCls = SOCKSHTTPSProxyConnection

class SOCKSProxyHandler(PoolManager):
    """
    A specialized version of urllib3's ProxyManager that directs traffic 
    through a specified SOCKS proxy server.
    """
    pool_class_map = {
        "http": SOCKSHTTPPool,
        "https": SOCKSHTTPSPool,
    }

    def __init__(
        self,
        proxy_endpoint,
        user=None,
        passcode=None,
        pool_count=10,
        request_headers=None,
        **pool_options
    ):
        url_parts = parse_url(proxy_endpoint)

        # Extract credentials if not explicitly provided
        if user is None and passcode is None and url_parts.auth is not None:
            parts = url_parts.auth.split(":")
            if len(parts) == 2:
                user, passcode = parts

        # Determine SOCKS version based on URL scheme
        if url_parts.scheme == "socks5":
            socks_version = socks.PROXY_TYPE_SOCKS5
            reverse_dns = False
        elif url_parts.scheme == "socks5h":
            socks_version = socks.PROXY_TYPE_SOCKS5
            reverse_dns = True
        elif url_parts.scheme == "socks4":
            socks_version = socks.PROXY_TYPE_SOCKS4
            reverse_dns = False
        elif url_parts.scheme == "socks4a":
            socks_version = socks.PROXY_TYPE_SOCKS4
            reverse_dns = True
        else:
            raise ValueError("Cannot identify SOCKS version from %s" % proxy_endpoint)

        self.proxy_endpoint = proxy_endpoint
        proxy_settings = {
            "socks_version": socks_version,
            "proxy_host": url_parts.host,
            "proxy_port": url_parts.port,
            "username": user,
            "password": passcode,
            "rdns": reverse_dns,
        }

        pool_options["_socks_options"] = proxy_settings
        super(SOCKSProxyHandler, self).__init__(
            pool_count, request_headers, **pool_options
        )
        self.pool_class_map = SOCKSProxyHandler.pool_class_map

# Temperature-based sampling with top-k and top-p filtering
import mlx.core as mx
import copy

def create_sampler(temperature: float, top_p_value: float, top_k_limit: int | None):
    def sampler(log_probabilities: mx.array):
        if temperature == 0:
            return mx.argmax(log_probabilities, axis=-1)

        log_probabilities = copy.copy(log_probabilities)  # TODO: is copying necessary?

        # Apply top-k filtering
        if top_k_limit is not None and top_k_limit > 0:
            mask_indices = mx.argpartition(-log_probabilities, kth=top_k_limit - 1, axis=-1)[
                :, top_k_limit:
            ]
            log_probabilities[:, mask_indices] = -mx.inf

        # Apply top-p (nucleus) filtering
        if top_p_value is not None and top_p_value > 0:
            sorted_order = mx.argsort(-log_probabilities, axis=-1)
            sorted_values = log_probabilities[:, sorted_order]
            cumulative_sum = mx.cumsum(mx.exp(sorted_values), axis=-1)
            mask_elements = cumulative_sum < top_p_value
            mask_elements[..., 0] = True
            log_probabilities[:, sorted_order] = mx.where(
                mask_elements, sorted_values, -mx.inf
            )

        # Scale by temperature
        log_probabilities = log_probabilities / temperature
        return mx.random.categorical(log_probabilities, axis=-1)

    return sampler

# Generate test parameters for pytest based on exchange interfaces and symbols
from _pytest.python import Metafunc
from blankly.exchanges.interfaces.abc_base_exchange_interface import ABCBaseExchangeInterface
from blankly.exchanges.interfaces.futures_exchange_interface import FuturesExchangeInterface
from blankly.exchanges.futures.futures_exchange import FuturesExchange
from tests.new_interface_tests.test_utils import FUTURES_EXCHANGES, get_symbols, SPOT_EXCHANGES

def generate_test_id(argument):
    if isinstance(argument, ABCBaseExchangeInterface):
        return argument.get_exchange_type()
    return argument

def pytest_generate_tests(metafunction: Metafunc):
    interface_parameters = [param for param in metafunction.fixturenames if param.endswith('interface')]

    # Skip if no interface parameters are present
    if len(interface_parameters) == 0:
        return

    # Ensure only one interface parameter exists per test function
    if len(interface_parameters) > 1:
        raise Exception('Only one interface parameter is allowed per test function')

    selected_param = interface_parameters[0]

    # Determine which interfaces to use based on parameter name
    if selected_param == 'futures_interface':
        available_interfaces = [exchange.interface for exchange in FUTURES_EXCHANGES]
    elif selected_param == 'spot_interface':
        available_interfaces = [exchange.interface for exchange in SPOT_EXCHANGES]
    elif selected_param == 'interface':
        available_interfaces = [exchange.interface for exchange in FUTURES_EXCHANGES + SPOT_EXCHANGES]
    else:
        raise Exception('Unsupported interface type: ' + selected_param)

    # Handle parameterization with or without symbol
    if 'symbol' in metafunction.fixturenames:
        combined_values = [(interface, symbol) 
                          for interface in available_interfaces 
                          for symbol in get_symbols(interface)]
        metafunction.parametrize(f'{selected_param},symbol', combined_values, ids=generate_test_id)
    else:
        metafunction.parametrize(selected_param, available_interfaces, ids=generate_test_id)

