    base_url = f"https://api.github.com/repos/huggingface/transformers/actions/workflows/{workflow_identifier}/runs"

    # Parameters: main branch, schedule event, exclude PRs, limit results
    query_url = f"{base_url}?branch=main&event=schedule&exclude_pull_requests=true&per_page={count}"
    response_data = requests.get(query_url, headers=auth_headers).json()
