                url = artifact_links[name]
                download_artifact(
                    artifact_name=name, 
                    artifact_url=url, 
                    output_dir=save_dir, 
                    token=auth_token
                )

def extract_ci_reports(artifact_names, save_dir, auth_token):
    """Load and parse contents of artifacts from the latest completed scheduled CI run."""
    fetch_latest_ci_artifacts(artifact_names, save_dir, auth_token)
    parsed_results = {}
    for name in artifact_names:
        zip_path = os.path.join(save_dir, f"{name}.zip")
        if os.path.isfile(zip_path):
            parsed_results[name] = {}
            with zipfile.ZipFile(zip_path) as archive:
                for entry in archive.namelist():
                    if not os.path.isdir(entry):
                        with archive.open(entry) as file:
