# Session quota management script
import os
import sys
import json
from datetime import datetime, timedelta

SCRIPT_PATH = os.path.dirname(os.path.abspath(__file__))
ROOT_DIR = os.path.dirname(SCRIPT_PATH)
STORAGE_DIR = os.path.join(ROOT_DIR, 'data')
os.makedirs(STORAGE_DIR, exist_ok=True)
CONFIG_FILE = os.path.join(STORAGE_DIR, 'session_quota.json')

def fetch_quota():
    """Retrieve current quota configuration"""
    if os.path.exists(CONFIG_FILE):
        with open(CONFIG_FILE, 'r') as file:
            return json.load(file)
    return {
        'caps': {},      # {model: max_sessions_per_day}
        'logs': {},      # {date: {model: count}}
    }

def store_quota(data):
    """Persist quota data to disk"""
    with open(CONFIG_FILE, 'w') as file:
        json.dump(data, file, indent=2)

def configure_limit(model_name, session_cap):
    """Define maximum sessions allowed per day for a specific model"""
    config = fetch_quota()
    config['caps'][model_name] = session_cap
    store_quota(config)
    print(f"Configured limit: {model_name} -> {session_cap} sessions/day")

def log_activity(model_name):
    """Log a new session activity for a model"""
    config = fetch_quota()
    current_date = datetime.now().strftime('%Y-%m-%d')

    if current_date not in config['logs']:
        config['logs'][current_date] = {}

    if model_name not in config['logs'][current_date]:
        config['logs'][current_date][model_name] = 0

    config['logs'][current_date][model_name] += 1
    store_quota(config)
    print(f"Logged session for {model_name}")

def verify_quota(model_name):
    """Verify remaining quota for a model"""
    config = fetch_quota()
    current_date = datetime.now().strftime('%Y-%m-%d')

    cap = config['caps'].get(model_name, -1)  # -1 indicates no restriction
    consumed = config['logs'].get(current_date, {}).get(model_name, 0)

    if cap == -1:
        return {'eligible': True, 'cap': 'unlimited', 'consumed': consumed}

    remaining = cap - consumed
    return {
        'eligible': remaining > 0,
        'cap': cap,
        'consumed': consumed,
        'remaining': remaining
    }

def retrieve_daily_logs():
    """Fetch all logged sessions for today"""
    config = fetch_quota()
    current_date = datetime.now().strftime('%Y-%m-%d')
    return config['logs'].get(current_date, {})

def cli_entry():
    """Command-line interface handler"""
    if len(sys.argv) < 2:
        print("Usage: session_quota.py [configure|log|verify|logs]")
        sys.exit(1)

    action = sys.argv[1]

    if action == 'configure':
        if len(sys.argv) < 4:
            print("Usage: session_quota.py configure <model> <max_sessions>")
            sys.exit(1)
        configure_limit(sys.argv[2], int(sys.argv[3]))
    elif action == 'log':
        if len(sys.argv) < 3:
            print("Usage: session_quota.py log <model>")
            sys.exit(1)
        log_activity(sys.argv[2])
    elif action == 'verify':
        if len(sys.argv) < 3:
            print("Usage: session_quota.py verify <model>")
            sys.exit(1)
        print(json.dumps(verify_quota(sys.argv[2]), indent=2))
    elif action == 'logs':
        print(json.dumps(retrieve_daily_logs(), indent=2))
    else:
        print(f"Unknown command: {action}")
        sys.exit(1)

if __name__ == '__main__':
    cli_entry()

# NATS callback function registry implementation
from django.conf import settings

class CallbackRegistry:
    """Registry for managing NATS callback functions"""
    def __init__(self):
        self._registry = {}

    def add(self, name=None, callback=None, **options):
        # Direct registration: add(callback, name, ...)
        if callback is not None:
            return self._register_callback(callback, name, **options)

        # Decorator without arguments: @add
        if name is not None and callback is None and callable(name):
            return self._register_callback(name, **options)

        # Decorator with arguments: @add(...)
        def decorator(callback):
            return self.add(name, callback, **options)
        return decorator

    def _register_callback(self, callback, name: str = None, **options):
        namespace = options.get('namespace', getattr(settings, 'NATS_NAMESPACE', 'default'))
        func_name = name or getattr(callback, '_decorated_function', callback).__name__
        jetstream = options.get('js', False)
        identifier = f'{namespace}.js.{func_name}' if jetstream else f'{namespace}.{func_name}'

        if identifier in self._registry:
            raise ValueError(f'Duplicate NATS callback key `{identifier}`.')

        self._registry[identifier] = {
            'callback': callback,
            'namespace': namespace,
            'function_name': func_name,
            'jetstream': jetstream,
        }
        return callback

global_registry = CallbackRegistry()
register = global_registry.add

# Generate a .opt configuration file for Gmsh to visualize mesh data fields
def generate_opt_visualization(mesh_file_path, field_parameters=None):
    """
    Generate a .opt file for visualizing mesh fields in Gmsh.

    Parameters
    ----------
    mesh_file_path : str
        Path to the .msh file (without .opt extension)
    field_parameters : dict, optional
        Dictionary containing field configuration:
        - 'fields': list of field names to display
        - 'max_values': dict mapping field names to their maximum values (optional)
        - 'field_type': str, either 'node' or 'element' (default: 'node')
    """
    if field_parameters is None:
        field_parameters = {}

    field_list = field_parameters.get("fields", [])
    value_limits = field_parameters.get("max_values", {})

    opt_text = """// Gmsh visualization settings for mesh fields
Mesh.SurfaceFaces = 0;
Mesh.SurfaceEdges = 0;
Mesh.Points = 0;
Mesh.Lines = 0;
"""

    for idx, field_name in enumerate(field_list):
        view_id = idx + 1
        upper_bound = value_limits.get(field_name, 1.0)

        opt_text += f"""// View[{view_id}] ({field_name})
View[{view_id}].Visible = 1;
View[{view_id}].ColormapNumber = {idx + 1};
View[{view_id}].RangeType = 2;
View[{view_id}].CustomMin = 0;
View[{view_id}].CustomMax = {upper_bound};
View[{view_id}].ShowScale = 1;
View[{view_id}].ColormapAlpha = 1;
View[{view_id}].ColormapAlphaPower = 0.08;
"""

    opt_text += "// Field information:\n"
    for idx, field_name in enumerate(field_list):
        upper_bound = value_limits.get(field_name, 1.0)
        opt_text += f"// View[{idx + 1}]: {field_name} (max: {upper_bound:.6f})\n"

    config_path = f"{mesh_file_path}.opt"
    with open(config_path, "w") as file:
        file.write(opt_text)

    return config_path

