# Context manager for managing request-specific context
from contextlib import contextmanager
from contextvars import ContextVar

REQUEST_CONTEXT = ContextVar("request_context", default=None)

def retrieve_request_context(key, fallback=None):
    current_ctx = REQUEST_CONTEXT.get()
    return current_ctx[key] if current_ctx and key in current_ctx else fallback

def modify_request_context(**kwargs):
    current_ctx = REQUEST_CONTEXT.get()
    if current_ctx is not None:
        current_ctx.update(kwargs)

@contextmanager
def establish_request_context(data):
    token = REQUEST_CONTEXT.set(data)
    try:
        yield
    finally:
        REQUEST_CONTEXT.reset(token)

# Calculate symbolic shapes of input tensors from model constraints
import sympy
from pathlib import Path
from graph_net.dynamic_dim_constraints import DynamicDimConstraints
import graph_net.graph_net_json_file_util as gn_json

class ExtractInputSymbolicShapes:
    def __init__(self, settings):
        self.settings = self.configure(**settings)

    def configure(self, model_directory_prefix, skip_reified=True):
        return {
            "model_directory_prefix": model_directory_prefix,
            "skip_reified": skip_reified,
        }

    def __call__(self, model_name):
        base_model_path = Path(self.settings["model_directory_prefix"]) / model_name
        constraint_file = base_model_path / "input_tensor_constraints.py"

        if not constraint_file.exists():
            print(f"extract-symbolic-shapes None {model_name}")
            return

        if self.settings["skip_reified"] and self._has_reified_dimensions(
            str(base_model_path)
        ):
            print(f"extract-symbolic-shapes <reified> {model_name}")
            return

        constraints = DynamicDimConstraints.unserialize_from_py_file(
            str(constraint_file)
        )

        for shape, tensor_name in constraints.input_shapes:
            if not any(isinstance(dim, sympy.Expr) for dim in shape):
                continue
            print(f"{shape=} {tensor_name=}")

        serialized_shapes = str(constraints.serialize_symbolic_input_shapes_to_str())
        print(f"extract-symbolic-shapes {serialized_shapes} {model_name}")

    def _has_reified_dimensions(self, model_dir):
        json_data = gn_json.read_json(model_dir)
        if gn_json.kSymbolicDimensionReifier not in json_data:
            return False
        return json_data[gn_json.kSymbolicDimensionReifier] is not None

# Abstract base class for file storage backends
from abc import ABCMeta, abstractmethod

class StorageInterface(metaclass=ABCMeta):
    """Abstract interface for file storage mechanisms.
    Each concrete implementation must provide two core methods: ``fetch()`` and ``fetch_text()``.
    ``fetch()`` retrieves data as raw bytes, while ``fetch_text()`` reads content as human-readable text.
    """

    @abstractmethod
    def fetch(self, path):
        pass

    @abstractmethod
    def fetch_text(self, path):
        pass


class CacheStorage(StorageInterface):
    """Memcached-based caching layer for file access.
    Attributes:
        config_servers (str): Path to configuration file containing server list.
        config_client (str): Path to client-specific configuration file.
        extra_path (str | None): Additional directory to append to Python's module search path.
            Defaults to None.
    """

    def __init__(self, config_servers, config_client, extra_path=None):
        if extra_path is not None:
            import sys
            sys.path.append(extra_path)
        try:
            import mc
        except ImportError:
            raise ImportError('Memcached library required. Please install memcached support.')
        self.config_servers = config_servers
        self.config_client = config_client
        self._cache_client = mc.MemcachedClient.GetInstance(self.config_servers, self.config_client)
        # pyvector serves as a buffer pointer for memory cache operations
        self._cache_buffer = mc.pyvector()

    def fetch(self, path):
        path = str(path)
        import mc
        self._cache_client.Get(path, self._cache_buffer)
        data = mc.ConvertBuffer(self._cache_buffer)
        return data

    def fetch_text(self, path):
        raise NotImplementedError("Text retrieval not supported by this backend.")


class LocalDiskStorage(StorageInterface):
    """Direct filesystem access using standard disk I/O."""

    def fetch(self, path):
        path = str(path)
        with open(path, 'rb') as file_handle:
            data = file_handle.read()
        return data

    def fetch_text(self, path):
        path = str(path)
        with open(path, 'r', encoding='utf-8') as file_handle:
            data = file_handle.read()
        return data


class LmdbStorage(StorageInterface):
    """LMDB (Lightning Memory-Mapped Database) storage backend.
    Args:
        database_paths (str | list[str]): One or more LMDB database file paths.
        instance_keys (str | list[str]): Identifiers for different LMDB instances. Default: 'default'.
        read_only (bool, optional): Open LMDB in read-only mode. Default: True.
        enable_locking (bool, optional): Enable concurrency control. Default: False.
        enable_prefetch (bool, optional): Disable OS readahead for improved random access. Default: False.
    Attributes:
        database_paths (list): List of LMDB database file paths.
        _instances (dict): Dictionary mapping keys to LMDB environment objects.
    """

    def __init__(self, database_paths, instance_keys='default', read_only=True, enable_locking=False, enable_prefetch=False, **options):
        try:
            import lmdb
        except ImportError:
            raise ImportError('LMDB library required. Please install lmdb package.')

        if isinstance(instance_keys, str):
            instance_keys = [instance_keys]

        if isinstance(database_paths, list):
            self.database_paths = [str(p) for p in database_paths]
        elif isinstance(database_paths, str):
            self.database_paths = [str(database_paths)]

        assert len(instance_keys) == len(self.database_paths), (
            f"Number of keys ({len(instance_keys)}) must match number of databases ({len(self.database_paths)})."
        )

        self._instances = {}
        for key, db_path in zip(instance_keys, self.database_paths):
            self._instances[key] = lmdb.open(
                db_path,
                readonly=read_only,
                lock=enable_locking,
                readahead=enable_prefetch,
                **options
            )

    def fetch(self, key, instance_key):
        """Retrieve binary data from specified LMDB instance.
        Args:
            key (str | Path): The lookup key within the LMDB database.
            instance_key (str): Identifier for the target LMDB environment.
        Returns:
            bytes: Raw byte data retrieved from the database.
        """
        key = str(key)
        assert instance_key in self._instances, (
            f"Requested instance '{instance_key}' not found among available instances."
        )

        env = self._instances[instance_key]
        with env.begin(write=False) as transaction:
            result = transaction.get(key.encode('ascii'))
        return result

    def fetch_text(self, path):
        raise NotImplementedError("Text retrieval not supported by this backend.")


class FileManager(object):
    """Unified file access manager supporting multiple storage backends.
    This class provides a consistent interface to retrieve files regardless of
    underlying storage mechanism. It supports dynamic registration of new backends.
    Attributes:
        storage_type (str): Type of storage backend being used. Options include "disk",
            "memcached", and "lmdb".
        accessor (:obj:`StorageInterface`): The active storage backend instance.
    """

    _registry = {
        'disk': LocalDiskStorage,
        'memcached': CacheStorage,
        'lmdb': LmdbStorage,
    }

    def __init__(self, storage_type='disk', **config):
        if storage_type not in self._registry:
            raise ValueError(
                f"Unsupported backend '{storage_type}'. Available options: {list(self._registry.keys())}"
            )

        self.storage_type = storage_type
        self.accessor = self._registry[storage_type](**config)

    def read(self, path, instance_key='default'):
        """Read file content using appropriate backend method.
        For LMDB backend, requires specifying the instance key.
        """
        if self.storage_type == 'lmdb':
            return self.accessor.fetch(path, instance_key)
        else:
            return self.accessor.fetch(path)

    def read_text(self, path):
        """Read file content as text using appropriate backend method."""
        return self.accessor.fetch_text(path)

