# Process and filter memory-related data entries
def clean_memory_records(memory_records):
    cleaned_data = {}
    for category, content in memory_records.items():
        if category == "text_mem":
            cleaned_data[category] = []
            for group in content:
                # Determine if using the updated format (list of MemoryEntry instances)
                if "memories" in group and isinstance(group["memories"], list):
                    # Updated format: list of MemoryEntry objects
                    processed_memories = []
                    for entry in group["memories"]:
                        # Build a sanitized dictionary representation
                        sanitized_entry = {
                            "id": entry.id,
                            "memory": entry.memory,
                            "metadata": {},
                        }
                        # Sanitize metadata, omitting embedding field
                        if hasattr(entry, "metadata") and entry.metadata:
                            for field_name in dir(entry.metadata):
                                if not field_name.startswith("_") and field_name != "embedding":
                                    field_value = getattr(entry.metadata, field_name)
                                    if not callable(field_value):
                                        sanitized_entry["metadata"][field_name] = field_value
                        processed_memories.append(sanitized_entry)
                    cleaned_group = {
                        "cube_id": group.get("cube_id", ""),
                        "memories": processed_memories,
                    }
                    cleaned_data[category].append(cleaned_group)
                else:
                    # Legacy format: dictionary containing nodes and edges
                    cleaned_group = {
                        "memories": {"nodes": [], "edges": group["memories"].get("edges", [])}
                    }
                    for node in group["memories"].get("nodes", []):
                        cleaned_node = {
                            "id": node.get("id"),
                            "memory": node.get("memory"),
                            "metadata": {
                                k: v
                                for k, v in node.get("metadata", {}).items()
                                if k != "embedding"
                            },
                        }
                        cleaned_group["memories"]["nodes"].append(cleaned_node)
                    cleaned_data[category].append(cleaned_group)
        else:
            cleaned_data[category] = content
    return cleaned_data

import json

def ApiError(msg: str):
    return "API Error: " + msg

def ProcessVolcResponse(api_response: dict):
    if not api_response:
        return ApiError("Empty response")

    parsed_response = api_response if not isinstance(api_response, str) else json.loads(api_response)
    error_info = parsed_response.get("ResponseMetadata", {}).get("Error")

    if error_info and isinstance(error_info, dict):
        error_message = error_info.get("Message", "Unknown error")
        return ApiError(error_message)

    return str(api_response)

