# Utility functions for handling model loading and data iteration
import os
import binascii
from safetensors import safe_open
import torch
from diffusers.pipelines.stable_diffusion.convert_from_ckpt import convert_ldm_unet_checkpoint, convert_ldm_vae_checkpoint

def generate_random_name(length=8, extension=''):
    # Generate a random hex string as filename component
    random_part = binascii.b2a_hex(os.urandom(length)).decode('utf-8')
    if extension:
        if not extension.startswith('.'):
            extension = '.' + extension
        random_part += extension
    return random_part

def iterate_forever(dataloader):
    while True:
        for batch in dataloader:
            yield batch

def check_exists(value):
    return value is not None

def pass_through(x):
    return x

def merge_lora_weights(unet_model, vae_model=None, checkpoint_path=None, blend_factor=1.0, base_model_path=""):
    # Return early if no checkpoint provided
    if checkpoint_path is None:
        return unet_model

    # Load checkpoint based on file extension
    if checkpoint_path.endswith(".ckpt"):
        raw_state_dict = torch.load(checkpoint_path)['state_dict']
    elif checkpoint_path.endswith(".safetensors"):
        loaded_state = {}
        with safe_open(checkpoint_path, framework="pt", device="cpu") as f:
            for tensor_key in f.keys():
                loaded_state[tensor_key] = f.get_tensor(tensor_key)

        # Determine if it's a LoRA checkpoint
        is_lora_format = all("lora" in key for key in loaded_state.keys())
        if not is_lora_format:
            raw_state_dict = loaded_state
        else:
            # For LoRA, need base model to interpolate
            raw_state_dict = {}
            with safe_open(base_model_path, framework="pt", device="cpu") as f:
                for base_key in f.keys():
                    raw_state_dict[base_key] = f.get_tensor(base_key)

    # Convert checkpoint to UNet format
    adapted_unet_dict = convert_ldm_unet_checkpoint(raw_state_dict, unet_model.config)
    current_unet_state = unet_model.state_dict()

    # Apply blending between loaded weights and current weights
    for param_name in adapted_unet_dict:
        adapted_unet_dict[param_name] = (blend_factor * adapted_unet_dict[param_name] + 
                                        (1.0 - blend_factor) * current_unet_state[param_name])

    # Load adapted weights into UNet
    unet_model.load_state_dict(adapted_unet_dict, strict=False)

    # Handle VAE if provided
    if vae_model is not None:
        adapted_vae_dict = convert_ldm_vae_checkpoint(raw_state_dict, vae_model.config)
        vae_model.load_state_dict(adapted_vae_dict)

    return unet_model, vae_model

