import csv
from pdd.path_resolution import get_default_resolver

def get_comment_syntax(lang: str) -> str:
    try:
        resolver = get_default_resolver()
        csv_path = resolver.resolve_data_file("data/language_format.csv")
    except ValueError:
        return "del"

    if not isinstance(lang, str):
        return "del"

    lang = lang.lower()

    try:
        with open(str(csv_path), mode="r", newline="") as file:
            reader = csv.DictReader(file)
            for record in reader:
                if record["language"].lower() == lang:
                    comment_syntax = record.get("comment", "")
                    return comment_syntax if comment_syntax else "del"
    except FileNotFoundError:
        return "del"
    except Exception:
        return "del"

    return "del"

