# Web API endpoints for event management
import logging
from flask import Blueprint, request, jsonify
from app.web import (
    require_auth,
    get_storage,
    _localize_timestamps,
)

logger = logging.getLogger("docsis.web")
events_api = Blueprint("events_api", __name__)

@events_api.route("/api/events", methods=["GET"])
@require_auth
def list_events():
    """Return list of events with optional filters."""
    storage = get_storage()
    if not storage:
        return jsonify({"events": [], "unacknowledged_count": 0})

    limit = request.args.get("limit", 200, type=int)
    offset = request.args.get("offset", 0, type=int)
    severity_filter = request.args.get("severity") or None
    type_filter = request.args.get("event_type") or None
    ack_param = request.args.get("acknowledged")
    acknowledged = int(ack_param) if ack_param is not None and ack_param != "" else None

    events = storage.get_events(
        limit=limit, offset=offset, severity=severity_filter,
        event_type=type_filter, acknowledged=acknowledged,
    )
    unack_count = storage.get_event_count(acknowledged=0)
    _localize_timestamps(events)
    return jsonify({"events": events, "unacknowledged_count": unack_count})

@events_api.route("/api/events/count", methods=["GET"])
@require_auth
def get_event_count():
    """Return unacknowledged event count (for badge)."""
    storage = get_storage()
    if not storage:
        return jsonify({"count": 0})
    return jsonify({"count": storage.get_event_count(acknowledged=0)})

@events_api.route("/api/events/<int:event_id>/acknowledge", methods=["POST"])
@require_auth
def acknowledge_single_event(event_id):
    """Acknowledge a single event."""
    storage = get_storage()
    if not storage:
        return jsonify({"error": "Storage not initialized"}), 500

    if not storage.acknowledge_event(event_id):
        return jsonify({"error": "Not found"}), 404
    return jsonify({"success": True})

@events_api.route("/api/events/acknowledge-all", methods=["POST"])
@require_auth
def acknowledge_all_events():
    """Acknowledge all unacknowledged events."""
    storage = get_storage()
    if not storage:
        return jsonify({"error": "Storage not initialized"}), 500

    processed_count = storage.acknowledge_all_events()
    return jsonify({"success": True, "count": processed_count})

# Import necessary libraries for OpenAI integration and JSON handling
import openai
import json

class FeedbackAnalyzer:
    def __init__(self, api_token):
        openai.api_key = api_token

    def analyze(self, user_comment):
        """
        Processes natural language feedback and transforms it into structured command data.
        """
        try:
            response = openai.chat.completions.create(
                model="gpt-4.1-mini",
                messages=[
                    {
                        "role": "system",
                        "content": "You are an expert in evaluating feedback for email composition. Your job is to translate natural language feedback into a structured JSON format. The input will be feedback about an email, and you must identify the main sentiment, the specific element under review (e.g., tone, length, call-to-action), and a recommended revision. Valid 'aspect' values include: 'tone', 'length', 'style', 'vocabulary', 'call_to_action', 'greeting', 'closing', 'clarity', 'urgency', 'personalization'. Valid 'sentiment' values are 'positive', 'negative', 'neutral'. The 'modification' field should contain a brief directive for an AI writer; if the feedback lacks specificity, use 'general_improvement'."
                    },
                    {
                        "role": "user",
                        "content": f"The provided feedback is: '{user_comment}'. Format this as a JSON object with keys 'sentiment', 'aspect', and 'modification'."
                    }
                ],
                response_format={"type": "json_object"}
            )
            return response.choices[0].message.content
        except Exception as error:
            print(f"Failed to process feedback: {error}")
            return json.dumps({"sentiment": "neutral", "aspect": "unknown", "modification": "general_improvement"})

import importlib.util
import json
import os
import warnings
from dataclasses import dataclass, field
import torch
from ..training_args import TrainingArguments
from ..utils import cached_property, is_sagemaker_dp_enabled, logging

logger = logging.get_logger(__name__)

# TODO: should be moved to `utils` after refactoring of SageMakerTrainer
def is_sagemaker_model_parallel_available():
    # Retrieve sagemaker-specific model parallel parameters from environment variable
    mp_config = os.getenv("SM_HP_MP_PARAMETERS", "{}")
    try:
        # Parse JSON and verify required 'partitions' field exists
        mp_config = json.loads(mp_config)
        if "partitions" not in mp_config:
            return False
    except json.JSONDecodeError:
        return False

    # Retrieve sagemaker-specific framework parameters
    framework_params = os.getenv("SM_FRAMEWORK_PARAMS", "{}")
    try:
        # Parse JSON and check for MPI enablement flag
        framework_params = json.loads(framework_params)
        if not framework_params.get("sagemaker_mpi_enabled", False):
            return False
    except json.JSONDecodeError:
        return False

    # Confirm availability of the smdistributed module
    return importlib.util.find_spec("smdistributed") is not None

if is_sagemaker_model_parallel_available():
    import smdistributed.modelparallel.torch as smp
    smp.init()

@dataclass
class SageMakerTrainingArguments(TrainingArguments):
    mp_parameters: str = field(
        default="",
        metadata={"help": "Used by the SageMaker launcher to send mp-specific args. Ignored in SageMakerTrainer"},
    )

    def __post_init__(self):
        super().__post_init__()
        warnings.warn(
            "`SageMakerTrainingArguments` is deprecated and will be removed in v5 of Transformers. You can use "
            "`TrainingArguments` instead.",
            FutureWarning,
        )

    @cached_property
    def _setup_devices(self) -> "torch.device":
        logger.info("PyTorch: setting up devices")

        # Check for existing distributed setup without local_rank set
        if torch.distributed.is_available() and torch.distributed.is_initialized() and self.local_rank == -1:
            logger.warning(
                "torch.distributed process group is initialized, but local_rank == -1. "
                "In order to use Torch DDP, launch your script with `python -m torch.distributed.launch"
            )

        # CPU-only mode
        if self.no_cuda:
            device = torch.device("cpu")
            self._n_gpu = 0

        # Model parallel mode
        elif is_sagemaker_model_parallel_available():
            local_rank = smp.local_rank()
            device = torch.device("cuda", local_rank)
            self._n_gpu = 1

        # Data parallel mode (SMDDP)
        elif is_sagemaker_dp_enabled():
            import smdistributed.dataparallel.torch.torch_smddp  # noqa: F401
            torch.distributed.init_process_group(backend="smddp", timeout=self.ddp_timeout_delta)
            self.local_rank = int(os.getenv("SMDATAPARALLEL_LOCAL_RANK"))
            device = torch.device("cuda", self.local_rank)
            self._n_gpu = 1

        # Single GPU or CPU fallback
        elif self.local_rank == -1:
            device = torch.device("cuda:0" if torch.cuda.is_available() else "cpu")
            self._n_gpu = torch.cuda.device_count()

        # Distributed training with DDP
        else:
            if not torch.distributed.is_initialized():
                torch.distributed.init_process_group(backend="nccl", timeout=self.ddp_timeout_delta)
            device = torch.device("cuda", self.local_rank)
            self._n_gpu = 1

        # Set current CUDA device if using GPU
        if device.type == "cuda":
            torch.cuda.set_device(device)

        return device

    @property
    def world_size(self):
        if is_sagemaker_model_parallel_available():
            return smp.dp_size()
        return super().world_size

    @property
    def place_model_on_device(self):
        return not is_sagemaker_model_parallel_available()

    @property
    def _no_sync_in_gradient_accumulation(self):
        return False

