# OAuth scopes for accessing Gmail, Calendar, and Drive services
SCOPES = [
    'https://www.googleapis.com/auth/gmail.readonly',
    'https://www.googleapis.com/auth/gmail.send',
    'https://www.googleapis.com/auth/gmail.modify',
    'https://www.googleapis.com/auth/calendar',
    'https://www.googleapis.com/auth/drive',
]

TOKEN_FILE = Path(__file__).parent / 'google_suite_tokens.json'
CLIENT_SECRETS_FILE = Path(__file__).parent / 'google_suite_credentials.json'


def get_skill_metadata():
    return {
        "identifier": "google-suite",
        "label": "Google Suite Skill",
        "categories": ["google", "gmail", "calendar", "drive", "api", "automation"],
        "summary": "Unified access to Gmail, Google Calendar, and Google Drive APIs."
    }


def obtain_credentials() -> Credentials:
    credentials = None
    if TOKEN_FILE.exists():
        credentials = Credentials.from_authorized_user_file(str(TOKEN_FILE), SCOPES)

    # If no valid credentials exist, initiate the OAuth flow
    if not credentials or not credentials.valid:
        if credentials and credentials.expired and credentials.refresh_token:
            credentials.refresh(Request())
        else:
            oauth_flow = InstalledAppFlow.from_client_config(
                {
                    "installed": {
                        "client_id": os.environ.get("GOOGLE_OAUTH_CLIENT_ID"),
                        "client_secret": os.environ.get("GOOGLE_OAUTH_CLIENT_SECRET"),
                        "redirect_uris": [os.environ.get("GOOGLE_OAUTH_REDIRECT_URI")],
                        "auth_uri": "https://accounts.google.com/o/oauth2/auth",
                        "token_uri": "https://oauth2.googleapis.com/token"
                    }
                },
                SCOPES
            )
            credentials = oauth_flow.run_local_server(port=0)

        # Persist credentials for future use
        with open(TOKEN_FILE, 'w') as token_file:
            token_file.write(credentials.to_json())

    return credentials


class GoogleSuiteIntegration:
    def __init__(self):
        self.auth = obtain_credentials()

    def perform_operation(self, config: Dict[str, Any]) -> Any:
        service_name = config.get("service")
        operation_type = config.get("action")

        if service_name == "gmail":
            return self._process_gmail(operation_type, config)
        elif service_name == "calendar":
            return self._process_calendar(operation_type, config)
        elif service_name == "drive":
            return self._process_drive(operation_type, config)
        else:
            raise ValueError(f"Unsupported service: {service_name}")

    # Gmail-specific operations
    def _process_gmail(self, operation, config):
        gmail_service = build('gmail', 'v1', credentials=self.auth)

        if operation == "send":
            return self._send_email(gmail_service, config)
        elif operation == "list":
            return self._list_emails(gmail_service, config)
        elif operation == "delete":
            return self._remove_email(gmail_service, config)
        else:
            raise ValueError(f"Invalid Gmail operation: {operation}")

    def _send_email(self, gmail_service, config):
        from email.mime.text import MIMEText
        import base64

        email_body = config.get("body", "")
        recipient = config.get("to")
        subject = config.get("subject", "")

        message = MIMEText(email_body)
        message['to'] = recipient
        message['subject'] = subject
        encoded_message = base64.urlsafe_b64encode(message.as_bytes()).decode()

        request_body = {'raw': encoded_message}
        response = gmail_service.users().messages().send(userId="me", body=request_body).execute()
        return {"message_id": response.get("id"), "result": "sent"}

    def _list_emails(self, gmail_service, config):
        search_query = config.get("query", "in:inbox")
        limit = int(config.get("max_results", 10))

        results = gmail_service.users().messages().list(
            userId="me", 
            q=search_query, 
            maxResults=limit
        ).execute()

        message_list = results.get('messages', [])
        emails = []

        for msg in message_list:
            details = gmail_service.users().messages().get(userId="me", id=msg['id']).execute()
            preview = details.get('snippet', '')
            emails.append({"id": msg['id'], "preview": preview})

        return emails

    def _remove_email(self, gmail_service, config):
        message_identifier = config.get("message_id")
        if not message_identifier:
            raise ValueError("message_id is required for deletion")

        gmail_service.users().messages().delete(userId="me", id=message_identifier).execute()
        return {"message_id": message_identifier, "result": "deleted"}

    # Calendar-specific operations
    def _process_calendar(self, operation, config):
        calendar_service = build('calendar', 'v3', credentials=self.auth)

        if operation == "list":
            return self._list_events(calendar_service, config)
        elif operation == "create":
            return self._schedule_event(calendar_service, config)
        elif operation == "update":
            return self._modify_event(calendar_service, config)
        elif operation == "delete":
            return self._cancel_event(calendar_service, config)
        else:
            raise ValueError(f"Invalid Calendar operation: {operation}")

    def _list_events(self, calendar_service, config):
        from datetime import datetime, timedelta

        current_time = datetime.utcnow().isoformat() + 'Z'
        days_to_include = int(config.get("days", 7))
        end_time = (datetime.utcnow() + timedelta(days=days_to_include)).isoformat() + 'Z'

        events_response = calendar_service.events().list(
            calendarId='primary', 
            timeMin=current_time, 
            timeMax=end_time,
            maxResults=int(config.get("max_events", 10)), 
            singleEvents=True,
            orderBy='startTime'
        ).execute()

        events = events_response.get('items', [])
        return [
            {
                "id": e["id"], 
                "title": e.get("summary"), 
                "start_time": e["start"], 
                "end_time": e["end"]
            } 
            for e in events
        ]

    def _schedule_event(self, calendar_service, config):
        new_event = {
            'summary': config.get('summary'),
            'start': {'dateTime': config.get('start')},
            'end': {'dateTime': config.get('end')},
        }

        created_event = calendar_service.events().insert(
            calendarId='primary', 
            body=new_event
        ).execute()

        return {"event_id": created_event["id"], "result": "created"}

    def _modify_event(self, calendar_service, config):
        event_identifier = config.get('event_id')
        if not event_identifier:
            raise ValueError("event_id is required for update operation")

        event = calendar_service.events().get(
            calendarId='primary', 
            eventId=event_identifier
        ).execute()

        if 'summary' in config:
            event['summary'] = config['summary']
        if 'start' in config:
            event['start']['dateTime'] = config['start']
        if 'end' in config:
            event['end']['dateTime'] = config['end']

        updated_event = calendar_service.events().update(
            calendarId='primary', 
            eventId=event_identifier, 
            body=event
        ).execute()

        return {"event_id": updated_event["id"], "result": "updated"}

    def _cancel_event(self, calendar_service, config):
        event_identifier = config.get('event_id')
        if not event_identifier:
            raise ValueError("event_id is required for deletion")

        calendar_service.events().delete(
            calendarId='primary', 
            eventId=event_identifier
        ).execute()

        return {"event_id": event_identifier, "result": "deleted"}

    # Drive-specific operations
    def _process_drive(self, operation, config):
        drive_service = build('drive', 'v3', credentials=self.auth)

        if operation == "list":
            return self._list_files(drive_service, config)
        elif operation == "upload":
            return self._upload_file(drive_service, config)
        elif operation == "download":
            return self._retrieve_file(drive_service, config)
        elif operation == "delete":
            return self._erase_file(drive_service, config)
        else:
            raise ValueError(f"Invalid Drive operation: {operation}")

    def _list_files(self, drive_service, config):
        search_criteria = config.get("query", "")
        file_limit = int(config.get("max_files", 10))

        results = drive_service.files().list(
            q=search_criteria, 
            pageSize=file_limit, 
            fields="files(id, name)"
        ).execute()

        file_list = results.get('files', [])
        return [{"id": f["id"], "name": f["name"]} for f in file_list]

    def _upload_file(self, drive_service, config):
        from googleapiclient.http import MediaFileUpload

        source_path = config.get("file_path")
        if not source_path or not os.path.exists(source_path):
            raise ValueError("file_path must be provided and point to an existing file")

        file_info = {'name': os.path.basename(source_path)}
        file_media = MediaFileUpload(source_path, resumable=True)

        uploaded_file = drive_service.files().create(
            body=file_info, 
            media_body=file_media, 
            fields='id'
        ).execute()

        return {"file_id": uploaded_file["id"], "result": "uploaded"}

