    client_details = get_connected_clients_info()

    return success_response(data=client_details)

@websocket_api.route('/broadcast', methods=['POST'])
@require_auth()
def send_system_alert():
    """Send a system-wide alert to all connected WebSocket clients (admin only)."""
    payload = request.get_json()
    alert_message = payload.get('message', '')
    alert_category = payload.get('alert_type', 'system')
    urgency_level = payload.get('severity', 'info')

    if not alert_message:
        return error_response('Message content is mandatory', 400)

    emit_system_alert(alert_category, alert_message, urgency_level)

    operator = g.current_user.username if hasattr(g, 'current_user') else 'unknown'

    return success_response(data={
        'confirmation': 'Alert dispatched',
        'metadata': {
            'category': alert_category,
            'urgency': urgency_level,
            'operator': operator
        }
    })

