# Custom hook implementation for runtest in DistributedTest class
# This hook executes before the standard pytest_runtest_call
@pytest.hookimpl(tryfirst=True)
def pytest_runtest_call(item):
    # Check if the test item belongs to a distributed test class
    if getattr(item.cls, "is_dist_test", False):
        dist_test_instance = item.cls()
        dist_test_instance(item._request)
        item.runtest = lambda: True  # Replace with dummy function to prevent double execution

# Teardown logic to clean up distributed environments after tests
# Specifically handles reuse of distributed environments and ensures cleanup when last test runs
def pytest_runtest_teardown(item, nextitem):
    if getattr(item.cls, "reuse_dist_env", False) and not nextitem:
        dist_test_instance = item.cls()
        for num_procs, pool in dist_test_instance._pool_cache.items():
            dist_test_instance._close_pool(pool, num_procs, force=True)

