# Document management routes for assistants and threads
import os
import tempfile
from flask import Blueprint, jsonify, request
from backboard import (
    BackboardAPIError,
    BackboardNotFoundError,
    BackboardValidationError,
)
from ..services.backboard import BackboardService

doc_bp = Blueprint("documents", __name__)

def get_backboard_service() -> BackboardService:
    """Retrieve a BackboardService instance."""
    return BackboardService()

# Supported file extensions for upload
SUPPORTED_EXTENSIONS = {
    "pdf",
    "docx",
    "xlsx",
    "pptx",
    "doc",
    "xls",
    "ppt",
    "txt",
    "csv",
    "md",
    "markdown",
    "py",
    "js",
    "html",
    "css",
    "xml",
    "json",
    "jsonl",
}

def is_valid_extension(filename: str) -> bool:
    """Determine if the file extension is permitted."""
    return "." in filename and filename.rsplit(".", 1)[1].lower() in SUPPORTED_EXTENSIONS

@doc_bp.route("/assistants/<assistant_id>/documents", methods=["POST"])
def upload_doc_to_assistant(assistant_id: str):
    """Handle document upload for a specific assistant."""
    try:
        if "file" not in request.files:
            return jsonify({"error": "No file provided"}), 400

        uploaded_file = request.files["file"]
        if uploaded_file.filename == "":
            return jsonify({"error": "No file selected"}), 400

        if not is_valid_extension(uploaded_file.filename):
            return jsonify({"error": "File type not allowed"}), 400

        # Save to temporary file and upload
        with tempfile.NamedTemporaryFile(
            delete=False, suffix=os.path.splitext(uploaded_file.filename)[1]
        ) as temp_file:
            uploaded_file.save(temp_file.name)
            service = get_backboard_service()
            result = service.upload_document_to_assistant(assistant_id, temp_file.name)
            os.unlink(temp_file.name)

        return jsonify(result), 201

    except BackboardNotFoundError:
        return jsonify({"error": "Not found", "detail": "Assistant not found"}), 404
    except BackboardValidationError as e:
        return jsonify({"error": "Validation error", "detail": str(e)}), 400
    except BackboardAPIError as e:
        return jsonify({"error": "API error", "detail": str(e)}), 500

