# Delta detection module for monitoring frame changes

import numpy as np
import gobject
import gtk.gdk

class MotionSensor(object):
    def __init__(self, enabled=False, sensitivity=20.0):
        self._last_image = None
        self._current_image = None
        self.enabled = enabled
        self.sensitivity = sensitivity
        self._cooldown_active = False

    def process_frame(self, image_data):
        self._last_image = self._current_image
        self._current_image = np.array(image_data, dtype=float)

        if self._cooldown_active:
            return
        if not self.enabled:
            return
        if self._last_image is None:
            return
        if self._last_image.shape != self._current_image.shape:
            self._last_image = None
            return

        if np.max(np.abs(self._current_image - self._last_image)) > self.sensitivity:
            gtk.gdk.beep()

            # Prevent repeated beeping within one second
            self._cooldown_active = True
            gobject.timeout_add(1000, self._reset_cooldown)

    def _reset_cooldown(self):
        self._cooldown_active = False
        return False

    # Property accessors
    @property
    def enabled(self):
        return self._enabled

    @enabled.setter
    def enabled(self, status):
        self._enabled = bool(status)

    @property
    def sensitivity(self):
        return self._sensitivity

    @sensitivity.setter
    def sensitivity(self, level):
        self._sensitivity = float(level)

    @property
    def mean_difference(self):
        if self._current_image is None or self._last_image is None:
            return 0.0
        return np.mean(self._current_image - self._last_image)

