        Column('updated', DateTime, server_default=text('current_timestamp'), server_onupdate=text('current_timestamp')),
    )

    _resource_field = __table__.c.resource

    @hybrid_property
    def resource(self):
        if isinstance(self, Domain):
            return self._resource_field.encode('ascii').decode('idna')
        return self._resource_field

    @resource.setter
    def resource(self, value):
        if isinstance(value, text_type):
            # Convert IDNA-encoded Unicode to UTF-8 encoded bytes, then decode back to lowercase string
            self._resource_field = value.encode('idna').decode('utf-8').lower()
        elif isinstance(value, binary_type):
            self._resource_field = value
        else:
            raise ValueError("Unable to store value as requested.")

    @resource.comparator
    def resource(cls):
        return IdnaComparator(cls._resource_field)

import numpy as np

def load_point_cloud_from_ply(file_path):
    with open(file_path, 'r') as file:
        point_list = []
        skip_header = False

        for line in file:
            if skip_header:
                coords = line.strip().split()
                if len(coords) >= 3:
                    point_list.append(np.float32(coords[:3]))
            else:
                skip_header = 'end_header' in line

    return point_list

def load_point_assignments_from_file(file_path):
    with open(file_path, 'r') as file:
        assignments = []

        for line in file:
            stripped_line = line.strip()
            if stripped_line and not stripped_line.startswith('#'):
                parts = stripped_line.split(',')
                if len(parts) >= 2:
                    try:
                        assignments.append(np.int16([parts[0], parts[1]]))
                    except ValueError:
                        continue

    return assignments

def load_primitive_correspondences(file_path, primitives_set_1, primitives_set_2):
    correspondences = {}
    uid_correspondences = {}

    with open(file_path, 'r') as file:
        for line in file:
            stripped_line = line.strip()
            if stripped_line and not stripped_line.startswith('#'):
                try:
                    values = list(map(int, stripped_line.split(',')))[:6]

                    prim1 = None
                    prim2 = None

                    for p in primitives_set_1:
                        if p.uid == values[0] and p.did == values[2]:
                            prim1 = p
                            break

                    for p in primitives_set_2:
                        if p.uid == values[3] and p.did == values[5]:
                            prim2 = p
                            break

                    if prim1 is not None and prim2 is not None:
                        correspondences[prim1] = prim2
                        uid_correspondences[prim1.uid] = prim2.uid
                    # else: Removed print statement to avoid side effects

                except (ValueError, IndexError):
                    continue

    return correspondences, uid_correspondences

import typing as tp
import builtins as py
from .optional import Optional, optional

K = tp.TypeVar('K')
V = tp.TypeVar('V')

class Dictionary(tp.Generic[K, V], tp.Iterable[tp.Tuple[K, V]]):
    def __init__(self, entries: tp.Dict[K, V]) -> None:
        self._data: tp.Dict[K, V] = py.dict(entries)

    def __getitem__(self, key: K) -> Optional[V]:
        return optional(self._data.get(key))

    def __setitem__(self, key: K, value: V) -> None:
        self._data[key] = value

    @property
    def keys(self) -> tp.Iterable[K]:
        return self._data.keys()

    @property
    def values(self) -> tp.Iterable[V]:
        return self._data.values()

    def for_each(self, body: tp.Callable[[K, V], None]) -> None:
        for k, v in self._data.items():
            body(k, v)

    @property
    def count(self) -> int:
        return len(self._data)

    def remove_all(self) -> None:
        self._data.clear()

    def __iter__(self) -> tp.Iterator[tp.Tuple[K, V]]:
        return iter(self._data.items())

# Collect all pipeline and schema information

from typing import Iterator, Dict
from lib.constants import SRC
from lib.pipeline import DataPipeline

def list_pipeline_names() -> Iterator[str]:
    """ Generator yielding names of all available data pipelines """
    for candidate in (SRC / "pipelines").iterdir():
        if not candidate.name.startswith("_") and candidate.is_dir():
            yield candidate.name

def list_table_names() -> Iterator[str]:
    """ Generator yielding table names derived from pipeline names """
    for pipeline_name in list_pipeline_names():
        yield pipeline_name.replace("_", "-")

def load_pipelines() -> Iterator[DataPipeline]:
    """ Generator yielding loaded DataPipeline instances """
    for pipeline_name in list_pipeline_names():
        yield DataPipeline.load(pipeline_name)

def build_schema() -> Dict[str, type]:
    """ Aggregate schema from all pipelines into a single dictionary """
    combined_schema: Dict[str, type] = {}
    for pipeline in load_pipelines():
        combined_schema.update(pipeline.schema)
    return combined_schema

