import random
from contextlib import contextmanager
from time import time, sleep
from locust import User, task, constant, events

# Custom context manager for manual performance reporting
class ManualReporting:
    def __init__(self, name):
        self.name = name
        self.start_time = None

    def __enter__(self):
        self.start_time = time()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        elapsed_time = (time() - self.start_time) * 1000
        if exc_type is not None:
            events.request_failure.fire(
                request_type="manual",
                name=self.name,
                response_time=elapsed_time,
                response_length=0,
                exception=exc_val,
            )
        else:
            events.request_success.fire(
                request_type="manual",
                name=self.name,
                response_time=elapsed_time,
                response_length=0,
            )
        return False  # Re-raise exceptions

# Decorator function for manual reporting
def auto_report(func=None, *, name=None):
    def decorator(fn):
        def wrapper(*args, **kwargs):
            with ManualReporting(name or fn.__name__):
                return fn(*args, **kwargs)
        return wrapper

    if func is not None:
        return decorator(func)
    return decorator

class PerformanceTestUser(User):
    wait_time = constant(1)

    @task
    def normal_operation(self):
        with ManualReporting("normal_operation"):
            sleep(random.random())

    @task
    @auto_report
    def decorated_scenario(self):
        if random.random() > 0.5:
            raise Exception("decorated_scenario failed")
        sleep(random.random())

    @task
    def error_scenario(self):
        with ManualReporting("error_scenario"):
            sleep(random.random())
            raise Exception("Simulated failure occurred!")

