def rotFreshNeighbours(x, y: int, grid: List[List[int]]) -> bool:
    # Check adjacent cells (up, down, left, right) for fresh oranges
    affected = False
    directions = [[1, 0], [-1, 0], [0, 1], [0, -1]]

    for dx, dy in directions:
        nx, ny = x + dx, y + dy

        # Skip if out of bounds
        if nx < 0 or nx >= len(grid):
            continue
        if ny < 0 or ny >= len(grid[0]):
            continue

        # Convert fresh orange to rotten
        if grid[nx][ny] == 1:
            grid[nx][ny] = 2
            affected = True

    return affected

# Handle notification system with fallback support

import sys

def _import_notify():
    try:
        import gi
        gi.require_version('Notify', '0.7')
        from gi.repository import Notify
        return Notify, None
    except (ImportError, AttributeError, ValueError):
        try:
            from scudcloud import notify2
            return None, notify2
        except ImportError:
            return None, None

class Notifier(object):
    def __init__(self, application_name, default_icon):
        self.default_icon = default_icon
        self.enabled = True

        # Try to initialize notification system
        try:
            notify_lib, fallback_lib = _import_notify()

            if notify_lib is not None:
                notify_lib.init(application_name)
                self.backend = notify_lib
                self.use_gi = True
            elif fallback_lib is not None:
                fallback_lib.init(application_name)
                self.backend = fallback_lib
                self.use_gi = False
            else:
                raise ImportError("No notification library available")

        except Exception as e:
            print("WARNING: No notification daemon found! "
                  "Notifications will be ignored.")
            self.enabled = False

    def send(self, title, content, icon_path=None):
        if not self.enabled:
            return

        # Use provided icon or fall back to default
        display_icon = icon_path if icon_path is not None else self.default_icon

        # Create notification based on available backend
        if self.use_gi:
            notification = self.backend.Notification.new(title, content, display_icon)
        else:
            notification = self.backend.Notification(title, content, display_icon)

        # Add hint for canonical append behavior
        notification.set_hint_string('x-canonical-append', '')

        # Attempt to display notification
        try:
            notification.show()
        except:
            # Silently ignore any errors during notification display
            pass

# Custom UTC datetime class with formatted string representations

from datetime import datetime
from .utc_timezone import UTC

# Format strings for ISO 8601 representation
ISO_FORMAT_BASIC = '%Y-%m-%dT%H:%M:%SZ'
ISO_FORMAT_PRECISE = '%Y-%m-%dT%H:%M:%S.%fZ'

class utcdatetime(object):
    def __init__(self, year, month, day, hour=0, minute=0, second=0,
                 microsecond=0):
        # Initialize the underlying datetime object with UTC timezone
        self.__dt = datetime(year, month, day, hour, minute, second,
                             microsecond, tzinfo=UTC)

    def __str__(self):
        # Return formatted string based on whether microseconds are present
        if self.__dt.microsecond != 0:
            return self.__dt.strftime(ISO_FORMAT_PRECISE)
        else:
            return self.__dt.strftime(ISO_FORMAT_BASIC)

    def __repr__(self):
        # Build constructor arguments list conditionally
        args = [self.__dt.year, self.__dt.month, self.__dt.day,
                self.__dt.hour, self.__dt.minute]

        # Add seconds only if non-zero
        if self.__dt.second != 0:
            args.append(self.__dt.second)
        # Add microseconds only if non-zero
        if self.__dt.microsecond != 0:
            args.append(self.__dt.microsecond)

        # Format as constructor call string
        return 'utcdatetime({0})'.format(', '.join(
            [str(value) for value in args]))

