        for field_name in ['tender', 'awards', 'contracts']:
            model_class = getattr(Release, field_name).model_class

            if field_name in current_tender:
                # Use fromDiff to compare previous and current values
                previous_value = previous_tender.get(field_name, '')
                current_value = current_tender.get(field_name, '')
                release_data[field_name] = model_class.fromDiff(previous_value, current_value)
            elif field_name == 'tender':
                # Special case for 'tender' field when not present in current
                release_data[field_name] = model_class.fromDiff(previous_tender, current_tender)

        # Yield a new Release object with the collected data
        yield Release(release_data)

        # Update previous_tender for next iteration
        previous_tender = current_tender

def package_all_tenders(tender_list, parameters):
    """Constructs a ReleasePackage from a list of tenders and parameter metadata."""
    package_data = {}

    # Populate package fields from parameters where applicable
    for field in ReleasePackage._fields:
        if field in parameters:
            package_data[field] = parameters.get(field, '')

    # Generate releases for each tender using the prefix from parameters
    prefix = parameters.get('prefix', '')
    package_data['releases'] = [
        create_release_from_tender(tender, prefix) 
        for tender in tender_list
    ]

    # Serialize and return the ReleasePackage
    return ReleasePackage(package_data).serialize()

