from openerp import models, fields, api

class ResPartner(models.Model):
    _inherit = ['res.partner']

    mobile_clean = fields.Char(compute='_normalize_mobile', store=True)

    @api.multi
    @api.depends('mobile', 'phone')
    def _normalize_mobile(self):
        valid_digits = '+0123456789'

        for partner in self:
            # Use phone as fallback if mobile is empty
            if not partner.mobile:
                partner.mobile = partner.phone or ''

            # Extract only allowed characters
            raw_number = ''.join(ch for ch in (partner.mobile or '') if ch in valid_digits)

            # Normalize to international format
            normalized = raw_number
            if normalized and normalized[0] != '+':
                if normalized.startswith('00') and len(normalized) >= 2:
                    normalized = '+' + normalized[2:]
                else:
                    # Default country code - can be enhanced with partner's country
                    normalized = '+45' + normalized

            # Validate final format: only '+' at start, max length 18
            has_extra_plus = any(c == '+' for c in normalized[1:])
            too_long = len(normalized) > 18

            partner.mobile_clean = False if (has_extra_plus or too_long) else normalized

