import asyncio
import collections
import time

class FailSafeConnection:
    """Disconnect automatically if too many failures occur within a specific time window."""

    class ConnectionLost(Exception):
        pass

    def __init__(self, *, max_failures, time_window, timer_source=None):
        self.failure_times = collections.deque(maxlen=max_failures)
        self.time_window = time_window
        self.timer_source = timer_source or time.monotonic

    @property
    def is_active(self):
        if len(self.failure_times) < self.failure_times.maxlen:
            return True
        if self.failure_times[0] + self.time_window < self.timer_source():
            return True
        return False

    def record_failure(self, exception_class=ConnectionLost):
        self.failure_times.append(self.timer_source())
        if self.is_active:
            return True
        elif exception_class:
            raise exception_class()
        else:
            return False

async def delayed_action(duration, *, error_type=asyncio.TimeoutError, event_loop=None):
    """Pause execution for specified duration. If duration is None or non-positive, wait indefinitely."""
    if duration is None or duration <= 0:
        await asyncio.Event(loop=event_loop).wait()  # Indefinite wait
    else:
        await asyncio.sleep(duration, loop=event_loop)
        if error_type:
            raise error_type()

