import warnings
from distutils.version import LooseVersion as V

def verify_zmq_requirements(required_version, package_name='IPython.zmq'):
    try:
        import zmq
    except ImportError:
        raise ImportError(f"{package_name} requires pyzmq >= {required_version}")

    installed_version = zmq.__version__

    # Check version if not a development version
    if 'dev' not in installed_version and V(installed_version) < V(required_version):
        raise ImportError(
            f"{package_name} requires pyzmq >= {required_version}, "
            f"but you have {installed_version}"
        )

    # Add missing constants for older pyzmq versions
    if not hasattr(zmq, 'DEALER'):
        zmq.DEALER = zmq.XREQ
    if not hasattr(zmq, 'ROUTER'):
        zmq.ROUTER = zmq.XREP

    # Warn about libzmq 4.x compatibility issues
    if V(zmq.zmq_version()) >= V('4.0.0'):
        warnings.warn(
            "libzmq 4 detected.\n"
            "It is unlikely that IPython's zmq code will work properly.\n"
            "Please install libzmq stable, which is 2.1.x or 2.2.x",
            RuntimeWarning
        )

