from i3pystatus import IntervalModule
from subprocess import check_output, CalledProcessError

class ShellCommand(IntervalModule):
    """
    Displays the result of executing a shell command
    """
    text_color = "#FFFFFF"
    failure_color = "#FF0000"

    config_options = (
        ("command", "shell command to execute"),
        ("text_color", "default display color"),
        ("failure_color", "color used when command fails")
    )

    mandatory = ("command",)

    def update(self):
        try:
            result = check_output(self.command, shell=True)
            display_color = self.text_color
        except CalledProcessError as error:
            result = error.output
            display_color = self.failure_color

        # Convert bytes to string and normalize whitespace
        output_text = result.decode("UTF-8").replace("\n", " ")

        # Remove trailing space if present
        try:
            if output_text and output_text[-1] == " ":
                output_text = output_text[:-1]
        except Exception:
            output_text = ""

        self.status = {
            "full_text": output_text,
            "color": display_color
        }

