# Tokenize source code using Pygments library

import pygments
import pygments.lexers

class CodeTokenizer:
    def __init__(self, application):
        self.application = application

    def tokenize(self, source_code, lexer=None):
        """Process source code and return tokenized representation.

        Returns a list of tuples (category, text_segment) where text_segment
        is a piece of the original code and category indicates its syntactic role.
        :param str source_code: Source code to analyze.
        :param lexer: Lexer instance to apply for tokenization.
        :return: List of categorized tokens.
        """
        if lexer is None:
            if not isinstance(source_code, str):
                # Convert bytes to string if needed
                source_code = source_code.decode("utf-8")
            return [("default", source_code),]

        tokens = pygments.lex(source_code, lexer)
        categorized_tokens = []

        for token_type, token_value in tokens:
            category = "default"

            if token_type in pygments.token.Keyword:
                category = "keyword"
            elif token_type == pygments.token.Comment:
                category = "comment"
            elif token_type in pygments.token.Literal.String:
                category = "string_literal"
            elif token_type in pygments.token.Literal.Number:
                category = "numeric_literal"
            elif token_type == pygments.token.Name.Function:
                category = "function_identifier"
            elif token_type == pygments.token.Name.Class:
                category = "class_identifier"
            elif token_type == pygments.token.Operator:
                category = "operator"
            elif token_type == pygments.token.Name.Builtin.Pseudo:
                category = "language_constant"

            categorized_tokens.append((category, token_value))

        return categorized_tokens

