import logging
import sys
from modularodm import Q
from framework.mongo import database
from framework.transactions.context import TokuTransaction
from website.app import init_app
from scripts import utils as script_utils

logger = logging.getLogger(__name__)
DATA_SOURCES = ['mendeley', 'zotero']

def update_document_field(doc, source):
    try:
        collection_name = '{}nodesettings'.format(source)

        # First, set the new field using the old one's value
        database[collection_name].find_one_and_update(
            {'_id': doc['_id']},
            {'$set': {'list_id': doc['{}_list_id'.format(source)]}}
        )

        # Then, remove the old field
        database[collection_name].find_one_and_update(
            {'_id': doc['_id']},
            {'$unset': {'{}_list_id'.format(source): ''}}
        )
    except Exception:
        return False
    return True

def validate_document(doc, source):
    try:
        assert '_id' in doc
        assert '{}_list_id'.format(source) in doc
    except AssertionError:
        return False
    return True

def run_migration(dry_run=True):
    migration_results = {
        'success': {},
        'missing_field': {},
        'failed': {}
    }

    for source in DATA_SOURCES:
        migration_results['success'][source] = []
        migration_results['missing_field'][source] = []
        migration_results['failed'][source] = []

        collection = database['{}nodesettings'.format(source)]
        for doc in collection.find():
            if validate_document(doc, source):
                if update_document_field(doc, source):
                    migration_results['success'][source].append(doc)
                else:
                    migration_results['failed'][source].append(doc)
            else:
                migration_results['missing_field'][source].append(doc)

    for source in DATA_SOURCES:
        if migration_results['success'][source]:
            logger.info('Successfully migrated {0} {1} node settings documents:\n{2}'.format(
                len(migration_results['success'][source]), source,
                [item['_id'] for item in migration_results['success'][source]]
            ))
        if migration_results['missing_field'][source]:
            logger.error('Failed to migrate {0} {1} node settings documents due to missing {1}_list_id field:\n{2}'.format(
                len(migration_results['missing_field'][source]), source,
                [item['_id'] for item in migration_results['missing_field'][source]]
            ))
        if migration_results['failed'][source]:
            logger.error('Failed to migrate {0} {1} node settings documents for unknown reason:\n{2}'.format(
                len(migration_results['failed'][source]), source,
                [item['_id'] for item in migration_results['failed'][source]]
            ))

    if dry_run:
        raise RuntimeError('Dry run, transaction rolled back.')

def execute():
    dry_run_mode = False
    if '--dry' in sys.argv:
        dry_run_mode = True

    if not dry_run_mode:
        script_utils.add_file_logger(logger, __file__)

    init_app(set_backends=True, routes=False)

    with TokuTransaction():
        run_migration(dry_run=dry_run_mode)

if __name__ == "__main__":
    execute()

