# Sanitize and convert numpy types safely

import math

try:
    import numpy as np
except ImportError:
    np = None

def clean_value(val):
    # Handle NaN values first
    if val is not None and (isinstance(val, float) or (np and isinstance(val, (float, np.floating)))):
        if math.isnan(val) or (np and np.isnan(val)):
            return None

    # Return None directly for None input
    if val is None:
        return None

    # Handle basic numeric types
    if isinstance(val, (int, float, complex)):
        return val

    # Handle numpy scalar types
    if np:
        if isinstance(val, np.integer):
            return int(val)
        elif isinstance(val, np.floating):
            return float(val)

    return val

def to_numpy_array(val):
    # If already a numpy array, return as-is
    if isinstance(val, np.ndarray):
        return val

    # Convert scalars to 1-element arrays
    if np and np.isscalar(val):
        return np.array([val])

    return val

def compute_quantization_scale(tensor_data):
    # Ensure we have a numpy array
    processed = tensor_data if isinstance(tensor_data, np.ndarray) else tensor_data.numpy()

    # Return scale factor based on data type
    return 1 if processed.dtype == np.uint8 else 255

import math

class ClickModel(object):
    '''
    Simple Position-biased Model:
    P(C_r=1) = P(A_r=1|E_r=1)P(E_r=1),
    where
        C_r is click on the r-th document,
        A_r is being attracted by the r-th document, and
        E_r is examination of the r-th document.
    In this simple model, the examination probability is defined as
    P(E_r=1) = exp(- r / sigma).
    Therefore, P(A_r=1|E_r=1) = P(C_r=1) / P(E_r=1).
    '''
    @classmethod
    def estimate(cls, ctrs, sigma=10.0, topk=10):
        result = {}
        for ctr in ctrs:
            if ctr.rank <= topk:
                # Calculate examination probability using exponential decay
                eprob = cls._examination_prob(ctr.rank, sigma)
                # Compute attraction probability, capped at 1.0
                aprob = ctr.ctr / eprob if ctr.ctr / eprob < 1.0 else 1.0
                result[(ctr.query_id, ctr.question_id)] = aprob
        return result

    @classmethod
    def _examination_prob(cls, rank, sigma):
        # Exponential decay of examination probability with rank
        return math.exp(- rank / sigma)

