    @api.multi
    def generate_variant_with_bom(self, attr_value_ids, custom_vals=None):
        """Create variant and attach BOM lines from associated attribute products."""
        if custom_vals is None:
            custom_vals = {}

        # Generate the variant using the parent method
        created_variant = super(ProductTemplate, self).create_get_variant(
            attr_value_ids, custom_values=custom_vals
        )

        # Collect related attribute product records
        attr_product_records = created_variant.attribute_value_ids.mapped('product_id')

        # Prepare BOM line data for each attribute product
        bom_line_data = []
        for product in attr_product_records:
            bom_line_data.append((0, 0, {'product_id': product.id}))

        # Create the manufacturing BOM record
        bom_vals = {
            'product_tmpl_id': self.id,
            'product_id': created_variant.id,
            'bom_line_ids': bom_line_data
        }
        self.env['mrp.bom'].create(bom_vals)

        return created_variant

import re
from .common import (
    ReadCancelledError, InvalidParameterError, TypeNotFoundError,
    InvalidChecksumError
)
from .rpc_errors import (
    RPCError, InvalidDCError, BadRequestError, UnauthorizedError,
    ForbiddenError, NotFoundError, FloodError, ServerError, BadMessageError
)
from .rpc_errors_303 import *
from .rpc_errors_400 import *
from .rpc_errors_401 import *
from .rpc_errors_420 import *

def rpc_message_to_error(status_code, error_text):
    # Map status codes to their respective error dictionaries
    error_map = {
        303: rpc_303_errors,
        400: rpc_400_errors,
        401: rpc_401_errors,
        420: rpc_420_errors
    }

    matching_errors = error_map.get(status_code)

    if matching_errors is not None:
        for pattern, error_class in matching_errors.items():
            match = re.match(pattern, error_text)
            if match:
                # Extract additional data if present in the regex match
                additional_data = int(match.group(1)) if match.groups() else None
                return error_class(extra=additional_data)
    elif status_code == 403:
        return ForbiddenError(error_text)
    elif status_code == 404:
        return NotFoundError(error_text)
    elif status_code == 500:
        return ServerError(error_text)

    # Default fallback error
    return RPCError('{} (code {})'.format(error_text, status_code))

