from typing import Dict, Union, Optional
from avalanche.evaluation.metric_definitions import Metric

class ForwardTransfer(Metric[Union[float, None, Dict[int, float]]]):
    """
        A standalone implementation of the Forward Transfer evaluation metric.

        This class computes how much performance improves from random initialization
        to after training on previous tasks, measured per task ID. When no specific
        task key is requested, it provides a mapping of all task IDs to their respective
        forward transfer scores. If a particular key is specified, only that score is returned.
        """

    def __init__(self):
        """
        Initializes the Forward Transfer metric with empty tracking dictionaries
        for initial (pre-training) and prior-task (post-training) performance values.
        """
        super().__init__()
        self._initial_performance: Dict[int, float] = {}
        self._prior_task_performance: Dict[int, float] = {}

    def record_initial_value(self, task_id: int, value: float) -> None:
        """Records the baseline (random initialization) performance for a given task."""
        self._initial_performance[task_id] = value

    def record_prior_task_value(self, task_id: int, value: float) -> None:
        """Records the post-training performance for a given task."""
        self._prior_task_performance[task_id] = value

    def update(self, task_id: int, value: float, *, is_initial: bool = False) -> None:
        """
        Updates either the initial or prior task performance based on context.

        :param task_id: Identifier for the task being updated
        :param value: Performance metric value to store
        :param is_initial: If True, stores as initial (pre-training) value;
                           otherwise, stores as prior (post-training) value
        """
        if is_initial:
            self.record_initial_value(task_id, value)
        else:
            self.record_prior_task_value(task_id, value)

    def evaluate(self, task_id: Optional[int] = None) -> Union[float, None, Dict[int, float]]:
        """
        Computes forward transfer for one or all tasks.

        Forward transfer = (performance after prior training) - (initial performance)

        :param task_id: Optional specific task ID; if omitted, returns all valid transfers
        :return: For a single task, returns the computed difference; 
                 for multiple tasks, returns a dictionary of differences;
                 returns None if requested task has no recorded prior value
        """
        result = {}

        if task_id is not None:
            if task_id in self._prior_task_performance:
                return self._prior_task_performance[task_id] - self._initial_performance.get(task_id, 0.0)
            else:
                return None

        # Compute for all tasks where both initial and prior values exist
        for tid in self._prior_task_performance:
            if tid in self._initial_performance:
                result[tid] = self._prior_task_performance[tid] - self._initial_performance[tid]
        return result

    def clear_prior_values(self) -> None:
        """Resets only the prior (post-training) performance values."""
        self._prior_task_performance.clear()

    def reset(self) -> None:
        """Completely resets both initial and prior performance tracking."""
        self._initial_performance.clear()
        self._prior_task_performance.clear()

import sys

# Constants and initialization
TERMINATOR = "#"
word_trie = {}

def insert_word(text):
    # Navigate/create path in trie for each character
    node = word_trie
    for symbol in text.strip():  # strip to remove newline
        if symbol in node:
            node = node[symbol]
        elif TERMINATOR in node:  # already have this word
            return
        else:
            break

    # Create trie path for the word
    node = word_trie
    for symbol in text.strip():
        node = node.setdefault(symbol, {})
    node[TERMINATOR] = TERMINATOR

def process_command_line(args):
    # Load words from file
    try:
        with open("./words.txt") as source:
            for line in source:
                insert_word(line)
    except FileNotFoundError:
        pass  # Handle missing file gracefully

    if len(args) > 0 and args[0] == "-c":
        # Solo mode with random selection
        print("Starting solo mode (random)")
    elif len(args) > 1 and args[0] == "-l":
        starting_letter = args[1][0].lower()
        print(f"Starting solo mode with letter '{starting_letter}'")
    else:
        # Standard human vs computer mode
        print("Starting standard game mode")

if __name__ == "__main__":
    process_command_line(sys.argv[1:])

