import json
import urllib
try:
    import http.client as httplib
except ImportError:
    import httplib

class WebhookError(Exception):
    def __init__(self, status_code, error_msg):
        self.status = status_code
        self.message = 'Rocket.Chat server error, code {0}: {1}'.format(status_code, error_msg)
        super(WebhookError, self).__init__(self.message)

class Webhook(object):
    def __init__(self, base_url, api_token):
        # Determine protocol type
        if base_url.startswith('https://'):
            self.use_ssl = True
        else:
            self.use_ssl = False

        # Extract domain without path and protocol
        url_parts = base_url.split('://')
        self.domain = url_parts[-1].split('/')[0]
        self.api_key = api_token

    def send_simple(self, content):
        """Send a basic text message using a single webhook."""
        self.send(TextMessage(content))

    def send(self, msg_obj):
        """Transmit a structured message to Rocket.Chat.
        msg_obj should be a pyrocketchat.TextMessage instance.
        For simple text-only messages, use send_simple() instead.
        Raises pyrocketchat.WebhookError when HTTP response is not 200."""
        assert isinstance(msg_obj, TextMessage), 'Error: message must be a pyrocketchat.TextMessage'

        payload_data = {}
        if msg_obj.body:
            payload_data['text'] = msg_obj.body
        if msg_obj.avatar_url:
            payload_data['icon_url'] = msg_obj.avatar_url
        if msg_obj.embeds:
            payload_data['attachments'] = msg_obj.embeds

        encoded_payload = 'payload=' + urllib.quote(json.dumps(payload_data))
        request_headers = {'Content-Type': 'application/x-www-form-urlencoded'}

        # Establish connection based on protocol
        if self.use_ssl:
            connection = httplib.HTTPSConnection(self.domain)
        else:
            connection = httplib.HTTPConnection(self.domain)

        # Send POST request
        connection.request('POST', '/hooks/' + self.api_key, encoded_payload, request_headers)
        response = connection.getresponse()

        # Handle non-200 responses
        if response.status != 200:
            error_response = json.loads(response.read())
            connection.close()
            raise WebhookError(response.status, error_response.get('message', 'Unknown error'))

        connection.close()

class TextMessage(object):
    def __init__(self, body='', avatar_url=None):
        self.body = body
        self.avatar_url = avatar_url
        self.embeds = []

    def add_line(self, new_content):
        """Append additional text to the message body."""
        if self.body:
            self.body += '\n' + new_content
        else:
            self.body = new_content

    def include_embed(self, **details):
        """Add an embedded element to the message.
        Supported fields (as of Rocket.Chat v0.17):
            * title
            * title_link
            * description
            * media_url
            * accent_color
        Multiple embeds can be added per message.
        """
        self.embeds.append(details)

import functools
from inspect import iscoroutine
from aiohttp.web import (
    json_response, HTTPError,
    HTTPSuccessful, HTTPRedirection
)

def async_json_output(handler=None, *, response_status=200, media_type='application/json', **extra_kwargs):
    """Convert dictionary results from request handlers into JSON responses.
    Designed for use with aiohttp web handlers.
    """
    if handler is None:
        return functools.partial(async_json_output, 
                                 response_status=response_status, 
                                 media_type=media_type, 
                                 **extra_kwargs)

    @functools.wraps(handler)
    async def decorated(*args, **kwargs):
        try:
            result = handler(*args, **kwargs)
            if iscoroutine(result):
                result = await result
        except (HTTPSuccessful, HTTPRedirection):
            raise
        except HTTPError as http_err:
            if http_err.empty_body:
                raise
            response_status_code = http_err.status_code
            result = {
                'error': http_err.body,
            }
        else:
            response_status_code = response_status

        try:
            response_status_code = result['status']
        except KeyError:
            result['status'] = response_status_code

        return json_response(
            result,
            status=response_status_code,
            content_type=media_type,
            **extra_kwargs
        )
    return decorated

import glob
import os
import lxml.etree as ET
from cumulusci.core.tasks import BaseTask


class RemoveElementsXPath(BaseTask):
    task_options = {
        'elements': {
            'description': 'A list of dictionaries containing path and xpath keys. The path key is a file path that supports wildcards and xpath is the xpath for the elements to remove.  Multiple dictionaries can be passed in the list to run multiple removal queries in the same task.  Metadata elements in the xpath need to be prefixed with ns:, for example: ./ns:Layout/ns:relatedLists',
            'required': True,
        },
        'chdir': {
            'description': 'Change the current directory before running the replace',
        }
    }

    def _run_task(self):
        original_dir = os.getcwd()
        target_dir = self.options.get('chdir')

        if target_dir:
            self.logger.info(f'Changing working directory to {target_dir}')
            os.chdir(target_dir)

        for removal_spec in self.options['elements']:
            self._execute_removal(removal_spec)

        if target_dir:
            os.chdir(original_dir)

    def _execute_removal(self, removal_spec):
        self.logger.info(
            f'Removing elements matching {removal_spec["xpath"]} from {removal_spec["path"]}'
        )

        # Process each file matching the pattern
        for filepath in glob.glob(removal_spec['path']):
            try:
                # Read original content
                with open(filepath, 'r', encoding='utf-8') as file_obj:
                    original_content = file_obj.read()

                # Parse XML and perform removals
                tree_root = ET.parse(filepath).getroot()
                xpath_expr = removal_spec['xpath'].replace(
                    'ns:', 
                    '{http://soap.sforce.com/2006/04/metadata}'
                )

                # Find and remove matching elements
                matched_elements = tree_root.findall(xpath_expr)
                for target_element in matched_elements:
                    if target_element.getparent() is not None:
                        target_element.getparent().remove(target_element)

                # Generate new XML content
                modified_xml = ET.tostring(
                    tree_root, 
                    encoding='unicode', 
                    xml_declaration=True
                )
                new_content = f'{modified_xml}\n'

                # Write back only if changes were made
                if original_content.strip() != new_content.strip():
                    self.logger.info(f'Updating {filepath}')
                    with open(filepath, 'w', encoding='utf-8') as file_obj:
                        file_obj.write(new_content)

            except Exception as e:
                self.logger.warning(f'Error processing {filepath}: {str(e)}')

