def extract_candidates_by_status(election_details, membership_list):
    current_eligible = set()
    previous_eligible = set()

    for membership_record in membership_list:
        # Skip if not matching candidate role
        if membership_record.get('role') != election_details['candidate_membership_role']:
            continue

        # Create person object from membership data
        candidate_person = PopItPerson.create_from_dict(membership_record['person_id'])

        # Check if membership overlaps with election date
        if membership_covers_date(membership_record, election_details['election_date']):
            current_eligible.add(candidate_person)
        else:
            # Look through all elections to find overlapping past ones
            for other_election_key, other_election_info in settings.ELECTIONS_BY_DATE:
                # Skip elections not suitable for candidate suggestions
                if not other_election_info.get('use_for_candidate_suggestions'):
                    continue

                # Check if membership covers this other election date
                if membership_covers_date(
                        membership_record,
                        other_election_info['election_date']
                ):
                    previous_eligible.add(candidate_person)

    return current_eligible, previous_eligible

import sys

class OperatingSystem:
    @staticmethod
    def is_macos(name=None):
        name = name or sys.platform
        return 'darwin' in name

    @staticmethod
    def is_bsd_variant(name=None):
        name = name or sys.platform
        return name.startswith("freebsd")

    @staticmethod
    def is_linux_system(name=None):
        name = name or sys.platform
        return 'linux' in name

    @staticmethod
    def is_unix_like(name=None):
        """ Determine if the system follows Unix-like characteristics. """
        name = name or sys.platform
        return (OperatingSystem.is_macos(name) or 
                OperatingSystem.is_bsd_variant(name))

    @staticmethod
    def is_solaris_system(name=None):
        name = name or sys.platform
        return name == "sunos5"

    @staticmethod
    def is_posix_compliant(name=None):
        """ Check if the platform adheres to POSIX standards. """
        name = name or sys.platform
        return (OperatingSystem.is_macos(name) or 
                OperatingSystem.is_linux_system(name) or 
                OperatingSystem.is_bsd_variant(name))

    @staticmethod
    def is_windows(name=None):
        name = name or sys.platform
        return name == "win32"

