import discord

def count_members_by_type(guild: discord.Guild):
    """Counts bots and users separately in a guild."""
    bot_count = 0
    user_count = 0
    for member in guild.members:
        if member.bot:
            bot_count += 1
        else:
            user_count += 1
    return bot_count, user_count

def calculate_bot_to_user_ratio(guild: discord.Guild) -> float:
    """Calculates the ratio of bots to users, avoiding division by zero."""
    bots, users = count_members_by_type(guild)
    return bots / users if users > 0 else float('inf')

async def is_blacklisted(bot, guild_id: int) -> bool:
    """Returns True if the guild ID exists in the blacklisted_guilds table."""
    async with bot.pgpool.acquire() as conn:
        result = await conn.fetchrow(
            'SELECT 1 FROM blacklisted_guilds WHERE guild_id = $1', 
            guild_id
        )
        return result is not None

async def is_bot_collection(bot, guild: discord.Guild) -> bool:
    """Determines whether a guild appears to be a bot collection."""
    # Immediately flag blacklisted guilds
    if await is_blacklisted(bot, guild.id):
        return True

    # Check for suspicious keywords in the guild name
    suspicious_keywords = ['bot collection', 'bot hell']
    if any(keyword in guild.name.lower() for keyword in suspicious_keywords):
        return True

    # Whitelist known non-bot-collection guilds
    safe_guild_ids = {110373943822540800, 228317351672545290}
    if guild.id in safe_guild_ids:
        return False

    # High bot-to-user ratio threshold
    if calculate_bot_to_user_ratio(guild) >= 8:
        return True

    return False

