class UserDeletionManagerMixin:
    def users_to_notify(self):
        """Identifies users who have been inactive for a specified period and haven't received a notification."""
        user_deletion_config = apps.get_app_config('user_deletion')
        cutoff_date = timezone.now() - relativedelta(
            months=user_deletion_config.MONTH_NOTIFICATION
        )
        return self.filter(last_login__lte=cutoff_date, notified=False)

    def users_to_delete(self):
        """Identifies users who have been inactive beyond the deletion threshold and were previously notified."""
        user_deletion_config = apps.get_app_config('user_deletion')
        deletion_cutoff = timezone.now() - relativedelta(
            months=user_deletion_config.MONTH_DELETION
        )
        return self.filter(last_login__lte=deletion_cutoff, notified=True)

