import random
import json
import SocketExtend as SockExt
import config as conf
import parser as p

def check_connection(sock):
    try:
        # Generate a random number between 1 and 99999
        test_value = random.randint(1, 99999)
        payload = {
            'request': 'ping',
            'contents': {'value': test_value}
        }

        # Send the ping request
        SockExt.send_msg(sock, json.dumps(payload))

        # Receive and parse the response
        response_data = SockExt.recv_msg(sock)
        response = json.loads(response_data)

        # Verify if the returned value matches what was sent
        return response.get('return') == test_value
    except Exception as error:
        print("Error during connection check:", error)
        return False

def verify_multiple_connections(server_port, host_list=[]):
    all_successful = True

    for host_ip in host_list:
        try:
            # Create a new TCP socket
            connection = socket.socket(socket.AF_INET, socket.SOCK_STREAM)

            # Connect to the specified host and port
            connection.connect((host_ip, int(server_port)))

            # Check if this connection responds correctly
            if not check_connection(connection):
                all_successful = False

            # Properly close the connection
            connection.shutdown(socket.SHUT_RDWR)
            connection.close()

        except Exception as err:
            # If any exception occurs, mark as failure
            all_successful = False

    return all_successful

def test_availability(port_number, server_addresses=[]):
    attempts_made = 0
    is_available = False

    while attempts_made < conf.tries:
        try:
            if verify_multiple_connections(port_number, server_addresses):
                is_available = True
                break
        except Exception as exc:
            attempts_made += 1

    return is_available

from datetime import datetime, timedelta
import sys

class ProgressIndicator:
    def __init__(self, file_name, display_format):
        self.file_name = file_name
        self.display_format = display_format
        self.current_value = 0
        self.maximum_value = 0
        self.start_time = datetime.now()
        self.last_update_time = self.start_time

    def update(self, current, total):
        self.current_value = current
        self.maximum_value = total
        is_complete = current == total

        if (datetime.now() - self.last_update_time > timedelta(seconds=0.5)) or is_complete:
            formatted_output = self.display_format.format(
                filename=self.file_name,
                percentage=self.calculate_percentage(),
                rate=self.calculate_throughput()
            )
            sys.stdout.write('\r' + formatted_output)
            if is_complete:
                sys.stdout.write('\n')
            sys.stdout.flush()
            self.last_update_time = datetime.now()

    def calculate_percentage(self):
        return self.current_value / float(self.maximum_value)

    def calculate_throughput(self):
        elapsed_time = datetime.now() - self.start_time
        if elapsed_time.total_seconds() == 0:
            return 0
        return self.current_value * 8 / elapsed_time.total_seconds() / 1000 / 1000

