def apply_to_pairs(func, mapping):
    return dict(func(key, value) for key, value in mapping.items())

def transform_keys(func, mapping):
    return apply_to_pairs(lambda k, v: (func(k), v), mapping)

def transform_values(func, mapping):
    return apply_to_pairs(lambda k, v: (k, func(v)), mapping)

def filter_keys(func, mapping):
    return { k: v for k, v in mapping.items() if func(k, v) }

def extract_signature(value):
    if not callable(value):
        value = lambda: value
    return util.fninfo(value)

def collect_dependencies(graph):
    dependencies_map = {}
    for node_name, node_info in graph.items():
        for dependency in node_info["required"]:
            dependencies_map.setdefault(node_name, set()).add(dependency)
    return dependencies_map

def topological_sort(dependencies):
    if not dependencies:
        return []

    # Find nodes with no incoming edges (sources)
    all_nodes = set(dependencies.keys())
    dependent_nodes = set(chain.from_iterable(dependencies.values()))
    sources = list(all_nodes - dependent_nodes)

    if not sources:
        raise ValueError("Graph cycle detected!")

    # Recursively process remaining nodes excluding current sources
    remaining_deps = filter_keys(lambda k, _: k not in sources, dependencies)
    return sources + topological_sort(remaining_deps)

def process_graph(graph):
    if callable(graph):
        return graph

    # Process each component recursively
    processed = transform_values(process_graph, graph)
    schematized = transform_values(extract_signature, processed)

    # Build dependency information
    dep_info = collect_dependencies(schematized)

    # Get reverse topological order
    topo_order = topological_sort(dep_info)[::-1]

    return {
        "schema": schematized,
        "node_order": topo_order,
        "edges": dep_info,
    }

# Find the maximum length of word chain where each word is formed by removing one character from the previous word

def findLongestChain(word_list):
    if not word_list:
        return 0

    # Group words by their lengths using a dictionary
    words_by_length = {}
    for w in word_list:
        length = len(w)
        if length not in words_by_length:
            words_by_length[length] = set()
        words_by_length[length].add(w)

    # Get sorted list of unique lengths
    lengths = sorted(words_by_length.keys())

    # Track the maximum chain length ending at each word
    chain_lengths = {word: 1 for word in word_list}
    overall_max = 1

    # Process words by increasing length
    for i in range(1, len(lengths)):
        current_len = lengths[i]
        prev_len = current_len - 1

        # Only process if there are words with length-1
        if prev_len in words_by_length:
            # For each word of current length
            for word in words_by_length[current_len]:
                # Try removing each character to see if predecessor exists
                for pos in range(len(word)):
                    predecessor = word[:pos] + word[pos+1:]
                    if predecessor in words_by_length[prev_len]:
                        # Update chain length if we found a longer chain
                        new_length = chain_lengths[predecessor] + 1
                        if new_length > chain_lengths[word]:
                            chain_lengths[word] = new_length
                            if new_length > overall_max:
                                overall_max = new_length

    return overall_max

