from typing import IO, TYPE_CHECKING, Optional
from rdflib.term import URIRef

if TYPE_CHECKING:
    from rdflib.graph import Graph

__all__ = ["Serializer"]

class Serializer:
    def __init__(self, store_instance: "Graph"):
        self.store: "Graph" = store_instance
        self._encoding: str = "utf-8"
        self._base_uri: Optional[str] = None

    def serialize(
        self,
        output_stream: IO[bytes],
        base_uri: Optional[str] = None,
        char_encoding: Optional[str] = None,
        **kwargs
    ) -> None:
        """Abstract method for serializing the RDF graph"""

    def adjust_uri(self, full_uri: str) -> URIRef:
        current_base = self._base_uri
        if current_base is not None and full_uri.startswith(current_base):
            relative_path = full_uri.replace(current_base, "", 1)
            return URIRef(relative_path)
        return URIRef(full_uri)

