from .base import Base

class Source(Base):
    def __init__(self, vim):
        super().__init__(vim)
        self.name = 'vimtex_toc'
        self.kind = 'file'

    @staticmethod
    def generate_number_string(number_info):
        # Handle invalid or special section types
        if not number_info or not isinstance(number_info, dict):
            return ''

        # Skip frontmatter and backmatter sections
        if number_info.get('frontmatter') or number_info.get('backmatter'):
            return ''

        # Extract non-zero hierarchical numbers in order
        hierarchy_keys = [
            'part',
            'chapter',
            'section',
            'subsection',
            'subsubsection',
            'subsubsubsection'
        ]

        numeric_parts = []
        for key in hierarchy_keys:
            value = number_info.get(key)
            if value is not None and value != 0:
                numeric_parts.append(str(value))

        # Convert chapter number to letter if in appendix
        if number_info.get('appendix') and numeric_parts:
            try:
                chapter_num = int(numeric_parts[0])
                numeric_parts[0] = chr(64 + chapter_num)  # Convert 1->A, 2->B, etc.
            except (ValueError, TypeError):
                pass

        # Join with dots to form final number string
        return '.'.join(numeric_parts)

    @staticmethod
    def build_entry_display(entry, max_depth):
        # Calculate indentation based on level difference
        level_diff = int(max_depth) - int(entry['level'])
        indent = ' ' * 2 * level_diff
        title = entry.get('title', '')
        display_title = (indent + title)[:60]

        # Generate section number
        section_number = Source.generate_number_string(entry.get('number'))

        # Format the abbreviated line
        formatted_line = '{:65}{:10}'.format(display_title, section_number)

        return {
            'word': title,
            'abbr': formatted_line,
            'action__path': entry.get('file', ''),
            'action__line': entry.get('line', 0)
        }

    def gather_candidates(self, context):
        # Get TOC entries from vimtex
        entries = self.vim.eval('vimtex#toc#get_entries()')

        # Determine maximum depth for indentation calculation
        if not entries:
            return []

        max_level = max(int(e.get('level', 0)) for e in entries)

        # Build candidate list
        return [Source.build_entry_display(entry, max_level) for entry in entries]

