from types import NoneType

def normalize_mode(mode):
    # Check if mode is already an integer or None
    if isinstance(mode, (int, type(None))):
        return mode

    try:
        # Attempt to convert mode to integer (e.g., '755' -> 755)
        return int(mode)
    except (TypeError, ValueError):
        # If conversion fails, return original value unchanged
        pass

    return mode

def perform_sed_substitution(file_path, content_line, replacement_text, options=None):
    # Normalize flags to string format
    option_str = ''.join(options) if options else ''

    # Escape forward slashes in both search and replacement strings
    escaped_line = content_line.replace('/', '\\/')
    escaped_replace = replacement_text.replace('/', '\\/')

    # Construct sed command for in-place substitution
    return 'sed -i "s/{0}/{1}/{2}" {3}'.format(
        escaped_line, escaped_replace, option_str, file_path
    )

def set_permissions(path, permission_mode, apply_recursively=False):
    # Build chmod command with optional recursive flag
    return 'chmod {0}{1} {2}'.format(
        '-R ' if apply_recursively else '', 
        permission_mode, 
        path
    )

def change_ownership(path, owner_name, group_name=None, apply_recursively=False):
    base_command = 'chown'
    ownership_spec = None

    # Determine ownership specification based on provided parameters
    if owner_name and group_name:
        ownership_spec = '{0}:{1}'.format(owner_name, group_name)
    elif owner_name:
        ownership_spec = owner_name
    elif group_name:
        base_command = 'chgrp'
        ownership_spec = group_name

    # Construct final command with optional recursive flag
    return '{0}{1} {2} {3}'.format(
        base_command,
        ' -R' if apply_recursively else '',
        ownership_spec,
        path
    )

import os
from threading import Thread

def _remove_and_link(target: str, source: str, should_link: bool):
    os.remove(target)
    if should_link:
        os.symlink(source, target)

def process_file_group(file_list, create_symlink=False):
    # Keep the first file as reference to avoid removing everything
    reference = None
    original_path = ""
    removed_items = []
    linked_items = []
    issues = []

    for item in file_list:
        if os.path.isfile(item):
            if reference is None:
                reference = True
                original_path = item

            else:
                Thread(target=_remove_and_link, args=(item, original_path, create_symlink)).start()
                removed_items.append(item)

                if create_symlink:
                    linked_items.append(item)

        else:
            issues.append(f"File not recognized: \"{item}\"")

    return {
        "kept": original_path,
        "symlinked": linked_items,
        "removed": removed_items,
        "errors": issues
    }

# Main function to handle duplicate files
def manage_duplicates(duplicates_dict, make_link=False):
    if len(duplicates_dict) == 0:
        return None

    results = []
    for group in duplicates_dict.values():
        results.append(process_file_group(group, make_link))

    return results

# Convenience functions for specific operations
def remove_duplicates(duplicates):
    return manage_duplicates(duplicates)

def symlink_duplicates(duplicates):
    return manage_duplicates(duplicates, True)

# Check server availability through repeated ping attempts

import random
import json
import time
import socket
import SocketExtend as SockExt
import config as conf
import parser as p

def test_connection(sock):
    try:
        # Generate a unique identifier for this test
        identifier = random.randint(1, 99999)
        payload = {'request': 'ping', 'contents': {'value': identifier}}

        # Send the ping request
        SockExt.send_msg(sock, json.dumps(payload))

        # Wait for and parse the response
        response = json.loads(SockExt.recv_msg(sock))

        # Verify the response matches our identifier
        return response['return'] == identifier

    except Exception as error:
        print "Error during connection test:", error
        return False

def verify_servers(port, server_list=[]):
    all_servers_responding = True

    for server_ip in server_list:
        connection = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        #connection.settimeout(120.0)

        try:
            connection.connect((server_ip, int(port)))

            if not test_connection(connection):
                all_servers_responding = False

            connection.shutdown(socket.SHUT_RDWR)
            connection.close()

        except Exception as e:
            all_servers_responding = False
            try:
                connection.close()
            except:
                pass

    return all_servers_responding

def check_server_health(port, host_list=[]):
    tries_count = 0
    servers_are_up = False

    while tries_count < conf.tries:
        try:
            if verify_servers(port, host_list):
                servers_are_up = True
                break
        except Exception as exception:
            time.sleep(1)
            tries_count += 1

    return servers_are_up

