import json
import aioredis
from kyokai import Request
from kyokai.context import HTTPRequestContext

async def cached_execution(ctx: HTTPRequestContext, handler_func, *params, ttl=300):
    """
    Execute a coroutine with caching support.
    Stores the outcome in Redis using a generated key.
    """
    assert isinstance(ctx.redis, aioredis.Redis)

    # Generate cache key from function name and parameters
    cache_key = handler_func.__name__ + repr(params)

    # Try to retrieve cached result
    cached_value = await ctx.redis.get(cache_key)
    if cached_value is not None:
        return cached_value.decode('utf-8')

    # Execute the handler function
    computed_result = await handler_func(ctx, *params)

    # Store the result in cache with expiration time
    await ctx.redis.set(cache_key, computed_result, ex=ttl)

    return computed_result

def json_response_decorator(handler_func):
    """
    Wrap a handler function to automatically convert its output to JSON format.
    """
    async def wrapped_handler(ctx: HTTPRequestContext):
        raw_result = await handler_func(ctx)

        assert isinstance(ctx.request, Request)

        if isinstance(raw_result, tuple):
            # Prepare base request metadata
            base_metadata = {"_request": {"route": ctx.request.path, "api_version": 1}}

            # Merge base metadata with response data
            merged_data = {**base_metadata, **raw_result[0]} if isinstance(raw_result[0], dict) else raw_result

            # Handle different tuple lengths for status code and headers
            if len(raw_result) == 1:
                return json.dumps(merged_data), 200, {"Content-Type": "application/json"}
            elif len(raw_result) == 2:
                return json.dumps(merged_data), raw_result[1], {"Content-Type": "application/json"}
            else:
                # Combine default headers with any additional headers provided
                default_headers = {"Content-Type": "application/json"}
                extra_headers = raw_result[2] if isinstance(raw_result[2], dict) else {}
                combined_headers = {**default_headers, **extra_headers}
                return json.dumps(merged_data), raw_result[1], combined_headers
        else:
            # Single return value case - wrap in metadata
            base_metadata = {"_request": {"route": ctx.request.path, "api_version": 1}}
            final_response = {**base_metadata, **raw_result} if isinstance(raw_result, dict) else raw_result
            return json.dumps(final_response), 200, {"Content-Type": "application/json"}

    return wrapped_handler

