from zou.app.utils import auth, permissions
from sqlalchemy.exc import IntegrityError

class PersonsCsvImportResource(BaseCsvImportResource):
    def check_permissions(self):
        # Verify that the current user has administrative privileges
        return permissions.check_admin_permissions()

    def import_row(self, row):
        # Extract person data from the CSV row
        first_name = row["First Name"]
        last_name = row["Last Name"]
        email = row["Email"]
        phone = row.get("Phone", "")

        # Normalize role values according to system conventions
        raw_role = row.get("Role", "")
        role = None

        if raw_role == "Studio Manager":
            role = "admin"
        elif raw_role == "Supervisor":
            role = "manager"
        elif raw_role == "Client":
            role = "client"
        else:
            # Default to 'user' if role is specified but not recognized
            if raw_role and len(raw_role.strip()) > 0:
                role = "user"

        try:
            # Set default password and attempt to find existing person by email
            encrypted_password = auth.encrypt_password("default")
            existing_person = Person.get_by(email=email)

            if existing_person is None:
                # Create new person record if none exists
                person_data = {
                    "email": email,
                    "password": encrypted_password,
                    "first_name": first_name,
                    "last_name": last_name,
                    "phone": phone
                }
                if role is not None:
                    person_data["role"] = role

                person = Person.create(**person_data)
            else:
                # Update existing person's information
                update_data = {
                    "first_name": first_name,
                    "last_name": last_name,
                    "phone": phone
                }
                if role is not None:
                    update_data["role"] = role
                existing_person.update(update_data)
                person = existing_person

        except IntegrityError:
            # In case of integrity issues (e.g., duplicate), fetch the existing record
            person = Person.get_by(email=email)

        return person.serialize_safe()

