# Solution for Advent of Code 2019 Day 13 - Care Package

from collections import deque
from typing import TextIO, Dict, Tuple
from aoc2019.intcode import Computer, read_program


def update_screen(computer: Computer, display: Dict[Tuple[int, int], int]) -> None:
    """Process output from the computer and update the screen dictionary."""
    while computer.output:
        x = computer.output.popleft()
        y = computer.output.popleft()
        tile_id = computer.output.popleft()
        display[(x, y)] = tile_id


def count_blocks(display: Dict[Tuple[int, int], int]) -> int:
    """Count the number of block tiles (tile ID 2) on the screen."""
    return sum(1 for tile in display.values() if tile == 2)


def play_game(computer: Computer, display: Dict[Tuple[int, int], int]) -> int:
    """Simulate gameplay until the game ends."""
    # Set game mode to "play" by modifying program[0] to 2
    computer.program[0] = 2

    game_over = False
    while not game_over:
        try:
            computer.run()
            game_over = True
        except IndexError:
            # Computer is waiting for input
            pass

        # Update screen with any new output
        update_screen(computer, display)

        # Find ball and paddle positions
        ball_pos = next((x for (x, y), tile in display.items() if tile == 4), None)
        paddle_positions = [x for (x, y), tile in display.items() if tile == 3]
        paddle_center = sum(paddle_positions) / len(paddle_positions) if paddle_positions else 0

        # Determine joystick movement based on relative positions
        if ball_pos is not None:
            if ball_pos < paddle_center:
                computer.input.append(-1)  # Move left
            elif ball_pos > paddle_center:
                computer.input.append(1)   # Move right
            else:
                computer.input.append(0)   # No movement
        else:
            computer.input.append(0)       # Default no movement if ball not found

    # Return score (stored at position (-1, 0))
    return display.get((-1, 0), 0)


