@app.route("/worker", methods=['POST', 'GET'])
def worker_handler():
    # Process form submission if present
    process_worker_form(flask.request.form)

    # Build dictionary of configured workers per pool
    pool_workers = {}
    for current_pool in btcnet_info.get_pools():
        if current_pool.name is None:
            logging.debug('Skipping pool with no name: %s', current_pool)
            continue

        pool_name = current_pool.name
