    # Validate required fields exist
    required_fields = ['method', 'username', 'password', 'pool']
    for field in required_fields:
        if field not in form_data:
            return

    action = form_data['method']

    if action == 'delete':
        worker_config.remove(
            form_data['pool'], 
            form_data['username'], 
            form_data['password']
        )

    elif action == 'create':
        worker_config.add(
            form_data['pool'], 
            form_data['username'], 
            form_data['password']
        )

