        # Test when the highest-priority language is supported
        request_headers = {
            'Accept-Language': 'de;q=1.0, en;q=0.3'
        }
        with self.application.test_request_context('/', headers=request_headers):
            detected_locale = orchard.extensions.flask_babel._get_locale()
