        request_headers = {
            'Accept-Language': 'fr;q=1.0, en;q=0.8'
        }
        with self.application.test_request_context('/', headers=request_headers):
            detected_locale = orchard.extensions.flask_babel._get_locale()
            self.assertEqual(detected_locale, 'en')

        # Test when no accepted languages are supported (fallback to default)
        request_headers = {
            'Accept-Language': 'es;q=1.0, fr;q=0.9'
        }
        with self.application.test_request_context('/', headers=request_headers):
