from sklearn.model_selection import train_test_split

class Backend(object):
    def __init__(self):
        self.dataset_identifier = 0
        self.random_seed_counter = 0
        self.dataset = None
        self.trained_model = None

    def load(self, dataset):
        self.trained_model = None
        self.dataset_identifier += 1
        self.dataset = dataset
        self.features = dataset['data']
        self.labels = dataset['target']
        return True

    def is_loaded(self):
        return (self.dataset is not None)

    def train(self):
        if not self.is_loaded():
            return False
        classifier = self.classifier()
        classifier.fit(self.features, self.labels)
        self.trained_model = classifier
        return True

    def is_trained(self):
        return (self.trained_model is not None)

    def evaluate(self, test_ratio=0.2):
        if not self.is_loaded():
            return []
        self.random_seed_counter += 1
        classifier = self.classifier()
        X_train, X_test, y_train, y_test = train_test_split(
            self.features, self.labels, test_size=test_ratio, 
            random_state=self.random_seed_counter
        )
        classifier.fit(X_train, y_train)
        return [classifier.score(X_test, y_test)]

    def infer(self, input_data):
        return self.trained_model.predict(input_data)

