import collections

def apply_to_each(func, seq):
    for element in seq:
        func(element)

def apply_with_unpacked_args(func, pairs):
    for args_tuple in pairs:
        func(*args_tuple)

def find_extremes(*values):
    minimum = None
    maximum = None
    for val in values:
        if maximum is None or val > maximum:
            maximum = val
        if minimum is None or val < minimum:
            minimum = val
    return minimum, maximum

def transform_list_recursively(func, target_list, levels=0):
    if levels <= 0:
        target_list[:] = list(map(func, target_list))
    else:
        for sub_item in target_list:
            transform_list_recursively(func, sub_item, levels - 1)

def filter_count(predicate, sequence):
    tally = 0
    for entry in sequence:
        if predicate(entry):
            tally += 1
    return tally

def apply_multiple_funcs(data_seq, *operations):
    result = []
    for item in data_seq:
        transformed = [op(item) for op in operations]
        result.append(transformed)
    return result

class Distribution(collections.defaultdict):
    """Represents a probability distribution and supports comparison with others"""
    def __init__(self):
        super().__init__(int)

    def fetch(self, key, default=0):
        return dict.get(self, key, default)

    def divergence_from(self, other_dist):
        all_keys = set(self.keys()) | set(other_dist.keys())
        total_diff = 0
        for key in all_keys:
            diff = abs(self.fetch(key) - other_dist.fetch(key))
            total_diff += diff
        return total_diff

