import inspect
from enum import IntEnum
from pdfquery import PDFQuery

class FieldType(IntEnum):
    NUMERIC = 1
    STRING = 2
    FUNCTIONAL = 3  # Note: Consider replacing with callable-based approach in future

class FieldDefinition(object):
    def __init__(self, coordinates, category=FieldType.STRING, mandatory=False,
                 label=None):
        self.coordinates = coordinates
        self.category = category
        self.mandatory = mandatory
        self.label = label

class SchemaDefinition(object):
    @classmethod
    def get_pdf_selectors(cls, target_field=None):
        """Generate pdfminer selectors for specified field. If no field is
        provided, return selectors for all defined fields.
        """
        if target_field is not None:
            field = getattr(cls, target_field, None)
            if (field is None) or (not isinstance(field, FieldDefinition)):
                raise ValueError(
                    '{field} is not a FieldDefinition attribute on {klass}'.format(
                        field=target_field, klass=cls.__name__
                    )
                )
            field_list = [('extraction_year', field)]
        else:
            field_list = inspect.getmembers(
                cls, lambda f: isinstance(f, FieldDefinition)
            )

        base_selectors = [('format_converter', 'text')]
        base_selectors.extend(
            (name, 'LTTextLineHorizontal:in_bbox("{coords}")'.format(
                coords=', '.join(str(val) for val in field.coordinates)
            ))
            for name, field in field_list
        )
        return base_selectors

class DocumentModel(object):
    variants = []

    def __init__(self, source_file):
        # TODO: Validate input type (str vs file object)
        self._source = PDFQuery(source_file)
        self._content = {}
        self._validate_setup()

    @property
    def content(self):
        """Read-only property containing extracted data after `process()` execution."""
        return self._content

    def identify_variant(self):
        raise NotImplementedError('Subclass DocumentModel and override this method')

    def process(self):
        self._source.load()
        variant = self.identify_variant()
        selectors = variant.get_pdf_selectors()
        results = self._source.extract(selectors)
        self._content = results

    def _validate_setup(self):
        if not self.variants:
            raise ValueError(
                "The class '{name}' hasn't been configured with any variants."
                " Set {name}.variants to a list of SchemaDefinition types.".format(
                    name=self.__class__.__name__
                )
            )

# Alternative implementation of optimization functions using scipy

from scipy import optimize as opt
import numpy as np
import clean as cln

def local_minimize(func, params):
    bracket_range = params['bracket']
    bounds_tuple  = params['bounds']
    solver_method = params['method']
    tolerance     = params['tol']
    solver_opts   = params['options']

    try:
        return opt.minimize_scalar(
            func, 
            bracket=bracket_range, 
            bounds=bounds_tuple, 
            method=solver_method, 
            tol=tolerance, 
            options=solver_opts
        )
    except Exception as error:
        return str(error)

def global_minimize(func, config):
    initial_guess    = config['guess']
    max_iterations   = config['iterations']
    cooling_temp     = config['temperature']
    step_length      = config['stepSize']
    collect_all_mins = config['includeAllMinsFound']
    report_interval  = config['interval']

    minima_list = []

    # Define callback to capture intermediate minima if requested
    if collect_all_mins:
        def monitor(xk, fval, accept):
            minima_list.append([xk[0], fval, accept])
    else:
        monitor = None

    try:
        result = opt.basinhopping(
            func, 
            x0=initial_guess, 
            niter=max_iterations, 
            stepsize=step_length, 
            T=cooling_temp, 
            callback=monitor, 
            interval=report_interval
        )

        # Convert numpy array to list for JSON compatibility
        result['x'] = result['x'].tolist()

        # Add collected minima if requested
        if collect_all_mins:
            result['allMins'] = minima_list

        return result
    except Exception as err:
        return str(err)

def nnls_solver(matrix_A, vector_b):
    try:
        solution_vec, residual_val = opt.nnls(np.asarray(matrix_A), np.asarray(vector_b))
        return {
            'solution': solution_vec.tolist(),
            'residual': residual_val
        }
    except Exception as exc:
        return str(exc)

