# but preserving the same functionality (extracting Build, DefaultOptions, and dependencies)

from __future__ import (unicode_literals, division,
                        absolute_import, print_function)
from reggae.build import Build, DefaultOptions
from inspect import getmembers
import os
from modulefinder import ModuleFinder

def extract_build_object(module_obj):
    # Collect all attributes that are instances of Build
    build_candidates = []
    for name, value in getmembers(module_obj):
        if isinstance(value, Build):
            build_candidates.append(value)

    # Ensure exactly one Build object exists
    if len(build_candidates) != 1:
        raise AssertionError("Expected exactly one Build instance")
    return build_candidates[0]

def extract_default_options(module_obj):
    # Collect all attributes that are instances of DefaultOptions
    options_candidates = []
    for name, value in getmembers(module_obj):
        if isinstance(value, DefaultOptions):
            options_candidates.append(value)

    # Allow zero or one DefaultOptions instances
    if len(options_candidates) > 1:
        raise AssertionError("At most one DefaultOptions instance expected")
    return options_candidates[0] if options_candidates else None

def find_local_dependencies(module_path):
    # Use ModuleFinder to analyze imports in the given module
    analyzer = ModuleFinder()
    analyzer.run_script(module_path)

    # Get absolute paths of all imported modules with files
    all_module_files = []
    for mod_name, mod_obj in analyzer.modules.items():
        if hasattr(mod_obj, '__file__') and mod_obj.__file__ is not None:
            all_module_files.append(os.path.abspath(mod_obj.__file__))

    # Filter to only include modules in the same directory as the input module
    base_dir = os.path.dirname(os.path.abspath(module_path))
    local_deps = []
    for dep_path in all_module_files:
        if dep_path and os.path.dirname(dep_path).startswith(base_dir) and dep_path != os.path.abspath(module_path):
            local_deps.append(dep_path)

    return local_deps

