import random
from dataclasses import dataclass
from typing import List, Dict, Any
from training.dataset.vos_segment_loader import LazySegments

MAX_ATTEMPTS = 1000

@dataclass
class FrameObjectSample:
    selected_frames: List[int]
    target_objects: List[int]

class VOSFrameSelector:
    def __init__(self, order_by_time=True):
        # Frames are sorted by frame index when order_by_time is True
        self.order_by_time = order_by_time

    def select(self, video_data):
        raise NotImplementedError()

class UniformRandomSelector(VOSFrameSelector):
    def __init__(
        self,
        frame_count,
        object_limit,
        time_reverse_chance=0.0,
    ):
        self.frame_count = frame_count
        self.object_limit = object_limit
        self.time_reverse_chance = time_reverse_chance

    def select(self, video_data, segmentation_provider, current_epoch=None):
        for attempt in range(MAX_ATTEMPTS):
            total_frames = len(video_data.frames)
            if total_frames < self.frame_count:
                raise ValueError(
                    f"Cannot select {self.frame_count} frames from video '{video_data.name}' "
                    f"which only contains {total_frames} annotated frames."
                )

            # Randomly pick starting point
            start_idx = random.randint(0, total_frames - self.frame_count)
            candidate_frames = [
                video_data.frames[start_idx + offset] 
                for offset in range(self.frame_count)
            ]

            # Optionally reverse temporal order
            if random.random() < self.time_reverse_chance:
                candidate_frames.reverse()

            # Extract visible objects from the first selected frame
            available_ids = []
            segments = segmentation_provider.get(candidate_frames[0].index)

            if isinstance(segments, LazySegments):
                available_ids = list(segments.keys())
            else:
                for obj_id, mask in segments.items():
                    if mask.any():  # Check if segment has any non-zero pixels
                        available_ids.append(obj_id)

            # Accept sample only if at least one object is visible
            if len(available_ids) > 0:
                break

            if attempt >= MAX_ATTEMPTS - 1:
                raise RuntimeError("No visible objects found after maximum attempts")

        # Randomly select up to object_limit objects
        selected_objects = random.sample(
            available_ids,
            min(len(available_ids), self.object_limit)
        )

        return FrameObjectSample(
            selected_frames=candidate_frames,
            target_objects=selected_objects
        )

class EvaluationSelector(VOSFrameSelector):
    """
    VOS Selector for evaluation: includes all frames and all objects in a video
    """
    def __init__(self):
        super().__init__()

    def select(self, video_data, segmentation_provider, current_epoch=None):
        """
        Selects every frame and every object present in the video
        """
        if self.order_by_time:
            # Sort frames chronologically by their indices
            frames = sorted(video_data.frames, key=lambda f: f.index)
        else:
            # Preserve original ordering
            frames = video_data.frames

        # Get all object IDs from the first frame
        initial_segments = segmentation_provider.get(frames[0].index)
        object_ids = list(initial_segments.keys()) if not isinstance(initial_segments, LazySegments) else list(initial_segments.keys())

        if not object_ids:
            raise ValueError("First frame of the video contains no objects")

        return FrameObjectSample(
            selected_frames=frames,
            target_objects=object_ids
        )

