import fnmatch
import logging
import os
import re
import sys
from . import DistlibException
from .compat import fsdecode
from .util import convert_path

__all__ = ['Manifest']
logger = logging.getLogger(__name__)

# Precompile regex patterns for efficiency
_PATTERN_MAP = {
    'include': 'include',
    'exclude': 'exclude', 
    'global-include': 'global-include',
    'global-exclude': 'global-exclude',
    'recursive-include': 'recursive-include',
    'recursive-exclude': 'recursive-exclude',
    'graft': 'graft',
    'prune': 'prune'
}

class Manifest(object):
    """
    A list of files built by exploring the filesystem and filtered by applying various
    patterns to what we find there.
    """
    def __init__(self, base=None):
        """Initialize an instance."""
        self.base_dir = os.path.abspath(os.path.normpath(base or os.getcwd()))
        self._file_set = set()
        self._discovered_files = []
        self._prefix_path = self.base_dir + os.sep

    # Public API methods
    def find_all(self):
        """Find all files under the base directory and store them."""
        from stat import S_ISREG, S_ISDIR, S_ISLNK

        self._discovered_files.clear()
        traversal_stack = [self.base_dir]

        while traversal_stack:
            current_dir = traversal_stack.pop()
            try:
                entries = os.listdir(current_dir)
            except OSError:
                continue

            for entry in entries:
                full_path = os.path.join(current_dir, entry)
                try:
                    file_stat = os.stat(full_path)
                    if S_ISREG(file_stat.st_mode):
                        self._discovered_files.append(fsdecode(full_path))
                    elif S_ISDIR(file_stat.st_mode) and not S_ISLNK(file_stat.st_mode):
                        traversal_stack.append(full_path)
                except OSError:
                    continue

    def add_file(self, path):
        """Add a single file to the manifest."""
        normalized = os.path.normpath(path)
        if not normalized.startswith(self._prefix_path):
            normalized = os.path.normpath(os.path.join(self.base_dir, path))
        self._file_set.add(normalized)

    def add_multiple(self, paths):
        """Add multiple files to the manifest."""
        for p in paths:
            self.add_file(p)

    def get_sorted_list(self, include_dirs=False):
        """Return sorted list of files, optionally including directories."""
        def collect_parent_dirs(directory):
            dir_set = set()
            current = directory
            while current and current != self.base_dir:
                parent = os.path.dirname(current)
                if parent == current:
                    break
                dir_set.add(parent)
                current = parent
            return dir_set

        result = set(self._file_set)
        if include_dirs:
            for f in list(result):
                result.update(collect_parent_dirs(os.path.dirname(f)))

        # Sort by path components
        sorted_paths = []
        for path in result:
            parts = tuple(os.path.split(path))
            sorted_paths.append(parts)
        sorted_paths.sort()

        return [os.path.join(*parts) for parts in sorted_paths]

    def reset(self):
        """Clear all collected files."""
        self._file_set.clear()
        self._discovered_files.clear()

    def apply_directive(self, directive_text):
        """Process a directive string to modify the manifest."""
        action, patterns, target_dir, dir_pattern = self._validate_directive(directive_text)

        if action == 'include':
            found_any = False
            for pattern in patterns:
                if self._apply_include(pattern, anchored=True):
                    found_any = True
            if not found_any:
                logger.warning('no files matched pattern %r', patterns[0] if patterns else '')

        elif action == 'exclude':
            for pattern in patterns:
                self._apply_exclude(pattern, anchored=True)

        elif action == 'global-include':
            found_any = False
            for pattern in patterns:
                if self._apply_include(pattern, anchored=False):
                    found_any = True
            if not found_any:
                logger.warning('no files matched pattern %r anywhere', patterns[0] if patterns else '')

        elif action == 'global-exclude':
            for pattern in patterns:
                self._apply_exclude(pattern, anchored=False)

        elif action == 'recursive-include':
            found_any = False
            for pattern in patterns:
                if self._apply_include(pattern, prefix=target_dir):
                    found_any = True
            if not found_any:
                logger.warning('no files matched pattern %r under %r', 
                              patterns[0] if patterns else '', target_dir)

        elif action == 'recursive-exclude':
            for pattern in patterns:
                self._apply_exclude(pattern, prefix=target_dir)

        elif action == 'graft':
            if not self._apply_include(None, prefix=dir_pattern):
                logger.warning('no directories matched %r', dir_pattern)

        elif action == 'prune':
            if not self._apply_exclude(None, prefix=dir_pattern):
                logger.warning('no directories matched %r for pruning', dir_pattern)

    # Private validation method
    def _validate_directive(self, directive_text):
        """Parse and validate a directive string."""
        tokens = directive_text.split()
        if len(tokens) == 0:
            raise DistlibException('empty directive')

        # Default action if none specified
        if tokens[0] not in _PATTERN_MAP:
            tokens.insert(0, 'include')

        action = tokens[0]
        patterns = None
        target_dir = None
        dir_pattern = None

        if action in ('include', 'exclude', 'global-include', 'global-exclude'):
            if len(tokens) < 2:
                raise DistlibException('%s requires at least one pattern' % action)
            patterns = [convert_path(t) for t in tokens[1:]]

        elif action in ('recursive-include', 'recursive-exclude'):
            if len(tokens) < 3:
                raise DistlibException('%s requires directory and patterns' % action)
            target_dir = convert_path(tokens[1])
            patterns = [convert_path(t) for t in tokens[2:]]

        elif action in ('graft', 'prune'):
            if len(tokens) != 2:
                raise DistlibException('%s requires exactly one directory pattern' % action)
            dir_pattern = convert_path(tokens[1])

        else:
            raise DistlibException('unknown action %s' % action)

        return action, patterns, target_dir, dir_pattern

    def _apply_include(self, pattern, anchored=True, prefix=None):
        """Include files matching pattern."""
        if self._discovered_files is None or len(self._discovered_files) == 0:
            self.find_all()

        pattern_regex = self._compile_pattern(pattern, anchored, prefix)
        matched = False

        for filepath in self._discovered_files:
            if pattern_regex.search(filepath):
                self._file_set.add(filepath)
                matched = True

        return matched

    def _apply_exclude(self, pattern, anchored=True, prefix=None):
        """Exclude files matching pattern."""
        pattern_regex = self._compile_pattern(pattern, anchored, prefix)
        matched = False

        for filepath in list(self._file_set):
            if pattern_regex.search(filepath):
                self._file_set.discard(filepath)
                matched = True

        return matched

    def _compile_pattern(self, pattern, anchored=True, prefix=None):
        """Compile pattern into a regex."""
        if pattern is None:
            # For graft/prune actions where pattern is None
            if prefix:
                return re.compile(re.escape(prefix) + r'(?:/|$)')
            else:
                return re.compile(r'^$')

        # Convert glob pattern to regex
        regex_str = self._glob_to_regex(pattern)

        # Handle anchoring
        if anchored:
            base_escaped = re.escape(self.base_dir + os.sep)
            regex_str = '^' + base_escaped + regex_str

        # Handle prefix
        if prefix:
            prefix_regex = self._glob_to_regex(prefix)
            base_escaped = re.escape(self.base_dir + os.sep)

            # Remove anchors from both patterns
            if regex_str.startswith('^'):
                regex_str = regex_str[1:]
            if regex_str.endswith('$'):
                regex_str = regex_str[:-1]
            if prefix_regex.startswith('^'):
                prefix_regex = prefix_regex[1:]
            if prefix_regex.endswith('$'):
                prefix_regex = prefix_regex[:-1]

            # Combine prefix and pattern with wildcard between
            sep = r'[\\/]' if os.sep == '\\' else os.sep
            regex_str = base_escaped + prefix_regex + r'.*' + sep + regex_str

        return re.compile(regex_str)

    def _glob_to_regex(self, glob_pattern):
        """Convert glob pattern to regex."""
        # Use fnmatch.translate and then adjust for special characters
        regex = fnmatch.translate(glob_pattern)

        # Make * and ? not match path separators
        sep = os.sep
        if sep == '\\':
            sep = r'\\\\'

        # Replace unescaped dots with character classes excluding separator
        regex = re.sub(
            r'((?<!\\)(\\\\)*)\.', 
            r'\1[^%s]' % sep, 
            regex
        )

        return regex

