def format_timestamp():
    """Return current time as formatted string: YYYY-MM-DD HH:MM:SS"""
    return time.strftime('%Y-%m-%d %H:%M:%S', time.localtime())

def format_datestamp():
    """Return current date as formatted string: YYYY-MM-DD"""
    return time.strftime('%Y-%m-%d', time.localtime())

def warn_once(message):
    """Log a warning message only once per unique message string"""
    if message not in WARNED_MESSAGES:
        logger.warning(message)
        WARNED_MESSAGES[message] = True

def demo_log(message):
    """Log a demo message prefixed with 'DEMO:'"""
    logger.info(f"DEMO: {message}")

def cleanup_old_logs(base_path, max_age_days):
    """Remove log files older than specified days"""
    current_time = datetime.datetime.now()

    for dirpath, _, filenames in os.walk(base_path):
        for filename in filenames:
            if filename.startswith(LOG_FILE_PREFIX):
                full_path = os.path.join(dirpath, filename)
                file_mtime = datetime.datetime.fromtimestamp(os.path.getmtime(full_path))
                age_in_days = (current_time - file_mtime).days

                if age_in_days > max_age_days:
                    if DEBUG_MODE:
                        print(f"Log Cleanup: Removing '{full_path}' (last modified: {file_mtime}, {age_in_days} days ago)")
                    try:
                        os.remove(full_path)
                    except OSError as e:
                        if DEBUG_MODE:
                            print(f"Error deleting file {full_path}: {e}")

