# Helper formatting functions
def hr_header(title, level=3):
    """Print a formatted header line"""
    title_str = str(title).upper()

    if level == 1:
        logger.info('=' * 20 + ' ' + title_str + ' ' + '=' * 20)
    elif level == 2:
        logger.info('-' * 20 + ' ' + title_str + ' ' + '-' * 20)
    elif level == 3:
        logger.info('<' * 3 + ' ' + title_str + ' ' + '>' * 3)
    elif level == 0:
        content = '|' + ' ' * 20 + title_str + ' ' * 20 + '|'
        border = '+' + '-' * (len(content) - 2) + '+'
        logger.info(border)
        logger.info(content)
        logger.info(border)

def log_attribute(name, value):
    """Log a key-value pair in bracketed format"""
    logger.info('[%s] %s' % (str(name), str(value)))

def log_aligned_attr(name, value, prefix='', width=22):
    """Log an attribute with right-aligned name field"""
    name_str = str(name).rjust(width)
    if prefix:
        name_str = prefix + name_str[len(prefix):]
    logger.info('%s: %s' % (name_str, str(value)))

# Attach helper methods to logger instance
logger.hr = types.MethodType(hr_header, logger)
logger.attr = types.MethodType(log_attribute, logger)
logger.attr_align = types.MethodType(log_aligned_attr, logger)

