import uuid
import chardet
from bs4 import BeautifulSoup, NavigableString, Tag, Comment
import html

# Helper: detect encoding from raw bytes
def detect_file_encoding(path=None, data=None):
    if data is not None:
        return chardet.detect(data).get('encoding', 'utf-8')
    with open(path, 'rb') as f:
        raw = f.read()
    return chardet.detect(raw)['encoding']

# Mapping for heading prefixes
HEADING_MARKDOWN_PREFIX = {
    "h1": "#", "h2": "##", "h3": "###",
    "h4": "####", "h5": "#####", "h6": "######"
}

# Block-level HTML elements that should be treated as separate sections
SECTIONABLE_TAGS = {
    "h1", "h2", "h3", "h4", "h5", "h6",
    "p", "div", "article", "section", "aside",
    "ul", "ol", "li", "table", "pre", "code",
    "blockquote", "figure", "figcaption"
}


class RAGHtmlProcessor:
    def __call__(self, filepath=None, binary_data=None, max_tokens_per_chunk=512):
        # Load content depending on input type
        if binary_data:
            enc = self._detect_encoding_from_bytes(binary_data)
            text = binary_data.decode(enc, errors='ignore')
        else:
            enc = detect_file_encoding(path=filepath)
            with open(filepath, 'r', encoding=enc, errors='ignore') as fp:
                text = fp.read()
        return self._process_text(text, max_tokens_per_chunk)

    @staticmethod
    def _detect_encoding_from_bytes(data):
        try:
            return chardet.detect(data)['encoding'] or 'utf-8'
        except Exception:
            return 'utf-8'

    @classmethod
    def _process_text(cls, raw_html, chunk_limit):
        if not isinstance(raw_html, str):
            raise TypeError("Input must be a string.")

        soup = BeautifulSoup(raw_html, "html.parser")

        # Remove script/style tags and attributes
        for tag in soup.find_all(['script', 'style']):
            tag.decompose()
        for div in soup.find_all('div'):
            for s in div.find_all('script'):
                s.decompose()
        for elem in soup.find_all(True):
            elem.attrs.pop('style', None)
        for comment in soup.find_all(string=lambda t: isinstance(t, Comment)):
            comment.extract()

        # Extract structured blocks
        extracted_blocks = []
        cls._traverse_tree(soup.body or soup, extracted_blocks, chunk_limit)

        # Merge adjacent content under same block ID
        merged_blocks, tables = cls._group_by_block_id(extracted_blocks)

        # Split large blocks into chunks
        final_chunks = cls._split_into_chunks(merged_blocks, chunk_limit)

        # Append table contents as standalone items
        for tbl in tables:
            final_chunks.append(tbl.get("content", ""))

        return final_chunks

    @classmethod
    def _traverse_tree(cls, node, collector, limit, parent_tag=None, current_block_id=None):
        if isinstance(node, NavigableString):
            txt = str(node).strip()
            if not txt:
                return []

            # Check if it contains embedded HTML
            try:
                inner_soup = BeautifulSoup(txt, "html.parser")
                has_html = bool(inner_soup.find())
            except Exception:
                has_html = False

            if has_html:
                result = []
                cls._traverse_tree(inner_soup, result, limit, parent_tag, current_block_id)
                return result
            else:
                info = {
                    "text": txt,
                    "type": parent_tag or "inner_text",
                    "meta": {"block_id": current_block_id}
                }
                return [info]

        elif isinstance(node, Tag):
            tag_name = node.name.lower()
            new_block_id = None
            if tag_name in SECTIONABLE_TAGS:
                new_block_id = str(uuid.uuid4())

            results = []
            for child in node.children:
                sub_results = cls._traverse_tree(child, [], limit, tag_name, new_block_id)
                results.extend(sub_results)
            return results

        return []

    @classmethod
    def _group_by_block_id(cls, items):
        grouped = []
        current_text = ""
        last_id = None
        tables = []

        for item in items:
            text = item["text"]
            tag = item["type"]
            bid = item["meta"]["block_id"]

            is_title = tag in HEADING_MARKDOWN_PREFIX

            if bid is not None:
                if is_title:
                    text = f"{HEADING_MARKDOWN_PREFIX[tag]} {text}"

                if last_id != bid:
                    if last_id is not None:
                        grouped.append(current_text)
                    current_text = text
                    last_id = bid
                else:
                    current_text += (" " if current_text else "") + text
            else:
                if tag == "table":
                    tables.append(item)
                else:
                    current_text += (" " if current_text else "") + text

        if current_text:
            grouped.append(current_text)

        return grouped, tables

    @staticmethod
    def _tokenize(text):
        # Placeholder — assumes rag_tokenizer.tokenize exists elsewhere
        from app.core.rag.nlp import rag_tokenizer
        return rag_tokenizer.tokenize(text)

    @classmethod
    def _split_into_chunks(cls, paragraphs, token_limit):
        output = []
        buffer = ""
        buffer_tokens = 0

        for para in paragraphs:
            tokens_str = cls._tokenize(para)
            para_tokens = len(tokens_str.split()) if tokens_str else 0

            if para_tokens > token_limit:
                if buffer:
                    output.append(buffer)
                    buffer = ""
                    buffer_tokens = 0

                token_list = tokens_str.split()
                idx = 0
                while idx < len(token_list):
                    segment = token_list[idx:idx + token_limit]
                    output.append(" ".join(segment))
                    idx += token_limit
            else:
                if buffer_tokens + para_tokens <= token_limit:
                    buffer += ("\n" if buffer else "") + para
                    buffer_tokens += para_tokens
                else:
                    output.append(buffer)
                    buffer = para
                    buffer_tokens = para_tokens

        if buffer:
            output.append(buffer)

        return output

    @staticmethod
    def _extract_tables(html_content, max_tokens=512):
        soup = BeautifulSoup(html_content, "html.parser")
        rows = soup.find_all("tr")
        groups = []
        current_group = []
        count = 0

        for row in rows:
            row_str = str(row)
            tokens = len(RAGHtmlProcessor._tokenize(row_str).split())
            if count + tokens > max_tokens:
                groups.append(current_group)
                current_group = []
                count = 0
            current_group.append(row)
            count += tokens

        if current_group:
            groups.append(current_group)

        result = []
        for group in groups:
            new_table = soup.new_tag("table")
            for r in group:
                new_table.append(r)
            result.append(str(new_table))
        return result

