import string
import pandas as pd
from mindspeed_mm.tasks.evaluation.eval_datasets.datasets_base import BaseEvalDataset
from mindspeed_mm.tasks.evaluation.utils.string_utils import string_to_list, is_expected_type

class MMMUEvalDataset(BaseEvalDataset):
    def __init__(self, dataset_path, dataset_name):
        super().__init__(dataset_path, dataset_name)

    @staticmethod
    def parse_MMMU_input(message_list):
        text_content = None
        image_refs = []

        # Separate images and text from the input messages
        for item in message_list:
            if item['type'] == 'image':
                image_refs.append(item['value'])
            elif item['type'] == 'text':
                if text_content is not None:
                    raise ValueError("Multiple text messages encountered")
                text_content = item['value']

        # Handle case with no image tags
        if '<image ' not in text_content:
            return message_list

        # Split by image tag pattern
        parts = text_content.split('<image ')
        result_segments = [dict(type='text', value=parts[0])]

        # Process each image tag segment
        for idx, fragment in enumerate(parts):
            if idx == 0:
                continue

            # Validate format: must start with digit followed by '>'
            if not (is_expected_type(fragment[0], int) and fragment[1] == '>'):
                raise ValueError("Malformed image reference tag")

            # Extract image index (convert to 0-based)
            img_index = int(fragment[0]) - 1
            result_segments.append(dict(type='image', value=image_refs[img_index]))
            result_segments.append(dict(type='text', value=fragment[2:]))

        return result_segments

    def _construct_prompt(self, sample):
        # Handle integer index or full row input
        if isinstance(sample, int):
            sample = self.data.iloc[sample]

        # Determine image paths
        if self.meta_only:
            image_paths = string_to_list(sample['image_path'])
        else:
            image_paths = self.dump_image(sample)

        # Build question and options
        question_text = sample['question']
        answer_choices = {
            letter: sample[letter]
            for letter in string.ascii_uppercase
            if letter in sample and not pd.isna(sample[letter])
        }

        # Format options section
        options_section = 'Options:\n'
        for choice_letter, choice_text in answer_choices.items():
            options_section += f'{choice_letter}. {choice_text}\n'

        # Add hint if available
        hint_text = sample.get('hint')
        if hint_text is not None and not pd.isna(hint_text):
            prompt = f'Hint: {hint_text}\n'
        else:
            prompt = ''

        # Add question and options
        prompt += f'Question: {question_text}\n'
        if answer_choices:
            prompt += options_section
            prompt += 'Please select the correct answer from the options above. \n'

        # Construct message list
        messages = []
        if isinstance(image_paths, list):
            messages.extend([dict(type='image', value=path) for path in image_paths])
        else:
            messages = [dict(type='image', value=image_paths)]

        messages.append(dict(type='text', value=prompt))
        return messages

    def create_prompt(self, sample):
        base_messages = self._construct_prompt(sample)
        final_messages = self.parse_MMMU_input(base_messages)
        return final_messages

