    if prefill_context_parallel_size is not None:
        config["prefill_context_parallel_size"] = prefill_context_parallel_size
    if decode_context_parallel_size is not None:
        config["decode_context_parallel_size"] = decode_context_parallel_size

    if speculative_config is not None:
        config["speculative_config"] = speculative_config
    if compilation_config is not None:
        config["compilation_config"] = compilation_config

    return config


