import json
import sys

class BaseModel(object):
    """Parent class for all data models."""

    def _convert_to_dict(self, skip_none=True):
        """Convert object to dictionary representation, optionally excluding None values."""
        def traverse(item):
            if isinstance(item, BaseModel):
                attributes = vars(item)
                result = {}
                for key in attributes:
                    value = traverse(attributes[key])
                    if skip_none and value is None:
                        continue
                    # Capitalize first letter of key (camelCase conversion)
                    formatted_key = key[0].upper() + key[1:] if key else ""
                    result[formatted_key] = value
                return result
            elif isinstance(item, list):
                processed_items = [traverse(element) for element in item]
                return [item for item in processed_items if not (skip_none and item is None)]
            else:
                # Handle string encoding for Python 2 compatibility
                if isinstance(item, str if sys.version_info[0] >= 3 else unicode) and sys.version_info[0] == 2:
                    return item.encode("UTF-8")
                return item

        return traverse(self)

    def _parse_from_dict(self, data):
        """Initialize object from dictionary data."""
        return None

    def to_json(self, *args, **kwargs):
        """Serialize object to JSON string with Unicode support."""
        if "ensure_ascii" not in kwargs:
            kwargs["ensure_ascii"] = False
        return json.dumps(self._convert_to_dict(skip_none=False), *args, **kwargs)

    def load_from_json(self, json_text):
        """Deserialize object from JSON string."""
        data = json.loads(json_text)
        self._parse_from_dict(data)

    def __str__(self):
        return "%s" % self.to_json()

