def _is_valid_smiles_pattern(input_str):
    """Heuristic check for SMILES-like patterns."""
    if not input_str:
        return "ambiguous"

    # Check for common SMILES features
    has_parentheses = '(' in input_str or ')' in input_str
    has_brackets = '[' in input_str or ']' in input_str
    has_double_bonds = '=' in input_str
    has_stereochemistry = '@' in input_str
    has_ring_numbers = any(c.isdigit() for c in input_str)

    # Count aromatic rings (pattern like c1ccccc1)
    aromatic_count = sum(1 for c in input_str.lower() if c == 'c') + sum(1 for c in input_str.lower() if c == 'n')

    # Determine type based on heuristics
    if has_parentheses or has_brackets or has_double_bonds or has_stereochemistry:
        return "smiles"

    if has_ring_numbers and aromatic_count >= 4:
        return "ambiguous"  # Could be SMILES ring or something else

    # Check for IUPAC naming patterns
    iupac_suffixes = ('-ol', '-one', '-oic acid', '-al', '-amine', 'acid')
    if any(input_str.lower().endswith(suffix) for suffix in iupac_suffixes):
        return "iupac"

    # Check for common drug names or names with spaces
    if ' ' in input_str or input_str.lower() in ['aspirin', 'caffeine']:
        return "iupac"

    # Short strings are ambiguous (could be abbreviations)
    if len(input_str) <= 3:
        return "ambiguous"

    return "iupac"


class TestDetectInputTypeRefactored:
