import re
from typing import List, Dict, Any, Optional

class NetworkCommDetector:
    """Enhanced network communication pattern detector."""

    # Precompiled regex patterns for performance
    URL_PATTERN = re.compile(r'(https?|ftp)://[^\s]+')
    IPV4_PATTERN = re.compile(r'\b(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\b')
    IPV6_PATTERN = re.compile(r'\b(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}\b|\b(?:[0-9a-fA-F]{1,4}:){1,7}:|(?:[0-9a-fA-F]{1,4}:){1,6}:[0-9a-fA-F]{1,4}|(?:[0-9a-fA-F]{1,4}:){1,5}(?::[0-9a-fA-F]{1,4}){1,2}|(?:[0-9a-fA-F]{1,4}:){1,4}(?::[0-9a-fA-F]{1,4}){1,3}|(?:[0-9a-fA-F]{1,4}:){1,3}(?::[0-9a-fA-F]{1,4}){1,4}|(?:[0-9a-fA-F]{1,4}:){1,2}(?::[0-9a-fA-F]{1,4}){1,5}|[0-9a-fA-F]{1,4}:(?:(?::[0-9a-fA-F]{1,4}){1,6})|:(?:(?::[0-9a-fA-F]{1,4}){1,7}|:)\b')
    DOMAIN_PATTERN = re.compile(r'\b[a-zA-Z0-9][a-zA-Z0-9-]*\.[a-zA-Z]{2,}\b')
    SUSPICIOUS_TLDS = {'.tk', '.ml', '.ga', '.cf', '.gq', '.xyz', '.top'}
    NETWORK_LIBS = {'socket', 'urllib', 'requests', 'paramiko', 'http.client', 'ftplib'}
    CRITICAL_LIBS = {'socket', 'paramiko', 'asyncio', 'websockets'}
    SENSITIVE_FUNCS = {
        'socket.connect', 'socket.bind', 'socket.listen', 
        'requests.post', 'requests.get', 'urlopen', 'urllib.request.urlopen',
        'ftp.connect', 'ftplib.FTP.connect'
    }
    CC_KEYWORDS = ['beacon', 'callback', 'c2', 'command', 'control', 'backdoor', 'botnet', 'zombie']
    SUSPICIOUS_PORTS = {1337, 4444, 6666, 31337, 1234, 8080, 443, 22, 21, 23, 3389, 5900, 6379, 27017}

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.findings = []
        self.custom_patterns = set()
        self.blacklist = set()

        if config:
            if 'custom_cc_patterns' in config:
                self.custom_patterns.update(p.lower() for p in config['custom_cc_patterns'])
            if 'custom_blacklist' in config:
                self.blacklist.update(d.lower() for d in config['custom_blacklist'])

    def scan(self, data: bytes, context: str = "") -> List[Dict[str, Any]]:
        """Main scanning method that orchestrates all detection techniques."""
        text_data = data.decode('utf-8', errors='ignore')
        self.findings = []

        # Run all detection methods
        self._scan_urls(text_data, context)
        self._scan_ipv4_addresses(text_data, context)
        self._scan_ipv6_addresses(text_data, context)
        self._scan_domains(text_data, context)
        self._scan_network_libraries(text_data, context)
        self._scan_network_functions(text_data, context)
        self._scan_cc_patterns(text_data, context)
        self._scan_suspicious_ports(text_data, context)
        self._scan_blacklisted_domains(text_data, context)

        return self.findings

    def _add_finding(self, finding_type: str, details: Dict[str, Any], context: str):
        """Helper to add a finding with proper structure."""
        self.findings.append({
            "type": finding_type,
            "context": context,
            **details
        })

    def _extract_snippet(self, text: str, position: int, length: int = 60) -> str:
        """Extract surrounding context around a match."""
        start = max(0, position - length // 2)
        end = min(len(text), position + length // 2)
        snippet = text[start:end].strip()
        return snippet.replace('\n', ' ')[:100]

    def _scan_urls(self, text: str, context: str):
        """Scan for URLs in the text."""
        for match in self.URL_PATTERN.finditer(text):
            url = match.group(0)
            confidence = 0.7

            # Check for suspicious ports in URLs
            if ':1337' in url or ':4444' in url or ':6666' in url:
                confidence = 0.9

            self._add_finding("url_detected", {
                "url": url,
                "confidence": confidence,
                "severity": "MEDIUM" if confidence < 0.8 else "HIGH"
            }, context)

    def _scan_ipv4_addresses(self, text: str, context: str):
        """Scan for IPv4 addresses and classify them."""
        for match in self.IPV4_PATTERN.finditer(text):
            ip = match.group(0)
            octets = list(map(int, ip.split('.')))

            # Determine IP classification
            is_private = (
                (octets[0] == 10) or
                (octets[0] == 172 and 16 <= octets[1] <= 31) or
                (octets[0] == 192 and octets[1] == 168)
            )

            is_global = not is_private and not (
                octets[0] == 127 or  # Loopback
                (octets[0] == 169 and octets[1] == 254)  # Link-local
            )

            confidence = 0.5 if is_private else 0.8

            self._add_finding("ipv4_address", {
                "ip": ip,
                "is_private": is_private,
                "is_global": is_global,
                "confidence": confidence,
                "severity": "LOW" if is_private else "MEDIUM"
            }, context)

    def _scan_ipv6_addresses(self, text: str, context: str):
        """Scan for IPv6 addresses."""
        for match in self.IPV6_PATTERN.finditer(text):
            ip = match.group(0)
            self._add_finding("ipv6_address", {
                "ip": ip,
                "confidence": 0.7,
                "severity": "LOW"
            }, context)

    def _scan_domains(self, text: str, context: str):
        """Scan for domain names and assess risk."""
        for match in self.DOMAIN_PATTERN.finditer(text):
            domain = match.group(0).lower()
            tld = '.' + domain.split('.')[-1]

            # Check for suspicious TLDs
            is_suspicious = tld in self.SUSPICIOUS_TLDS

            # Check against blacklist
            is_blacklisted = domain in self.blacklist

            if is_blacklisted:
                confidence = 1.0
                severity = "CRITICAL"
            elif is_suspicious:
                confidence = 0.85
                severity = "HIGH"
            else:
                confidence = 0.5
                severity = "LOW"

            self._add_finding("domain_name", {
                "domain": domain,
                "tld": tld,
                "confidence": confidence,
                "severity": severity,
                "is_suspicious": is_suspicious,
                "is_blacklisted": is_blacklisted
            }, context)

    def _scan_network_libraries(self, text: str, context: str):
        """Scan for network library imports."""
        for lib in self.NETWORK_LIBS:
            pattern = re.compile(rf'\bimport\s+{lib}\b|\bfrom\s+{lib}\b', re.IGNORECASE)
            if pattern.search(text):
                severity = "CRITICAL" if lib in self.CRITICAL_LIBS else "MEDIUM"
                self._add_finding("network_library", {
                    "library": lib,
                    "confidence": 0.9,
                    "severity": severity
                }, context)

    def _scan_network_functions(self, text: str, context: str):
        """Scan for network function calls."""
        for func in self.SENSITIVE_FUNCS:
            pattern = re.compile(rf'{func}\s*\(', re.IGNORECASE)
            for match in pattern.finditer(text):
                self._add_finding("network_function", {
                    "function": func,
                    "snippet": self._extract_snippet(text, match.start()),
                    "confidence": 0.85,
                    "severity": "HIGH"
                }, context)

    def _scan_cc_patterns(self, text: str, context: str):
        """Scan for command & control indicators."""
        text_lower = text.lower()

        # Check for custom C&C patterns
        for pattern in self.custom_patterns:
            if pattern in text_lower:
                self._add_finding("cc_pattern", {
                    "pattern": pattern,
                    "snippet": self._extract_snippet(text, text_lower.find(pattern)),
                    "confidence": 0.95,
                    "severity": "CRITICAL"
                }, context)

        # Check for standard C&C keywords
        for keyword in self.CC_KEYWORDS:
            if keyword in text_lower:
                self._add_finding("cc_pattern", {
                    "pattern": keyword,
                    "snippet": self._extract_snippet(text, text_lower.find(keyword)),
                    "confidence": 0.9,
                    "severity": "CRITICAL"
                }, context)

    def _scan_suspicious_ports(self, text: str, context: str):
        """Scan for suspicious port numbers."""
        port_pattern = re.compile(r':(\d+)\b')
        for match in port_pattern.finditer(text):
            port = int(match.group(1))
            if port in self.SUSPICIOUS_PORTS:
                self._add_finding("suspicious_port", {
                    "port": port,
                    "confidence": 0.8,
                    "severity": "HIGH" if port in {1337, 4444, 31337} else "MEDIUM"
                }, context)

    def _scan_blacklisted_domains(self, text: str, context: str):
        """Scan for blacklisted domains."""
        for domain in self.blacklist:
            if domain in text.lower():
                self._add_finding("blacklisted_domain", {
                    "domain": domain,
                    "confidence": 1.0,
                    "severity": "CRITICAL"
                }, context)


def detect_network_communication(file_path: str, config: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:
    """Convenience function to scan a file for network patterns."""
    try:
        with open(file_path, 'rb') as f:
            data = f.read()
        detector = NetworkCommDetector(config)
        return detector.scan(data, file_path)
    except FileNotFoundError:
        return [{
            "type": "error",
            "message": f"File not found: {file_path}",
            "severity": "CRITICAL"
        }]
    except Exception as e:
        return [{
            "type": "error",
            "message": f"Error reading file: {str(e)}",
            "severity": "CRITICAL"
        }]

