def create_navit_attention_masks(
    batch_size: int,
    original_context_length_list: list,
    history_context_length: int,
    encoder_hidden_states_seq_len: int,
    device: torch.device,
    restrict_self_attn: bool = False,
    guidance_cross_attn: bool = False,
):
    # Prepare self-attention masks
    if restrict_self_attn:
        # Compute cumulative sequence lengths for queries
        cumsum_q = [0]
        for _ in range(batch_size):
            for length in original_context_length_list:
                cumsum_q.append(cumsum_q[-1] + length)
        cumsum_q = torch.tensor(cumsum_q, device=device, dtype=torch.int32)
        max_seqlen_q = max(original_context_length_list)

        # Compute cumulative sequence lengths for keys/values
        cumsum_kv = [0]
        for _ in range(batch_size):
            for length in original_context_length_list:
                cumsum_kv.append(cumsum_kv[-1] + length + history_context_length)
        cumsum_kv = torch.tensor(cumsum_kv, device=device, dtype=torch.int32)
        max_seqlen_kv = max(original_context_length_list) + history_context_length
    else:
        # Shared cumulative sequence lengths
        cumsum_kv = [0]
        for _ in range(batch_size):
            for length in original_context_length_list:
                cumsum_kv.append(cumsum_kv[-1] + length + history_context_length)
        cumsum_kv = torch.tensor(cumsum_kv, device=device, dtype=torch.int32)
        max_seqlen_kv = max(original_context_length_list) + history_context_length
        cumsum_q = cumsum_kv
        max_seqlen_q = max_seqlen_kv

    navit_hidden_attention_mask = (cumsum_q, cumsum_kv, max_seqlen_q, max_seqlen_kv)

    # Prepare history attention masks
    navit_history_hidden_attention_mask = None
    if restrict_self_attn:
        cumsum_kv = [0]
        for _ in range(batch_size):
            for length in original_context_length_list:
                cumsum_kv.append(cumsum_kv[-1] + history_context_length)
        cumsum_kv = torch.tensor(cumsum_kv, device=device, dtype=torch.int32)
        max_seqlen_kv = history_context_length
        cumsum_q = cumsum_kv
        max_seqlen_q = max_seqlen_kv
        navit_history_hidden_attention_mask = (cumsum_q, cumsum_kv, max_seqlen_q, max_seqlen_kv)

    # Prepare cross-attention masks
    if guidance_cross_attn:
        cross_cumsum_q = [0]
        for _ in range(batch_size):
            for length in original_context_length_list:
                cross_cumsum_q.append(cross_cumsum_q[-1] + length)
        cross_cumsum_q = torch.tensor(cross_cumsum_q, device=device, dtype=torch.int32)
        cross_max_seqlen_q = max(original_context_length_list)
    else:
        cross_cumsum_q = [0]
        for _ in range(batch_size):
            for length in original_context_length_list:
                cross_cumsum_q.append(cross_cumsum_q[-1] + length + history_context_length)
        cross_cumsum_q = torch.tensor(cross_cumsum_q, device=device, dtype=torch.int32)
        cross_cumsum_q[0] = 0
        cross_max_seqlen_q = max(original_context_length_list) + history_context_length

    # KV cumulative sequence lengths for cross-attention
    kv_cumsum = [0]
    for _ in range(batch_size):
        for length in original_context_length_list:
            kv_cumsum.append(kv_cumsum[-1] + encoder_hidden_states_seq_len)
    kv_cumsum = torch.tensor(kv_cumsum, device=device, dtype=torch.int32)
    kv_max_seqlen = encoder_hidden_states_seq_len

    navit_encoder_attention_mask = (cross_cumsum_q, kv_cumsum, cross_max_seqlen_q, kv_max_seqlen)

    return navit_hidden_attention_mask, navit_encoder_attention_mask, navit_history_hidden_attention_mask

@torch.compiler.disable
def _flash_wrapper(q, k, v):
    return flash_attn_func(q, k, v)

@torch.compiler.disable
def _flash_varlen_wrapper(q, k, v, cu_seqlens_q, cu_seqlens_kv, max_seqlen_q, max_seqlen_kv):
    return flash_attn_varlen_func(q, k, v, cu_seqlens_q, cu_seqlens_kv, max_seqlen_q, max_seqlen_kv)

def attn_varlen_func(q, k, v, attention_mask=None):
    if attention_mask is None:
        # Standard (non-padded) attention path
        if flash_attn_func is not None:
            return _flash_wrapper(q, k, v)
        elif sageattn is not None:
            return sageattn(q, k, v, tensor_layout="NHD")
        elif xformers_attn_func is not None:
            return xformers_attn_func(q, k, v)
        else:
            # Fallback to PyTorch's scaled_dot_product_attention
            return torch.nn.functional.scaled_dot_product_attention(
                q.transpose(1, 2), k.transpose(1, 2), v.transpose(1, 2)
            ).transpose(1, 2)

    # Padded attention path
    B, L, H, C = q.shape
    q_flat = q.flatten(0, 1)
    k_flat = k.flatten(0, 1)
    v_flat = v.flatten(0, 1)

    cu_seqlens_q, cu_seqlens_kv, max_seqlen_q, max_seqlen_kv = attention_mask

    if flash_attn_varlen_func is not None:
        output = _flash_varlen_wrapper(q_flat, k_flat, v_flat, 
                                       cu_seqlens_q, cu_seqlens_kv, 
                                       max_seqlen_q, max_seqlen_kv)
    elif sageattn_varlen is not None:
        output = sageattn_varlen(q_flat, k_flat, v_flat, 
                                 cu_seqlens_q, cu_seqlens_kv, 
                                 max_seqlen_q, max_seqlen_kv)
    else:
        raise NotImplementedError("No varlen attention implementation is available!")

    return output.unflatten(0, (B, L))

# Function to find prime numbers less than a given non-negative integer

def get_primes_below(n):
    """Returns a list of the first prime numbers that are less than n.

    Examples:
    get_primes_below(5) => [2, 3]
    get_primes_below(11) => [2, 3, 5, 7]
    get_primes_below(0) => []
    get_primes_below(20) => [2, 3, 5, 7, 11, 13, 17, 19]
    get_primes_below(1) => []
    get_primes_below(18) => [2, 3, 5, 7, 11, 13, 17]
    """
    if n <= 2:
        return []

    def check_prime(value):
        if value < 2:
            return False
        if value == 2:
            return True
        if value % 2 == 0:
            return False
        divisor = 3
        while divisor * divisor <= value:
            if value % divisor == 0:
                return False
            divisor += 2
        return True

    result = []
    candidate = 2
    while candidate < n:
        if check_prime(candidate):
            result.append(candidate)
        candidate += 1
    return result

import logging
from jinja2.exceptions import TemplateError
from transformers import AutoTokenizer
from transformers.tokenization_utils_base import BatchEncoding

logger = logging.getLogger(__name__)

def _merge_system_into_first_user(messages):
    """Consolidate a single system message into the first user message.

    If no user message exists, creates one with the system content.
    Raises ValueError if multiple system messages are found.
    """
    system_entries = [msg for msg in messages if isinstance(msg, dict) and msg.get("role") == "system"]

    if len(system_entries) > 1:
        raise ValueError("Multiple system messages detected. Only one is allowed.")

    system_text = system_entries[0].get("content", "") if system_entries else ""

    processed = []
    inserted = False

    for msg in messages:
        if isinstance(msg, dict) and msg.get("role") == "system":
            continue

        if not inserted and isinstance(msg, dict) and msg.get("role") == "user":
            merged_content = f"{system_text}\n{msg['content']}" if system_text else msg["content"]
            processed.append({"role": "user", "content": merged_content})
            inserted = True
        else:
            processed.append(msg)

    if not inserted and system_text:
        processed.insert(0, {"role": "user", "content": system_text})

    return processed

class NeMoAutoTokenizerWithBosEosEnforced(AutoTokenizer):
    """
    Extended tokenizer wrapper that ensures consistent BOS/EOS token insertion.
    Addresses inconsistencies in certain tokenizers where special tokens may be omitted.
    """

    @classmethod
    def from_pretrained(cls, pretrained_model_name_or_path, *args, insert_bos=True, insert_eos=True, **kwargs):
        """
        Initialize tokenizer with optional BOS/EOS insertion behavior.

        Args:
            pretrained_model_name_or_path: Model identifier or path
            insert_bos: Whether to prepend BOS token (default: True)
            insert_eos: Whether to append EOS token (default: True)
        """
        tokenizer = super().from_pretrained(pretrained_model_name_or_path, *args, **kwargs)

        # Handle special_tokens_pattern issue for tokenizers missing CLS/SEP definitions
        if getattr(tokenizer, "special_tokens_pattern", None) == "cls_sep" and (
            getattr(tokenizer, "cls_token_id", None) is None or 
            getattr(tokenizer, "sep_token_id", None) is None
        ):
            tokenizer.special_tokens_pattern = "none"

        # Configure BOS token insertion
        if insert_bos and getattr(tokenizer, "bos_token", None) is not None:
            try:
                tokenizer.add_bos_token = insert_bos
            except ValueError:
                tokenizer._add_bos_token = insert_bos

        # Configure EOS token insertion
        if insert_eos and getattr(tokenizer, "eos_token", None) is not None:
            try:
                tokenizer.add_eos_token = insert_eos
            except ValueError:
                tokenizer._add_eos_token = insert_eos

        # Preserve original tokenizer class for serialization
        original_class = type(tokenizer)
        tokenizer._original_tokenizer_class = original_class
        tokenizer.__class__ = type(cls.__name__, (cls, original_class), {})

        return tokenizer

    def apply_chat_template(self, conversation, *args, **kwargs):
        has_system_message = any(isinstance(m, dict) and m.get("role") == "system" for m in conversation)

        if not has_system_message:
            return super().apply_chat_template(conversation, *args, **kwargs)

        system_messages = [m for m in conversation if isinstance(m, dict) and m.get("role") == "system"]

        if len(system_messages) > 1:
            raise ValueError("Only one system message is permitted per conversation.")

        try:
            return super().apply_chat_template(conversation, *args, **kwargs)
        except TemplateError as exc:
            if "System role not supported" not in str(exc):
                raise
            logger.debug("Template doesn't support system role; merging into first user message.")
            adjusted_conversation = _merge_system_into_first_user(conversation)
            return super().apply_chat_template(adjusted_conversation, *args, **kwargs)

    def __call__(self, *args, **kwargs):
        result = super().__call__(*args, **kwargs)

        if not kwargs.get("add_special_tokens", True):
            return result

        if isinstance(result, BatchEncoding):
            keys_to_process = {"input_ids", "attention_mask", "assistant_masks"}
            should_insert_bos = self.add_bos_token and getattr(self, "bos_token_id", None) is not None
            should_insert_eos = self.add_eos_token and getattr(self, "eos_token_id", None) is not None

            if "input_ids" not in result:
                return result

            if should_insert_bos:
                _insert_special_token(result, self.bos_token_id, 0, "input_ids")

            if should_insert_eos:
                _insert_special_token(result, self.eos_token_id, -1, "input_ids")

            for field in {"attention_mask", "assistant_masks"}:
                if field not in result:
                    continue

                if should_insert_bos:
                    _insert_special_token(result, 1, 0, field)

                if should_insert_eos:
                    _insert_special_token(result, 1, -1, field)

        return result

    def encode(self, *args, **kwargs):
        encoded = super().encode(*args, **kwargs)

        if not kwargs.get("add_special_tokens", True):
            return encoded

        bos_id = getattr(self, "bos_token_id", None)
        eos_id = getattr(self, "eos_token_id", None)

        if self.add_bos_token and bos_id is not None and (not encoded or encoded[0] != bos_id):
            encoded = [bos_id] + encoded

        if self.add_eos_token and eos_id is not None and (not encoded or encoded[-1] != eos_id):
            encoded = encoded + [eos_id]

        return encoded

    def save_pretrained(self, save_directory, push_to_hub: bool = False, **kwargs):
        # Ensure correct tokenizer_class is saved by temporarily reverting to original class
        base_class = getattr(self, "_original_tokenizer_class", None)
        if not base_class:
            return super().save_pretrained(save_directory, push_to_hub=push_to_hub, **kwargs)

        current_class = self.__class__
        try:
            self.__class__ = base_class
            return base_class.save_pretrained(self, save_directory, push_to_hub=push_to_hub, **kwargs)
        finally:
            self.__class__ = current_class

def _insert_special_token(tokenized_output, value, position, field_name):
    def _insert_at_position(sequence, val, idx, force_insert):
        if idx == 0:
            if force_insert or not sequence or sequence[0] != val:
                return [val] + sequence, True
            return sequence, False
        elif idx == -1:
            if force_insert or not sequence or sequence[-1] != val:
                return sequence + [val], True
            return sequence, False
        else:
            raise ValueError(f"Unsupported position index: {idx}")

    sequences = tokenized_output[field_name]
    force_add = field_name != "input_ids"

    if isinstance(sequences, list) and sequences and isinstance(sequences[0], list):
        modified_sequences = []
        updated_flags = []

        for seq in sequences:
            new_seq, was_updated = _insert_at_position(seq, value, position, force_add)
            modified_sequences.append(new_seq)
            updated_flags.append(was_updated)

        tokenized_output[field_name] = modified_sequences
        return any(updated_flags)

    elif isinstance(sequences, list):
        new_sequence, was_updated = _insert_at_position(sequences, value, position, force_add)
        tokenized_output[field_name] = new_sequence
        return was_updated

    else:
        raise ValueError(f"Unexpected data type for '{field_name}': {type(sequences)}")

