class BaseDataHandler:
    """Abstract base class for data conversion utilities in sequence classification tasks."""

    def extract_sample_from_tensor_dict(self, tensor_dictionary):
        """Creates a sample from a dictionary containing TensorFlow tensors."""
        raise NotImplementedError()

    def load_training_samples(self, directory_path):
        """Retrieves training samples from specified directory."""
        raise NotImplementedError()

    def load_validation_samples(self, directory_path):
        """Retrieves validation samples from specified directory."""
        raise NotImplementedError()

    def load_test_samples(self, directory_path):
        """Retrieves test samples from specified directory."""
        raise NotImplementedError()

    def retrieve_unique_labels(self):
        """Returns the complete list of possible labels."""
        raise NotImplementedError()

    def normalize_for_tfds(self, sample):
        """Adjusts sample format when converting from tensorflow_datasets."""
        if len(self.retrieve_unique_labels()) > 1:
            sample.target_value = self.retrieve_unique_labels()[int(sample.target_value)]
        return sample

    @classmethod
    def _load_tsv_data(cls, filepath, quote_char=None):
        """Reads tab-separated values from file."""
        with open(filepath, "r", encoding="utf-8-sig") as tsv_file:
            return list(csv.reader(tsv_file, delimiter="\t", quotechar=quote_char))

class TextClassificationHandler(BaseDataHandler):
    """Processor implementation for single-sentence classification datasets."""

    def __init__(self, unique_labels=None, instances=None, task_type="classification", show_progress=False):
        self.unique_labels = [] if unique_labels is None else unique_labels
        self.instances = [] if instances is None else instances
        self.task_type = task_type
        self.show_progress = show_progress

    def __len__(self):
        return len(self.instances)

    def __getitem__(self, index):
        if isinstance(index, slice):
            return TextClassificationHandler(
                unique_labels=self.unique_labels, 
                instances=self.instances[index]
            )
        return self.instances[index]

    @classmethod
    def from_csv_file(
        cls, 
        csv_path, 
        dataset_split="", 
        label_column=0, 
        text_column=1, 
        id_column=None, 
        skip_header=False, 
        **kwargs
    ):
        handler = cls(**kwargs)
        handler.import_from_csv(
            csv_path,
            split_name=dataset_split,
            label_col=label_column,
            text_col=text_column,
            id_col=id_column,
            skip_first_line=skip_header,
            replace_labels=True,
            replace_instances=True,
        )
        return handler

    @classmethod
    def from_raw_data(cls, text_data, labels=None, **kwargs):
        handler = cls(**kwargs)
        handler.import_instances(text_data, labels=labels)
        return handler

    def import_from_csv(
        self,
        csv_path,
        split_name="",
        label_col=0,
        text_col=1,
        id_col=None,
        skip_first_line=False,
        replace_labels=False,
        replace_instances=False,
    ):
        raw_lines = self._load_tsv_data(csv_path)

        if skip_first_line and raw_lines:
            raw_lines = raw_lines[1:]

        texts_list = []
        labels_list = []
        ids_list = []

        for idx, line in enumerate(raw_lines):
            texts_list.append(line[text_col])
            labels_list.append(line[label_col])

            if id_col is not None:
                ids_list.append(line[id_col])
            else:
                guid = f"{split_name}-{idx}" if split_name else str(idx)
                ids_list.append(guid)

        return self.import_instances(
            texts_list, 
            labels_list, 
            ids_list,
            replace_labels=replace_labels,
            replace_instances=replace_instances
        )

    def import_instances(
        self, 
        text_or_text_label_pairs, 
        labels=None, 
        identifiers=None, 
        replace_labels=False, 
        replace_instances=False
    ):
        # Validate input lengths
        if labels is not None and len(text_or_text_label_pairs) != len(labels):
            raise ValueError(
                f"Mismatch between text ({len(text_or_text_label_pairs)}) and label ({len(labels)}) counts"
            )
        if identifiers is not None and len(text_or_text_label_pairs) != len(identifiers):
            raise ValueError(
                f"Mismatch between text ({len(text_or_text_label_pairs)}) and ID ({len(identifiers)}) counts"
            )

        # Set defaults for optional parameters
        if identifiers is None:
            identifiers = [None] * len(text_or_text_label_pairs)
        if labels is None:
            labels = [None] * len(text_or_text_label_pairs)

        new_instances = []
        discovered_labels = set()

        for text_input, label_val, instance_id in zip(text_or_text_label_pairs, labels, identifiers):
            # Handle tuple/list inputs where text and label are bundled
            if isinstance(text_input, (list, tuple)) and label_val is None:
                text_content, label_val = text_input
            else:
                text_content = text_input

            discovered_labels.add(label_val)
            new_instances.append(SampleInstance(
                identifier=instance_id,
                primary_text=text_content,
                secondary_text=None,
                target_value=label_val
            ))

        # Update stored instances
        if replace_instances:
            self.instances = new_instances
        else:
            self.instances.extend(new_instances)

        # Update label set
        if replace_labels:
            self.unique_labels = sorted(list(discovered_labels))
        else:
            self.unique_labels = sorted(list(set(self.unique_labels).union(discovered_labels)))

        return self.instances

    def prepare_features(
        self,
        tokenizer,
        max_seq_length=None,
        pad_at_start=False,
        padding_token_id=0,
        use_one_for_valid_tokens=True,
        output_format=None,
    ):
        """
        Transforms examples into model-ready features.
        """
        if max_seq_length is None:
            max_seq_length = tokenizer.max_len

        # Create label-to-index mapping
        label_to_index = {label: idx for idx, label in enumerate(self.unique_labels)}
        all_token_sequences = []

        # Tokenize all examples
        for sample_idx, sample in enumerate(self.instances):
            if sample_idx % 10000 == 0:
                logger.info(f"Processing tokenization for example {sample_idx}")

            token_sequence = tokenizer.encode(
                sample.primary_text,
                add_special_tokens=True,
                max_length=min(max_seq_length, tokenizer.max_len),
            )
            all_token_sequences.append(token_sequence)

        # Determine maximum sequence length in batch
        batch_max_length = max(len(seq) for seq in all_token_sequences)

        # Prepare final features
        processed_features = []
        for sample_idx, (token_ids, sample) in enumerate(zip(all_token_sequences, self.instances)):
            if sample_idx % 10000 == 0:
                logger.info(f"Constructing feature set {sample_idx}/{len(self.instances)}")

            # Build attention mask
            attention_mask = [1 if use_one_for_valid_tokens else 0] * len(token_ids)

            # Apply padding
            padding_size = batch_max_length - len(token_ids)

            if pad_at_start:
                token_ids = ([padding_token_id] * padding_size) + token_ids
                attention_mask = (
                    ([0 if use_one_for_valid_tokens else 1] * padding_size) + attention_mask
                )
            else:
                token_ids = token_ids + ([padding_token_id] * padding_size)
                attention_mask = attention_mask + ([0 if use_one_for_valid_tokens else 1] * padding_size)

            # Validate lengths
            if len(token_ids) != batch_max_length:
                raise ValueError(f"Incorrect token sequence length: {len(token_ids)} vs {batch_max_length}")
            if len(attention_mask) != batch_max_length:
                raise ValueError(f"Incorrect attention mask length: {len(attention_mask)} vs {batch_max_length}")

            # Process label based on task type
            if self.task_type == "classification":
                label_index = label_to_index[sample.target_value]
            elif self.task_type == "regression":
                label_index = float(sample.target_value)
            else:
                raise ValueError(f"Unsupported task type: {self.task_type}")

            # Log sample info if enabled
            if sample_idx < 5 and self.show_progress:
                logger.info("*** Sample ***")
                logger.info(f"id: {sample.identifier}")
                logger.info(f"tokens: {' '.join([str(x) for x in token_ids])}")
                logger.info(f"mask: {' '.join([str(x) for x in attention_mask])}")
                logger.info(f"label: {sample.target_value} (index = {label_index})")

            processed_features.append(FeatureSet(
                token_indices=token_ids,
                attention_mask=attention_mask,
                label_value=label_index
            ))

        # Return appropriate format based on request
        if output_format is None:
            return processed_features
        elif output_format == "tf":
            if not is_tf_available():
                raise RuntimeError("TensorFlow requested but not available")

            import tensorflow as tf

            def feature_generator():
                for feat in processed_features:
                    yield (
                        {"input_ids": feat.token_indices, "attention_mask": feat.attention_mask}, 
                        feat.label_value
                    )

            dataset = tf.data.Dataset.from_generator(
                feature_generator,
                (
                    {"input_ids": tf.int32, "attention_mask": tf.int32}, 
                    tf.int64
                ),
                (
                    {"input_ids": tf.TensorShape([None]), "attention_mask": tf.TensorShape([None])}, 
                    tf.TensorShape([])
                ),
            )
            return dataset
        elif output_format == "pt":
            if not is_torch_available():
                raise RuntimeError("PyTorch requested but not available")

            import torch
            from torch.utils.data import TensorDataset

            all_tokens = torch.tensor([f.token_indices for f in processed_features], dtype=torch.long)
            all_masks = torch.tensor([f.attention_mask for f in processed_features], dtype=torch.long)

            if self.task_type == "classification":
                all_labels = torch.tensor([f.label_value for f in processed_features], dtype=torch.long)
            else:
                all_labels = torch.tensor([f.label_value for f in processed_features], dtype=torch.float)

            dataset = TensorDataset(all_tokens, all_masks, all_labels)
            return dataset
        else:
            raise ValueError("output_format must be 'tf', 'pt', or None")

