class ClassNotFound(ValueError):
    """Raised when a matching class cannot be found during lookup."""

class OptionError(Exception):
    """
    Raised by option processing functions when the type or value 
    of an argument is invalid.
    """

def get_choice_opt(options, optname, allowed, default=None, normcase=False):
    """
    Retrieve the value for `optname` from `options`, validating it against `allowed`.
    If `normcase` is True, perform case-insensitive comparison.
    """
    string_val = options.get(optname, default)
    if normcase:
        string_val = string_val.lower()
    if string_val not in allowed:
        raise OptionError(f'Value for option {optname} must be one of {", ".join(map(str, allowed))}')
    return string_val

def get_bool_opt(options, optname, default=None):
    """
    Get a boolean option from `options`. Accepts string representations:
    True: 1, yes, true, on; False: 0, no, false, off (case-insensitive).
    Returns the boolean value or raises OptionError for invalid input.
    """
    val = options.get(optname, default)
    if isinstance(val, bool):
        return val
    elif isinstance(val, int):
        return bool(val)
    elif not isinstance(val, str):
        raise OptionError(f'Invalid type {val!r} for option {optname}; use 1/0, yes/no, true/false, on/off')
    elif val.lower() in ('1', 'yes', 'true', 'on'):
        return True
    elif val.lower() in ('0', 'no', 'false', 'off'):
        return False
    else:
        raise OptionError(f'Invalid value {val!r} for option {optname}; use 1/0, yes/no, true/false, on/off')

def get_int_opt(options, optname, default=None):
    """Get an integer option from `options`, raising OptionError on failure."""
    val_str = options.get(optname, default)
    try:
        return int(val_str)
    except TypeError:
        raise OptionError(f'Invalid type {val_str!r} for option {optname}; you must give an integer value')
    except ValueError:
        raise OptionError(f'Invalid value {val_str!r} for option {optname}; you must give an integer value')

def get_list_opt(options, optname, default=None):
    """
    Get a list option from `options`. If the value is a string, split on whitespace.
    If already a list/tuple, convert to list. Otherwise raise OptionError.
    """
    val = options.get(optname, default)
    if isinstance(val, str):
        return val.split()
    elif isinstance(val, (list, tuple)):
        return list(val)
    else:
        raise OptionError(f'Invalid type {val!r} for option {optname}; you must give a list value')

def docstring_headline(obj):
    """Extract the first non-empty line(s) from an object's docstring."""
    if not obj.__doc__:
        return ''
    result_lines = []
    for line in obj.__doc__.strip().splitlines():
        stripped = line.strip()
        if stripped:
            result_lines.append(" " + stripped)
        else:
