    return ''.join(result_lines).lstrip()

def make_analysator(func):
    """Create a static text analysis function that returns normalized float values between 0.0 and 1.0."""
    def text_analyse(text):
        try:
            raw_result = func(text)
        except Exception:
            return 0.0
        if not raw_result:
            return 0.0
        try:
            normalized = float(raw_result)
            return min(1.0, max(0.0, normalized))
        except (ValueError, TypeError):
            return 0.0
    text_analyse.__doc__ = func.__doc__
    return staticmethod(text_analyse)

def shebang_matches(text, pattern):
    r"""
    Check if the given regex matches the interpreter name in a shebang line.
    Handles both Unix-style paths and Windows executable extensions.
    """
    newline_pos = text.find('\n')
    first_line = text[:newline_pos].lower() if newline_pos >= 0 else text.lower()
    if first_line.startswith('#!'):
        try:
            parts = [p for p in split_path_re.split(first_line[2:].strip()) if p and not p.startswith('-')]
            candidate = parts[-1]
        except IndexError:
            return False
        compiled_pattern = re.compile(r'^' + pattern + r'(\.(exe|cmd|bat|bin))?$', re.IGNORECASE)
        return compiled_pattern.search(candidate) is not None
    return False

