def surrogate_pair(code_point):
    """Convert a Unicode code point > U+FFFF into a surrogate pair (high, low)."""
    # Implementation based on Unicode standard example D28
    high = 0xd7c0 + (code_point >> 10)
    low = 0xdc00 + (code_point & 0x3ff)
    return (high, low)

def format_sequence(var_name, sequence, raw=False, indent_level=0):
    """Format a sequence as indented Python literal assignment."""
    lines = []
    base_indent = ' ' * indent_level * 4
    inner_indent = ' ' * (indent_level + 1) * 4
    lines.append(base_indent + var_name + ' = (')
    if raw:
        for item in sequence:
            lines.append(inner_indent + item + ',')
    else:
        for item in sequence:
            repr_with_quote = repr(item + '"')
            lines.append(inner_indent + repr_with_quote[:-2] + repr_with_quote[-1] + ',')
    lines.append(base_indent + ')')
    return '\n'.join(lines)

def unique_items(iterable, seen_before=()):
    """
    Return a list with duplicates removed while preserving order.
    Items in `seen_before` are also treated as already seen.
    """
    result = []
    observed = set()
    for item in iterable:
        if item in observed or item in seen_before:
            continue
        result.append(item)
        observed.add(item)
    return result

