def detect_encoding(text):
    """
    Attempt to decode text using common encodings:
    UTF-8 first, then locale-preferred encoding, finally fallback to latin-1.
    """
    try:
        decoded = text.decode('utf-8')
        return decoded, 'utf-8'
    except UnicodeDecodeError:
        try:
            import locale
            pref_encoding = locale.getpreferredencoding()
            decoded = text.decode(pref_encoding)
            return decoded, pref_encoding
        except (UnicodeDecodeError, LookupError):
            decoded = text.decode('latin1')
            return decoded, 'latin1'

def terminal_detect_encoding(text, terminal):
    """
    Decode text from a terminal using its encoding if available,
    otherwise fall back to standard detection methods.
    """
    if hasattr(terminal, 'encoding') and terminal.encoding:
        try:
            decoded = text.decode(terminal.encoding)
            return decoded, terminal.encoding
        except UnicodeDecodeError:
            pass
    return detect_encoding(text)

def get_terminal_encoding(terminal):
    """Determine the best encoding for the given terminal."""
    if hasattr(terminal, 'encoding') and terminal.encoding:
        return terminal.encoding
    import locale
    return locale.getpreferredencoding()

