from pca9685 import PCA9685
import math
import time

class Servos:
    def __init__(self, i2c, address=0x40, freq=50, min_us=600, max_us=2400,
                 degrees=180):
        self.period = 1000000 / freq
        self.min_duty = self._convert_to_duty(min_us)
        self.max_duty = self._convert_to_duty(max_us)
        self.degrees_range = degrees
        self.frequency = freq
        self.controller = PCA9685(i2c, address)
        self.controller.freq(freq)
        self.servo_positions = [0] * 16

    def _convert_to_duty(self, pulse_width_us):
        # Convert microseconds to duty cycle value (0-4095)
        return int(4095 * pulse_width_us / self.period)

    def set_position(self, channel, angle=None, radian=None, microsecond=None, 
                     duty_cycle=None, apply_immediately=True):
        start_time = time.ticks_us()

        if duty_cycle is not None:
            target_duty = duty_cycle
        elif angle is not None:
            duty_span = self.max_duty - self.min_duty
            target_duty = self.min_duty + (duty_span * angle / self.degrees_range)
        elif radian is not None:
            duty_span = self.max_duty - self.min_duty
            total_degrees = math.degrees(radian)
            target_duty = self.min_duty + (duty_span * total_degrees / self.degrees_range)
        elif microsecond is not None:
            target_duty = self._convert_to_duty(microsecond)
        else:
            # Return current position when no parameters provided
            return self.controller.duty(channel)

        print('Angle calculation time:', time.ticks_diff(time.ticks_us(), start_time))

        # Store the new duty value
        update_start = time.ticks_us()
        self.servo_positions[channel] = target_duty
        print('Storage time:', time.ticks_diff(time.ticks_us(), update_start))

        # Apply the change if requested
        apply_start = time.ticks_us()
        if apply_immediately:
            self.controller.duty(channel, target_duty)
        print('Apply time:', time.ticks_diff(time.ticks_us(), apply_start), 'apply:', apply_immediately)

    def set_duty(self, channel, duty_value):
        self.servo_positions[channel] = duty_value
        self.controller.duty(channel, duty_value)

    def disable_servo(self, channel):
        self.controller.duty(channel, 0)

    def disable_all(self):
        for idx in range(16):
            self.servo_positions[idx] = 0
        self.apply_all_values()

    def apply_all_values(self):
        self.controller.allpwm(self.servo_positions)

