# ============ BM25 IMPLEMENTATION (Refactored) ============
class TextRanker:
    """BM25-based text ranking engine"""
    def __init__(self, k1=1.5, b=0.75):
        self.k1 = k1
        self.b = b
        self.documents = []
        self.lengths = []
        self.mean_length = 0
        self.inverse_doc_freq = {}
        self.term_document_counts = Counter()
        self.total_docs = 0

    def _clean_and_split(self, text):
        """Normalize text: lowercase, remove punctuation, filter short tokens"""
        normalized = re.sub(r'[^\w\s]', ' ', str(text).lower())
        return [token for token in normalized.split() if len(token) > 2]

    def train(self, corpus):
        """Build index from document corpus"""
        self.documents = [self._clean_and_split(doc) for doc in corpus]
        self.total_docs = len(self.documents)
        if self.total_docs == 0:
            return

        self.lengths = [len(doc) for doc in self.documents]
        self.mean_length = sum(self.lengths) / self.total_docs

        # Count document frequencies
        for doc in self.documents:
            unique_terms = set(doc)
            for term in unique_terms:
                self.term_document_counts[term] += 1

        # Compute IDF values
        for term, df in self.term_document_counts.items():
            self.inverse_doc_freq[term] = log((self.total_docs - df + 0.5) / (df + 0.5) + 1)

    def rank(self, query):
        """Compute relevance scores for all documents against the query"""
        query_tokens = self._clean_and_split(query)
        scores = []

        for doc_idx, doc in enumerate(self.documents):
            score = 0.0
            doc_len = self.lengths[doc_idx]

            # Term frequency calculation
            term_counts = Counter(doc)

            for token in query_tokens:
                if token in self.inverse_doc_freq:
                    tf = term_counts[token]
                    idf = self.inverse_doc_freq[token]

                    numerator = tf * (self.k1 + 1)
                    denominator = tf + self.k1 * (1 - self.b + self.b * doc_len / self.mean_length)
                    score += idf * numerator / denominator

            scores.append((doc_idx, score))

        # Sort by descending score
        return sorted(scores, key=lambda x: x[1], reverse=True)

# ============ SEARCH FUNCTIONS (Refactored) ============
def _read_csv_file(path):
    """Load CSV data as list of dictionaries"""
    try:
        with open(path, 'r', encoding='utf-8') as file:
            return list(csv.DictReader(file))
    except FileNotFoundError:
        return []

def _execute_search(file_path, input_fields, output_fields, search_query, limit):
    """Core search logic using TextRanker"""
    if not file_path.exists():
        return []

    records = _read_csv_file(file_path)
    if not records:
        return []

    # Construct searchable documents
    searchable_texts = [
        " ".join(str(row.get(field, "")) for field in input_fields)
        for row in records
    ]

    # Perform BM25 search
    ranker = TextRanker()
    ranker.train(searchable_texts)
    ranked_results = ranker.rank(search_query)

    # Extract top results with positive scores
    final_results = []
    for idx, score in ranked_results[:limit]:
        if score > 0:
            record = records[idx]
            filtered_record = {field: record.get(field, "") for field in output_fields if field in record}
            final_results.append(filtered_record)

    return final_results

def _identify_category(query):
