            "error": f"Stack file not found: {file_path}",
            "framework": framework
        }

    results = _execute_search(
        file_path,
        FRAMEWORK_COLUMNS["input_cols"],
        FRAMEWORK_COLUMNS["output_cols"],
        query,
        limit
    )

    return {
        "category": "stack",
        "framework": framework,
        "query_text": query,
        "source_file": FRAMEWORK_CONFIG[framework]["path"],
        "result_count": len(results),
        "data": results
    }

