import os
import shutil
from pathlib import Path
from unittest.mock import MagicMock

class MockLocalAGFS:
    """
    A mock implementation of AGFSClient that operates on a local directory.
    Useful for tests where running a real AGFS server is not feasible or desired.
    """
    def __init__(self, config=None, root_path=None):
        self.config = config
        # Use provided root path or default to /tmp/viking_data
        base_dir = root_path if root_path else "/tmp/viking_data"
        self.root = Path(base_dir)
        self.root.mkdir(parents=True, exist_ok=True)

    def _normalize_path(self, path):
        """Convert viking:// URIs and absolute paths to relative paths under root"""
        path_str = str(path)

        # Remove viking:// prefix if present
        if path_str.startswith("viking://"):
            path_str = path_str[9:]  # len("viking://") == 9

        # Remove leading slash if present
        if path_str.startswith("/"):
            path_str = path_str[1:]

        return self.root / path_str

    def exists(self, path, ctx=None):
        """Check if a file or directory exists at the given path"""
        return self._normalize_path(path).exists()

    def mkdir(self, path, ctx=None, parents=True, exist_ok=True):
        """Create a directory at the given path"""
        target = self._normalize_path(path)
        target.mkdir(parents=parents, exist_ok=exist_ok)

    def ls(self, path, ctx=None, **kwargs):
        """List contents of a directory"""
        dir_path = self._normalize_path(path)

        if not dir_path.exists() or not dir_path.is_dir():
            return []

        result = []
        for entry in dir_path.iterdir():
            result.append({
                "name": entry.name,
                "isDir": entry.is_dir(),
                "type": "directory" if entry.is_dir() else "file",
                "size": entry.stat().st_size if entry.is_file() else 0,
                "mtime": entry.stat().st_mtime,
                "uri": f"viking://{path}/{entry.name}".replace("//", "/")
            })
        return result

    def writeto(self, path, content, ctx=None, **kwargs):
        """Write content to a file"""
        target = self._normalize_path(path)
        target.parent.mkdir(parents=True, exist_ok=True)

        if isinstance(content, str):
            target.write_text(content, encoding="utf-8")
        else:
            target.write_bytes(content)

        return str(target)

    def write(self, path, content, ctx=None, **kwargs):
        """Alias for writeto"""
        return self.writeto(path, content, ctx, **kwargs)

    def write_file(self, path, content, ctx=None, **kwargs):
        """Alias for writeto"""
        return self.writeto(path, content, ctx, **kwargs)

    def read_file(self, path, ctx=None, **kwargs):
        """Read and return file contents as bytes"""
        target = self._normalize_path(path)

        if not target.exists():
            raise FileNotFoundError(path)

        return target.read_bytes()

    def read(self, path, ctx=None, **kwargs):
        """Alias for read_file"""
        return self.read_file(path, ctx, **kwargs)

    def rm(self, path, recursive=False, ctx=None):
        """Remove a file or directory"""
        target = self._normalize_path(path)

        if target.exists():
            if target.is_dir():
                if recursive:
                    shutil.rmtree(target)
                else:
                    target.rmdir()
            else:
                target.unlink()

    def delete_temp(self, path, ctx=None):
        """Delete a path recursively (for temporary files/directories)"""
        self.rm(path, recursive=True, ctx=ctx)

    def mv(self, src, dst, ctx=None):
        """Move/rename a file or directory"""
        source = self._normalize_path(src)
        destination = self._normalize_path(dst)

        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.move(str(source), str(destination))

    def stat(self, path, ctx=None):
        """Get file/directory statistics"""
        target = self._normalize_path(path)

        if not target.exists():
            raise FileNotFoundError(path)

        stats = target.stat()
        return {
            "size": stats.st_size,
            "mtime": stats.st_mtime,
            "is_dir": target.is_dir()
        }

    def bind_request_context(self, ctx):
        """Return a context manager stub"""
        return MagicMock(__enter__=lambda x: None, __exit__=lambda x, y, z: None)

