import json
from pathlib import Path

def load_relations(path_relations: Path, path_weights: Path):
    # Initialize relationship and weight structures
    relationships = {
        "subsidiaries": {}, 
        "parents": {}, 
        "suppliers": {}, 
        "customers": {}
    }
    weights = {
        "subsidiary_to_parent": 1.0, 
        "parent_to_subsidiary": 0.8, 
        "customer_to_supplier": 0.5, 
        "supplier_to_customer": 0.3
    }

    # Load relationships from file if possible
    try:
        loaded_rels = json.loads(path_relations.read_text(encoding="utf-8"))
        relationships.update(loaded_rels)
    except Exception:
        pass

    # Load weights from file if possible
    try:
        loaded_weights = json.loads(path_weights.read_text(encoding="utf-8"))
        weights.update(loaded_weights)
    except Exception:
        pass

    # Automatically infer inverse relationships when missing
    # Infer 'parents' from 'subsidiaries' if parents are not provided
    if not relationships.get("parents") and relationships.get("subsidiaries"):
        parent_map = {}
        for parent, subsidiaries in relationships["subsidiaries"].items():
            for subsidiary in subsidiaries:
                parent_map.setdefault(subsidiary, []).append(parent)
        relationships["parents"] = parent_map

    # Infer 'customers' from 'suppliers' if customers are not provided
    if not relationships.get("customers") and relationships.get("suppliers"):
        customer_map = {}
        for supplier, customers in relationships["suppliers"].items():
            for customer in customers:
                customer_map.setdefault(customer, []).append(supplier)
        relationships["customers"] = customer_map

    return relationships, weights

import subprocess
from subprocess import Popen
from threading import Event, Thread
from typing import List, Dict, Any

def terminate_threads(thread_list: List[Thread]) -> None:
    """Gracefully terminate a collection of threads with timeout"""
    for t in thread_list:
        t.join(timeout=5)

def terminate_subprocesses(proc_list: List[Popen]) -> None:
    """Safely terminate a list of subprocesses with fallback to force kill"""
    for proc in proc_list:
        if proc.poll() is None:  # Process still running
            proc.terminate()
            try:
                proc.wait(timeout=60)
            except subprocess.TimeoutExpired:
                proc.kill()

def watch_subprocess(proc: Popen, shutdown_flag: Event, error_log: List[Dict[str, Any]], label: str) -> None:
    """Observe subprocess execution and log errors to shared storage"""
    exit_status = proc.wait()

    if exit_status != 0:
        error_details = {
            "message": f"{label.title()} failed with exit code {exit_status}",
            "stderr": ""
        }

        try:
            if proc.stderr:
                error_details["stderr"] = proc.stderr.read().decode("utf-8")
                error_details["message"] += "\n" + error_details["stderr"]
        except Exception:
            pass

        error_log.append(RuntimeError(error_details["message"]))

    shutdown_flag.set()

import os

# Determine project base directory from environment variables or default path
PROJECT_BASE_ENV = os.getenv("RAG_PROJECT_BASE") or os.getenv("RAG_DEPLOY_BASE")

def get_project_base_directory(*args):
    global PROJECT_BASE_ENV
    if PROJECT_BASE_ENV is None:
        # Navigate up four directories from current file location
        current_dir = os.path.dirname(os.path.realpath(__file__))
        parent_dirs = [os.pardir] * 4
        PROJECT_BASE_ENV = os.path.abspath(
            os.path.join(current_dir, *parent_dirs)
        )

    # Return joined path if additional arguments provided, else return base directory
    if args:
        return os.path.join(PROJECT_BASE_ENV, *args)
    return PROJECT_BASE_ENV

def traverse_files(directory):
    # Walk through directory tree and yield full paths to files
    for dirpath, dirnames, filenames in os.walk(directory):
        for filename in filenames:
            full_path = os.path.join(dirpath, filename)
            yield full_path

import collections
import ssl
import threading
import time
import traceback
import msgpack
from websocket import create_connection
import blankly
from blankly.utils.utils import info_print
from blankly.exchanges.abc_exchange_websocket import ABCExchangeWebsocket
from blankly.exchanges.auth.utils import load_auth
from blankly.exchanges.interfaces.alpaca.alpaca_websocket_utils import parse_alpaca_timestamp, switch_type


def _send_subscription(ws, action, channel, symbols=None):
    payload = {
        'action': action,
        channel: tuple(symbols) if symbols is not None else ()
    }
    ws.send(msgpack.packb(payload))


def _establish_connection(url, key, secret):
    ws = create_connection(
        url,
        sslopt={"cert_reqs": ssl.CERT_NONE},
        header={'Content-Type': 'application/msgpack'}
    )
    # Authenticate
    auth_msg = {
        'action': 'auth',
        'key': key,
        'secret': secret
    }
    ws.send(msgpack.packb(auth_msg))

    # Validate connection response
    raw_resp = msgpack.unpackb(ws.recv())
    if not raw_resp or raw_resp[0].get('msg') != 'connected':
        info_print("Connection failed.")
        raise ConnectionError("Initial connection handshake failed.")

    # Validate authentication response
    auth_resp = msgpack.unpackb(ws.recv())
    if not auth_resp or auth_resp[0].get('msg') != 'authenticated':
        if auth_resp and auth_resp[0].get('msg') == 'connection limit exceeded':
            # Retry after unsubscribing
            _send_subscription(ws, 'unsubscribe', '')
            info_print("Rate limited; retrying subscription...")
            msgpack.unpackb(ws.recv())  # consume unsubscribe confirmation
            _send_subscription(ws, 'subscribe', '', [])
            info_print("Resubscription attempted.")
            msgpack.unpackb(ws.recv())  # consume subscribe confirmation
        else:
            info_print("Authentication failed.")
            raise PermissionError("Auth failed.")
    return ws


class Tickers(ABCExchangeWebsocket):
    def __init__(self, symbol, stream, log_file_path=None,
                 pre_event_handler=None, initially_paused=False,
                 websocket_endpoint="wss://stream.data.alpaca.markets/v2/iex/", **kwargs):
        """
        Initialize ticker listener for Alpaca data streams.
        Args:
            symbol: Trading pair like "AAPL"
            stream: Data type such as 'trades', 'quotes', etc.
            log_file_path: Optional path to write logs
            websocket_endpoint: WebSocket URL
        """
        self.__symbol = symbol
        self.__stream_name = stream
        self.__log_callback, self.__event_converter, log_header = switch_type(stream)
        self.__extra_kwargs = kwargs

        # Setup logging file
        self.__logging_enabled = log_file_path is not None
        self.__log_path = log_file_path
        if self.__logging_enabled:
            try:
                self.__log_handle = open(log_file_path, 'x+')
                self.__log_handle.write(log_header)
            except FileExistsError:
                self.__log_handle = open(log_file_path, 'a')
        else:
            self.__log_handle = None

        self.__ws_url = websocket_endpoint
        self.__ws_instance = None
        self.__latest_raw_response = None
        self.__subscription_ack = None
        self.__last_tick_data = None
        self.__last_tick_time = None
        self.__callback_list = []
        self.__pre_event_hook = pre_event_handler

        # Load user settings
        prefs = blankly.utils.load_user_preferences()
        buffer_capacity = prefs["settings"]["websocket_buffer_size"]
        self.__data_buffer = collections.deque(maxlen=buffer_capacity)
        self.__time_buffer = collections.deque(maxlen=buffer_capacity)

        if not initially_paused:
            self.resume_stream()

    def resume_stream(self):
        """Start or restart the WebSocket connection."""
        if self.__ws_instance is None:
            _, auth = load_auth('alpaca')
            self.__ws_instance = _establish_connection(
                self.__ws_url,
                auth['API_KEY'],
                auth['API_SECRET']
            )
            self.__latest_raw_response = self.__ws_instance.recv()
            worker = threading.Thread(target=self.__consume_socket)
            worker.daemon = True
            worker.start()
        else:
            if self.__ws_instance.connected:
                info_print("Stream already active.")
            else:
                self.__ws_instance = None
                self.resume_stream()

    def __consume_socket(self):
        attempts = 0
        while self.__ws_instance and self.__ws_instance.connected:
            try:
                raw_data = self.__ws_instance.recv()
                parsed = msgpack.unpackb(raw_data)[0]

                # Handle timestamp conversion
                if 't' in parsed:
                    parsed['t'] = parse_alpaca_timestamp(parsed['t'])
                    current_time = parsed['t']
                elif 'code' in parsed:
                    continue
                else:
                    current_time = time.time()

                # Log if enabled
                if self.__logging_enabled and self.__log_handle:
                    self.log_response(self.__log_callback, parsed)

                # Convert and store tick
                converted_tick = self.__event_converter(parsed)
                self.__last_tick_time = current_time
                self.__time_buffer.append(current_time)
                self.__last_tick_data = converted_tick
                self.__data_buffer.append(converted_tick)

                # Trigger callbacks
                for cb in self.__callback_list:
                    try:
                        cb(converted_tick, **self.__extra_kwargs)
                    except Exception:
                        traceback.print_exc()

            except Exception as e:
                traceback.print_exc()
                if self.__ws_instance and self.__ws_instance.connected:
                    continue
                else:
                    info_print(f"WebSocket error for {self.__symbol} on {self.__stream_name}; reconnecting...")
                    time.sleep(2)
                    if self.__ws_instance:
                        self.__ws_instance.close()
                    self.__ws_instance = None
                    self.resume_stream()

    """ Required interface methods """

    def is_stream_active(self):
        return bool(self.__ws_instance and self.__ws_instance.connected)

    def get_underlying_asset(self):
        return self.__symbol

    def register_callback(self, handler):
        self.__callback_list.append(handler)

    def fetch_latest_tick(self):
        return self.__last_tick_data

    def fetch_latest_timestamp(self):
        return self.__last_tick_time

    def get_time_series(self):
        return list(self.__time_buffer)

    def get_data_series(self):
        return list(self.__data_buffer)

    def get_last_raw_message(self):
        return self.__latest_raw_response

    def terminate_stream(self):
        if self.__ws_instance and self.__ws_instance.connected:
            self.__ws_instance.close()
        else:
            info_print(f"Stream for {self.__symbol} ({self.__stream_name}) already closed")

    def reset_and_reconnect(self):
        self.resume_stream()

