import base64
import json
import os
from cosmos_rl.utils.logging import logger
from cosmos_rl.utils.wfm.validator import JsonDict, Validator

"""
Environment variable parser that supports multiple input sources:
- Direct environment variables
- JSON file
- Base64-encoded JSON string
Each field is validated using associated Validator instances.
"""

class EnvParser:
    def __init__(self, encoded_data=None):
        if encoded_data:
            logger.critical(f"Received encoded data: {encoded_data}")
            self._load_from_base64(encoded_data)
        else:
            self._load_from_environment()

    def _load_from_environment(self):
        validation_rules = self._get_validation_rules()
        for var_name in validation_rules:
            raw_value = os.getenv(var_name.upper())
            logger.debug(f"Fetching env var {var_name.upper()}: {raw_value}")
            if raw_value is not None:
                setattr(self, var_name, raw_value)
        self._validate_required_fields()

    def _load_from_json_file(self, filepath):
        with open(filepath, 'r') as fp:
            logger.info(f"Loading configuration from {filepath}")
            config_dict = json.load(fp)
            for param, val in config_dict.items():
                setattr(self, param, val)
            self._validate_required_fields()

    def _convert_to_base64(self):
        serialized = self._serialize()
        # Convert to bytes before encoding
        byte_data = serialized.encode('utf-8')
        encoded = base64.b64encode(byte_data).decode('utf-8')
        print(encoded)
        return encoded

    def _load_from_base64(self, encoded_str):
        decoded_bytes = base64.b64decode(encoded_str)
        decoded_str = decoded_bytes.decode('utf-8')
        parsed = json.loads(decoded_str)
        for field, value in parsed.items():
            setattr(self, field, value)
        self._validate_required_fields()

    def _validate_required_fields(self):
        rules = self._get_validation_rules()
        for field_name, rule in rules.items():
            current_value = getattr(self, field_name, None)
            if current_value is None and rule.default is None:
                raise ValueError(f"Required environment variable missing: {field_name}")

    @classmethod
    def _get_validation_rules(cls):
        logger.debug(f"Retrieving validators for {cls.__name__}")
        result = {}
        result.update(
            {
                attr: val
                for attr, val in cls.__dict__.items()
                if isinstance(val, Validator)
            }
        )
        return result

    def _log_validators(self):
        rules = self._get_validation_rules()
        for name, validator in rules.items():
            logger.debug(f"{name}: {validator.__get__(self)}")

    def _serialize(self, output_path=None):
        # Only include fields defined by validators
        serializable = {
            key.upper(): validator.__get__(self)
            for key, validator in EnvParser.__dict__.items()
            if isinstance(validator, Validator)
        }
        json_output = json.dumps(serializable, indent=4)
        print(json_output)
        if output_path:
            with open(output_path, 'w') as f:
                logger.info(f"Saving configuration to {output_path}")
                f.write(json_output)
        return json_output

    def _to_string_mapping(self):
        mapping = {}
        rules = self._get_validation_rules()
        for field, rule in rules.items():
            value = getattr(self, field, None)
            if value is None:
                value = rule.default
            if isinstance(rule, JsonDict):
                value = json.dumps(value)
            else:
                value = str(value)
            mapping[field] = value
        return mapping

    def __repr__(self):
        return ", ".join(f"{k}={v}" for k, v in self.__dict__.items())

import re
import torch

def deepseekv3_to_hf_mapping(args, param_name, param_value):
    # Handle top-level embeddings and output layers
    if param_name == "module.module.embedding.word_embeddings.weight":
        return [("model.embed_tokens.weight", param_value)]
    if param_name == "module.module.output_layer.weight":
        return [("lm_head.weight", param_value)]
    if param_name == "module.module.decoder.final_layernorm.weight":
        return [("model.norm.weight", param_value)]

    # Compute head dimension with fallback
    try:
        head_dim = args.kv_channels or (args.hidden_size // args.num_attention_heads)
    except AttributeError:
        head_dim = args.hidden_size // args.num_attention_heads

    num_query_groups = args.num_query_groups
    q_per_group = args.num_attention_heads // num_query_groups

    # Match decoder layer parameters
    layer_pattern = r"module\.module\.decoder\.layers\.(\d+)\.(.+)"
    layer_match = re.match(layer_pattern, param_name)
    if layer_match:
        layer_id, rest_param = layer_match.groups()
        layer_id = str(layer_id)

        # Expert-specific mappings
        expert_regex = r"mlp\.experts\.(.+)\.weight(\d+)"
        expert_match = re.match(expert_regex, rest_param)
        if expert_match:
            sub_part, exp_idx = expert_match.groups()
            if sub_part == "linear_fc1":
                gate, up = torch.chunk(param_value, 2, dim=0)
                return [
                    (f"model.layers.{layer_id}.mlp.experts.{exp_idx}.gate_proj.weight", gate),
                    (f"model.layers.{layer_id}.mlp.experts.{exp_idx}.up_proj.weight", up),
                ]
            elif sub_part == "linear_fc2":
                return [(f"model.layers.{layer_id}.mlp.experts.{exp_idx}.down_proj.weight", param_value)]
            else:
                raise ValueError(f"Unknown expert parameter: {param_name}")

        # Shared expert mappings
        shared_exp_regex = r"mlp\.shared_experts\.(.+)"
        shared_match = re.match(shared_exp_regex, rest_param)
        if shared_match:
            sub_part = shared_match.group(1)
            if sub_part == "linear_fc1.weight":
                gate, up = torch.chunk(param_value, 2, dim=0)
                return [
                    (f"model.layers.{layer_id}.mlp.shared_experts.gate_proj.weight", gate),
                    (f"model.layers.{layer_id}.mlp.shared_experts.up_proj.weight", up),
                ]
            elif sub_part == "linear_fc2.weight":
                return [(f"model.layers.{layer_id}.mlp.shared_experts.down_proj.weight", param_value)]
            else:
                raise ValueError(f"Unknown shared expert parameter: {param_name}")

        # Standard attention & MLP mappings
        if rest_param == "self_attention.linear_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.o_proj.weight", param_value)]
        elif rest_param == "self_attention.linear_q_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.q_proj.weight", param_value)]
        elif rest_param == "self_attention.linear_q_down_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.q_a_proj.weight", param_value)]
        elif rest_param == "self_attention.linear_q_up_proj.layer_norm_weight":
            return [(f"model.layers.{layer_id}.self_attn.q_a_layernorm.weight", param_value)]

        # Indexer-related transformations
        elif rest_param == "self_attention.wq_b.weight":
            wq_b = param_value.view(-1, 128, param_value.shape[-1])
            wq_b = torch.cat([wq_b[:, 64:], wq_b[:, :64]], dim=1).view_as(param_value)
            return [(f"model.layers.{layer_id}.self_attn.indexer.wq_b.weight", wq_b)]
        elif rest_param == "self_attention.wk.weight":
            wk = torch.cat([param_value[64:], param_value[:64]], dim=0)
            return [(f"model.layers.{layer_id}.self_attn.indexer.wk.weight", wk)]
        elif rest_param == "self_attention.weights_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.indexer.weights_proj.weight", param_value)]
        elif rest_param == "self_attention.k_norm.weight":
            knorm_w = torch.cat([param_value[64:], param_value[:64]], dim=0)
            return [(f"model.layers.{layer_id}.self_attn.indexer.k_norm.weight", knorm_w)]
        elif rest_param == "self_attention.k_norm.bias":
            knorm_b = torch.cat([param_value[64:], param_value[:64]], dim=0)
            return [(f"model.layers.{layer_id}.self_attn.indexer.k_norm.bias", knorm_b)]
        elif rest_param == "self_attention.linear_q_up_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.q_b_proj.weight", param_value)]
        elif rest_param == "self_attention.linear_qkv.bias":
            bias_view = param_value.view(num_query_groups, -1)
            q_b, k_b, v_b = torch.split(
                bias_view,
                [q_per_group * head_dim, head_dim, head_dim],
                dim=1,
            )
            return [
                (f"model.layers.{layer_id}.self_attn.q_proj.bias", q_b.flatten()),
                (f"model.layers.{layer_id}.self_attn.k_proj.bias", k_b.flatten()),
                (f"model.layers.{layer_id}.self_attn.v_proj.bias", v_b.flatten()),
            ]
        elif rest_param == "mlp.linear_fc1.weight":
            gate_w, up_w = torch.chunk(param_value, 2, dim=0)
            return [
                (f"model.layers.{layer_id}.mlp.gate_proj.weight", gate_w),
                (f"model.layers.{layer_id}.mlp.up_proj.weight", up_w),
            ]
        elif rest_param == "mlp.linear_fc2.weight":
            return [(f"model.layers.{layer_id}.mlp.down_proj.weight", param_value)]
        elif rest_param in ("self_attention.linear_qkv.layer_norm_weight", "input_layernorm.weight"):
            return [(f"model.layers.{layer_id}.input_layernorm.weight", param_value)]
        elif rest_param == "mlp.linear_fc1.layer_norm_weight":
            return [(f"model.layers.{layer_id}.post_attention_layernorm.weight", param_value)]
        elif rest_param == "self_attention.linear_kv_down_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.kv_a_proj_with_mqa.weight", param_value)]
        elif rest_param == "self_attention.linear_kv_up_proj.layer_norm_weight":
            return [(f"model.layers.{layer_id}.self_attn.kv_a_layernorm.weight", param_value)]
        elif rest_param == "self_attention.linear_kv_up_proj.weight":
            return [(f"model.layers.{layer_id}.self_attn.kv_b_proj.weight", param_value)]
        elif rest_param == "pre_mlp_layernorm.weight":
            return [(f"model.layers.{layer_id}.post_attention_layernorm.weight", param_value)]
        elif rest_param == "mlp.router.weight":
            return [(f"model.layers.{layer_id}.mlp.gate.weight", param_value)]
        elif rest_param == "mlp.router.expert_bias":
            return [(f"model.layers.{layer_id}.mlp.gate.e_score_correction_bias", param_value)]

    # MTP layer handling
    mtp_pattern = r"module\.module\.mtp\.layers\.(\d+)\.(.+)"
    mtp_match = re.match(mtp_pattern, param_name)
    if mtp_match:
        mtp_layer_id, rest_mtp = mtp_match.groups()
        global_layer_id = int(mtp_layer_id) + args.num_layers
        if rest_mtp == "eh_proj.weight":
            return [(f"model.layers.{global_layer_id}.eh_proj.weight", param_value)]
        elif rest_mtp == "enorm.weight":
            return [(f"model.layers.{global_layer_id}.enorm.weight", param_value)]
        elif rest_mtp == "hnorm.weight":
            return [(f"model.layers.{global_layer_id}.hnorm.weight", param_value)]
        elif rest_mtp == "final_layernorm.weight":
            return [(f"model.layers.{global_layer_id}.shared_head.norm.weight", param_value)]
        else:
            # Fallback to recursive call with adjusted name
            new_name = f"module.module.decoder.layers.{global_layer_id}.{rest_mtp}"
            new_name = new_name.replace("transformer_layer.", "")
            return deepseekv3_to_hf_mapping(args, new_name, param_value)

    raise ValueError(f"Unrecognized parameter name: {param_name}")

# Dynamic module loader with plugin support and registration system

import importlib
import pkgutil
from mindspeed.fsdp.utils.log import print_rank

def load_module(module_path, verbose=True):
    # Normalize path format by replacing slashes with dots and removing leading/trailing dots
    if "/" in module_path:
        module_path = module_path.replace("/", ".")
    module_path = module_path.strip(".")

    try:
        module = importlib.import_module(module_path)
        if verbose:
            print_rank(print, f"Successfully loaded: {module_path}")
        return module, module_path
    except ModuleNotFoundError as error:
        if verbose:
            print_rank(print, f"Module loading failed: {module_path}. Error: {error}")
        else:
            raise error
    return None, None

def load_plugins(plugin_paths=None):
    if not plugin_paths:
        return

    for plugin_location in plugin_paths:
        module, module_name = load_module(plugin_location, verbose=True)
        if not hasattr(module, "__path__"):
            continue

        # Iterate through submodules in the package
        for _, submodule_name, is_package in pkgutil.walk_packages(
            module.__path__, prefix=f"{module_name}."
        ):
            # Only import non-package modules (actual modules, not subpackages)
            if not is_package:
                _ = load_module(submodule_name, verbose=False)

class RegistryManager:
    def __init__(self):
        self._entries = {}

    def add_entry(self, entry_key):
        def wrapper(target):
            nonlocal entry_key
            if entry_key in self._entries:
                existing = self._entries[entry_key]
                raise KeyError(f"Key '{entry_key}' already registered to {existing.__name__}.")
            self._entries[entry_key] = target
        return wrapper

    def fetch(self, entry_key):
        if entry_key not in self._entries:
            raise KeyError(f"Key '{entry_key}' has no registration.")
        return self._entries[entry_key]

# Create separate registries for models and data components
model_registry = RegistryManager()
data_registry = RegistryManager()

