def sigmoid(x):
    """Compute sigmoid activation function"""
    return 1.0 / (1.0 + np.exp(-x))


def normalize_pesq(raw_score):
    """Convert raw PESQ score to normalized [0,1] range"""
    return (raw_score + 0.5) / 5.0


def compute_pesq_score(predicted, reference):
    """Calculate normalized PESQ score between predicted and reference signals"""
    raw_score = pesq(fs=16000, ref=reference.numpy(), deg=predicted.numpy(), mode="wb")
    return normalize_pesq(raw_score)


def compute_srmr_normalized(signal, sample_rate=16000):
    """Compute SRMR with normalization to [0,1] range"""
    raw_srmr = srmr(
        signal.numpy(),
        fs=sample_rate,
        n_cochlear_filters=23,
        low_freq=125,
        min_cf=4,
        max_cf=128,
        fast=True,
        norm=False,
    )[0]
    return sigmoid(0.1 * raw_srmr)


def compute_srmr_raw(signal, sample_rate=16000):
    """Compute raw SRMR score without normalization"""
    return float(srmr(
        signal.numpy(),
        fs=sample_rate,
        n_cochlear_filters=23,
        low_freq=125,
        min_cf=4,
        max_cf=128,
        fast=True,
        norm=False,
    )[0])


def request_dnsmos_score(audio_data):
    """Request DNSMOS score from scoring service with retry logic"""
    # Normalize audio amplitude
    normalized_audio = audio_data.numpy()
    max_amplitude = max(abs(normalized_audio))
    if max_amplitude > 0:
        normalized_audio = normalized_audio / max_amplitude

    payload = {"data": normalized_audio.tolist()}

    # Retry loop for server access
    while True:
        try:
            parsed_url = urlparse(SCORING_URI)
            endpoint = urljoin(f"https://{parsed_url.netloc}", "score")
            response = requests.post(
                endpoint,
                data=json.dumps(payload),
                headers=headers,
            )
            result = response.json()
            return sigmoid(result["mos"])
        except Exception as error:
            print(f"DNSMOS request failed: {error}")
            time.sleep(10)  # Wait before retry


def request_dnsmos_raw_score(audio_data):
    """Request raw DNSMOS score from scoring service with retry logic"""
