class TrainingPhase(Enum):
    """Track current stage of the training process"""
    GENERATOR_ONLY = auto()
    CURRENT_DATA = auto()
    HISTORICAL_DATA = auto()


class SpeechEnhancementBrain(sb.Brain):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.historical_data = {}
        self.noisy_scores_cache = {}
        self.training_metrics = {"G": [], "D": []}

    def load_historical_records(self):
        """Load previously saved historical data from disk"""
        if os.path.exists(self.hparams.historical_file):
            with open(self.hparams.historical_file, 'rb') as file:
                self.historical_data = pickle.load(file)

    def extract_spectrogram_features(self, waveforms):
        """Extract magnitude spectrogram features from waveforms"""
        stft_features = self.hparams.compute_STFT(waveforms)
        magnitude = spectral_magnitude(stft_features, power=0.5)
        return magnitude

    def generate_enhanced_signal(self, batch, phase):
        """Generate enhanced speech signal based on current phase"""
        batch = batch.to(self.device)

        if phase == TrainingPhase.HISTORICAL_DATA:
            enhanced_waveform, lengths = batch.enh_sig
            return enhanced_waveform
        else:
            noisy_waveform, lengths = batch.noisy_sig
            noisy_spectrum = self.extract_spectrogram_features(noisy_waveform)

            mask = self.modules.generator(noisy_spectrum, lengths=lengths)
            mask = mask.clamp(min=self.hparams.min_mask).squeeze(2)
            enhanced_spectrum = torch.mul(mask, noisy_spectrum)

            # Convert back to waveform
            enhanced_waveform = self.hparams.resynth(enhanced_spectrum, noisy_waveform)

            return enhanced_waveform, mask

    def calculate_training_loss(self, predictions, batch, phase, optimizer_name=""):
        """Compute total loss based on current phase and optimizer"""
        if phase == TrainingPhase.HISTORICAL_DATA:
            enhanced_waveform = predictions
        else:
            enhanced_waveform, mask = predictions

        enhanced_spectrum = self.extract_spectrogram_features(enhanced_waveform)
        utterance_ids = self.generate_utterance_ids(batch.id, optimizer_name)

        if phase != TrainingPhase.HISTORICAL_DATA:
            noisy_waveform, lengths = batch.noisy_sig

        if optimizer_name == "generator":
            estimated_score = self.estimate_discriminator_score(enhanced_spectrum)
            target_score = self.hparams.target_score * torch.ones(
                self.batch_size, 1, device=self.device
            )

            noisy_spectrum = self.extract_spectrogram_features(noisy_waveform)
            mse_loss = self.hparams.compute_cost(enhanced_spectrum, noisy_spectrum, lengths)

        # Discriminator learns scores of enhanced speech
        elif optimizer_name == "D_enh" and phase == TrainingPhase.CURRENT_DATA:
            target_score = self.calculate_metric_score(
                utterance_ids, enhanced_waveform, enhanced_waveform, lengths
            )
            estimated_score = self.estimate_discriminator_score(enhanced_spectrum)

            # Save enhanced wavs during discriminator training
            self.save_enhanced_samples(utterance_ids, enhanced_waveform, target_score, lengths)

        # Discriminator relearns scores from previous epochs
        elif optimizer_name == "D_enh" and phase == TrainingPhase.HISTORICAL_DATA:
            target_score = batch.score.unsqueeze(1).float()
            estimated_score = self.estimate_discriminator_score(enhanced_spectrum)

        # Discriminator learns scores of noisy speech
        elif optimizer_name == "D_noisy":
            noisy_spectrum = self.extract_spectrogram_features(noisy_waveform)
            target_score = self.calculate_metric_score(
                utterance_ids, noisy_waveform, noisy_waveform, lengths
            )
            estimated_score = self.estimate_discriminator_score(noisy_spectrum)
            # Save scores of noisy wavs
            self.store_noisy_scores(utterance_ids, target_score)

        if phase == sb.Stage.TRAIN:
            # Compute the cost
            loss = self.hparams.compute_cost(estimated_score, target_score)
            if optimizer_name == "generator":
                loss += self.hparams.mse_weight * mse_loss
                self.training_metrics["G"].append(loss.detach())
            else:
                self.training_metrics["D"].append(loss.detach())

        # Validation and test metrics
        if phase != sb.Stage.TRAIN:
            clean_waveform, lengths = batch.clean_sig

            loss = self.hparams.compute_si_snr(enhanced_waveform, clean_waveform, lengths)

            # Evaluate speech quality/intelligibility
            self.stoi_metric.append(
                batch.id, enhanced_waveform, clean_waveform, lengths, reduction="batch"
            )
            self.pesq_metric.append(
                batch.id, predict=enhanced_waveform, target=clean_waveform, lengths=lengths
            )
            if self.hparams.calculate_dnsmos_on_validation_set:
                self.dnsmos_metric.append(
                    batch.id,
                    predict=enhanced_waveform,
                    target=enhanced_waveform,
                    lengths=lengths,
                )

            # Write wavs to file, for evaluation
            actual_lengths = lengths * clean_waveform.shape[1]
            for name, pred_wav, length in zip(batch.id, enhanced_waveform, actual_lengths):
                filename = name + ".wav"
                output_path = os.path.join(self.hparams.enhanced_folder, filename)
                torchaudio.save(
                    output_path,
                    torch.unsqueeze(pred_wav[: int(length)].cpu(), 0),
                    16000,
                )

        return loss

    def generate_utterance_ids(self, original_ids, optimizer_name):
        """Generate unique IDs based on optimizer context"""
        if optimizer_name == "D_enh":
            return [f"{uid}@{self.epoch}" for uid in original_ids]
        return original_ids

    def store_noisy_scores(self, batch_ids, scores):
        """Store noisy speech scores in cache"""
        for identifier, score_value in zip(batch_ids, scores):
            self.noisy_scores_cache[identifier] = score_value

    def calculate_metric_score(self, batch_ids, degraded, reference, lengths):
        """Calculate actual metric score (PESQ, SRMR, or DNSMOS)"""
        new_indices = [
            idx
            for idx, item_id in enumerate(batch_ids)
            if item_id not in self.historical_data and item_id not in self.noisy_scores_cache
        ]

        if len(new_indices) > 0:
            if self.hparams.target_metric in ["srmr", "dnsmos"]:
                self.target_metric.append(
                    ids=[batch_ids[i] for i in new_indices],
                    predict=degraded[new_indices].detach(),
                    target=reference[new_indices].detach(),
                    lengths=lengths[new_indices],
                )
                score = torch.tensor(
                    [[s] for s in self.target_metric.scores], device=self.device
                )
            else:
                raise ValueError("Expected 'srmr' or 'dnsmos' for target_metric")

            # Clear metric scores to prepare for next batch
            self.target_metric.clear()

        # Combine cached scores and new scores
        final_scores = []
        for idx, item_id in enumerate(batch_ids):
            if item_id in self.historical_data:
                final_scores.append([self.historical_data[item_id]["score"]])
            elif item_id in self.noisy_scores_cache:
                final_scores.append([self.noisy_scores_cache[item_id]])
            elif len(new_indices) > 0 and idx in new_indices:
                final_scores.append([score[new_indices.index(idx)]])
            else:
                final_scores.append([0.0])  # fallback value

        return torch.tensor(final_scores, device=self.device)

    def estimate_discriminator_score(self, degraded_spectrum):
        """Estimate discriminator score for given spectrum"""
        return self.modules.discriminator(degraded_spectrum.unsqueeze(1))

    def save_enhanced_samples(self, batch_ids, waveforms, scores, lengths):
        """Save enhanced waveforms and their scores for historical training"""
        actual_lengths = lengths * waveforms.shape[1]
        records = {}

        for i, (name, pred_wav, length) in enumerate(zip(batch_ids, waveforms, actual_lengths)):
            filepath = os.path.join(self.hparams.MetricGAN_folder, name + ".wav")
            audio_data = torch.unsqueeze(pred_wav[: int(length)].cpu(), 0)
            torchaudio.save(filepath, audio_data, self.hparams.Sample_rate)

            # Record path and score for historical training
            score_value = float(scores[i][0])
            records[name] = {
                "enh_wav": filepath,
                "score": score_value,
            }

        # Update records for historical training
        self.historical_data.update(records)

        with open(self.hparams.historical_file, 'wb') as file:
            pickle.dump(self.historical_data, file)

    def train_one_step(self, batch):
        """Perform one training step updating either D or G based on phase"""
        predictions = self.generate_enhanced_signal(batch, sb.Stage.TRAIN)
        loss_tracker = 0

        if self.phase == TrainingPhase.CURRENT_DATA:
            for mode in ["enh", "noisy"]:
                loss = self.calculate_training_loss(
                    predictions, batch, sb.Stage.TRAIN, f"D_{mode}"
                )
                self.d_optimizer.zero_grad()
                loss.backward()
                torch.nn.utils.clip_grad_norm_(
                    self.modules.parameters(), self.max_grad_norm
                )
                self.d_optimizer.step()
                loss_tracker += loss.detach() / 3
        elif self.phase == TrainingPhase.HISTORICAL_DATA:
            loss = self.calculate_training_loss(
                predictions, batch, sb.Stage.TRAIN, "D_enh"
            )
            self.d_optimizer.zero_grad()
            loss.backward()
            torch.nn.utils.clip_grad_norm_(
                self.modules.parameters(), self.max_grad_norm
            )
            self.d_optimizer.step()
            loss_tracker += loss.detach()
        elif self.phase == TrainingPhase.GENERATOR_ONLY:
            # Clamp Learnable_sigmoid parameters
            for name, param in self.modules.generator.named_parameters():
                if "Learnable_sigmoid" in name:
                    param.data = torch.clamp(param, max=3.5)

            loss = self.calculate_training_loss(
                predictions, batch, sb.Stage.TRAIN, "generator"
            )
            self.g_optimizer.zero_grad()
            loss.backward()
            torch.nn.utils.clip_grad_norm_(
                self.modules.parameters(), self.max_grad_norm
            )
            self.g_optimizer.step()
            loss_tracker += loss.detach()

        return loss_tracker

    def start_of_epoch(self, stage, epoch=None):
        """Initialize metrics and prepare for new epoch"""
        self.training_metrics = {"G": [], "D": []}

        if stage == sb.Stage.TRAIN:
            if self.hparams.target_metric == "srmr":
                self.target_metric = MetricStats(
                    metric=compute_srmr_normalized,
                    n_jobs=self.hparams.n_jobs,
                    batch_eval=False,
                )
            elif self.hparams.target_metric == "dnsmos":
                self.target_metric = MetricStats(
                    metric=request_dnsmos_score,
                    n_jobs=self.hparams.n_jobs,
                    batch_eval=False,
                )
            else:
                raise NotImplementedError(
                    "Right now we only support 'srmr' and 'dnsmos'"
                )

            # Train discriminator before generator training
            if self.phase == TrainingPhase.GENERATOR_ONLY:
                self.epoch = epoch
                self.train_discriminator()
                self.phase = TrainingPhase.GENERATOR_ONLY
                print("Generator training by current data...")

        if stage != sb.Stage.TRAIN:
            self.pesq_metric = MetricStats(
                metric=compute_pesq_score, n_jobs=self.hparams.n_jobs, batch_eval=False
            )
            self.stoi_metric = MetricStats(metric=stoi_loss)
            self.srmr_metric = MetricStats(
                metric=compute_srmr_raw,
                n_jobs=self.hparams.n_jobs,
                batch_eval=False,
            )
            self.dnsmos_metric = MetricStats(
                metric=request_dnsmos_raw_score,
                n_jobs=self.hparams.n_jobs,
                batch_eval=False,
            )

    def train_discriminator_network(self):
        """Complete three-pass training for discriminator"""
        # First pass: current data updates
        print("Discriminator training by current data...")
        self.phase = TrainingPhase.CURRENT_DATA
        self.fit(
            range(1),
            self.train_set,
            train_loader_kwargs=self.hparams.dataloader_options,
        )

        # Second pass: historical data updates
        if self.historical_data:
            print("Discriminator training by historical data...")
            self.phase = TrainingPhase.HISTORICAL_DATA
            self.fit(
                range(1),
                self.historical_data,
                train_loader_kwargs=self.hparams.dataloader_options,
            )

        # Third pass: current data again
        print("Discriminator training by current data again...")
        self.phase = TrainingPhase.CURRENT_DATA
        self.fit(
            range(1),
            self.train_set,
            train_loader_kwargs=self.hparams.dataloader_options,
        )

    def end_of_epoch(self, stage, stage_loss, epoch=None):
        """Summarize epoch progress and handle checkpointing"""
        if self.phase != TrainingPhase.GENERATOR_ONLY:
            return

        if stage == sb.Stage.TRAIN:
            self.train_loss = stage_loss
            g_losses = torch.tensor(self.training_metrics["G"])
            d_losses = torch.tensor(self.training_metrics["D"])
            print("Avg G loss: %.3f" % torch.mean(g_losses))
            print("Avg D loss: %.3f" % torch.mean(d_losses))
        else:
            if self.hparams.calculate_dnsmos_on_validation_set:
                validation_stats = {
                    "SI-SNR": -stage_loss,
                    "pesq": 5 * self.pesq_metric.summarize("average") - 0.5,
                    "stoi": -self.stoi_metric.summarize("average"),
                    "dnsmos": self.dnsmos_metric.summarize("average"),
                }
            else:
                validation_stats = {
                    "SI-SNR": -stage_loss,
                    "pesq": 5 * self.pesq_metric.summarize("average") - 0.5,
                    "stoi": -self.stoi_metric.summarize("average"),
                }

        if stage == sb.Stage.VALID:
            old_lr, new_lr = self.hparams.lr_annealing(5.0 - validation_stats["pesq"])
            sb.nnet.schedulers.update_learning_rate(self.g_optimizer, new_lr)

            if self.hparams.use_tensorboard:
                if self.hparams.calculate_dnsmos_on_validation_set:
                    valid_stats = {
                        "SI-SNR": -stage_loss,
                        "pesq": 5 * self.pesq_metric.summarize("average") - 0.5,
                        "stoi": -self.stoi_metric.summarize("average"),
                        "dnsmos": self.dnsmos_metric.summarize("average"),
                    }
                else:
                    valid_stats = {
                        "SI-SNR": -stage_loss,
                        "pesq": 5 * self.pesq_metric.summarize("average") - 0.5,
                        "stoi": -self.stoi_metric.summarize("average"),
                    }

                self.hparams.tensorboard_train_logger.log_stats(
                    {"lr": old_lr}, valid_stats
                )
            self.hparams.train_logger.log_stats(
                {"Epoch": epoch, "lr": old_lr},
                train_stats={"loss": self.train_loss},
                valid_stats=validation_stats,
            )
            self.checkpointer.save_and_keep_only(meta=validation_stats, max_keys=["pesq"])

        if stage == sb.Stage.TEST:
            self.hparams.train_logger.log_stats(
                {"Epoch loaded": self.hparams.epoch_counter.current},
                test_stats=validation_stats,
            )

    def create_dataloader(self, dataset, stage, ckpt_prefix="dataloader-", **loader_kwargs):
        """Custom dataloader creation with sampling strategy"""
        if stage == sb.Stage.TRAIN:
            if self.phase == TrainingPhase.HISTORICAL_DATA:
                dataset = sb.dataio.dataset.DynamicItemDataset(
                    data=dataset,
                    dynamic_items=[enh_pipeline],
                    output_keys=["id", "enh_sig", "score"],
                )
                samples = round(len(dataset) * self.hparams.history_portion)
                samples = max(samples, 1)
            else:
                samples = self.hparams.number_of_samples

            # Ensure reproducible sampling across epochs
            current_epoch = self.hparams.epoch_counter.current

            # Equal weights for all samples
            weights = torch.ones(len(dataset))
            replacement = samples > len(dataset)
            sampler = ReproducibleWeightedRandomSampler(
                weights,
                epoch=current_epoch,
                replacement=replacement,
                num_samples=samples,
            )
            loader_kwargs["sampler"] = sampler

            if self.phase == TrainingPhase.GENERATOR_ONLY:
                self.train_sampler = sampler

        return super().create_dataloader(dataset, stage, ckpt_prefix, **loader_kwargs)

    def initialize_optimizers(self):
        """Initialize generator and discriminator optimizers"""
        self.g_optimizer = self.hparams.g_opt_class(
            self.modules.generator.parameters()
        )
        self.d_optimizer = self.hparams.d_opt_class(
            self.modules.discriminator.parameters()
        )

        if self.checkpointer is not None:
            self.checkpointer.add_recoverable("g_opt", self.g_optimizer)
            self.checkpointer.add_recoverable("d_opt", self.d_optimizer)

    def reset_gradients(self, set_to_none=False):
        """Reset gradients for both optimizers"""
        self.g_optimizer.zero_grad(set_to_none)
        self.d_optimizer.zero_grad(set_to_none)


# Define audio pipelines for training set
@sb.utils.data_pipeline.takes("noisy_wav")
@sb.utils.data_pipeline.provides("noisy_sig")
def audio_pipeline_train(noisy_wav):
    yield sb.dataio.dataio.read_audio(noisy_wav)


# Define audio pipelines for validation/test set
@sb.utils.data_pipeline.takes("noisy_wav", "clean_wav")
@sb.utils.data_pipeline.provides("noisy_sig", "clean_sig")
def audio_pipeline_valid(noisy_wav, clean_wav):
    yield sb.dataio.dataio.read_audio(noisy_wav)
    yield sb.dataio.dataio.read_audio(clean_wav)


# For historical data
@sb.utils.data_pipeline.takes("enh_wav")
@sb.utils.data_pipeline.provides("enh_sig")
def enh_pipeline(enh_wav):
    yield sb.dataio.dataio.read_audio(enh_wav)


def prepare_datasets(hparams):
    """Prepare datasets for training, validation, and testing"""
    datasets = {}

    datasets["train"] = sb.dataio.dataset.DynamicItemDataset.from_json(
        json_path=hparams["train_annotation"],
        replacements={"data_root": hparams["data_folder"]},
        dynamic_items=[audio_pipeline_train],
        output_keys=["id", "noisy_sig"],
    )
    datasets["valid"] = sb.dataio.dataset.DynamicItemDataset.from_json(
        json_path=hparams["valid_annotation"],
        replacements={"data_root": hparams["data_folder"]},
        dynamic_items=[audio_pipeline_valid],
        output_keys=["id", "noisy_sig", "clean_sig"],
    )

    datasets["test"] = sb.dataio.dataset.DynamicItemDataset.from_json(
        json_path=hparams["test_annotation"],
        replacements={"data_root": hparams["data_folder"]},
        dynamic_items=[audio_pipeline_valid],
        output_keys=["id", "noisy_sig", "clean_sig"],
    )

    return datasets


def ensure_directory_exists(path):
    """Create directory if it doesn't exist"""
    if not os.path.isdir(path):
        os.makedirs(path)


# Recipe begins!
if __name__ == "__main__":
    # Load hyperparameters file with command-line overrides
    hparams_file, run_opts, overrides = sb.parse_arguments(sys.argv[1:])
    with open(hparams_file) as config_file:
        hparams = load_hyperpyyaml(config_file, overrides)

    # Initialize ddp (useful only for multi-GPU DDP training)
    sb.utils.distributed.ddp_init_group(run_opts)

    # Data preparation
    from voicebank_prepare import prepare_voicebank  # noqa

    run_on_main(
        prepare_voicebank,
        kwargs={
            "data_folder": hparams["data_folder"],
            "save_folder": hparams["data_folder"],
            "skip_prep": hparams["skip_prep"],
        },
    )

    # Create dataset objects
    datasets = prepare_datasets(hparams)

    # Create experiment directory
    sb.create_experiment_directory(
        experiment_directory=hparams["output_folder"],
        hyperparams_to_save=hparams_file,
        overrides=overrides,
    )

    if hparams["use_tensorboard"]:
        from speechbrain.utils.train_logger import TensorboardLogger

        hparams["tensorboard_train_logger"] = TensorboardLogger(
            hparams["tensorboard_logs"]
        )

    # Create the folder to save enhanced files (+ support for DDP)
    run_on_main(ensure_directory_exists, kwargs={"folder": hparams["enhanced_folder"]})

    se_brain = SpeechEnhancementBrain(
        modules=hparams["modules"],
