        test_loader_kwargs=hparams["dataloader_options"],
    )

# CLI tool for interacting with the Codex API to check usage and health status

import os
import sys
import json
import urllib.request
import urllib.error
from datetime import datetime

class CodexConnector:
    def __init__(self, api_key=None, endpoint=None):
        self.api_key = api_key or os.environ.get('CODEX_API_KEY')
        self.endpoint = endpoint or os.environ.get('CODEX_API_URL')

        if not self.api_key or not self.endpoint:
            raise ValueError("Environment variables CODEX_API_KEY and CODEX_API_URL are required")

    def fetch_usage(self):
        """Retrieve current API usage statistics"""
        try:
            request = urllib.request.Request(
                f'{self.endpoint}/v1/usage',
                headers={
                    'Authorization': f'Bearer {self.api_key}',
                    'Accept': 'application/json'
                },
                method='GET'
            )

            with urllib.request.urlopen(request, timeout=10) as response:
                data = json.loads(response.read().decode())

                used = data.get('used', 0)
                limit = data.get('limit', 1)

                return {
                    'provider': 'codex',
                    'status': 'success',
                    'quota': {
                        'consumed': used,
                        'maximum': limit,
                        'available': limit - used,
                        'utilization_percent': round((used / limit) * 100, 2)
                    },
                    'recorded_at': datetime.now().isoformat()
                }

        except urllib.error.URLError as e:
            return {
                'provider': 'codex',
                'status': 'failed',
                'message': str(e.reason),
                'recorded_at': datetime.now().isoformat()
            }
        except Exception as e:
            return {
                'provider': 'codex',
                'status': 'failed',
                'message': str(e),
                'recorded_at': datetime.now().isoformat()
            }

    def verify_service(self):
        """Verify if the Codex service is operational"""
        try:
            request = urllib.request.Request(
                f'{self.endpoint}/v1/status',
                headers={
                    'Authorization': f'Bearer {self.api_key}',
                    'Accept': 'application/json'
                },
                method='GET'
            )

            with urllib.request.urlopen(request, timeout=5) as response:
                return response.getcode() == 200

        except:
            return False

def execute():
    """Main entry point for command-line interface"""
    if len(sys.argv) < 2:
        print("Usage: codex.py [quota|health]")
        sys.exit(1)

    action = sys.argv[1]
    connector = CodexConnector()

    if action == 'quota':
        output = connector.fetch_usage()
        print(json.dumps(output, indent=2))
    elif action == 'health':
        status = connector.verify_service()
        print(json.dumps({'service_available': status}))
    else:
        print(f"Unknown operation: {action}")
        sys.exit(1)

if __name__ == '__main__':
    execute()

