import logging
import types
from typing import Callable, List, Tuple, Any
import torch
from torch.distributed import DeviceMesh
from torch.distributed.tensor import Shard, DTensor, Replicate, distribute_tensor, distribute_module

# Import internal utilities
from mindspeed.fsdp.distributed.expert_parallel.dispatcher import get_experts_forward_fn as _get_eager_dispatcher
from mindspeed.fsdp.distributed.expert_parallel.dispatcher_mc2 import get_experts_forward_mc2_fn as _get_mc2_dispatcher
from mindspeed.fsdp.parallel_engine_config import EPPlanConfig
from mindspeed.fsdp.utils.log import print_rank
from mindspeed.fsdp.utils.str_match import module_name_match

_logger = logging.getLogger(__name__)


def apply_expert_parallel(modules: torch.nn.Module, ep_mesh: DeviceMesh, config: EPPlanConfig) -> torch.nn.Module:
    """
    Apply expert parallelism to selected modules based on configuration.
    Replaces their forward method with an EP-aware version.
    """
    target_modules = _collect_expert_parallel_modules(modules, config)

    group = ep_mesh.get_group()
    world_size = torch.distributed.get_world_size(group)
    rank_in_group = torch.distributed.get_rank(group)

    for mod in target_modules:
        _distribute_module_weights(mod, ep_mesh)

        # Replace forward method
        if hasattr(mod, 'ep_forward') and callable(mod.ep_forward):
            mod.forward = lambda self, *args, ep_group=group, **kwargs: self.ep_forward(*args, ep_group=ep_group, **kwargs)
        else:
            dispatcher = _select_expert_forward_strategy(config.dispatcher_type, group)
            mod.forward = types.MethodType(dispatcher, mod)

    return modules


def _collect_expert_parallel_modules(root: torch.nn.Module, cfg: EPPlanConfig) -> List[torch.nn.Module]:
    """Gather modules matching patterns specified in the plan."""
    matched = []
    for pattern in cfg.apply_modules:
        for path, mod in root.named_modules():
            if module_name_match(pattern, path):
                print_rank(_logger.debug, f'[Expert Parallel]: Applying EP to module <{path}>')
                matched.append(mod)
    if not matched:
        raise RuntimeError(f'[Expert Parallel] No modules matched patterns: {cfg.apply_modules}')
    return matched


def _wrap_as_dtensor_if_needed(tensor: torch.Tensor, mesh: DeviceMesh) -> DTensor:
    """Ensure tensor is wrapped as DTensor using Replicate placement if not already."""
    if isinstance(tensor, DTensor):
        return tensor
    return DTensor.from_local(tensor, mesh, (Replicate(),), run_check=False)


def _prepare_inputs_for_distribute(module: torch.nn.Module, inputs: Tuple[Any], mesh: DeviceMesh) -> Tuple[Any]:
    """Convert local tensors in inputs to DTensors before distribution."""
    new_inputs = list(inputs)
    for i, t in enumerate(new_inputs):
        new_inputs[i] = _wrap_as_dtensor_if_needed(t, mesh)
    return tuple(new_inputs)


def _convert_outputs_to_local(module: torch.nn.Module, outputs: Any, mesh: DeviceMesh) -> Any:
    """Convert DTensor outputs back to local tensors."""
    if isinstance(outputs, DTensor):
        return outputs.to_local()
    return outputs


def _distribute_module_weights(module: torch.nn.Module, mesh: DeviceMesh):
    """Distribute parameters across device mesh using Shard(0)."""
    def _distribute_param(m: torch.nn.Module):
        for n, p in m.named_parameters(recurse=False):
            dist_p = torch.nn.Parameter(distribute_tensor(p, mesh, [Shard(0)]))
            m.register_parameter(n, dist_p)

    # Recursively apply to submodules
    for child in module.children():
        _distribute_param(child)
    _distribute_param(module)

    # Register hooks for gradient scaling
    _attach_gradient_scaling_hooks(module, torch.distributed.get_world_size(mesh.get_group()))


def _attach_gradient_scaling_hooks(module: torch.nn.Module, ep_world_size: int):
    """Add backward hook to divide gradients by expert parallel world size."""
    for param in module.parameters():
        if param.requires_grad and param.grad is not None:
            def _scale_grad_hook(grad):
                return grad / ep_world_size
            param.register_hook(_scale_grad_hook)


def _select_expert_forward_strategy(strategy: str, group) -> Callable:
    """Select appropriate expert forward function based on dispatcher type."""
    if strategy == 'eager':
        return _get_eager_dispatcher(group, fused=False)
    elif strategy == 'fused':
        return _get_eager_dispatcher(group, fused=True)
    elif strategy == 'mc2':
        return _get_mc2_dispatcher(group)
    else:
        raise RuntimeError(f'Unsupported dispatcher strategy: {strategy}')


def _qwen_expert_forward_impl(ep_group, fused=True):
    """Factory returning Qwen-specific expert forward closure."""
    from .fused_ep import fused_ep_forward as _fused_impl

    def _forward(self, hidden_states: torch.Tensor, routing_weights: torch.Tensor, router_indices: torch.Tensor):
        batch_dim = hidden_states.size(0)
        flat_hidden = hidden_states.view(-1, self.hidden_size)

        gate_up = self.gate_up_proj.to_local() if isinstance(self.gate_up_proj, DTensor) else self.gate_up_proj
        down = self.down_proj.to_local() if isinstance(self.down_proj, DTensor) else self.down_proj

        result = _fused_impl(
            num_experts=self.num_experts,
            routing_weights=routing_weights,
            indices=router_indices,
            input_tensor=flat_hidden,
            fc1_weight=gate_up,
            fc2_weight=down,
            process_group=ep_group
        )

        return result.view(batch_dim, -1, self.hidden_size)

    return _forward

