def apply_config_overrides(base_config: 'SimpleVllmConfig',
                           config_types: List[str],
                           override_maps: List[Dict[str, Any]]) -> 'SimpleVllmConfig':
    """Apply multiple overrides to a base configuration."""
    current_config = SimpleVllmConfig()

    # Copy existing values from base_config if provided
    if base_config is not None:
        current_config.additional_config = dict(base_config.additional_config)
        current_config.model_config = base_config.model_config

    for cfg_type, override in zip(config_types, override_maps):
        if cfg_type == "model":
            # Apply model-specific overrides
            for key, value in override.items():
                setattr(current_config.model_config, key, value)
        else:
            # Apply general overrides
            for key, value in override.items():
                setattr(current_config, key, value)

    return current_config

@dataclass
class SimpleVllmConfig:
    """Simplified VLLM configuration wrapper."""
    extra_settings: Dict[str, Any] = field(default_factory=dict)
    # Default max_model_len set to suppress warnings
    model_options: ModelConfig = field(
        default_factory=lambda: ModelConfig(max_model_len=1024))

@dataclass
class SimpleConfig(Config):
    """Configuration class implementing the base Config interface."""
    vllm_settings: SimpleVllmConfig
    param_a: str
    param_b: str
    param_c: int

    def matches(self, other: Config) -> bool:
        """Check equality between configurations, excluding vllm_settings."""
        for attr in fields(self):
            if attr.name != "vllm_settings":
                self_val = getattr(self, attr.name)
                other_val = getattr(other, attr.name)
                if self_val != other_val:
                    return False
        return True

