# Custom reward computation for environment service evaluation

from ajet.task_judge.base_judge import BaseJudge
from ajet.workflow import WorkflowOutput, WorkflowTask

class EnvServiceJudge(BaseJudge):
    def __init__(self, settings):
        self.settings = settings

    def calculate_reward(self, task: WorkflowTask, result: WorkflowOutput) -> tuple:
        base_score = 0.0
        environment = task.gym_env

        # Evaluate the episode without sparse rewards
        base_score = environment.evaluate(task.episode_uuid, params={"sparse": False})

        # Determine success based on threshold
        if base_score >= 1.0:
            success_flag = True
        else:
            success_flag = False

        # Apply reward scaling based on success status
        if success_flag:
            final_score = 1.0 + base_score * 0.5
        else:
            final_score = base_score * 0.5

        return final_score, success_flag

import warnings
import narwhals as nw
from narwhals.typing import Frame

class PolarsMaterializationWarning(Warning):
    pass

    @classmethod
    def check_and_warn_implementation(cls, expected_impl: nw.Implementation, actual_impl: nw.Implementation, extra_info: str = ""):
        if expected_impl is not actual_impl:
            msg = f"Narwhals implementation mismatch: native is {expected_impl}, got {actual_impl}. This will lead to materialization into an eager Polars frame."
            if extra_info:
                msg += f" {extra_info}"
            warnings.warn(msg, cls, stacklevel=3)

class MetaxyColumnMissingWarning(Warning):
    pass

    @classmethod
    def check_and_warn_column(cls, required_col: str, data_frame: Frame, additional_msg: str = ""):
        # Avoid PerformanceWarning on lazy frames by using collect_schema().names()
        available_cols = data_frame.collect_schema().names()
        if required_col in available_cols:
            return
        else:
            msg = f"Metaxy column missing: expected {required_col}, got {available_cols}."
            if additional_msg:
                msg += f" {additional_msg}"
            warnings.warn(msg, cls, stacklevel=3)

import datetime

def get_period_boundaries(start_date, end_date, period_type):
    result_periods = []

    if period_type == "monthly":
        # Start from the first day of the month of start_date
        current = datetime.date(start_date.year, start_date.month, 1)
        while current < end_date:
            # Calculate the first day of next month by going to last day of current month + 1 day
            # Using day=28 + 4 days ensures we're past the end of any month, then reset to day 1
            next_month = (current.replace(day=28) + datetime.timedelta(days=4)).replace(day=1)
            end_boundary = min(next_month, end_date)
            result_periods.append((current, end_boundary, current.strftime("%Y-%m")))
            current = next_month
    else:  # yearly
        # Start from January 1st of the start_date's year
        current = datetime.date(start_date.year, 1, 1)
        while current < end_date:
            next_year = datetime.date(current.year + 1, 1, 1)
            end_boundary = min(next_year, end_date)
            result_periods.append((current, end_boundary, str(current.year)))
            current = next_year

    return result_periods

def filter_entries_by_timeframe(entries, begin_date=None, finish_date=None):
    selected_entries = []

    for item in entries:
        # Skip date filtering if no date attribute exists
        if not hasattr(item, "date"):
            selected_entries.append(item)
            continue

        # Apply start date filter
        if begin_date is not None and item.date < begin_date:
            continue

        # Apply end date filter (exclusive upper bound)
        if finish_date is not None and item.date >= finish_date:
            continue

        selected_entries.append(item)

    return selected_entries

def build_account_tree(account_node):
    tree_structure = {
        "name": account_node.account,
        "values": {},
        "subaccounts": [],
    }

    # Aggregate balances by currency
    for holding in account_node.balance:
        currency = holding.units.currency
        value = float(holding.units.number)
        tree_structure["values"][currency] = tree_structure["values"].get(currency, 0) + value

    # Process child accounts in alphabetical order
    for child_account in sorted(account_node.values(), key=lambda acc: acc.account):
        child_tree = build_account_tree(child_account)

        # Only include non-empty subtrees
        if child_tree["subaccounts"] or child_tree["values"]:
            tree_structure["subaccounts"].append(child_tree)

    return tree_structure

def extract_subtree(realization_map, account_path, default_name):
    account = realization_map.get(account_path, default_name)
    if account is None:
        return {"name": default_name, "values": {}, "subaccounts": []}
    return build_account_tree(account)

def aggregate_balances(realization_map, account_path, default_name):
    account = realization_map.get(account_path, default_name)
    if account is None:
        return {}

    totals = {}

    def traverse(node):
        for holding in node.balance:
            currency = holding.units.currency
            amount = float(holding.units.number)
            totals[currency] = totals.get(currency, 0) + amount
        for child in node.values():
            traverse(child)

    traverse(account)
    return totals

def convert_to_target_currency(balances, price_data, target, as_of_date=None):
    """Convert a {currency: amount} dictionary into a single {target_currency: amount} value."""
    from beancount.core.prices import get_price

    converted_total = 0.0

    for currency, amount in balances.items():
        if currency == target:
            converted_total += amount
        else:
            price_result = get_price(price_data, (currency, target), as_of_date)
            if price_result is None:
                raise Exception(f"Missing price data for {currency} to {target}")

            _, rate = price_result
            converted_total += amount * float(rate)

    return {target: round(converted_total, 2)}

def compute_subtree_totals(tree_node):
    """Calculate total balance across entire subtree rooted at tree_node."""
    subtotal = sum(tree_node["values"].values())

    for child in tree_node["subaccounts"]:
        subtotal += compute_subtree_totals(child)

    return subtotal

def transform_tree_to_currency(tree_node, price_info, target_currency, on_date=None):
    """Recursively convert all balances in an account tree to specified currency."""
    # Convert child nodes first
    converted_children = [
        transform_tree_to_currency(child, price_info, target_currency, on_date) 
        for child in tree_node["subaccounts"]
    ]

    # Sort children by absolute total balance in descending order
    converted_children.sort(key=lambda c: abs(compute_subtree_totals(c)), reverse=True)

    # Build new node with converted values
    new_node = {
        "name": tree_node["name"],
        "values": convert_to_target_currency(tree_node["values"], price_info, target_currency, on_date) if tree_node["values"] else {},
        "subaccounts": converted_children,
    }

    return new_node

