class SOCKSHTTPBridge(HTTPConnection):
    """
    Extended HTTP connection that uses SOCKS proxy for routing.
    Overrides standard connection behavior to integrate SOCKS proxy functionality.
    """
    def __init__(self, *args, **kwargs):
        self._proxy_config = kwargs.pop("_socks_options")
        super(SOCKSHTTPBridge, self).__init__(*args, **kwargs)

    def _establish_link(self):
        """
        Create a new network link through the configured SOCKS proxy.
        """
        additional_params = {}

        if hasattr(self, 'source_address') and self.source_address:
            additional_params["source_address"] = self.source_address

        if hasattr(self, 'socket_options') and self.socket_options:
            additional_params["socket_options"] = self.socket_options

        try:
            target_addr = (self.host, self.port)
            proxy_cfg = self._proxy_config

            sock_conn = socks.create_connection(
                target_addr,
                proxy_type=proxy_cfg["socks_version"],
                proxy_addr=proxy_cfg["proxy_host"],
                proxy_port=proxy_cfg["proxy_port"],
                proxy_username=proxy_cfg.get("username"),
                proxy_password=proxy_cfg.get("password"),
                proxy_rdns=proxy_cfg["rdns"],
                timeout=self.timeout,
                **additional_params
            )
        except SocketTimeout:
            raise ConnectTimeoutError(
                self,
                f"Connection to {self.host} timed out. (connect timeout={self.timeout})"
            )
        except socks.ProxyError as proxy_err:
            # Handle proxy-specific errors with layered exception handling
            underlying_error = getattr(proxy_err, 'socket_err', None)

            if underlying_error is not None:
                if isinstance(underlying_error, SocketTimeout):
                    raise ConnectTimeoutError(
                        self,
                        f"Connection to {self.host} timed out. (connect timeout={self.timeout})"
                    )
                else:
                    raise NewConnectionError(
                        self, f"Failed to establish connection: {underlying_error}"
                    )
            else:
                raise NewConnectionError(
                    self, f"Proxy error occurred: {proxy_err}"
                )
        except SocketError as net_err:
            raise NewConnectionError(
                self, f"Network failure during connection: {net_err}"
            )

        return sock_conn


# HTTPS variant - inherits both SOCKS and HTTPS capabilities
class SOCKSTLSBridge(SOCKSHTTPBridge, HTTPSConnection):
    """Secure version of SOCKS-enabled connection."""
    pass


# Connection pools specialized for SOCKS routing
class SOCKSPlainPool(HTTPConnectionPool):
    ConnectionCls = SOCKSHTTPBridge


class SOCKSSecurePool(HTTPSConnectionPool):
    ConnectionCls = SOCKSTLSBridge


# High-level manager for SOCKS-based proxying
class SOCKSRouteManager(PoolManager):
    """
    Custom pool manager that handles routing via SOCKS proxies.
    Supports multiple SOCKS protocol versions and authentication methods.
    """

    pool_classes_by_scheme = {
        "http": SOCKSPlainPool,
        "https": SOCKSSecurePool,
    }

    def __init__(
        self,
        proxy_endpoint,
        login=None,
        secret=None,
        pool_count=10,
        request_headers=None,
        **pool_kwargs
    ):
        parsed_proxy = parse_url(proxy_endpoint)

        # Extract credentials from URL if not explicitly provided
        if login is None and secret is None and parsed_proxy.auth:
            auth_parts = parsed_proxy.auth.split(":", 1)
            if len(auth_parts) == 2:
                login, secret = auth_parts

        # Determine SOCKS protocol version and RDNS setting
        scheme_map = {
            "socks5": (socks.PROXY_TYPE_SOCKS5, False),
            "socks5h": (socks.PROXY_TYPE_SOCKS5, True),
            "socks4": (socks.PROXY_TYPE_SOCKS4, False),
            "socks4a": (socks.PROXY_TYPE_SOCKS4, True),
        }

        if parsed_proxy.scheme in scheme_map:
            socks_ver, rdns_flag = scheme_map[parsed_proxy.scheme]
        else:
            raise ValueError(f"Unsupported SOCKS scheme: {parsed_proxy.scheme}")

        # Store configuration for later use
        self.proxy_url = proxy_endpoint

