from blankly.exchanges.futures.futures_exchange import FuturesExchange
from tests.new_interface_tests.test_utils import FUTURES_EXCHANGES, get_symbols, SPOT_EXCHANGES

def generate_test_id(argument):
    # Return exchange type if it's an interface instance, otherwise return the argument as-is
    if isinstance(argument, ABCBaseExchangeInterface):
        return argument.get_exchange_type()
    return str(argument)

def pytest_generate_tests(metafunc: Metafunc):
    # Identify interface-related fixture names in the current test function
    interface_names = [name for name in metafunc.fixturenames if name.endswith('interface')]

    # Skip if no interface fixtures are present
    if not interface_names:
        return

    # Ensure only one interface parameter exists per test
    if len(interface_names) > 1:
        raise ValueError("Only one interface parameter is allowed per test function")

    selected_param = interface_names[0]

    # Determine which interfaces to use based on parameter name
    if selected_param == 'futures_interface':
        available_interfaces = [exch.interface for exch in FUTURES_EXCHANGES]
    elif selected_param == 'spot_interface':
        available_interfaces = [exch.interface for exch in SPOT_EXCHANGES]
    elif selected_param == 'interface':
        available_interfaces = [exch.interface for exch in FUTURES_EXCHANGES + SPOT_EXCHANGES]
    else:
        raise ValueError(f"Unsupported interface type: {selected_param}")

    # Handle symbol parameter if present
    if 'symbol' in metafunc.fixturenames:
        combined_values = []
        for iface in available_interfaces:
