import os
import zipfile
import requests
from get_ci_error_statistics import download_artifact, get_artifacts_links

def fetch_daily_workflow_runs(auth_token, count=7):
    """Retrieve workflow runs for the scheduled daily CI.
    Filters runs to only include those triggered by 'schedule' on the 'main' branch.
    """
    auth_headers = None
    if auth_token is not None:
        auth_headers = {
            "Accept": "application/vnd.github+json",
            "Authorization": f"Bearer {auth_token}"
        }

    # Workflow identifier (not run-specific)
    # Can be obtained from a workflow run via:
    # https://api.github.com/repos/huggingface/transformers/actions/runs/{run_id}
    workflow_identifier = "90575235"
    base_url = f"https://api.github.com/repos/huggingface/transformers/actions/workflows/{workflow_identifier}/runs"

    # Query parameters: main branch, schedule event, exclude PRs, limited results
    query_params = f"?branch=main&event=schedule&exclude_pull_requests=true&per_page={count}"
    full_url = base_url + query_params

    response = requests.get(full_url, headers=auth_headers)
    data = response.json()
    return data.get("workflow_runs", [])

def retrieve_latest_completed_run(auth_token):
    """Find the most recent completed workflow run ID for the daily CI."""
    runs_list = fetch_daily_workflow_runs(auth_token)
    run_id = None

    for run in runs_list:
        if run.get("status") == "completed":
            run_id = run.get("id")
            break

    return run_id

def fetch_latest_artifacts(artifact_names, target_directory, auth_token):
    """Download artifacts from the latest completed daily CI workflow run."""
    run_id = retrieve_latest_completed_run(auth_token)

    if run_id is not None:
        artifact_links = get_artifacts_links(workflow_run_id=run_id, token=auth_token)

        for name in artifact_names:
            if name in artifact_links:
                url = artifact_links[name]
                download_artifact(
                    artifact_name=name,
                    artifact_url=url,
                    output_dir=target_directory,
                    token=auth_token
                )

def extract_and_load_reports(artifact_names, target_directory, auth_token):
    """Load contents of artifacts from the latest completed daily CI workflow run."""
    fetch_latest_artifacts(artifact_names, target_directory, auth_token)

    report_data = {}

    for name in artifact_names:
        zip_path = os.path.join(target_directory, f"{name}.zip")

        if os.path.isfile(zip_path):
            report_data[name] = {}

            with zipfile.ZipFile(zip_path) as archive:
                for file_entry in archive.namelist():
                    if not os.path.isdir(file_entry):
                        with archive.open(file_entry) as file_obj:
                            content = file_obj.read().decode("UTF-8")
                            report_data[name][file_entry] = content

    return report_data

# Session quota management system - alternative implementation

import os
import sys
import json
from datetime import datetime, date

# Determine directory structure
BASE_PATH = os.path.dirname(os.path.abspath(__file__))
ROOT_DIR = os.path.dirname(BASE_PATH)
STORAGE_DIR = os.path.join(ROOT_DIR, 'data')
os.makedirs(STORAGE_DIR, exist_ok=True)

SESSION_FILE = os.path.join(STORAGE_DIR, 'session_quota.json')

def retrieve_quota_data():
    """Fetch current quota configuration"""
    if os.path.isfile(SESSION_FILE):
        with open(SESSION_FILE, 'r') as file:
            return json.load(file)
    return {
        'max_per_day': {},  # model -> maximum allowed sessions
        'daily_logs': {}    # date -> {model -> count}
    }

def persist_quota(data):
    """Store updated quota data to disk"""
    with open(SESSION_FILE, 'w') as output:
        json.dump(data, output, indent=2)

def configure_limit(model_name, session_cap):
    """Define daily session cap for a specific model"""
    config = retrieve_quota_data()
    config['max_per_day'][model_name] = session_cap
    persist_quota(config)
    print(f"Configured limit: {model_name} can have up to {session_cap} sessions per day")

def log_new_session(model_name):
    """Register a new session for a model"""
    config = retrieve_quota_data()
    current_date = datetime.now().strftime('%Y-%m-%d')

    if current_date not in config['daily_logs']:
        config['daily_logs'][current_date] = {}

    if model_name not in config['daily_logs'][current_date]:
        config['daily_logs'][current_date][model_name] = 0

    config['daily_logs'][current_date][model_name] += 1
    persist_quota(config)
    print(f"Session logged for model: {model_name}")

def verify_quota(model_name):
    """Determine remaining quota for a model today"""
    config = retrieve_quota_data()
    current_date = datetime.now().strftime('%Y-%m-%d')

    max_allowed = config['max_per_day'].get(model_name, None)  # None means unlimited
    current_usage = config['daily_logs'].get(current_date, {}).get(model_name, 0)

    if max_allowed is None:
        return {
            'status': True,
            'maximum': 'unlimited',
            'consumed': current_usage
        }

    remaining = max_allowed - current_usage
    return {
        'status': remaining > 0,
        'maximum': max_allowed,
        'consumed': current_usage,
        'left': remaining
    }

def fetch_daily_stats():
    """Retrieve all session counts for today"""
    config = retrieve_quota_data()
    current_date = datetime.now().strftime('%Y-%m-%d')
    return config['daily_logs'].get(current_date, {})

def cli_handler():
    """Process command-line arguments"""
    if len(sys.argv) < 2:
        print("Usage: session_quota.py [configure|log|verify|stats]")
        sys.exit(1)

    action = sys.argv[1]

    if action == 'configure':
        if len(sys.argv) != 4:
            print("Usage: session_quota.py configure <model> <limit>")
            sys.exit(1)
        configure_limit(sys.argv[2], int(sys.argv[3]))
    elif action == 'log':
        if len(sys.argv) != 3:
            print("Usage: session_quota.py log <model>")
            sys.exit(1)
        log_new_session(sys.argv[2])
    elif action == 'verify':
        if len(sys.argv) != 3:
            print("Usage: session_quota.py verify <model>")
            sys.exit(1)
        result = verify_quota(sys.argv[2])
        print(json.dumps(result, indent=2))
    elif action == 'stats':
        stats = fetch_daily_stats()
        print(json.dumps(stats, indent=2))
    else:
        print(f"Unknown operation: {action}")
        sys.exit(1)

if __name__ == '__main__':
    cli_handler()

# NATS callback function registry implementation

from django.conf import settings

class CallbackRegistry:
    """Manages registration of functions for NATS message handling"""

    def __init__(self):
        self._functions = {}

    def add(self, target_func=None, identifier=None, **options):
        # Direct registration: register(func, name, ...)
        if target_func is not None:
            return self._register_callback(target_func, identifier, **options)

        # Decorator usage without arguments: @register
        if identifier is not None and target_func is None and callable(identifier):
            return self._register_callback(identifier, **options)

        # Decorator usage with arguments: @register(...)
        def wrapper(func):
            return self.add(identifier, func, **options)
        return wrapper

    def _register_callback(self, func, name=None, **kwargs):
        # Determine namespace from kwargs or Django settings
        namespace = kwargs.get('stream', getattr(settings, 'NATS_NAMESPACE', 'default'))

        # Use provided name or fall back to function's decorated/original name
        func_name = name or getattr(func, '_decorated_function', func).__name__

        # Check if JavaScript-style NATS JetStream is enabled
        use_jetstream = kwargs.get('js', False)

        # Construct unique key based on namespace and JetStream flag
        key = f'{namespace}.js.{func_name}' if use_jetstream else f'{namespace}.{func_name}'

        # Prevent duplicate registrations
        if key in self._functions:
            raise ValueError(f'NATS function key `{key}` already registered.')

        # Store function metadata
        self._functions[key] = {
            'callback': func,
            'context': namespace,
            'identifier': func_name,
            'jetstream': use_jetstream,
        }

        return func

# Global registry instance and convenience accessor
global_registry = CallbackRegistry()
register = global_registry.add

def generate_visualization_config(mesh_file, field_data=None):
    """
    Generate a .opt configuration file for Gmsh to visualize mesh data fields.

    Parameters
    ----------
    mesh_file : str
        Path to the mesh file (without extension)
    field_data : dict, optional
        Configuration dictionary containing:
        - 'variables': list of field names to display
        - 'upper_bounds': dict mapping field names to maximum values (optional)
        - 'data_location': str, either 'node' or 'element' (default: 'node')
    """
    if field_data is None:
        field_data = {}

    variables = field_data.get("variables", [])
    upper_bounds = field_data.get("upper_bounds", {})

    config_text = """// Gmsh visualization setup for mesh fields
Mesh.SurfaceFaces = 0;
Mesh.SurfaceEdges = 0;
Mesh.Points = 0;
Mesh.Lines = 0;
"""

    # Process each field variable
    var_index = 0
    for var_name in variables:
        var_index += 1
        max_bound = upper_bounds.get(var_name, 1.0)

        config_text += f"""// View[{var_index}] ({var_name})
View[{var_index}].Visible = 1;
View[{var_index}].ColormapNumber = {var_index};
View[{var_index}].RangeType = 2;
View[{var_index}].CustomMin = 0;
View[{var_index}].CustomMax = {max_bound};
View[{var_index}].ShowScale = 1;
View[{var_index}].ColormapAlpha = 1;
View[{var_index}].ColormapAlphaPower = 0.08;
"""

    # Add metadata comments
    config_text += "// Field details:\n"
    for idx, var_name in enumerate(variables):
        max_val = upper_bounds.get(var_name, 1.0)
        config_text += f"// View[{idx + 1}]: {var_name} (max: {max_val:.6f})\n"

    # Write configuration to file
    config_path = f"{mesh_file}.opt"
    with open(config_path, "w") as file:
        file.write(config_text)

    return config_path

# USB device monitoring module using pyudev and PyQt6 signals

from PyQt6.QtCore import QObject, pyqtSignal
import pyudev

class UsbDeviceWatcher(QObject):
    # Signals for USB device events
    usb_inserted = pyqtSignal(str)
    usb_removed = pyqtSignal(str)
    all_devices_changed = pyqtSignal(dict)

    def __init__(self):
        super().__init__()
        self.context = pyudev.Context()
        self.event_monitor = pyudev.Monitor.from_netlink(self.context)
        self.event_monitor.filter_by(subsystem='block')
        self.known_devices = {}

        self._scan_current_devices()

        self.observer_thread = pyudev.MonitorObserver(
            self.event_monitor,
            callback=self._handle_device_event
        )
        self.observer_thread.start()

    def _scan_current_devices(self):
        # Enumerate existing USB block devices
        for dev in self.context.list_devices(subsystem='block', DEVTYPE='disk'):
            if dev.get('ID_BUS') == 'usb':
                device_path = dev.device_node
                self.known_devices[device_path] = device_path

        self.all_devices_changed.emit(self.known_devices)

    def _handle_device_event(self, device):
        # Process only disk-type USB devices
        if device.get('DEVTYPE') != 'disk':
            return
        if device.get('ID_BUS') != 'usb':
            return

        device_path = device.device_node

        if device.action == "add":
            self.known_devices[device_path] = device_path
            self.usb_inserted.emit(device_path)
        elif device.action == "remove":
            if device_path in self.known_devices:
                del self.known_devices[device_path]
                self.usb_removed.emit(device_path)

        self.all_devices_changed.emit(self.known_devices)

# Module imports for symbolic computation and file handling
import sympy
from pathlib import Path
from graph_net.dynamic_dim_constraints import DynamicDimConstraints
import graph_net.graph_net_json_file_util as gn_json

class ExtractInputSymbolicShapes:
    def __init__(self, settings):
        self.settings = self._prepare_settings(**settings)

    def _prepare_settings(self, model_directory_prefix, skip_reified=True):
        return {
            "model_directory_prefix": model_directory_prefix,
            "skip_reified": skip_reified,
        }

    def __call__(self, model_name):
        full_model_path = Path(self.settings["model_directory_prefix"]) / model_name
        constraints_file = full_model_path / "input_tensor_constraints.py"

        # Skip if constraint file doesn't exist
        if not constraints_file.exists():
            print(f"extract-symbolic-input-shapes None {model_name}")
            return

        # Skip if reified dimensions are present and should be skipped
        if self.settings["skip_reified"] and self._contains_reified_dimensions(
            str(full_model_path)
        ):
            print(f"extract-symbolic-input-shapes <reified> {model_name}")
            return

        # Load dynamic dimension constraints from file
        dim_constraints = DynamicDimConstraints.unserialize_from_py_file(
            str(constraints_file)
        )

        # Print shapes containing symbolic expressions
        for tensor_shape, tensor_name in dim_constraints.input_shapes:
            if not any(isinstance(dimension, sympy.Expr) for dimension in tensor_shape):
                continue
            print(f"{tensor_shape=} {tensor_name=}")

        # Serialize and output final symbolic shapes
        serialized_shapes = dim_constraints.serialize_symbolic_input_shapes_to_str()
        print(f"extract-symbolic-input-shapes {serialized_shapes} {model_name}")

    def _contains_reified_dimensions(self, model_dir):
        json_data = gn_json.read_json(model_dir)
        if gn_json.kSymbolicDimensionReifier not in json_data:
            return False
        return json_data[gn_json.kSymbolicDimensionReifier] is not None

from abc import ABC, abstractmethod

# Abstract base class for storage backends
class StorageBackend(ABC):
    """Base interface for file storage systems.

    Subclasses must implement:
      - retrieve_bytes(path): read raw bytes from file
      - retrieve_text(path): read textual content from file
    """

    @abstractmethod
    def retrieve_bytes(self, path):
        pass

    @abstractmethod
    def retrieve_text(self, path):
        pass


# In-memory caching backend using Memcached
class CacheStorage(StorageBackend):
    """Memcached-based backend for fast data retrieval.

    Parameters:
        config_servers (str): Path to server list configuration.
        config_client   (str): Path to client configuration.
        extra_path      (str | None): Optional system path to extend.
    """

    def __init__(self, config_servers, config_client, extra_path=None):
        if extra_path is not None:
            import sys
            sys.path.append(extra_path)

        try:
            import mc
        except ImportError:
            raise ImportError('Memcached support requires the "mc" module.')

        self._server_config = config_servers
        self._client_config = config_client
        self._cache_client = mc.MemcachedClient.GetInstance(config_servers, config_client)
        self._buffer = mc.pyvector()  # Shared buffer for data transfer

    def retrieve_bytes(self, path):
        path_str = str(path)
        self._cache_client.Get(path_str, self._buffer)
        return mc.ConvertBuffer(self._buffer)

    def retrieve_text(self, path):
        raise NotImplementedError("Text retrieval not supported by this backend.")


# Local disk storage backend
class DiskStorage(StorageBackend):
    """Direct filesystem access without abstraction layers."""

    def retrieve_bytes(self, path):
        with open(str(path), 'rb') as stream:
            return stream.read()

    def retrieve_text(self, path):
        with open(str(path), 'r', encoding='utf-8') as stream:
            return stream.read()


# LMDB-backed key-value storage
class LmdbStorage(StorageBackend):
    """Lightning Memory-Mapped Database (LMDB) backend.

    Args:
        db_locations     (list[str] | str): One or more LMDB database paths.
        db_keys          (list[str] | str): Identifiers for each DB instance.
        read_only        (bool): Enforce read-only mode.
        enforce_locking  (bool): Enable/disable locking in concurrent access.
        enable_prefetch  (bool): Use OS readahead optimization.
        **extra_opts     : Additional LMDB environment options.
    """

    def __init__(self, db_locations, db_keys='default', read_only=True,
                 enforce_locking=False, enable_prefetch=False, **extra_opts):
        try:
            import lmdb
        except ImportError:
            raise ImportError('LMDB backend requires the "lmdb" package.')

        # Normalize inputs into lists
        keys = [db_keys] if isinstance(db_keys, str) else list(db_keys)
        locations = ([db_locations] if isinstance(db_locations, str)
                     else [str(p) for p in db_locations])

        if len(keys) != len(locations):
            raise ValueError(f"Mismatch: {len(keys)} keys vs {len(locations)} paths.")

        self._databases = {}
        for key, loc in zip(keys, locations):
            env = lmdb.open(loc, readonly=read_only, lock=enforce_locking,
                            readahead=enable_prefetch, **extra_opts)
            self._databases[key] = env

    def retrieve_bytes(self, key, db_name):
        """Fetch binary value from specified LMDB instance."""
        assert db_name in self._databases, f"Unknown DB identifier: {db_name}"
        with self._databases[db_name].begin(write=False) as txn:
            return txn.get(str(key).encode('ascii'))

    def retrieve_text(self, path):
        raise NotImplementedError("Text retrieval not supported by this backend.")


# Unified file access facade
class FileManager:
    """Unified interface to multiple storage backends.

    Supports dynamic registration and dispatch based on backend type.

    Attributes:
        mode (str): Selected backend ("disk", "memcached", or "lmdb").
        accessor (StorageBackend): Active backend instance.
    """

    _registry = {
        'disk': DiskStorage,
        'memcached': CacheStorage,
        'lmdb': LmdbStorage,
    }

    def __init__(self, mode='disk', **backend_args):
        if mode not in self._registry:
            raise ValueError(f"Unsupported backend '{mode}'. Valid: {list(self._registry.keys())}")

        self.mode = mode
        self.accessor = self._registry[mode](**backend_args)

    def read(self, path, db_key='default'):
        """Read file content; delegates to backend-specific method."""
        if self.mode == 'lmdb':
            return self.accessor.retrieve_bytes(path, db_key)
        else:
            return self.accessor.retrieve_bytes(path)

    def read_text(self, path):
        """Read file as text."""
        return self.accessor.retrieve_text(path)

