import requests
import json
import os
import re
from urllib.parse import urlparse, urljoin
from collections import OrderedDict
from datetime import datetime
import pytz
import threading
import logging
from bs4 import BeautifulSoup

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class M3UAggregator:
    def __init__(self, region="Mexico", storage_root="LiveTV", validate_urls=True):
        self.registry = {}
        self.logo_placeholder = "https://bugsfreeweb.github.io/LiveTVCollector/BugsfreeLogo/default-logo.png"
        self.url_cache = {}
        self.output_folder = os.path.join(storage_root, region)
        self.lock = threading.Lock()
        self.should_validate = validate_urls
        os.makedirs(self.output_folder, exist_ok=True)

    def retrieve_content(self, url):
        """Download content from URL in streaming mode."""
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 '
                          '(KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
        }

        try:
            with requests.get(url, stream=True, headers=headers, timeout=10) as resp:
                resp.raise_for_status()
                raw_lines = [line.decode('utf-8', errors='ignore') if isinstance(line, bytes) else line 
                             for line in resp.iter_lines()]
                full_text = '\n'.join(raw_lines)
                if not raw_lines:
                    logging.warning(f"Empty response from {url}")
                else:
                    logging.info(f"Retrieved {len(raw_lines)} lines from {url}")
                return full_text, raw_lines
        except requests.RequestException as err:
            logging.error(f"Failed to fetch {url}: {err}")
            return None, []

    def harvest_links_from_page(self, html_body, origin_url):
        """Parse HTML to extract potential media URLs."""
        if not html_body:
            return []

        parsed_origin = urlparse(origin_url)
        soup = BeautifulSoup(html_body, 'html.parser')
        candidates = set()

        for anchor in soup.find_all('a', href=True):
            href = anchor['href']
            # Resolve relative URLs
            if not urlparse(href).scheme:
                href = urljoin(origin_url, href)

            exts = ('.m3u', '.m3u8')
            video_exts = ('.ts', '.mp4', '.avi', '.mkv', '.flv', '.wmv')
            keywords = ('playlist', 'stream')

            is_candidate = (
                href.endswith(exts) or
                any(href.lower().endswith(v) for v in video_exts) or
                any(kw in href.lower() for kw in keywords)
            )
            blacklisted = any(bl in href.lower() for bl in ('telegram', '.html', '.php', 'github.com', 'login', 'signup'))

            if is_candidate and not blacklisted:
                candidates.add(href)

        logging.info(f"Discovered {len(candidates)} candidate streams on {origin_url}")
        return list(candidates)

    def verify_link_health(self, url, timeout=2):
        """Quickly check if a stream URL responds successfully."""
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 '
                          '(KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
        }

        with self.lock:
            if url in self.url_cache:
                return self.url_cache[url]

        methods = [
            lambda u: requests.head(u, timeout=timeout, headers=headers, allow_redirects=True),
            lambda u: requests.get(u, stream=True, timeout=timeout, headers=headers)
        ]

        for method in methods:
            try:
                r = method(url)
                if r.status_code < 400:
                    result = (True, url)
                    with self.lock:
                        self.url_cache[url] = result
                    logging.info(f"Verified {url} — active")
                    return result
            except requests.RequestException:
                continue

        # Try alternate protocol only if original failed due to non-timeout reasons
        alt_url = None
        if url.startswith("http://"):
            alt_url = url.replace("http://", "https://", 1)
        elif url.startswith("https://"):
            alt_url = url.replace("https://", "http://", 1)

        if alt_url:
            try:
                r = requests.head(alt_url, timeout=timeout, headers=headers, allow_redirects=True)
                if r.status_code < 400:
                    result = (True, alt_url)
                    with self.lock:
                        self.url_cache[url] = result
                    logging.info(f"Verified {alt_url} — fallback success")
                    return result
            except requests.RequestException:
                pass

        with self.lock:
            self.url_cache[url] = (False, url)
        return False, url

    def ingest_stream_list(self, lines, source_ref):
        """Process M3U-style lines and store channel metadata."""
        current_entry = {}
        count = 0

        for line in map(str.strip, lines):
            if line.startswith('#EXTINF:'):
                logo_match = re.search(r'tvg-logo="([^"]*)"', line)
                group_match = re.search(r'group-title="([^"]*)"', line)
                name_match = re.search(r',(.+)$', line)

                current_entry = {
                    'name': name_match.group(1).strip() if name_match else "Unknown",
                    'logo': logo_match.group(1) if logo_match and logo_match.group(1) else self.logo_placeholder,
                    'category': group_match.group(1) if group_match else "General",
                    'origin': source_ref
                }
            elif line.startswith('http') and current_entry:
                with self.lock:
                    if line not in self.url_cache:
                        self.url_cache[line] = True
                        cat = current_entry['category']
                        if cat not in self.registry:
                            self.registry[cat] = []
                        entry_copy = current_entry.copy()
                        entry_copy['url'] = line
                        self.registry[cat].append(entry_copy)
                        count += 1
                current_entry = {}

        logging.info(f"Ingested {count} entries from {source_ref}")

    def sanitize_registry(self):
        """Remove dead links unless validation is disabled."""
        if not self.should_validate:
            logging.info("Skipping health checks for performance")
            return

        valid_entries = OrderedDict()
        all_items = [(cat, item) for cat, items in self.registry.items() for item in items]
        seen_urls = set()

        logging.info(f"Validating {len(all_items)} entries...")
        with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
            futures = {}
            for category, item in all_items:
                url = item['url']
                if url not in seen_urls:
                    seen_urls.add(url)
                    futures[pool.submit(self.verify_link_health, url)] = (category, item)

            for future in concurrent.futures.as_completed(futures):
                category, item = futures[future]
                try:
                    ok, final_url = future.result()
                    if ok:
                        item['url'] = final_url
                        if category not in valid_entries:
                            valid_entries[category] = []
                        valid_entries[category].append(item)
                except Exception as e:
                    logging.error(f"Validation error for {item['url']}: {e}")

        self.registry = valid_entries
        total = sum(len(v) for v in self.registry.values())
        logging.info(f"After cleanup: {total} working channels remain")

    def process_sources(self, urls):
        """Iterate over input sources and collect streams."""
        self.registry.clear()
        self.url_cache.clear()

        m3u_candidates = []

        for src in urls:
            body, lines = self.retrieve_content(src)
            if src.endswith('.html'):
                m3u_candidates.extend(self.harvest_links_from_page(body, src))
            else:
                self.ingest_stream_list(lines, src)

        for candidate in m3u_candidates:
            _, lines = self.retrieve_content(candidate)
            self.ingest_stream_list(lines, candidate)

        if self.registry:
            self.sanitize_registry()
        else:
            logging.warning("No channels were parsed from any source")

    def write_m3u(self, filename="LiveTV.m3u"):
        path = os.path.join(self.output_folder, filename)
        with open(path, 'w', encoding='utf-8') as f:
            f.write('#EXTM3U\n')
            for cat, items in self.registry.items():
                for item in items:
                    f.write(f'#EXTINF:-1 tvg-logo="{item["logo"]}" group-title="{cat}",{item["name"]}\n')
                    f.write(f'{item["url"]}\n')
        logging.info(f"Wrote M3U file: {path}")
        return path

    def write_text_report(self, filename="LiveTV.txt"):
        path = os.path.join(self.output_folder, filename)
        with open(path, 'w', encoding='utf-8') as f:
            for cat, items in sorted(self.registry.items()):
                f.write(f"Category: {cat}\n")
                for item in items:
                    f.write(f"Name: {item['name']}\n")
                    f.write(f"URL: {item['url']}\n")
                    f.write(f"Logo: {item['logo']}\n")
                    f.write(f"Source: {item['origin']}\n")
                    f.write("-" * 60 + "\n")
                f.write("\n")
        logging.info(f"Wrote text report: {path}")
        return path

    def write_json_dump(self, filename="LiveTV.json"):
        path = os.path.join(self.output_folder, filename)
        tz_mumbai = pytz.timezone('Asia/Kolkata')
        timestamp = datetime.now(tz_mumbai).strftime('%Y-%m-%d %H:%M:%S')

        payload = {
            "generated_at": timestamp,
            "entries": {k: v for k, v in self.registry.items()}
        }
        with open(path, 'w', encoding='utf-8') as f:
            json.dump(payload, f, ensure_ascii=False, indent=2)
        logging.info(f"Wrote JSON dump: {path}")
        return path

    def write_custom_format(self, filename="LiveTV"):
        path = os.path.join(self.output_folder, filename)
        output = []

        for cat, items in self.registry.items():
            for item in items:
                output.append({
                    "title": item['name'],
                    "group": cat,
                    "link": item['url'],
                    "icon": item['logo']
                })

        with open(path, 'w', encoding='utf-8') as f:
            json.dump(output, f, ensure_ascii=False, indent=2)
        logging.info(f"Wrote custom format: {path}")
        return path


def main():
    sources = [
        "https://raw.githubusercontent.com/Osares10/ipmx/refs/heads/main/Mexico.m3u",
        "https://raw.githubusercontent.com/Edgar-Reyna/ListaIPTV/refs/heads/main/FULLTV.M3U",
        "https://raw.githubusercontent.com/HelmerLuzo/PlutoTV_HL/refs/heads/main/tv/m3u/PlutoTV_tv_MX.m3u",
        "https://iptv-org.github.io/iptv/countries/mx.m3u",
    ]

    aggregator = M3UAggregator(region="Mexico", validate_urls=False)
    aggregator.process_sources(sources)

    aggregator.write_m3u("LiveTV.m3u")
    aggregator.write_text_report("LiveTV.txt")
    aggregator.write_json_dump("LiveTV.json")
    aggregator.write_custom_format("LiveTV")

    total_channels = sum(len(v) for v in aggregator.registry.values())
    now_mumbai = datetime.now(pytz.timezone('Asia/Kolkata'))
    logging.info(f"[{now_mumbai}] Aggregated {total_channels} verified channels for Mexico")
    logging.info(f"Total categories: {len(aggregator.registry)}")


