def process_memory_records(memories_data):
    result = {}
    for category, content in memories_data.items():
        if category == "text_mem":
            result[category] = []
            for group in content:
                # Handle new format: list of memory items
                if isinstance(group, dict) and "memories" in group and isinstance(group["memories"], list):
                    processed_memories = []
                    for item in group["memories"]:
                        # Build filtered memory entry
                        entry = {
                            "id": getattr(item, "id", None),
                            "memory": getattr(item, "memory", ""),
                            "metadata": {}
                        }
                        # Extract metadata attributes safely
                        if hasattr(item, "metadata") and item.metadata:
                            for prop in dir(item.metadata):
                                if not prop.startswith("_") and prop != "embedding":
                                    val = getattr(item.metadata, prop, None)
                                    if not callable(val):
                                        entry["metadata"][prop] = val
                        processed_memories.append(entry)

                    result[category].append({
                        "cube_id": group.get("cube_id", ""),
                        "memories": processed_memories
                    })
                else:
                    # Handle legacy format: dictionary with nodes/edges
                    legacy_group = {
                        "memories": {
                            "nodes": [],
                            "edges": group.get("memories", {}).get("edges", [])
                        }
                    }
                    for node in group.get("memories", {}).get("nodes", []):
                        cleaned_node = {
                            "id": node.get("id"),
                            "memory": node.get("memory"),
                            "metadata": {
                                k: v for k, v in node.get("metadata", {}).items()
                                if k != "embedding"
                            }
                        }
                        legacy_group["memories"]["nodes"].append(cleaned_node)
                    result[category].append(legacy_group)
        else:
            result[category] = content
    return result

import json

def format_api_error(error_msg: str) -> str:
    return "API Error: " + error_msg

def process_volc_response(api_response: dict) -> str:
    if not api_response:
        return format_api_error("Empty response")

    # Handle both dict and JSON string inputs
    parsed_data = api_response if isinstance(api_response, dict) else json.loads(api_response)

    # Extract error information from the response structure
    error_info = parsed_data.get("ResponseMetadata", {}).get("Error")

    if error_info and isinstance(error_info, dict):
        error_message = error_info.get("Message", "Unknown error")
        return format_api_error(error_message)

    return str(api_response)

