def generate_random_name(length=8, ext=''):
    # Generate a random hexadecimal string as base name
    random_bytes = os.urandom(length)
    hex_string = binascii.b2a_hex(random_bytes).decode('utf-8')

    # Append extension if provided
    if ext:
        if not ext.startswith('.'):
            ext = '.' + ext
        hex_string += ext

    return hex_string

def infinite_iterator(data_loader):
    # Create an infinite loop over the data loader
    while True:
        for item in data_loader:
            yield item

def check_exists(value):
    # Check if value is not None
    return value is not None

def pass_through(x):
    # Identity function: returns input unchanged
    return x

def merge_lora_weights(unet_model, vae_model=None, checkpoint_path=None, blend_factor=1.0, base_model_path=""):
    # Return early if no checkpoint path is provided
    if checkpoint_path is None:
        return unet_model

    loaded_state_dict = {}

    # Load checkpoint based on file extension
    if checkpoint_path.endswith(".ckpt"):
        checkpoint_data = torch.load(checkpoint_path, map_location="cpu")
        loaded_state_dict = checkpoint_data.get("state_dict", {})
    elif checkpoint_path.endswith(".safetensors"):
        with safe_open(checkpoint_path, framework="pt", device="cpu") as f:
            loaded_state_dict = {key: f.get_tensor(key) for key in f.keys()}

        # Determine if this is a LoRA-specific checkpoint
        is_lora_format = all("lora" in key for key in loaded_state_dict.keys())

        # If not LoRA format, use directly; otherwise load base model
        if not is_lora_format:
            base_state_dict = loaded_state_dict
        else:
            base_state_dict = {}
            with safe_open(base_model_path, framework="pt", device="cpu") as f:
                base_state_dict = {key: f.get_tensor(key) for key in f.keys()}

    # Convert checkpoint to UNet format
    converted_unet_dict = convert_ldm_unet_checkpoint(base_state_dict, unet_model.config)

    # Apply blending between converted weights and current UNet weights
    current_unet_state = unet_model.state_dict()
    for param_name in converted_unet_dict:
        converted_unet_dict[param_name] = (
            blend_factor * converted_unet_dict[param_name] + 
            (1.0 - blend_factor) * current_unet_state[param_name]
        )

    # Load updated weights into UNet
    unet_model.load_state_dict(converted_unet_dict, strict=False)

    # Handle VAE if provided
    if vae_model is not None:
        converted_vae_dict = convert_ldm_vae_checkpoint(base_state_dict, vae_model.config)
        vae_model.load_state_dict(converted_vae_dict)

    return unet_model, vae_model

