    cleaned = ''.join(line.strip() for line in lines)
    return json.loads(cleaned)


def compress_nested_dict(data: dict, prefix: str = "", delimiter: str = ".") -> dict:
    """
    Transform a nested dictionary into a flat one by concatenating keys.
    Preserves lists of primitives (non-container types) as-is.
    """
    result = {}
    for key, value in data.items():
        current_key = f"{prefix}{delimiter}{key}" if prefix else key

        if isinstance(value, dict):
            # Recursively flatten sub-dictionaries
            sub_flat = compress_nested_dict(value, current_key, delimiter)
            result.update(sub_flat)

        elif isinstance(value, list):
            # Check if all elements are non-container types
            is_primitive_list = all(not isinstance(item, (dict, list)) for item in value)
            if is_primitive_list:
                result[current_key] = value
            else:
                # Process each element individually
                for idx, elem in enumerate(value):
                    indexed_key = f"{current_key}{delimiter}{idx}"
                    if isinstance(elem, dict):
                        nested_result = compress_nested_dict(elem, indexed_key, delimiter)
                        result.update(nested_result)
                    elif isinstance(elem, list):
                        result[indexed_key] = elem
                    else:
                        result[indexed_key] = elem
        else:
            result[current_key] = value

    return result


def expand_flat_dict(flat_data: dict, delim: str = ".") -> dict:
    """
    Reconstruct a nested dictionary from a flattened version using a separator.
    """
    output = {}
    for full_key, val in flat_data.items():
        segments = full_key.split(delim)
        target = output
        for segment in segments[:-1]:
            if segment not in target:
                target[segment] = {}
            target = target[segment]
        target[segments[-1]] = val
    return output


def gather_batch_info(batch_obj):
