    )


def derive_batch_size_from_training_config(cfg: Config) -> int:
    """
    Compute total batch size based on number of samples defined across input sources.
    """
    total_samples = 0
    for _, src_cfg in cfg.model_input.items():
        total_samples += src_cfg.get("num_samples", 1)
    if total_samples <= 0:
        raise ValueError("At least one sample must be specified in source configurations.")
    return total_samples


def obtain_target_indices_for_loss(cfg: Config, loss_label: str) -> list[int] | None:
    """
    Retrieve target indices referenced by a specific loss function configuration.
    """
    correspondence_lists = [
        v.get("target_source_correspondence")
        for _, v in cfg.losses[loss_label].loss_fcts.items()
    ]
    filtered_correspondences = [list(t.keys()) for t in correspondence_lists if t is not None]
    unique_indices = sorted(set(int(k) for t in filtered_correspondences for k in t)) if filtered_correspondences else None
    return unique_indices


def assemble_active_stage_configuration(
    base_cfg: dict | OmegaConf,
    override_cfg: dict | OmegaConf,
    sections_to_exclude_disabled: list[str]
) -> dict | OmegaConf:
    """
    Merge base and override configs, then remove entries marked as disabled.
    """
    merged = merge_configs(base_cfg, override_cfg)
    return prune_config_by_activation_status(merged, sections_to_exclude_disabled)


def prune_config_by_activation_status(cfg: dict | OmegaConf, section_names: list[str]) -> dict | OmegaConf:
    """
    Remove entries from specified config sections where 'enabled' is explicitly False.
    """
    updated_cfg = copy.deepcopy(cfg)
    for section in section_names:
        active_entries = {}
        for name, entry in updated_cfg.get(section, {}).items():
            if entry.get("enabled", True):
                active_entries[name] = entry
        updated_cfg[section] = active_entries
    return updated_cfg

