# Configure logger for the module
logger = logging.getLogger(__name__)

# Define supported file extensions
IMAGE_TYPES = {".png", ".jpg", ".jpeg", ".webp", ".bmp"}
VIDEO_TYPES = {".mp4", ".avi", ".mov", ".mkv", ".webm"}
LORA_FILE_TYPES = {".safetensors"}

def find_files_with_extensions(
    base_dir: Path,
    valid_suffixes: set[str],
    *,
    resolve_symlinks: bool = True,
) -> iter:
    """Generate paths to files in *base_dir* whose extension matches one in *valid_suffixes*.

    Traverses directories recursively using os.walk, following symbolic links by default
    (important for Windows compatibility where pathlib.rglob doesn't follow symlinks).
    Skips broken or inaccessible files and directories without raising exceptions.
    """
    if not base_dir.is_dir():
        return

    # Walk through directory tree
    for current_path, _, filenames in os.walk(base_dir, followlinks=resolve_symlinks):
        current_dir = Path(current_path)

        for name in filenames:
            # Check if file has a matching extension (case-insensitive)
            ext = Path(name).suffix.lower()
            if ext not in valid_suffixes:
                continue

            full_path = current_dir / name

            # Attempt to verify it's a regular file
            try:
                if full_path.is_file():
                    yield full_path
            except (OSError, PermissionError) as err:
                logger.debug(
                    "find_files_with_extensions: skipping inaccessible file %s: %s",
                    full_path,
                    err
                )

