# Replaced @cache with a simple memoization wrapper for _connect
def _make_memoized_connect():
    cache = {}
    def memoized_connect(context: zmq.Context, endpoint: str):
        if endpoint not in cache:
            sock = context.socket(zmq.PUSH)
            sock.connect(endpoint)
            cache[endpoint] = sock
        return cache[endpoint]
    return memoized_connect

memoized_connect = _make_memoized_connect()

