class DisaggregationMode(Enum):
    NULL_MODE = "null"
    ENCODING = "encode"
    TRANSFORMING = "transformer"

def group_concurrent_contiguous(
    src_indices: npt.NDArray[np.int64],
    dst_indices: npt.NDArray[np.int64]
) -> Tuple[List[npt.NDArray[np.int64]], List[npt.NDArray[np.int64]]]:
    grouped_src = []
    grouped_dst = []

    if len(src_indices) == 0:
        return [], []

    current_src_block = [src_indices[0]]
    current_dst_block = [dst_indices[0]]

    for idx in range(1, len(src_indices)):
        src_gap = src_indices[idx] - src_indices[idx - 1]
        dst_gap = dst_indices[idx] - dst_indices[idx - 1]

        if src_gap == 1 and dst_gap == 1:
            current_src_block.append(src_indices[idx])
            current_dst_block.append(dst_indices[idx])
        else:
            grouped_src.append(np.array(current_src_block, dtype=np.int64))
            grouped_dst.append(np.array(current_dst_block, dtype=np.int64))
            current_src_block = [src_indices[idx]]
            current_dst_block = [dst_indices[idx]]

    grouped_src.append(np.array(current_src_block, dtype=np.int64))
    grouped_dst.append(np.array(current_dst_block, dtype=np.int64))

    return grouped_src, grouped_dst


