import argparse
import asyncio
import dataclasses
from datetime import datetime
from enum import Enum, auto
import json
import logging
import requests
import uvicorn
from fastapi import FastAPI, Request
from fastapi.responses import StreamingResponse
from typing import Dict, List, Optional, Any
from llava.constants import CONTROLLER_HEART_BEAT_EXPIRATION
from llava.utils import build_logger, server_error_msg

logger = build_logger("controller", "controller.log")


class RoutingStrategy(Enum):
    RANDOM_WEIGHTED = auto()
    MIN_QUEUE_DELAY = auto()

    @classmethod
    def parse(cls, name: str) -> "RoutingStrategy":
        if name == "lottery":
            return cls.RANDOM_WEIGHTED
        elif name == "shortest_queue":
            return cls.MIN_QUEUE_DELAY
        else:
            raise ValueError(f"Unsupported routing strategy: {name}")


@dataclasses.dataclass
class NodeStatus:
    supported_models: List[str]
    capacity_score: int
    pending_tasks: int
    monitor_enabled: bool
    last_seen: float


def _heartbeat_monitor(controller_instance: "Controller"):
    async def loop():
        while True:
            await asyncio.sleep(CONTROLLER_HEART_BEAT_EXPIRATION)
            controller_instance._prune_inactive_nodes()
    asyncio.create_task(loop())


class Controller:
    def __init__(self, strategy: str):
        self.nodes: Dict[str, NodeStatus] = {}
        self.routing_policy = RoutingStrategy.parse(strategy)
        asyncio.get_event_loop().run_in_executor(None, _heartbeat_monitor, self)
        logger.info("Controller initialized")

    def _add_or_update_node(self, node_id: str, should_monitor: bool, status_data: Optional[Dict]) -> bool:
        existing = node_id in self.nodes
        action = "Update" if existing else "Register"
        logger.info(f"{action} node: {node_id}")

        if not status_data:
            status_data = self._fetch_node_status(node_id)
        if not status_data:
            return False

        self.nodes[node_id] = NodeStatus(
            supported_models=status_data["models"],
            capacity_score=status_data["speed"],
            pending_tasks=status_data["queue_length"],
            monitor_enabled=should_monitor,
            last_seen=datetime.now().timestamp()
        )
        logger.info(f"Node registered: {node_id}, status={status_data}")
        return True

    def _fetch_node_status(self, url: str) -> Optional[Dict]:
        try:
            resp = requests.post(f"{url}/worker_get_status", timeout=5)
            if resp.status_code != 200:
                logger.error(f"Failed to fetch status from {url}: HTTP {resp.status_code}")
                return None
            return resp.json()
        except Exception as e:
            logger.warning(f"Error fetching status from {url}: {e}")
            return None

    def _remove_node(self, node_id: str):
        if node_id in self.nodes:
            del self.nodes[node_id]
            logger.info(f"Removed node: {node_id}")

    def _refresh_all_nodes(self):
        old_state = dict(self.nodes)
        self.nodes.clear()
        for nid, ninfo in old_state.items():
            self._add_or_update_node(nid, ninfo.monitor_enabled, None)

    def list_available_models(self) -> List[str]:
        models = {m for info in self.nodes.values() for m in info.supported_models}
        return sorted(models)

    def _select_worker(self, model_name: str) -> str:
        candidates = [
            (nid, info.pending_tasks / max(info.capacity_score, 1))
            for nid, info in self.nodes.items()
            if model_name in info.supported_models
        ]

        if not candidates:
            return ""

        if self.routing_policy == RoutingStrategy.RANDOM_WEIGHTED:
            weights = [info.capacity_score for _, info in self.nodes.items() if model_name in info.supported_models]
            total_weight = sum(weights)
            if total_weight <= 0:
                return ""
            probs = [w / total_weight for w in weights]
            idx = self._weighted_random_choice(probs)
            selected = list(self.nodes.keys())[idx]
            return selected

        elif self.routing_policy == RoutingStrategy.MIN_QUEUE_DELAY:
            best_idx = min(range(len(candidates)), key=lambda i: candidates[i][1])
            selected_node = list(self.nodes.keys())[best_idx]
            self.nodes[selected_node].pending_tasks += 1
            logger.debug(f"Selected node '{selected_node}' with queue delay {candidates[best_idx][1]:.2f}")
            return selected_node

        return ""

    def _weighted_random_choice(self, probs: List[float]) -> int:
        import random
        r = random.random()
        cumulative = 0.0
        for i, p in enumerate(probs):
            cumulative += p
            if r <= cumulative:
                return i
        return len(probs) - 1

    def _update_heartbeat(self, node_id: str, queue_len: int) -> bool:
        if node_id not in self.nodes:
            logger.warning(f"Heartbeat from unknown node: {node_id}")
            return False
        self.nodes[node_id].pending_tasks = queue_len
        self.nodes[node_id].last_seen = datetime.now().timestamp()
        logger.debug(f"Heartbeat received from {node_id}")
        return True

    def _prune_inactive_nodes(self):
        cutoff = datetime.now().timestamp() - CONTROLLER_HEART_BEAT_EXPIRATION
        stale = [nid for nid, info in self.nodes.items()
                 if info.monitor_enabled and info.last_seen < cutoff]
        for nid in stale:
            self._remove_node(nid)

    async def _stream_generate(self, params: Dict[str, Any]):
        worker_url = self._select_worker(params.get("model", ""))
        if not worker_url:
            logger.error(f"No available worker for model: {params['model']}")
            yield json.dumps({"text": server_error_msg, "error_code": 2}).encode() + b"\x00"
            return

        try:
            resp = requests.post(f"{worker_url}/worker_generate_stream",
                                 json=params, stream=True, timeout=5)
            for chunk in resp.iter_content(chunk_size=None, decode_unicode=False):
                if chunk:
                    yield chunk + b"\x00"
        except Exception as e:
            logger.error(f"Request to {worker_url} failed: {e}")
            yield json.dumps({"text": server_error_msg, "error_code": 3}).encode() + b"\x00"

    def get_overall_status(self) -> Dict[str, Any]:
        models = set()
        speed_sum = 0
        queue_sum = 0
        for info in self.nodes.values():
            models.update(info.supported_models)
            speed_sum += info.capacity_score
            queue_sum += info.pending_tasks
        return {
            "models": list(models),
            "speed": speed_sum,
            "queue_length": queue_sum,
        }


app = FastAPI()


@app.post("/register_worker")
async def register(request: Request):
    payload = await request.json()
    controller._add_or_update_node(
        payload["node_url"], payload.get("monitor", True), payload.get("status"))


@app.post("/refresh_all_nodes")
async def refresh():
    controller._refresh_all_nodes()


@app.post("/list_models")
async def list_models():
    return {"models": controller.list_available_models()}


@app.post("/get_worker_address")
async def get_address(request: Request):
    payload = await request.json()
    addr = controller._select_worker(payload["model"])
    return {"address": addr}


@app.post("/heartbeat")
async def heartbeat(request: Request):
    payload = await request.json()
    ok = controller._update_heartbeat(payload["node"], payload["queue_length"])
    return {"ok": ok}


@app.post("/generate_stream")
async def generate(request: Request):
    params = await request.json()
    return StreamingResponse(controller._stream_generate(params))


@app.post("/status")
async def status():
    return controller.get_overall_status()


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Controller service")
    parser.add_argument("--host", default="localhost")
    parser.add_argument("--port", type=int, default=21001)
    parser.add_argument("--strategy", choices=["lottery", "shortest_queue"], default="shortest_queue")
    args = parser.parse_args()

    logger.info(f"Starting controller with strategy: {args.strategy}")
    controller = Controller(args.strategy)
    uvicorn.run(app, host=args.host, port=args.port, log_level="info")

