def get_implementation_details():
    """Extract Python implementation name and version."""
    impl_name = platform.python_implementation()

    if impl_name == "CPython":
        version_str = platform.python_version()
    elif impl_name == "PyPy":
        pypy_info = sys.pypy_version_info
        version_str = f"{pypy_info.major}.{pypy_info.minor}.{pypy_info.micro}"
        if pypy_info.releaselevel != "final":
            version_str += pypy_info.releaselevel
    elif impl_name in ("Jython", "IronPython"):
        version_str = platform.python_version()  # Fallback guess
    else:
        version_str = "Unknown"

    return {"name": impl_name, "version": version_str}

def collect_system_info():
    """Gather platform and environment details."""
    try:
        sys_info = {
            "system": platform.system(),
            "release": platform.release()
        }
    except OSError:
        sys_info = {
            "system": "Unknown",
            "release": "Unknown"
        }

    return sys_info

def get_ssl_info():
    """Retrieve SSL/OpenSSL version information."""
    try:
        openssl_ver_num = ssl.OPENSSL_VERSION_NUMBER
        version_hex = f"{openssl_ver_num:x}" if openssl_ver_num else ""
    except Exception:
        version_hex = ""

    return {"version": version_hex}

