    if charset_normalizer_module:
        deps["charset_normalizer"] = {"version": getattr(charset_normalizer_module, "__version__", "")}
    else:
        deps["charset_normalizer"] = {"version": ""}

    # pyOpenSSL
    openssl_ver = ""
    if OpenSSL:
        openssl_ver = getattr(OpenSSL.SSL, "OPENSSL_VERSION_NUMBER", "")
        openssl_hex = f"{openssl_ver:x}" if openssl_ver else ""
        deps["pyOpenSSL"] = {
