def generate_report():
    """Compile all gathered information into a structured report."""
    base_info = {
        "platform": collect_system_info(),
        "implementation": get_implementation_details(),
        "system_ssl": get_ssl_info(),
        "using_pyopenssl": bool(pyopenssl_module),
        "using_charset_normalizer": chardet_module is None,
    }

    dep_info = get_dependency_versions()

    # Merge dependency info with base info
    for key, value in dep_info.items():
        base_info[key] = value

    # Add requests version (assumed available)
    try:
        from . import __version__ as requests_version
        base_info["requests"] = {"version": requests_version}
    except Exception:
        base_info["requests"] = {"version": ""}

    return base_info

def display_report():
