from typing import Dict, Any

class ServerlessStackGenerator:
    """Generate serverless application stacks using alternative implementation patterns."""

    def __init__(self, app_name: str, requirements: Dict[str, Any]):
        """
        Initialize with application requirements.
        Args:
            app_name: Application name (used for resource naming)
            requirements: Dictionary with API, database, auth requirements
        """
        # Normalize app name using different string manipulation approach
        normalized = app_name.strip().lower()
        self.app_name = ''.join(c if c.isalnum() or c == '-' else '-' for c in normalized).replace('--', '-')

        self.requirements = requirements
        self.region = requirements.get('region', 'us-east-1')

    def _format_table_name(self, env: str) -> str:
        """Generate formatted table name using alternative pattern."""
        return f"{env}-{self.app_name}-data"

    def _generate_dynamodb_resource(self, env: str) -> str:
        """Create DynamoDB resource block with modified structure."""
        table_id = self.app_name.replace('-', '')
        return f"""  {table_id}Table:
    Type: AWS::DynamoDB::Table
    Properties:
      TableName: !Sub '${{{env}}}-{self.app_name}-data'
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: PK
          AttributeType: S
        - AttributeName: SK
          AttributeType: S
      KeySchema:
        - AttributeName: PK
          KeyType: HASH
        - AttributeName: SK
          KeyType: RANGE
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true
      SSESpecification:
        SSEEnabled: true
      StreamSpecification:
        StreamViewType: NEW_AND_OLD_IMAGES
      Tags:
        - Key: Environment
          Value: !Ref {env}
        - Key: Application
          Value: {self.app_name}"""

    def _generate_lambda_role(self, table_id: str) -> str:
        """Create Lambda execution role with refactored policy structure."""
        return f"""  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Policies:
        - PolicyName: DynamoDBAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource: !GetAtt {table_id}Table.Arn"""

    def _generate_api_function(self, env: str, table_id: str) -> str:
        """Create Lambda function resource with alternate configuration."""
        return f"""  ApiFunction:
    Type: AWS::Serverless::Function
    Properties:
      FunctionName: !Sub '${{{env}}}-{self.app_name}-api'
      Handler: index.handler
      Runtime: nodejs18.x
      CodeUri: ./src
      MemorySize: 512
      Timeout: 10
      Role: !GetAtt LambdaExecutionRole.Arn
      Environment:
        Variables:
          TABLE_NAME: !Ref {table_id}Table
          ENVIRONMENT: !Ref {env}
      Events:
        ApiEvent:
          Type: Api
          Properties:
            Path: /{{proxy+}}
            Method: ANY
            RestApiId: !Ref ApiGateway
      Tags:
        Environment: !Ref {env}
        Application: {self.app_name}"""

    def _generate_api_gateway(self, env: str, cors_origins: str) -> str:
        """Create API Gateway resource with modified CORS and auth settings."""
        return f"""  ApiGateway:
    Type: AWS::Serverless::Api
    Properties:
      Name: !Sub '${{{env}}}-{self.app_name}-api'
      StageName: !Ref {env}
      Cors:
        AllowMethods: "'GET,POST,PUT,DELETE,OPTIONS'"
        AllowHeaders: "'Content-Type,Authorization,X-Amz-Date,X-Api-Key,X-Amz-Security-Token'"
        AllowOrigin: !Sub "'${{{cors_origins}}}'"
      Auth:
        DefaultAuthorizer: CognitoAuthorizer
        Authorizers:
          CognitoAuthorizer:
            UserPoolArn: !GetAtt UserPool.Arn
      ThrottleSettings:
        BurstLimit: 200
        RateLimit: 100
      Tags:
        Environment: !Ref {env}
        Application: {self.app_name}"""

    def _generate_cognito_resources(self, env: str) -> str:
        """Create Cognito resources with alternative configuration structure."""
        return f"""  UserPool:
    Type: AWS::Cognito::UserPool
    Properties:
      UserPoolName: !Sub '${{{env}}}-{self.app_name}-users'
      UsernameAttributes:
        - email
      AutoVerifiedAttributes:
        - email
      Policies:
        PasswordPolicy:
          MinimumLength: 8
          RequireUppercase: true
          RequireLowercase: true
          RequireNumbers: true
          RequireSymbols: false
      MfaConfiguration: OPTIONAL
      EnabledMfas:
        - SOFTWARE_TOKEN_MFA
      UserAttributeUpdateSettings:
        AttributesRequireVerificationBeforeUpdate:
          - email
      Schema:
        - Name: email
          Required: true
          Mutable: true
  UserPoolClient:
    Type: AWS::Cognito::UserPoolClient
    Properties:
      ClientName: !Sub '${{{env}}}-{self.app_name}-client'
      UserPoolId: !Ref UserPool
      GenerateSecret: false
      RefreshTokenValidity: 30
      AccessTokenValidity: 1
      IdTokenValidity: 1
      TokenValidityUnits:
        RefreshToken: days
