        IdToken: hours
      ExplicitAuthFlows:
        - ALLOW_USER_SRP_AUTH
        - ALLOW_REFRESH_TOKEN_AUTH"""

    def generate_cloudformation_template(self) -> str:
        """
        Generate CloudFormation template for serverless stack.
        Returns:
            YAML CloudFormation template as string
        """
        env_param = "dev"
        cors_origins = "*"
        table_id = self.app_name.replace('-', '')

        # Build template sections using helper methods
        dynamodb_section = self._generate_dynamodb_resource(env_param)
        role_section = self._generate_lambda_role(table_id)
        function_section = self._generate_api_function(env_param, table_id)
        api_section = self._generate_api_gateway(env_param, cors_origins)
        cognito_section = self._generate_cognito_resources(env_param)

        template = f"""AWSTemplateFormatVersion: '2010-09-09'
Transform: AWS::Serverless-2016-10-31
Description: Serverless stack for {self.app_name}
Parameters:
  Environment:
    Type: String
    Default: dev
    AllowedValues:
      - dev
      - staging
      - production
    Description: Deployment environment
  CorsAllowedOrigins:
    Type: String
    Default: '*'
    Description: CORS allowed origins for API Gateway
Resources:
{dynamodb_section}
{role_section}
{function_section}
{api_section}
{cognito_section}
  # CloudWatch Log Group
  ApiLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: !Sub '/aws/lambda/${{{env_param}}}-{self.app_name}-api'
      RetentionInDays: 7
Outputs:
  ApiUrl:
    Description: API Gateway endpoint URL
    Value: !Sub 'https://${{ApiGateway}}.execute-api.${{AWS::Region}}.amazonaws.com/${{{env_param}}}'
    Export:
