# Retrieve comment symbol for a given programming language

import csv
from pdd.path_resolution import get_default_resolver

def fetch_comment_symbol(lang_input: str) -> str:
    try:
        resolver = get_default_resolver()
        csv_path = resolver.resolve_data_file("data/language_format.csv")
    except ValueError:
        return "del"

    if not isinstance(lang_input, str):
        return "del"

    lang = lang_input.strip().lower()
    if not lang:
        return "del"

    try:
        with open(str(csv_path), mode="r", newline="", encoding="utf-8") as file:
            csv_reader = csv.DictReader(file)
            for entry in csv_reader:
                if entry.get("language", "").strip().lower() == lang:
                    comment_symbol = entry.get("comment", "").strip()
                    return comment_symbol if comment_symbol else "del"
    except FileNotFoundError:
        return "del"
    except Exception:
        return "del"

    return "del"

