import logging
from flask import Blueprint, request, jsonify
from app.web import (
    require_auth,
    get_storage,
    _localize_timestamps,
)

log = logging.getLogger("docsis.web")
events_bp = Blueprint("events_bp", __name__)

@events_bp.route("/api/events", methods=["GET"])
@require_auth
def api_events_list():
    """Return list of events with optional filters."""
    storage = get_storage()
    if not storage:
        return jsonify({"events": [], "unacknowledged_count": 0})

    # Parse query parameters with defaults
    limit_param = request.args.get("limit", 200)
    offset_param = request.args.get("offset", 0)
    severity_filter = request.args.get("severity") or None
    type_filter = request.args.get("event_type") or None

    # Handle acknowledged status parameter
    ack_param = request.args.get("acknowledged")
    ack_status = None
    if ack_param is not None and ack_param.strip() != "":
        try:
            ack_status = int(ack_param)
        except ValueError:
            ack_status = None

    # Fetch events based on filters
    events = storage.get_events(
        limit=int(limit_param),
        offset=int(offset_param),
        severity=severity_filter,
        event_type=type_filter,
        acknowledged=ack_status,
    )

    # Get count of unacknowledged events
    unack_count = storage.get_event_count(acknowledged=0)

    # Localize timestamps in the events
    _localize_timestamps(events)

    return jsonify({
        "events": events,
        "unacknowledged_count": unack_count
    })

@events_bp.route("/api/events/count", methods=["GET"])
@require_auth
def api_events_count():
    """Return unacknowledged event count (for badge)."""
    storage = get_storage()
    if not storage:
        return jsonify({"count": 0})

    # Return only the count of unacknowledged events
    return jsonify({"count": storage.get_event_count(acknowledged=0)})

@events_bp.route("/api/events/<int:event_id>/acknowledge", methods=["POST"])
@require_auth
def api_event_acknowledge(event_id):
    """Acknowledge a single event."""
    storage = get_storage()
    if not storage:
        return jsonify({"error": "Storage not initialized"}), 500

    # Attempt to acknowledge the specific event
    result = storage.acknowledge_event(event_id)
    if not result:
        return jsonify({"error": "Event not found"}), 404

    return jsonify({"success": True})

@events_bp.route("/api/events/acknowledge-all", methods=["POST"])
@require_auth
def api_events_acknowledge_all():
    """Acknowledge all unacknowledged events."""
    storage = get_storage()
    if not storage:
        return jsonify({"error": "Storage not initialized"}), 500

    # Acknowledge all unacknowledged events and get count
    processed_count = storage.acknowledge_all_events()

    return jsonify({
        "success": True,
        "count": processed_count
    })

