# Modified scopes list for enhanced security and modularity
AUTH_SCOPES = [
    'https://www.googleapis.com/auth/gmail.readonly',
    'https://www.googleapis.com/auth/gmail.send',
    'https://www.googleapis.com/auth/gmail.modify',
    'https://www.googleapis.com/auth/calendar.events',
    'https://www.googleapis.com/auth/drive.file'
]

TOKEN_FILE = Path(__file__).parent / 'google_tokens.json'
CLIENT_SECRETS = Path(__file__).parent / 'google_client_secrets.json'


def get_skill_metadata():
    return {
        "identifier": "google-suite",
        "title": "Google Workspace Integration",
        "categories": ["google", "email", "calendar", "cloud-storage", "api"],
        "summary": "Unified interface for Gmail, Calendar, and Drive services"
    }


def fetch_credentials() -> Credentials:
    credentials = None
    if TOKEN_FILE.exists():
        try:
            credentials = Credentials.from_authorized_user_file(str(TOKEN_FILE), AUTH_SCOPES)
        except Exception:
            credentials = None

    # Validate or refresh credentials
    if not credentials or not credentials.valid:
        if credentials and credentials.expired and credentials.refresh_token:
            credentials.refresh(Request())
        else:
            client_config = {
                "installed": {
                    "client_id": os.getenv("GOOGLE_CLIENT_ID"),
                    "client_secret": os.getenv("GOOGLE_CLIENT_SECRET"),
                    "redirect_uris": [os.getenv("GOOGLE_REDIRECT_URI")],
                    "auth_uri": "https://accounts.google.com/o/oauth2/auth",
                    "token_uri": "https://oauth2.googleapis.com/token"
                }
            }

            flow = InstalledAppFlow.from_client_config(client_config, AUTH_SCOPES)
            credentials = flow.run_local_server(port=0)

        # Persist updated credentials
        with open(TOKEN_FILE, 'w') as token_file:
            token_file.write(credentials.to_json())

    return credentials


class GoogleWorkspaceSkill:
    def __init__(self):
        self.auth = fetch_credentials()

    def process_request(self, request_data: Dict[str, Any]) -> Any:
        service_type = request_data.get("service")
        operation = request_data.get("operation")

        if service_type == "gmail":
            return self._process_gmail_operation(operation, request_data)
        elif service_type == "calendar":
            return self._process_calendar_operation(operation, request_data)
        elif service_type == "drive":
            return self._process_drive_operation(operation, request_data)
        else:
            raise ValueError(f"Unsupported service: {service_type}")

    # Gmail-specific handlers
    def _process_gmail_operation(self, operation, data):
        service = build('gmail', 'v1', credentials=self.auth)
        if operation == "transmit":
            return self._send_email(service, data)
        elif operation == "scan":
            return self._retrieve_emails(service, data)
        elif operation == "remove":
            return self._purge_message(service, data)
        else:
            raise ValueError(f"Invalid Gmail operation: {operation}")

    def _send_email(self, service, data):
        from email.mime.text import MIMEText
        import base64

        msg = MIMEText(data.get("content", ""))
        msg['to'] = data.get("recipient")
        msg['subject'] = data.get("title", "")
        encoded = base64.urlsafe_b64encode(msg.as_bytes()).decode()

        response = service.users().messages().send(
            userId="me", 
            body={'raw': encoded}
        ).execute()

        return {"message_id": response.get("id"), "result": "delivered"}

    def _retrieve_emails(self, service, data):
        search_query = data.get("filter", "in:inbox")
        limit = int(data.get("limit", 10))

        results = service.users().messages().list(
            userId="me", 
            q=search_query, 
            maxResults=limit
        ).execute()

        messages = results.get('messages', [])
        emails = []

        for item in messages:
            detail = service.users().messages().get(userId="me", id=item['id']).execute()
            emails.append({
                "uid": item['id'], 
                "preview": detail.get('snippet', '')
            })

        return emails

    def _purge_message(self, service, data):
        message_id = data.get("message_id")
        if not message_id:
            raise ValueError("Message ID is required for deletion")

        service.users().messages().delete(userId="me", id=message_id).execute()
        return {"message_id": message_id, "result": "deleted"}


    # Calendar-specific handlers
    def _process_calendar_operation(self, operation, data):
        service = build('calendar', 'v3', credentials=self.auth)
        if operation == "view":
            return self._list_events(service, data)
        elif operation == "add":
            return self._schedule_event(service, data)
        elif operation == "edit":
            return self._modify_event(service, data)
        elif operation == "erase":
            return self._cancel_event(service, data)
        else:
            raise ValueError(f"Invalid Calendar operation: {operation}")

    def _list_events(self, service, data):
        from datetime import datetime, timedelta

        start_time = datetime.utcnow().isoformat() + 'Z'
        days = int(data.get("duration_days", 7))
        end_time = (datetime.utcnow() + timedelta(days=days)).isoformat() + 'Z'

        events = service.events().list(
            calendarId='primary',
            timeMin=start_time,
            timeMax=end_time,
            maxResults=int(data.get("event_limit", 10)),
            singleEvents=True,
            orderBy='startTime'
        ).execute()

        items = events.get('items', [])
        return [
            {
                "id": e["id"],
                "title": e.get("summary"),
                "start": e["start"],
                "end": e["end"]
            } for e in items
        ]

    def _schedule_event(self, service, data):
        event_data = {
            'summary': data.get('title'),
            'start': {'dateTime': data.get('start_time')},
            'end': {'dateTime': data.get('end_time')},
        }

        created = service.events().insert(
            calendarId='primary', 
            body=event_data
        ).execute()

        return {"id": created["id"], "result": "created"}

    def _modify_event(self, service, data):
        event_id = data.get('event_id')
        if not event_id:
            raise ValueError("Event ID is required for modification")

        event = service.events().get(
            calendarId='primary', 
            eventId=event_id
        ).execute()

        if 'title' in data:
            event['summary'] = data['title']
        if 'start_time' in data:
            event['start']['dateTime'] = data['start_time']
        if 'end_time' in data:
            event['end']['dateTime'] = data['end_time']

        updated = service.events().update(
            calendarId='primary', 
            eventId=event_id, 
            body=event
        ).execute()

        return {"id": updated["id"], "result": "updated"}

    def _cancel_event(self, service, data):
        event_id = data.get('event_id')
        if not event_id:
            raise ValueError("Event ID is required for cancellation")

        service.events().delete(
            calendarId='primary', 
            eventId=event_id
        ).execute()

        return {"id": event_id, "result": "cancelled"}


    # Drive-specific handlers
    def _process_drive_operation(self, operation, data):
        service = build('drive', 'v3', credentials=self.auth)
        if operation == "browse":
            return self._explore_files(service, data)
        elif operation == "store":
            return self._upload_file(service, data)
        elif operation == "fetch":
            return self._download_file(service, data)
        elif operation == "destroy":
            return self._remove_file(service, data)
        else:
            raise ValueError(f"Invalid Drive operation: {operation}")

    def _explore_files(self, service, data):
        filter_query = data.get("search_term", "")
        file_limit = int(data.get("max_items", 10))

        results = service.files().list(
            q=filter_query,
            pageSize=file_limit,
            fields="files(id, name)"
        ).execute()

        files = results.get('files', [])
        return [{"id": f["id"], "name": f["name"]} for f in files]

    def _upload_file(self, service, data):
        from googleapiclient.http import MediaFileUpload

        source_path = data.get("source_path")
        if not source_path or not os.path.isfile(source_path):
            raise ValueError("Valid file path required for upload")

        file_meta = {'name': os.path.basename(source_path)}
        media = MediaFileUpload(source_path, resumable=True)

        uploaded = service.files().create(
            body=file_meta, 
            media_body=media, 
            fields='id'
        ).execute()

        return {"id": uploaded["id"], "result": "uploaded"}

    def _download_file(self, service, data):
        from googleapiclient.http import MediaIoBaseDownload
        import io

        file_id = data.get("file_id")
        target_path = data.get("target_path")

        if not file_id or not target_path:
            raise ValueError("Both file_id and target_path are required for download")

        request = service.files().get_media(fileId=file_id)

        with open(target_path, 'wb') as output_file:
            downloader = MediaIoBaseDownload(output_file, request)
            completed = False
            while not completed:
                status, completed = downloader.next_chunk()

        return {"id": file_id, "result": "downloaded", "location": target_path}

    def _remove_file(self, service, data):
        file_id = data.get("file_id")
        if not file_id:
            raise ValueError("File ID is required for deletion")

        service.files().delete(fileId=file_id).execute()
        return {"id": file_id, "result": "deleted"}

