class OllamaEngine:
    def __init__(self):
        print("OllamaEngine initialized")

    async def generate(self, job_input):
        model_name = os.getenv("OLLAMA_MODEL_NAME", "llama3.2:1b")

        # Determine route type based on input format
        if isinstance(job_input.llm_input, str):
            route = "/v1/completions"
            payload = {
                "model": model_name,
                "prompt": job_input.llm_input,
                "stream": getattr(job_input, 'stream', False)
            }
        else:
            route = "/v1/chat/completions"
            payload = {
                "model": model_name,
                "messages": job_input.llm_input,
                "stream": getattr(job_input, 'stream', False)
            }

        # Construct new job input for OpenAI-compatible endpoint
        modified_job = JobInput({
            "openai_route": route,
            "openai_input": payload
        })

        # Delegate to OpenAI-compatible engine
        adapter_engine = OllamaOpenAiEngine()
        async for result in adapter_engine.generate(modified_job):
            yield result

class OllamaOpenAiEngine(OllamaEngine):
    def __init__(self):
        print("OllamaOpenAiEngine initialized")

    async def generate(self, job_input):
        route = job_input.openai_route
        input_data = job_input.openai_input

        if route == "/v1/models":
            async for item in self._process_model_list():
                yield item
        elif route in ["/v1/chat/completions", "/v1/completions"]:
            is_chat = route == "/v1/chat/completions"
            async for chunk in self._process_completion_request(input_data, is_chat):
                yield chunk
        else:
            yield {"error": "Unsupported endpoint"}

    async def _process_model_list(self):
        try:
            models_response = ollama_client.models.list()
            formatted_models = [
                {"id": m.id, "created": m.created, "object": m.object, "owned_by": m.owned_by}
                for m in models_response.data
            ]
            yield {"object": "list", "data": formatted_models}
        except Exception as error:
            yield {"error": str(error)}

    async def _process_completion_request(self, request_params, is_chat=False):
        try:
            # Route call appropriately
            if is_chat:
                raw_response = ollama_client.chat.completions.create(**request_params)
            else:
                raw_response = ollama_client.completions.create(**request_params)

            # Handle non-streaming case
            if not request_params.get("stream", False):
                yield raw_response.model_dump()
                return

            # Stream chunks
            for part in raw_response:
                print(f"Chunk received: {part}")
                yield f"data: {json.dumps(part.model_dump(), separators=(',', ':'))}\n\n"
            yield "data: [DONE]"
        except Exception as exception:
            yield {"error": str(exception)}

import json
from volcengine.ApiInfo import ApiInfo
from typing import Any
from volcengine import Credentials
from volcengine import ServiceInfo
from volcengine.base import Service

class BaseApi(Service.Service):
    def __init__(self, region, endpoint, api_info, service, ak, sk):
        """Initialize the API client with configuration parameters.

        :param region:   AWS region identifier for the request
        :param api_info: Instance of volcengine.ApiInfo.ApiInfo() containing API details
        :param endpoint: Gateway endpoint URL for the service
        :param service:  Service name registered on the gateway
        :param ak:       Access key ID for authentication
        :param sk:       Secret access key for authentication
        """
        self.conn_timeout = 10
        self.sock_timeout = 10
        self.protocol = 'https'
        self.headers = {}
        self.headers["Content-Type"] = "application/json"
        self.endpoint_url = endpoint
        self.auth_creds = Credentials.Credentials(ak, sk, service, region)
        self.service_config = ServiceInfo.ServiceInfo(
            self.endpoint_url,
            self.headers,
            self.auth_creds,
            self.conn_timeout,
            self.sock_timeout,
            self.protocol,
        )
        self.api_details = api_info
        Service.Service.__init__(self, self.service_config, self.api_details)

    @staticmethod
    def convert_to_query_params(obj: Any) -> dict[str, Any]:
        """Transform a request object into a parameter dictionary, excluding None values.

        This utility handles mapping between Python snake_case attributes and API 
        expected camelCase parameter names using attribute_map metadata when available.
        """
        payload = {}

        if hasattr(obj, "to_dict"):
            payload = obj.to_dict()
        elif hasattr(obj, "model_dump"):
            payload = obj.model_dump()
        elif isinstance(obj, dict):
            payload = obj.copy()
        else:
            payload = vars(obj) if hasattr(obj, "__dict__") else {}

        # Apply attribute name transformation if mapping exists
        name_mapping = getattr(obj, "attribute_map", {})
        if isinstance(name_mapping, dict) and name_mapping:
            transformed = {}
            for key, value in payload.items():
                mapped_key = name_mapping.get(key, key)
                transformed[mapped_key] = value
            payload = transformed

        # Filter out None values
        return {k: v for k, v in payload.items() if v is not None}

    def execute_get_request(self, action, params, doseq=0):
        raw_response = super(BaseApi, self).get(action, params, doseq)
        try:
            response_data = json.loads(raw_response)
        except Exception as err:
            raise Exception("Response body is not valid JSON, %s, %s" % (err, raw_response))

        if "ResponseMetadata" not in response_data:
            raise Exception(
                "Missing ResponseMetadata in response, action %s, response %s" % (action, raw_response)
            )
        elif "Error" in response_data["ResponseMetadata"]:
            raise Exception("%s operation failed, %s" % (action, raw_response))

        return response_data

