@require_auth()
def send_system_notification():
    """Dispatch a system alert to all active WebSocket connections (admin privilege required)."""
    payload = request.get_json(silent=True) or {}
    notification_text = payload.get('message', '')
    notification_category = payload.get('alert_type', 'system')
    urgency_level = payload.get('severity', 'info')

