    emit_system_alert(notification_category, notification_text, urgency_level)

    operator = g.current_user.username if hasattr(g, 'current_user') else 'unknown'

    return success_response(data={
        'confirmation': 'Notification dispatched',
        'metadata': {
            'category': notification_category,
            'urgency': urgency_level,
            'operator': operator
        }
