def complex_aggregation(x, values):
    accumulator = 0
    for val in values:
        if val > 0:
            accumulator += val
        else:
            accumulator -= abs(val)

    if accumulator > 10 and x:
        for idx in range(5):
            if idx % 2 == 0:
                accumulator += idx
            else:
                accumulator -= idx

    try:
        while accumulator < 100:
            if accumulator % 3 == 0 and accumulator % 5 == 0:
                break
            if accumulator % 2 == 0:
                accumulator += 7
            else:
                accumulator += 3
    except Exception:
        accumulator = -1

    return accumulator

