    BackboardValidationError,
)
from ..services.backboard import BackboardService

documents_bp = Blueprint("documents", __name__)

def _get_backboard_service():
    """Retrieve a new instance of the Backboard service."""
    return BackboardService()

# Supported file extensions for upload
SUPPORTED_EXTENSIONS = {
    "pdf",
    "docx",
    "xlsx",
    "pptx",
    "doc",
    "xls",
    "ppt",
    "txt",
    "csv",
    "md",
    "markdown",
    "py",
    "js",
    "html",
    "css",
    "xml",
    "json",
    "jsonl",
}

def _is_extension_valid(filename):
    """Determine if the file extension is in the allowed list."""
    if "." not in filename:
        return False
    ext = filename.rsplit(".", 1)[-1].lower()
    return ext in SUPPORTED_EXTENSIONS

@documents_bp.route("/assistants/<aid>/documents", methods=["POST"])
def assistant_document_upload(aid: str):
    """Handle document uploads for a specific assistant."""
    try:
        uploaded_files = request.files
        if "file" not in uploaded_files:
            return jsonify({"error": "No file provided"}), 400

        file_obj = uploaded_files["file"]
        if not file_obj.filename:
            return jsonify({"error": "No file selected"}), 400

        if not _is_extension_valid(file_obj.filename):
            return jsonify({"error": "File type not allowed"}), 400

        # Save to temporary location
        _, ext = os.path.splitext(file_obj.filename)
        with tempfile.NamedTemporaryFile(delete=False, suffix=ext) as temp_file:
            file_obj.save(temp_file.name)
            svc = _get_backboard_service()
            response_data = svc.upload_document_to_assistant(aid, temp_file.name)
            os.unlink(temp_file.name)

        return jsonify(response_data), 201

    except BackboardNotFoundError:
        return jsonify({"error": "Not found", "detail": "Assistant not found"}), 404
    except BackboardValidationError as err:
        return jsonify({"error": "Validation error", "detail": str(err)}), 400
    except BackboardAPIError as err:
        return jsonify({"error": "API error", "detail": str(err)}), 500

